// Generado desde Drive «CALOT-OS COMPLETO» (juegos-nuevos-contenido-R1-R4.md · 6 juegos nuevos). Cada ítem lleva `grade` (R1–R4) y se filtra con canSee().
export const JUEGOS_NUEVOS = {
  guardia: [
    {"id": "GN-R1-01", "grade": "R1", "caso": "Hombre de 58 años, día 2 postoperatorio de colectomía por cáncer de colon. A las 3:00 a. m. la enfermera te llama: está pálido, sudoroso, con drenaje de 400 mL de sangre en la última hora y dolor abdominal difuso.", "tema": "Estado de choque — choque hipovolémico hemorrágico postoperatorio.", "t0": "FC 128 lpm, TA 88/54 mmHg, SatO2 94% al aire ambiente, temperatura 36.1 °C, dolor 7/10, Glasgow 15. Hb de hace 6 h: 11.2 g/dL. Drenaje abdominal sanguinolento, 400 mL/h. Piel fría y moteada, llenado capilar 4 s, diuresis 15 mL/h.", "q": "¿Qué pides primero y qué manejo inicias en los próximos 30 minutos?", "opts": ["Reponer con cristaloides a chorro y esperar la Hb", "Activar protocolo de hemorragia masiva / transfusión balanceada y avisar al adscrito y a quirófano", "Dar solo vasopresor para subir la TA"], "ans": 1, "t1Good": "Se canalizan dos vías gruesas, se inicia transfusión balanceada, se pide Hb, lactato, gasometría y coagulación; FC 118 lpm, TA 96/60 mmHg, diuresis 30 mL/h, sigue sangrando por el drenaje pero el paciente se mantiene perfundido.", "t1Bad": "1.5 L de cristaloide diluyen sin reponer sangre, la TA sube un momento a 100/60 y luego cae; FC 142 lpm, TA 78/46 mmHg, SatO2 91%, Glasgow 14, diuresis 5 mL/h, lactato en ascenso. El vasopresor solo, sin volumen ni sangre, no corrige la causa.", "t2Good": "Reexploración quirúrgica oportuna, se encuentra sangrado de un vaso del mesocolon, se controla; Hb 8.4 g/dL tras transfundir, FC 102 lpm, TA 112/68 mmHg, diuresis 45 mL/h. Sobrevive y pasa a terapia intermedia.", "t2Bad": "Choque hemorrágico descompensado, coagulopatía, hipotermia y acidosis — la tríada letal —, paro en quirófano o en la cama. La demora en avisar es lo que más pesa en el desenlace.", "answer": "Activar protocolo de hemorragia masiva / transfusión balanceada, dos vías gruesas, reponer sangre y avisar de inmediato al adscrito y preparar quirófano para reexploración. El cristaloide es puente, no tratamiento; el vasopresor no sustituye sangre.", "exp": "Sangrado activo con taquicardia, hipotensión, piel fría, oliguria y caída del drenaje sanguinolento es choque hipovolémico hemorrágico hasta demostrar lo contrario. La Hb tarda en caer y no se espera para actuar. La transfusión balanceada (concentrados, plasma y plaquetas en proporción) y el control quirúrgico del sangrado son el tratamiento; diluir con litros de cristaloide agrava la coagulopatía y la hipotermia."},
    {"id": "GN-R1-02", "grade": "R1", "caso": "Mujer de 71 años, día 1 postoperatorio de colecistectomía laparoscópica. A las 3:00 a. m. está confusa, con náusea, cefalea y una convulsión tónico-clónica breve presenciada por la enfermera.", "tema": "Líquidos y electrolitos — hiponatremia grave postoperatoria.", "t0": "FC 96 lpm, TA 138/82 mmHg, SatO2 96%, temperatura 36.8 °C, dolor 3/10, Glasgow 13 (confusa, desorientada en tiempo). Recibió 3 L de solución glucosada al 5% en 24 h y orina poco. Na+ de ayer: 138 mEq/L.", "q": "¿Qué estudio pides de inmediato y qué corrección inicias?", "opts": ["Pedir electrolitos, osmolaridad y gasometría, y dar solución salina hipertónica al 3% con monitoreo estrecho", "Restringir líquidos y observar hasta la mañana", "Dar solución glucosada y un sedante para la agitación"], "ans": 0, "t1Good": "Na+ 118 mEq/L, osmolaridad baja; se inicia salina hipertónica en infusión controlada y se suspende la glucosada; a los 40 min Glasgow 14, sin nuevas convulsiones, Na+ 121 mEq/L.", "t1Bad": "Segunda convulsión a las 3:35 a. m., Glasgow 10, SatO2 89%, FC 112 lpm, TA 150/95 mmHg; la glucosada sigue bajando el sodio y el sedante enmascara el deterioro neurológico.", "t2Good": "Na+ 124 mEq/L, Glasgow 15, sin convulsiones, se corrige despacio (no más de 10-12 mEq/L en 24 h) y se investiga la causa (SIADH, exceso de líquidos hipotónicos).", "t2Bad": "Edema cerebral, estatus convulsivo, intubación de urgencia y daño neurológico; corregir demasiado rápido después también daña (desmielinización osmótica), por eso la corrección es controlada, no a chorro.", "answer": "Electrolitos urgentes y salina hipertónica al 3% con monitoreo estrecho ante hiponatremia grave sintomática (convulsión, Glasgow bajo). Suspender líquidos hipotónicos.", "exp": "Hiponatremia aguda sintomática con convulsión es una emergencia neurológica: el agua entra al cerebro y lo edematiza. La salina hipertónica sube el sodio lo suficiente para detener las convulsiones; luego la corrección debe ser lenta y vigilada. La solución glucosada al 5% es hipotónica una vez metabolizada la glucosa y es una causa clásica de hiponatremia postoperatoria."},
    {"id": "GN-R1-03", "grade": "R1", "caso": "Hombre de 45 años, día 3 tras laparotomía por trauma abdominal. A las 3:00 a. m. tiene fiebre, taquicardia, taquipnea y el abdomen distendido; la herida supura un poco.", "tema": "Respuesta biológica al trauma y fisiología quirúrgica — SIRS y sepsis postoperatoria.", "t0": "FC 124 lpm, TA 104/62 mmHg, SatO2 93%, temperatura 39.2 °C, dolor 6/10, Glasgow 15. Frecuencia respiratoria 26/min. Leucocitos de ayer: 13,000. Herida con eritema y secreción escasa.", "q": "¿Qué pides y qué haces en la primera hora?", "opts": ["Hemocultivos, lactato, biometría, procalcitonina si hay, cultivos de herida y drenajes, antibiótico de amplio espectro tras los cultivos y búsqueda del foco", "Solo paracetamol y esperar a la visita de las 7:00 a. m", "Antibiótico oral y curación local"], "ans": 0, "t1Good": "Lactato 3.1 mmol/L, leucocitos 17,500, se inicia antibiótico y líquidos; FC 112 lpm, TA 112/66 mmHg, temperatura 38.6 °C; la tomografía pedida muestra colección intraabdominal.", "t1Bad": "FC 138 lpm, TA 86/50 mmHg, SatO2 90%, temperatura 39.8 °C, Glasgow 14, frecuencia respiratoria 30/min, diuresis 20 mL/h: el SIRS ya es sepsis con hipoperfusión.", "t2Good": "Drenaje percutáneo o reintervención de la colección, antibiótico ajustado a cultivos, FC 98 lpm, TA 118/70 mmHg, lactato en descenso.", "t2Bad": "Choque séptico, necesidad de vasopresores e intubación, falla orgánica múltiple. La fiebre postoperatoria del día 3 ya no es solo \"respuesta al trauma\": hay que buscar el foco.", "answer": "Cultivos primero, luego antibiótico de amplio espectro en la primera hora, líquidos, lactato y búsqueda activa del foco (imagen y revisión de herida y drenajes).", "exp": "Tras la fase inicial de respuesta al trauma, fiebre alta con taquicardia, taquipnea y leucocitosis al tercer día obliga a descartar infección: herida, pulmón, vía urinaria, catéteres y, sobre todo, colección intraabdominal. En sepsis, cada hora de retraso del antibiótico y del control del foco empeora el desenlace (Surviving Sepsis Campaign 2021). El paracetamol solo tapa el termómetro."},
    {"id": "GN-R1-04", "grade": "R1", "caso": "Mujer de 62 años, diabética, día 5 postoperatorio de cirugía de colon. A las 3:00 a. m. grita de dolor en la herida: el dolor es mucho mayor de lo que se ve por fuera, la piel está tensa, con eritema que avanzó 3 cm en una hora y una ampolla.", "tema": "Infección en cirugía — fascitis necrosante de la herida quirúrgica.", "t0": "FC 122 lpm, TA 100/60 mmHg, SatO2 95%, temperatura 38.9 °C, dolor 9/10 (desproporcionado), Glasgow 15. Herida: eritema, edema tenso, dolor intenso a la palpación, una ampolla hemorrágica, sin crepitación clara. Glucosa 268 mg/dL.", "q": "¿Qué haces?", "opts": ["Avisar de inmediato al adscrito, antibiótico de amplio espectro, laboratorios y quirófano urgente para exploración y desbridamiento, sin esperar la tomografía", "Pedir tomografía y esperar el reporte para decidir", "Aumentar el analgésico y poner antibiótico oral"], "ans": 0, "t1Good": "En quirófano se confirma fascia grisácea sin sangrado y pus escaso; se desbrida amplio; FC 110 lpm, TA 108/64 mmHg, temperatura 38.4 °C.", "t1Bad": "El eritema avanza otros 5 cm, aparecen más ampollas y crepitación, FC 140 lpm, TA 82/48 mmHg, SatO2 90%, Glasgow 13, lactato 4.2 mmol/L: la infección ya es sistémica.", "t2Good": "Desbridamientos seriados, antibiótico, control glucémico y terapia intensiva; sobrevive con herida abierta que cierra por segunda intención.", "t2Bad": "Choque séptico, necrosis extensa, amputación de tejido o muerte. La imagen nunca debe retrasar el quirófano cuando el cuadro clínico manda.", "answer": "Sospecha clínica de fascitis necrosante: quirófano urgente para exploración y desbridamiento, antibiótico de amplio espectro y aviso inmediato. No esperar imagen.", "exp": "Dolor desproporcionado a los hallazgos cutáneos, eritema que avanza rápido, ampollas y deterioro sistémico en diabética postoperada es fascitis necrosante hasta demostrar lo contrario. Es una emergencia quirúrgica: el diagnóstico se confirma en quirófano y el tratamiento es desbridar, no la tomografía. Cada hora de retraso aumenta la necrosis y la mortalidad."},
    {"id": "GN-R1-05", "grade": "R1", "caso": "Hombre de 28 años llega a las 3:00 a. m. con dolor abdominal de 12 horas que empezó alrededor del ombligo y ahora está fijo en la fosa iliaca derecha. Vomitó dos veces, no tiene apetito y tiene fiebre baja.", "tema": "Abdomen agudo y apendicitis aguda.", "t0": "FC 104 lpm, TA 122/76 mmHg, SatO2 98%, temperatura 38.1 °C, dolor 7/10 en fosa iliaca derecha, Glasgow 15. Abdomen con dolor a la palpación en McBurney, rebote leve, Rovsing positivo. Leucocitos 14,200, PCR elevada.", "q": "¿Qué pides y qué decides?", "opts": ["Tomografía de abdomen con contraste y valoración para apendicectomía urgente", "Darlo de alta con analgésico y cita en una semana", "Pedir solo radiografía de abdomen y observar sin avisar a nadie"], "ans": 0, "t1Good": "La tomografía muestra apéndice de 11 mm con fecalito y grasa periapendicular inflamada, sin absceso; se programa apendicectomía laparoscópica en la mañana; FC 98 lpm, TA 118/74 mmHg, dolor controlado.", "t1Bad": "El dolor se generaliza, FC 126 lpm, TA 96/58 mmHg, temperatura 39.0 °C, abdomen rígido y con rebote generalizado: apéndice perforado con peritonitis.", "t2Good": "Apendicectomía sin complicaciones, alta en 24-48 h.", "t2Bad": "Perforación, absceso, peritonitis, estancia larga, posible reintervención y sepsis. Darlo de alta con dolor en fosa iliaca derecha y leucocitosis es el error clásico de la guardia.", "answer": "Imagen (tomografía con contraste, o ultrasonido si el contexto lo indica) y apendicectomía urgente. La apendicitis no se observa en casa.", "exp": "Migración del dolor de periumbilical a fosa iliaca derecha, anorexia, vómito, fiebre baja, dolor en McBurney con rebote y leucocitosis es apendicitis aguda hasta demostrar lo contrario (WSES 2020). La tomografía confirma y descarta diagnósticos diferenciales; el tratamiento es quirúrgico y oportuno, antes de la perforación."},
    {"id": "GN-R1-06", "grade": "R1", "caso": "Mujer de 54 años con antecedente de colelitiasis llega a las 3:00 a. m. con dolor intenso en hipocondrio derecho de 8 horas, fiebre y vómito. La vesícula se palpa y duele al inspirar.", "tema": "Patología biliar — colecistitis aguda.", "t0": "FC 112 lpm, TA 128/78 mmHg, SatO2 97%, temperatura 38.6 °C, dolor 8/10 en hipocondrio derecho, Glasgow 15. Murphy positivo, leucocitos 15,800, bilirrubina total 1.4 mg/dL, sin ictericia.", "q": "¿Qué pides y qué decides?", "opts": ["Ultrasonido de hígado y vías biliares, laboratorios, ayuno, líquidos, antibiótico y colecistectomía laparoscópica temprana", "Dar antiespasmódico y enviarla a casa porque \"es un cólico biliar\"", "Pedir solo radiografía y esperar a la mañana sin antibiótico"], "ans": 0, "t1Good": "El ultrasonido muestra vesícula distendida, pared de 5 mm, lito impactado en el cuello y líquido perivesicular; FC 102 lpm, TA 122/76 mmHg, dolor 5/10 con analgesia.", "t1Bad": "FC 130 lpm, TA 92/56 mmHg, temperatura 39.4 °C, dolor 9/10, abdomen con defensa en hipocondrio derecho y signo de irritación peritoneal: colecistitis gangrenosa o perforada.", "t2Good": "Colecistectomía laparoscópica temprana, sin complicaciones mayores.", "t2Bad": "Perforación vesicular, absceso perivesicular, peritonitis biliar y cirugía mucho más difícil y riesgosa.", "answer": "Ultrasonido, laboratorios, ayuno, antibiótico y colecistectomía laparoscópica temprana. La colecistitis aguda no es un cólico que se manda a casa.", "exp": "Dolor en hipocondrio derecho mayor de 6 horas con fiebre, leucocitosis y Murphy positivo es colecistitis aguda (criterios de las Guías de Tokio TG18). El ultrasonido confirma engrosamiento de pared, distensión y lito impactado. La colecistectomía temprana, en las primeras 72 horas, es el tratamiento y tiene menos complicaciones que esperar."},
    {"id": "GN-R1-07", "grade": "R1", "caso": "Hombre de 70 años con hernia inguinal derecha conocida desde hace años llega a las 3:00 a. m.: la hernia se le hizo dura, no se puede meter, vomita y no ha evacuado ni sacado gases en 12 horas. El abdomen está distendido.", "tema": "Hernias de pared abdominal y obstrucción intestinal — hernia estrangulada.", "t0": "FC 116 lpm, TA 118/70 mmHg, SatO2 96%, temperatura 37.9 °C, dolor 8/10, Glasgow 15. Hernia inguinal derecha tensa, dolorosa, no reductible, con piel enrojecida. Abdomen distendido, timpánico, ruidos intestinales escasos. Lactato 2.4 mmol/L.", "q": "¿Qué haces?", "opts": ["Ayuno, líquidos, laboratorios, sonda nasogástrica si hay vómito y distensión, y quirófano urgente por hernia estrangulada, sin intentar reducción forzada", "Intentar meter la hernia a la fuerza con sedación en urgencias", "Dar laxante y esperar a que evacue"], "ans": 0, "t1Good": "En quirófano se encuentra asa intestinal congestiva pero viable; se reduce, se repara la hernia; FC 100 lpm, TA 120/72 mmHg, dolor 4/10.", "t1Bad": "El intento de reducción rompe el asa o la mete necrosada al abdomen; FC 134 lpm, TA 86/52 mmHg, temperatura 39.1 °C, lactato 5.0 mmol/L, abdomen rígido: intestino necrosado y perforado.", "t2Good": "Reparación sin resección intestinal, recuperación sin complicaciones.", "t2Bad": "Resección intestinal, posible estoma, sepsis y estancia prolongada en terapia intensiva.", "answer": "Quirófano urgente por hernia estrangulada. No se intenta reducción forzada en una hernia tensa, dolorosa y con signos de estrangulación.", "exp": "Hernia no reductible, tensa y dolorosa con obstrucción (vómito, distensión, sin evacuaciones ni gases) y lactato elevado es estrangulación hasta demostrar lo contrario. El intestino atrapado se isquemia en horas. La reducción forzada puede meter un asa necrosada al abdomen y perforarla por dentro. El tratamiento es quirúrgico y urgente."},
    {"id": "GN-R1-08", "grade": "R1", "caso": "Hombre de 34 años llega a las 3:00 a. m. tras un choque de moto: golpe en el tórax, respira con dificultad, está agitado y con el cuello con las venas ingurgitadas. Un lado del tórax casi no se mueve.", "tema": "Trauma: evaluación inicial ATLS — neumotórax a tensión.", "t0": "FC 138 lpm, TA 78/50 mmHg, SatO2 84% con mascarilla, temperatura 36.4 °C, dolor 8/10, Glasgow 14 (agitado). Frecuencia respiratoria 32/min, tráquea desviada a la izquierda, ausencia de murmullo vesicular derecho, hiperresonancia a la percusión, venas del cuello ingurgitadas.", "q": "¿Qué haces primero?", "opts": ["Descompresión inmediata con aguja o toracostomía con dedo en el hemitórax derecho, en el segundo espacio intercostal o quinto espacio, sin esperar radiografía", "Pedir radiografía de tórax y esperar el reporte", "Intubarlo primero sin descomprimir"], "ans": 0, "t1Good": "Sale aire a presión, SatO2 sube a 94%, FC 118 lpm, TA 102/64 mmHg, frecuencia respiratoria 22/min; luego se coloca sonda pleural.", "t1Bad": "SatO2 76%, FC 152 lpm, TA 60/40 mmHg, Glasgow 11, paro respiratorio inminente; la ventilación con presión positiva sin descomprimir empeora el neumotórax a tensión.", "t2Good": "Sonda pleural funcionante, reexpansión pulmonar, estabilización y tomografía para buscar otras lesiones.", "t2Bad": "Paro cardiaco por obstrucción del retorno venoso. En trauma, el neumotórax a tensión mata en minutos y se diagnostica con las manos y los oídos, no con la radiografía.", "answer": "Descompresión inmediata del neumotórax a tensión, sin esperar imagen. Es un diagnóstico clínico (ATLS 10a ed.).", "exp": "Hipotensión, hipoxia, desviación traqueal, ausencia de murmullo, hiperresonancia e ingurgitación yugular tras trauma torácico es neumotórax a tensión: el aire atrapado colapsa el pulmón y comprime el corazón y la vena cava. La descompresión inmediata salva la vida; la radiografía retrasa y la ventilación a presión positiva lo agrava."},
    {"id": "GN-R1-09", "grade": "R1", "caso": "Mujer de 47 años, 6 horas después de una histerectomía, sangra por la herida y por el drenaje. Está mareada al sentarse. La Hb cayó de 12.0 a 8.1 g/dL.", "tema": "Sangre, hemostasia y transfusión — hemorragia postoperatoria y coagulopatía.", "t0": "FC 126 lpm, TA 92/58 mmHg, SatO2 95%, temperatura 35.8 °C, dolor 5/10, Glasgow 15. Herida con sangrado activo, drenaje con 350 mL de sangre en 2 h. Plaquetas 98,000, INR 1.6, fibrinógeno bajo. Piel fría, diuresis 20 mL/h.", "q": "¿Qué pides y qué das?", "opts": ["Transfundir con estrategia balanceada, corregir fibrinógeno y calcio, calentar a la paciente, pedir coagulación y avisar a quirófano", "Dar 2 L de cristaloide frío y esperar otra Hb en 4 horas", "Dar solo plasma fresco sin concentrados eritrocitarios"], "ans": 0, "t1Good": "Se transfunde, se calienta con manta térmica, se da fibrinógeno; FC 110 lpm, TA 106/64 mmHg, temperatura 36.5 °C, el sangrado disminuye.", "t1Bad": "FC 144 lpm, TA 76/44 mmHg, temperatura 35.2 °C, INR 2.1, plaquetas 65,000, sangrado que no para por la herida y el drenaje: coagulopatía dilucional e hipotermia.", "t2Good": "Reexploración con hemostasia, transfusión balanceada, temperatura y coagulación corregidas; sobrevive sin daño orgánico.", "t2Bad": "Sangrado incoercible, choque hemorrágico, falla multiorgánica.", "answer": "Transfusión balanceada, corrección de fibrinógeno y calcio, recalentamiento activo y control quirúrgico del sangrado. El frío y la dilución empeoran la coagulopatía.", "exp": "Hemorragia con caída de Hb, trombocitopenia, INR elevado, fibrinógeno bajo e hipotermia es coagulopatía del sangrado masivo. La estrategia restrictiva de \"una unidad y reevaluar\" es para el paciente estable sin sangrado activo; aquí se transfunde de forma balanceada, se corrige el fibrinógeno, se repone calcio y se calienta a la paciente. El cristaloide frío y en exceso diluye factores y plaquetas."},
    {"id": "GN-R1-10", "grade": "R1", "caso": "Hombre de 66 años, obeso y diabético, día 4 postoperatorio de laparotomía. A las 3:00 a. m. tose fuerte y siente que \"algo se le abrió\" en el abdomen; por la herida sale líquido claro y se ve intestino.", "tema": "Cicatrización y cuidado de las heridas quirúrgicas — dehiscencia y evisceración.", "t0": "FC 118 lpm, TA 124/76 mmHg, SatO2 96%, temperatura 37.8 °C, dolor 7/10, Glasgow 15. Herida abdominal abierta en su porción central, con asas intestinales expuestas, cubiertas con gasas. Sin sangrado activo. Glucosa 244 mg/dL.", "q": "¿Qué haces en los primeros minutos?", "opts": ["Cubrir las asas con gasas estériles húmedas con solución salina tibia, ayuno, líquidos, antibiótico, avisar al adscrito y quirófano urgente, sin intentar meter el intestino", "Intentar meter el intestino con la mano en la cama", "Poner una curación seca y esperar a la visita de la mañana"], "ans": 0, "t1Good": "Las asas se mantienen rosadas y húmedas, FC 104 lpm, TA 120/74 mmHg, dolor 5/10; en quirófano se lava y se cierra o se maneja con abdomen abierto según hallazgos.", "t1Bad": "Las asas se resecan y se edematizan, FC 132 lpm, TA 96/58 mmHg, temperatura 38.8 °C, dolor 9/10, riesgo de lesión intestinal y peritonitis.", "t2Good": "Cierre o manejo de abdomen abierto con control, sobrevive con estancia prolongada pero sin perforación.", "t2Bad": "Perforación intestinal, peritonitis, sepsis y reintervenciones múltiples.", "answer": "Cubrir con gasas estériles húmedas tibias, no reintroducir el intestino en la cama, ayuno y quirófano urgente.", "exp": "La evisceración es una emergencia quirúrgica. El intestino expuesto se reseca, se edematiza y se lesiona si se manipula fuera de quirófano; la curación seca lo daña más. Se protege húmedo y estéril, se mantiene perfundido al paciente y se resuelve en quirófano. La obesidad, la diabetes y la tos son factores de riesgo clásicos de dehiscencia."},
    {"id": "GN-R2-01", "grade": "R2", "caso": "Hombre de 52 años llega a las 3:00 a. m. con dolor torácico intenso tras vomitar con fuerza en una cena. Tiene enfisema subcutáneo en el cuello y el tórax, y duele al tragar.", "tema": "Patología esofágica y ERGE — perforación esofágica (síndrome de Boerhaave).", "t0": "FC 124 lpm, TA 100/62 mmHg, SatO2 92%, temperatura 38.4 °C, dolor torácico 9/10, Glasgow 15. Enfisema subcutáneo cervical, dolor a la palpación en epigastrio, murmullo vesicular disminuido en base izquierda. Leucocitos 16,000.", "q": "¿Qué pides y qué haces?", "opts": ["Tomografía de tórax con contraste oral hidrosoluble, ayuno, antibiótico de amplio espectro, líquidos y aviso urgente a cirugía y endoscopia, sin dar bario", "Dar antiácido y enviarlo a casa como reflujo", "Pedir endoscopia con insuflación de aire a presión sin imagen previa"], "ans": 0, "t1Good": "La tomografía muestra perforación del esófago distal con neumomediastino y derrame pleural izquierdo; se coloca sonda pleural y se planea reparación o stent según el tiempo y el estado; FC 112 lpm, TA 110/66 mmHg, SatO2 95%.", "t1Bad": "FC 142 lpm, TA 82/48 mmHg, SatO2 88%, temperatura 39.5 °C, Glasgow 13: mediastinitis y choque séptico; la endoscopia con aire agranda la perforación.", "t2Good": "Control temprano de la fuga, drenaje pleural y antibiótico; sobrevive con estancia larga.", "t2Bad": "Mediastinitis fulminante, empiema, falla multiorgánica y muerte. La perforación esofágica se mide en horas, no en días.", "answer": "Tomografía con contraste hidrosoluble, ayuno, antibiótico, líquidos y manejo urgente multidisciplinario. Nunca bario ni endoscopia con insuflación antes de saber dónde está la fuga.", "exp": "Vómito forzado seguido de dolor torácico, enfisema subcutáneo y fiebre es perforación esofágica hasta demostrar lo contrario. El contraste hidrosoluble (no bario, que contamina el mediastino) localiza la fuga. El tratamiento es ayuno, antibiótico, drenaje de colecciones y cierre de la perforación — quirúrgico o endoscópico según el caso — lo antes posible."},
    {"id": "GN-R2-02", "grade": "R2", "caso": "Hombre de 63 años con antecedente de úlcera péptica llega a las 3:00 a. m. vomitando sangre y con evacuaciones negras. Está pálido y mareado.", "tema": "Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica — hemorragia por úlcera duodenal.", "t0": "FC 128 lpm, TA 86/54 mmHg, SatO2 95%, temperatura 36.5 °C, dolor epigástrico 5/10, Glasgow 15. Hematemesis de 300 mL, melena, piel fría, Hb 8.2 g/dL, BUN elevado, creatinina normal.", "q": "¿Qué haces en la primera hora?", "opts": ["Dos vías gruesas, líquidos, transfusión con umbral restrictivo, inhibidor de bomba de protones intravenoso, corrección de coagulación y endoscopia urgente tras estabilizar", "Dar antiácido oral y esperar a la endoscopia de la mañana sin reponer volumen", "Transfundir hasta Hb de 10 g/dL antes de cualquier otra cosa"], "ans": 0, "t1Good": "Se estabiliza, FC 108 lpm, TA 104/64 mmHg, diuresis adecuada; la endoscopia muestra úlcera duodenal con vaso visible que se trata con clip y adrenalina.", "t1Bad": "Nueva hematemesis de 500 mL, FC 146 lpm, TA 72/44 mmHg, Glasgow 13, Hb 6.4 g/dL, riesgo de aspiración; transfundir de más sin control endoscópico no detiene el sangrado.", "t2Good": "Hemostasia endoscópica exitosa, sin resangrado, se busca y trata Helicobacter pylori.", "t2Bad": "Resangrado, necesidad de cirugía de urgencia (sutura de úlcera) o embolización, choque y muerte.", "answer": "Reanimación, transfusión restrictiva, inhibidor de bomba de protones intravenoso y endoscopia urgente tras estabilizar. La endoscopia diagnostica y trata.", "exp": "Hematemesis y melena con hipotensión y taquicardia es hemorragia digestiva alta, y la úlcera péptica es la causa más frecuente. Se repone volumen, se transfunde con umbral restrictivo (alrededor de 7 g/dL en el paciente estable), se da inhibidor de bomba de protones y se hace endoscopia temprana para hemostasia. Transfundir hasta 10 g/dL no mejora el desenlace y puede aumentar la presión portal y el resangrado."},
    {"id": "GN-R2-03", "grade": "R2", "caso": "Mujer de 48 años llega a las 3:00 a. m. con dolor en hipocondrio derecho, fiebre de 39 °C y escalofríos de una semana que empeoraron esta noche. Tiene antecedente de diabetes y un viaje reciente a zona rural.", "tema": "Patología hepática quirúrgica — absceso hepático.", "t0": "FC 118 lpm, TA 106/64 mmHg, SatO2 96%, temperatura 39.3 °C, dolor 7/10 en hipocondrio derecho, Glasgow 15. Dolor a la percusión hepática, leucocitos 18,500, fosfatasa alcalina elevada, bilirrubina 1.8 mg/dL. Sin ictericia franca.", "q": "¿Qué pides y qué haces?", "opts": ["Ultrasonido o tomografía de abdomen, hemocultivos, biometría, pruebas de función hepática, antibiótico de amplio espectro y drenaje percutáneo si el absceso es grande", "Dar paracetamol y antibiótico oral y citarla en una semana", "Pedir solo radiografía de abdomen"], "ans": 0, "t1Good": "La tomografía muestra absceso hepático de 7 cm en lóbulo derecho; se drena por vía percutánea, sale pus; FC 102 lpm, TA 116/70 mmHg, temperatura 38.2 °C.", "t1Bad": "FC 136 lpm, TA 84/50 mmHg, temperatura 40.0 °C, Glasgow 13, dolor pleurítico derecho: el absceso se rompe a pleura o peritoneo y hay sepsis.", "t2Good": "Drenaje, antibiótico prolongado y búsqueda de la causa (biliar, portal, amebiano según el contexto); la fiebre cede en días.", "t2Bad": "Ruptura del absceso, peritonitis, empiema y choque séptico.", "answer": "Imagen, hemocultivos, antibiótico y drenaje percutáneo del absceso grande. El absceso hepático no se cura con paracetamol.", "exp": "Fiebre prolongada con dolor en hipocondrio derecho, leucocitosis y colestasis en diabética es absceso hepático hasta demostrar lo contrario. La imagen lo confirma y mide; el drenaje percutáneo más antibiótico es el tratamiento de los abscesos grandes. Hay que buscar la causa: vía biliar, diseminación portal (apendicitis, diverticulitis) o amebiano, porque el tratamiento cambia."},
    {"id": "GN-R2-04", "grade": "R2", "caso": "Mujer de 68 años llega a las 3:00 a. m. con fiebre alta, escalofríos, ictericia y dolor en hipocondrio derecho. Tiene antecedente de colecistectomía hace dos años.", "tema": "Patología biliar — colangitis aguda por coledocolitiasis (Guías de Tokio TG18).", "t0": "FC 126 lpm, TA 92/58 mmHg, SatO2 95%, temperatura 39.5 °C, dolor 7/10, Glasgow 14 (confusa). Ictericia, dolor en hipocondrio derecho. Bilirrubina total 5.2 mg/dL, leucocitos 17,000, fosfatasa alcalina muy elevada. Es la tríada de Charcot completa, con confusión: pentada de Reynolds.", "q": "¿Qué haces?", "opts": ["Líquidos, hemocultivos, antibiótico de amplio espectro de inmediato y drenaje biliar urgente (CPRE) sin esperar a que mejore con antibiótico solo", "Antibiótico oral y observación hasta la mañana", "Pedir ultrasonido y esperar el reporte sin antibiótico"], "ans": 0, "t1Good": "Se inicia antibiótico y líquidos, FC 112 lpm, TA 104/64 mmHg, Glasgow 15; la CPRE urgente extrae el lito y drena la vía biliar.", "t1Bad": "FC 144 lpm, TA 74/46 mmHg, SatO2 90%, Glasgow 11, lactato 4.5 mmol/L, diuresis 10 mL/h: choque séptico de origen biliar.", "t2Good": "Drenaje biliar exitoso, la fiebre y la ictericia ceden, sobrevive.", "t2Bad": "Choque séptico refractario, falla hepática y renal, muerte. La colangitis con hipotensión y confusión no espera al turno matutino.", "answer": "Antibiótico inmediato, líquidos y drenaje biliar urgente por CPRE. La colangitis grave es una emergencia de drenaje, no solo de antibiótico.", "exp": "Fiebre, ictericia y dolor en hipocondrio derecho (tríada de Charcot) más hipotensión y confusión (pentada de Reynolds) es colangitis aguda grave por obstrucción biliar (Guías de Tokio TG18). El antibiótico no drena: la vía biliar obstruida e infectada debe descomprimirse con CPRE urgente. Cada hora sin drenaje aumenta la mortalidad."},
    {"id": "GN-R2-05", "grade": "R2", "caso": "Hombre de 55 años, alcohólico, llega a las 3:00 a. m. con dolor epigástrico intenso que se va a la espalda, vómito repetido y fiebre baja. No puede estar acostado boca arriba.", "tema": "Pancreatitis aguda y crónica — pancreatitis aguda grave.", "t0": "FC 122 lpm, TA 108/66 mmHg, SatO2 95%, temperatura 38.2 °C, dolor epigástrico 9/10 irradiado a espalda, Glasgow 15. Abdomen con dolor epigástrico, sin irritación peritoneal franca. Amilasa 1,800 U/L, lipasa 2,400 U/L, leucocitos 16,000, calcio 7.6 mg/dL, hematocrito 48%.", "q": "¿Qué pides y qué haces en la primera hora?", "opts": ["Ayuno, líquidos intravenosos agresivos con monitoreo, analgesia, lactato, gasometría, calcio, función renal, tomografía solo si hay deterioro o duda diagnóstica, y aviso a terapia intensiva si hay falla orgánica", "Pedir tomografía con contraste de inmediato y dar antibiótico profiláctico", "Dar de comer para \"probar tolerancia\" y analgésico oral"], "ans": 0, "t1Good": "Con 2 L de líquidos, FC 104 lpm, TA 118/72 mmHg, diuresis 40 mL/h, dolor 6/10, lactato 1.8 mmol/L; se estratifica la gravedad y se vigila.", "t1Bad": "FC 140 lpm, TA 84/52 mmHg, SatO2 89%, frecuencia respiratoria 28/min, diuresis 10 mL/h, calcio 6.9 mg/dL: falla orgánica, el contraste temprano no cambia el manejo y la alimentación empeora el dolor y el vómito.", "t2Good": "Pancreatitis grave identificada a tiempo, manejo en terapia intensiva si hay falla orgánica persistente, sin antibiótico innecesario; la necrosis, si aparece, se maneja de forma escalonada y tardía, no con cirugía precoz.", "t2Bad": "Choque, falla respiratoria y renal, necrosis infectada y muerte.", "answer": "Reanimación con líquidos y monitoreo estrecho, ayuno y analgesia; la tomografía temprana no se pide de rutina y el antibiótico profiláctico no está indicado.", "exp": "Dolor epigástrico irradiado a espalda con amilasa y lipasa tres veces por arriba de lo normal es pancreatitis aguda. El tratamiento inicial es líquidos, ayuno, analgesia y vigilancia de falla orgánica; la gravedad se define por la falla orgánica, no por la tomografía del primer día. El antibiótico profiláctico no previene la infección de la necrosis y la cirugía precoz en necrosis estéril empeora el desenlace."},
    {"id": "GN-R2-06", "grade": "R2", "caso": "Mujer de 33 años, 4 días después de una apendicectomía laparoscópica, llega a las 3:00 a. m. con fiebre, dolor en fosa iliaca derecha y diarrea. La herida del ombligo supura.", "tema": "Apendicitis aguda y abdomen agudo — absceso postapendicectomía.", "t0": "FC 116 lpm, TA 110/66 mmHg, SatO2 97%, temperatura 38.9 °C, dolor 7/10 en fosa iliaca derecha, Glasgow 15. Abdomen con dolor localizado, sin rigidez generalizada. Leucocitos 16,800, PCR muy elevada. Herida umbilical con secreción purulenta.", "q": "¿Qué pides y qué haces?", "opts": ["Tomografía de abdomen con contraste, hemocultivos, antibiótico de amplio espectro y drenaje percutáneo o quirúrgico de la colección según el tamaño y la localización", "Dar antibiótico oral y curación local y citarla en una semana", "Pedir solo radiografía y esperar"], "ans": 0, "t1Good": "La tomografía muestra colección de 6 cm en fosa iliaca derecha; se drena por vía percutánea; FC 100 lpm, TA 118/70 mmHg, temperatura 38.1 °C.", "t1Bad": "FC 134 lpm, TA 88/54 mmHg, temperatura 39.7 °C, dolor generalizado, Glasgow 14: la colección se rompe y hay peritonitis.", "t2Good": "Drenaje, antibiótico ajustado, la fiebre cede en 48 h y se evita reintervención mayor.", "t2Bad": "Peritonitis, reintervención de urgencia, sepsis y estancia prolongada.", "answer": "Tomografía, antibiótico y drenaje de la colección. La fiebre postapendicectomía con dolor localizado es absceso hasta demostrar lo contrario.", "exp": "Tras una apendicectomía, fiebre persistente con dolor localizado y leucocitosis es colección o absceso intraabdominal. La tomografía lo localiza y mide; las colecciones grandes y accesibles se drenan por vía percutánea y las complicadas van a quirófano. El antibiótico solo no drena un absceso."},
    {"id": "GN-R2-07", "grade": "R2", "caso": "Mujer de 78 años llega a las 3:00 a. m. con dolor intenso en la ingle derecha, vómito y distensión abdominal. Tiene una bolita dura y dolorosa en la ingle que no tenía ayer.", "tema": "Hernias de la pared abdominal — hernia femoral estrangulada.", "t0": "FC 120 lpm, TA 116/68 mmHg, SatO2 96%, temperatura 38.0 °C, dolor 8/10, Glasgow 15. Tumoración dura y dolorosa por debajo del ligamento inguinal derecho, no reductible, con piel enrojecida. Abdomen distendido, sin evacuaciones ni gases en 10 horas, lactato 2.8 mmol/L.", "q": "¿Qué haces?", "opts": ["Ayuno, líquidos, laboratorios y quirófano urgente por hernia femoral estrangulada, sin intentar reducción", "Intentar reducirla con presión en urgencias", "Dar analgésico y observar hasta la mañana"], "ans": 0, "t1Good": "En quirófano se encuentra asa congestiva viable; se repara la hernia femoral; FC 102 lpm, TA 120/72 mmHg, dolor 4/10.", "t1Bad": "FC 138 lpm, TA 84/50 mmHg, temperatura 39.3 °C, lactato 5.4 mmol/L, abdomen rígido: necrosis intestinal y perforación.", "t2Good": "Reparación sin resección, recuperación sin complicaciones mayores.", "t2Bad": "Resección intestinal, sepsis, estancia en terapia intensiva y alta mortalidad en una paciente de 78 años.", "answer": "Quirófano urgente. La hernia femoral se estrangula con más facilidad que la inguinal por su anillo rígido y estrecho.", "exp": "La hernia femoral es más frecuente en mujeres mayores, tiene un cuello estrecho y se estrangula con facilidad. Tumoración dolorosa y no reductible por debajo del ligamento inguinal con obstrucción es estrangulación hasta demostrar lo contrario. No se reduce a la fuerza: el intestino puede estar necrosado."},
    {"id": "GN-R2-08", "grade": "R2", "caso": "Hombre de 71 años con fibrilación auricular sin anticoagular llega a las 3:00 a. m. con dolor abdominal súbito, intenso y desproporcionado a la exploración: el abdomen duele mucho pero casi no hay defensa. Tiene antecedente de infarto.", "tema": "Obstrucción intestinal, vólvulo e isquemia intestinal — isquemia mesentérica aguda embólica.", "t0": "FC 128 lpm (irregular), TA 104/62 mmHg, SatO2 95%, temperatura 37.6 °C, dolor abdominal 10/10, Glasgow 15. Abdomen blando, con dolor difuso, sin rigidez ni rebote. Lactato 3.8 mmol/L, leucocitos 15,000, dolor fuera de proporción con los hallazgos físicos.", "q": "¿Qué pides y qué haces?", "opts": ["Angiotomografía de abdomen urgente, ayuno, líquidos, anticoagulación tras descartar sangrado y aviso urgente a cirugía y vascular, sin esperar a que aparezca peritonitis", "Dar analgésico y esperar a que el abdomen se ponga rígido para operar", "Pedir solo radiografía de abdomen y dar laxante"], "ans": 0, "t1Good": "La angiotomografía muestra émbolo en la arteria mesentérica superior; se inicia anticoagulación y revascularización o cirugía según el caso; FC 112 lpm, TA 112/68 mmHg, lactato 2.6 mmol/L.", "t1Bad": "FC 146 lpm, TA 80/48 mmHg, temperatura 38.9 °C, lactato 7.2 mmol/L, abdomen rígido con rebote generalizado, Glasgow 13: intestino necrosado en gran extensión.", "t2Good": "Revascularización oportuna con resección limitada del segmento necrosado, sobrevive.", "t2Bad": "Necrosis masiva de intestino delgado, síndrome de intestino corto o muerte. Cuando aparece la peritonitis, ya es tarde para salvar intestino.", "answer": "Angiotomografía urgente y manejo inmediato. El dolor fuera de proporción con la exploración en un paciente con fibrilación auricular es isquemia mesentérica hasta demostrar lo contrario.", "exp": "La isquemia mesentérica embólica da dolor súbito e intenso con abdomen blando al inicio: el intestino duele por isquemia, no por peritonitis, hasta que se necrosa. El lactato elevado y la fibrilación auricular sin anticoagular son las pistas. La angiotomografía es el estudio de elección y el tiempo es intestino: esperar a la rigidez es esperar a la necrosis."},
    {"id": "GN-R2-09", "grade": "R2", "caso": "Mujer de 66 años con diverticulosis conocida llega a las 3:00 a. m. con dolor en fosa iliaca izquierda, fiebre y vómito. No ha evacuado en dos días.", "tema": "Enfermedad diverticular y patología benigna de colon — diverticulitis aguda complicada.", "t0": "FC 114 lpm, TA 118/70 mmHg, SatO2 97%, temperatura 38.7 °C, dolor 8/10 en fosa iliaca izquierda, Glasgow 15. Dolor a la palpación con defensa localizada en fosa iliaca izquierda, sin rigidez generalizada. Leucocitos 16,200, PCR elevada.", "q": "¿Qué pides y qué decides?", "opts": ["Tomografía de abdomen con contraste, ayuno, líquidos, antibiótico y estratificación (Hinchey) para decidir manejo conservador, drenaje percutáneo o cirugía", "Dar antibiótico oral y enviarla a casa", "Pedir colonoscopia urgente esta noche"], "ans": 0, "t1Good": "La tomografía muestra diverticulitis con absceso de 4 cm; se drena por vía percutánea y se da antibiótico; FC 100 lpm, TA 122/74 mmHg, temperatura 38.0 °C.", "t1Bad": "FC 136 lpm, TA 86/52 mmHg, temperatura 39.6 °C, abdomen rígido y generalizado: perforación libre con peritonitis fecal; la colonoscopia en diverticulitis aguda perfora.", "t2Good": "Drenaje del absceso, antibiótico, cirugía electiva posterior si está indicada, sin estoma de urgencia.", "t2Bad": "Cirugía de urgencia con resección y colostomía (Hartmann), sepsis y estancia prolongada.", "answer": "Tomografía con contraste, ayuno, antibiótico y manejo según la clasificación de la complicación. La colonoscopia está contraindicada en la fase aguda.", "exp": "Dolor en fosa iliaca izquierda con fiebre y leucocitosis en paciente con diverticulosis es diverticulitis aguda. La tomografía confirma y clasifica: no complicada, absceso, perforación libre o fístula. El absceso se drena por vía percutánea; la perforación libre con peritonitis va a quirófano. La colonoscopia aguda aumenta el riesgo de perforación."},
    {"id": "GN-R2-10", "grade": "R2", "caso": "Hombre de 59 años con cáncer de colon conocido llega a las 3:00 a. m. con distensión abdominal marcada, vómito fecaloide y dolor tipo cólico. No evacua ni saca gases desde hace tres días.", "tema": "Cáncer de colon — obstrucción intestinal maligna.", "t0": "FC 112 lpm, TA 116/70 mmHg, SatO2 96%, temperatura 37.8 °C, dolor cólico 8/10, Glasgow 15. Abdomen muy distendido, timpánico, ruidos intestinales de lucha. Radiografía: niveles hidroaéreos y colon distendido. Creatinina 1.6 mg/dL, potasio 3.1 mEq/L, cloro bajo.", "q": "¿Qué pides y qué haces?", "opts": ["Ayuno, sonda nasogástrica, líquidos, corregir electrolitos y función renal, tomografía con contraste y valoración urgente para cirugía o stent según la localización y el estado", "Dar laxante fuerte y esperar a que evacue", "Dar de comer y analgésico y observar"], "ans": 0, "t1Good": "Se descomprime con sonda, se corrige el potasio a 3.8 mEq/L, FC 100 lpm, TA 122/74 mmHg, diuresis 40 mL/h; la tomografía muestra tumor en colon izquierdo con obstrucción completa, sin perforación.", "t1Bad": "FC 136 lpm, TA 88/54 mmHg, temperatura 39.0 °C, dolor continuo, abdomen rígido, lactato 4.8 mmol/L: perforación del colon distendido proximal al tumor (perforación diastásica del ciego).", "t2Good": "Cirugía de urgencia con resección y estoma o stent como puente según el caso, sobrevive.", "t2Bad": "Perforación, peritonitis fecal, choque séptico y muerte.", "answer": "Descompresión, reposición y corrección de electrolitos, tomografía y manejo urgente de la obstrucción maligna. El laxante en obstrucción completa no ayuda y la alimentación empeora la distensión.", "exp": "Obstrucción completa por cáncer de colon: distensión, vómito, ausencia de evacuaciones y gases, niveles hidroaéreos. El ciego, por la ley de Laplace, es el que más se distiende y el que se perfora primero cuando el diámetro crece. Se descomprime, se corrigen electrolitos y función renal, se define la localización con tomografía y se resuelve la obstrucción con cirugía o stent según el caso."},
    {"id": "GN-R3-01", "grade": "R3", "caso": "Mujer de 58 años con cáncer de mama en quimioterapia llega a las 3:00 a. m. con fiebre de 39 °C, escalofríos y malestar general. Su última quimioterapia fue hace 9 días.", "tema": "Cirugía oncológica: principios, estadificación y manejo multidisciplinario — neutropenia febril.", "t0": "FC 124 lpm, TA 98/60 mmHg, SatO2 95%, temperatura 39.1 °C, dolor 3/10, Glasgow 15. Sin foco evidente: garganta, pulmón, orina y catéter sin datos claros. Neutrófilos absolutos 320/mm³.", "q": "¿Qué haces en la primera hora?", "opts": ["Hemocultivos, urocultivo, radiografía de tórax, lactato, antibiótico de amplio espectro antipseudomona de inmediato y aislamiento, sin esperar los cultivos", "Dar paracetamol y esperar a la mañana a ver si baja la fiebre", "Dar antibiótico oral y enviarla a casa"], "ans": 0, "t1Good": "Se inicia antibiótico, FC 110 lpm, TA 108/66 mmHg, temperatura 38.4 °C; se busca el foco y se vigila en hospitalización.", "t1Bad": "FC 142 lpm, TA 80/48 mmHg, SatO2 90%, temperatura 39.8 °C, Glasgow 13, lactato 4.0 mmol/L: choque séptico en neutropenia.", "t2Good": "Antibiótico oportuno, recuperación de neutrófilos con factor estimulante si está indicado, sobrevive sin falla orgánica.", "t2Bad": "Sepsis grave, falla multiorgánica y muerte. En neutropenia febril no hay tiempo para \"ver cómo evoluciona\".", "answer": "Cultivos y antibiótico de amplio espectro en la primera hora, hospitalización y vigilancia estrecha. La fiebre en neutropenia es una emergencia.", "exp": "Fiebre mayor de 38.3 °C con neutrófilos menores de 500/mm³ es neutropenia febril: una emergencia oncológica. El paciente no tiene defensas para contener la infección y puede no tener foco evidente. El antibiótico antipseudomona se da en la primera hora, tras los cultivos, sin esperar resultados. El paracetamol tapa la fiebre y retrasa el tratamiento."},
    {"id": "GN-R3-02", "grade": "R3", "caso": "Mujer de 46 años, 8 horas después de una mastectomía con reconstrucción, llega la enfermera a las 3:00 a. m.: el colgajo está frío, pálido, con el drenaje lleno de sangre y la paciente con dolor creciente en el tórax.", "tema": "Cáncer de mama — hematoma postmastectomía y compromiso del colgajo.", "t0": "FC 118 lpm, TA 104/64 mmHg, SatO2 96%, temperatura 36.9 °C, dolor 7/10, Glasgow 15. Colgajo frío y pálido, con llenado capilar mayor de 4 s; drenaje con 300 mL de sangre en 2 h; Hb cayó de 12.5 a 9.8 g/dL.", "q": "¿Qué haces?", "opts": ["Avisar de inmediato al cirujano, reponer volumen, pedir Hb y coagulación, y quirófano urgente para evacuar el hematoma y revisar la vascularidad del colgajo", "Poner una compresa fría y esperar a la visita", "Dar analgésico y transfundir sin avisar a nadie"], "ans": 0, "t1Good": "En quirófano se evacua el hematoma, se controla el sangrado y el colgajo recupera color y temperatura; FC 102 lpm, TA 116/70 mmHg.", "t1Bad": "FC 136 lpm, TA 86/52 mmHg, colgajo cianótico y frío, Hb 7.9 g/dL: el hematoma comprime el pedículo vascular y el colgajo se necrosa.", "t2Good": "Colgajo viable, sin necrosis, recuperación sin reintervenciones mayores.", "t2Bad": "Necrosis del colgajo, pérdida de la reconstrucción, infección y múltiples cirugías.", "answer": "Quirófano urgente para evacuar el hematoma y revisar el colgajo. El hematoma que comprime el pedículo mata el colgajo en horas.", "exp": "Tras una mastectomía con reconstrucción, un colgajo frío y pálido con drenaje sanguinolento abundante y caída de Hb es hematoma con compromiso vascular del colgajo. El tratamiento es evacuar el hematoma y revisar la anastomosis o el pedículo en quirófano, de inmediato. Esperar a la mañana es perder el colgajo."},
    {"id": "GN-R3-03", "grade": "R3", "caso": "Hombre de 64 años, día 6 postoperatorio de colectomía con anastomosis por cáncer de colon, llega a las 3:00 a. m. con fiebre, taquicardia y dolor abdominal. El drenaje huele mal y sale líquido turbio.", "tema": "Cáncer colorrectal — fuga de anastomosis.", "t0": "FC 126 lpm, TA 100/62 mmHg, SatO2 94%, temperatura 39.0 °C, dolor 7/10, Glasgow 15. Drenaje abdominal con líquido turbio y fétido, 200 mL en 6 h. Abdomen con dolor en el sitio quirúrgico, sin rigidez generalizada. Leucocitos 17,500, PCR muy elevada, lactato 2.6 mmol/L.", "q": "¿Qué pides y qué haces?", "opts": ["Tomografía con contraste rectal o hidrosoluble, hemocultivos, lactato, antibiótico de amplio espectro, ayuno, líquidos y aviso urgente para drenaje o reintervención según la gravedad", "Dar paracetamol y cambiar la curación", "Retirar el drenaje porque \"ya no sirve\""], "ans": 0, "t1Good": "La tomografía muestra fuga de anastomosis con colección; se drena por vía percutánea o se reopera según el estado; FC 110 lpm, TA 110/68 mmHg, temperatura 38.3 °C.", "t1Bad": "FC 142 lpm, TA 82/50 mmHg, temperatura 39.8 °C, Glasgow 13, lactato 4.6 mmol/L, abdomen rígido: peritonitis fecal por fuga no controlada.", "t2Good": "Control del foco, drenaje y antibiótico; la fuga se maneja sin resección mayor o con estoma de protección según el caso; sobrevive.", "t2Bad": "Peritonitis, reintervención de urgencia con resección y estoma, sepsis y muerte.", "answer": "Tomografía, antibiótico, ayuno y control del foco (drenaje o cirugía). El drenaje turbio y fétido en el postoperatorio de una anastomosis es fuga hasta demostrar lo contrario.", "exp": "Fiebre, taquicardia, leucocitosis y drenaje turbio y fétido tras una anastomosis colorrectal es fuga de anastomosis. La tomografía con contraste confirma la fuga y la colección. El tratamiento es ayuno, antibiótico y control del foco: drenaje percutáneo si el paciente está estable y la colección es drenable, o cirugía si hay peritonitis o inestabilidad. Retirar el drenaje es quitar el testigo y el drenaje de la fuga."},
    {"id": "GN-R3-04", "grade": "R3", "caso": "Hombre de 67 años, día 4 postoperatorio de esofagectomía por cáncer de esófago, llega a las 3:00 a. m. con fiebre, taquicardia, dolor torácico y dificultad para respirar. El drenaje torácico sale turbio.", "tema": "Cáncer gástrico y de esófago — fuga de anastomosis esofágica y mediastinitis.", "t0": "FC 132 lpm, TA 96/60 mmHg, SatO2 90% con oxígeno, temperatura 39.2 °C, dolor torácico 8/10, Glasgow 15. Drenaje pleural con líquido turbio y restos alimentarios. Leucocitos 18,000, lactato 3.0 mmol/L, frecuencia respiratoria 28/min.", "q": "¿Qué pides y qué haces?", "opts": ["Tomografía de tórax con contraste oral hidrosoluble, hemocultivos, antibiótico de amplio espectro, ayuno, líquidos, drenaje pleural adecuado y aviso urgente a cirugía y terapia intensiva", "Dar analgésico y esperar a la mañana", "Dar de comer por la sonda para \"probar la anastomosis\""], "ans": 0, "t1Good": "La tomografía confirma fuga esofágica con colección mediastínica; se drena, se coloca stent o se reopera según el caso; FC 116 lpm, TA 106/66 mmHg, SatO2 94%.", "t1Bad": "FC 148 lpm, TA 78/46 mmHg, SatO2 85%, Glasgow 12, lactato 5.2 mmol/L: mediastinitis y choque séptico; la alimentación por la anastomosis fugada contamina el mediastino.", "t2Good": "Control de la fuga, drenaje y soporte en terapia intensiva; sobrevive con estancia larga.", "t2Bad": "Mediastinitis fulminante, empiema, falla multiorgánica y muerte. La fuga esofágica es la complicación que más mata tras una esofagectomía.", "answer": "Tomografía con contraste hidrosoluble, antibiótico, ayuno y drenaje y control urgente de la fuga. Nunca alimentar por una anastomosis que se sospecha fugada.", "exp": "Tras una esofagectomía, fiebre, taquicardia, dolor torácico, disnea y drenaje turbio con restos alimentarios es fuga de anastomosis esofágica hasta demostrar lo contrario. El contraste hidrosoluble localiza la fuga; el tratamiento es ayuno, antibiótico, drenaje de las colecciones y cierre o derivación de la fuga. La alimentación oral o por sonda agrava la contaminación mediastínica."},
    {"id": "GN-R3-05", "grade": "R3", "caso": "Mujer de 59 años, día 3 postoperatorio de hepatectomía derecha por metástasis de colon, llega a las 3:00 a. m. con fiebre, dolor en hipocondrio derecho y el drenaje con líquido amarillo-verdoso abundante.", "tema": "Hígado, vía biliar y páncreas (HPB) — fuga biliar posthepatectomía.", "t0": "FC 118 lpm, TA 108/64 mmHg, SatO2 96%, temperatura 38.8 °C, dolor 6/10, Glasgow 15. Drenaje con 400 mL de líquido bilioso en 12 h. Bilirrubina total 2.4 mg/dL, leucocitos 15,500, INR 1.4.", "q": "¿Qué pides y qué haces?", "opts": ["Medir bilirrubina en el drenaje, laboratorios, hemocultivos, antibiótico, ayuno relativo, mantener el drenaje permeable y valoración para CPRE con stent o drenaje percutáneo si la fuga persiste o hay colección", "Retirar el drenaje para que \"cierre solo\"", "Dar antibiótico oral y esperar"], "ans": 0, "t1Good": "La bilirrubina en el drenaje es tres veces la sérica: fuga biliar confirmada; se mantiene el drenaje, FC 104 lpm, TA 116/70 mmHg, temperatura 38.2 °C; la CPRE con stent reduce la presión y la fuga disminuye.", "t1Bad": "FC 136 lpm, TA 86/52 mmHg, temperatura 39.6 °C, dolor generalizado, lactato 4.0 mmol/L: biloma infectado y peritonitis biliar.", "t2Good": "La fuga se controla con drenaje y descompresión endoscópica, sin reintervención mayor; sobrevive.", "t2Bad": "Colección biliar infectada, sepsis, reintervención y estancia prolongada.", "answer": "Confirmar la fuga con bilirrubina en el drenaje, mantener el drenaje, antibiótico y descompresión biliar endoscópica si persiste. No retirar el drenaje.", "exp": "Líquido bilioso abundante por el drenaje tras una hepatectomía es fuga biliar. Se confirma cuando la bilirrubina del drenaje es mayor de tres veces la sérica. El drenaje es el tratamiento y el testigo: retirarlo deja el bilis libre en el abdomen. La CPRE con esfinterotomía y stent baja la presión en la vía biliar y favorece el cierre de la fuga."},
    {"id": "GN-R3-06", "grade": "R3", "caso": "Mujer de 52 años, 12 horas después de una tiroidectomía total por cáncer de tiroides, llega a las 3:00 a. m. con hormigueo en manos y alrededor de la boca, calambres y ansiedad. Está irritable y con el signo de Chvostek positivo.", "tema": "Cirugía endocrina: tiroides, paratiroides y suprarrenal — hipocalcemia post tiroidectomía.", "t0": "FC 108 lpm, TA 126/78 mmHg, SatO2 97%, temperatura 36.9 °C, dolor 4/10, Glasgow 15. Parestesias peribucales y en manos, calambres, Chvostek positivo, Trousseau positivo al inflar el baumanómetro. Calcio total 7.0 mg/dL, calcio iónico bajo, PTH baja.", "q": "¿Qué haces?", "opts": ["Gluconato de calcio intravenoso lento con monitoreo cardiaco, magnesio, calcitriol y calcio oral, y monitoreo estrecho de calcio y del ECG", "Dar solo calcio oral y esperar a la mañana", "Dar un sedante para la ansiedad y no pedir calcio"], "ans": 0, "t1Good": "Tras el gluconato de calcio, las parestesias disminuyen, FC 96 lpm, TA 120/74 mmHg, calcio 7.8 mg/dL, sin arritmia.", "t1Bad": "Calambres generalizados, laringoespasmo, FC 130 lpm, SatO2 89%, QT prolongado en el ECG y riesgo de convulsión y paro: la hipocalcemia grave no espera al calcio oral.", "t2Good": "Calcio estabilizado con calcio oral y calcitriol, PTH en recuperación o hipoparatiroidismo transitorio manejado; alta con suplementos y control.", "t2Bad": "Tetania grave, laringoespasmo, arritmia y paro cardiaco.", "answer": "Gluconato de calcio intravenoso lento con monitoreo cardiaco ante hipocalcemia sintomática, más magnesio, calcitriol y calcio oral.", "exp": "Parestesias peribucales, calambres, Chvostek y Trousseau positivos tras una tiroidectomía total son hipocalcemia por hipoparatiroidismo transitorio (lesión o devascularización de las paratiroides). La hipocalcemia sintomática se trata con calcio intravenoso lento y vigilado; el calcio oral solo tarda demasiado. Hay que corregir el magnesio, porque sin magnesio el calcio no se corrige."},
    {"id": "GN-R3-07", "grade": "R3", "caso": "Hombre de 60 años, día 5 postoperatorio de lobectomía por cáncer de pulmón, llega a las 3:00 a. m. con fiebre, dolor torácico y el drenaje pleural con líquido turbio y fétido. Respira con dificultad.", "tema": "Cirugía de tórax, pleura y mediastino — empiema postoracotomía.", "t0": "FC 124 lpm, TA 102/62 mmHg, SatO2 91% con oxígeno, temperatura 39.0 °C, dolor torácico 7/10, Glasgow 15. Drenaje pleural con líquido turbio y fétido, 250 mL en 12 h. Leucocitos 17,000, frecuencia respiratoria 26/min.", "q": "¿Qué pides y qué haces?", "opts": ["Cultivo del líquido pleural, pH y bioquímica pleural, hemocultivos, antibiótico de amplio espectro, asegurar el drenaje pleural permeable y valoración para drenaje adicional, fibrinolíticos o cirugía (decorticación) según la fase", "Retirar la sonda pleural porque \"ya lleva muchos días\"", "Dar antibiótico oral y esperar"], "ans": 0, "t1Good": "El líquido pleural es pus con pH bajo; se mantiene y se optimiza el drenaje, FC 108 lpm, TA 112/68 mmHg, SatO2 94%, temperatura 38.3 °C.", "t1Bad": "FC 142 lpm, TA 84/50 mmHg, SatO2 87%, temperatura 39.8 °C, Glasgow 13: el empiema se organiza, el pulmón queda atrapado y hay sepsis.", "t2Good": "Drenaje adecuado, antibiótico y, si es necesario, decorticación; el pulmón reexpande y sobrevive.", "t2Bad": "Empiema organizado, pulmón atrapado, fístula broncopleural y sepsis.", "answer": "Estudio del líquido pleural, antibiótico y drenaje pleural adecuado. El empiema no se cura con antibiótico solo: hay que drenar el pus.", "exp": "Tras una toracotomía, fiebre con líquido pleural turbio y fétido es empiema hasta demostrar lo contrario. El líquido pleural con pus, pH bajo y glucosa baja confirma la infección del espacio pleural. El tratamiento es drenaje más antibiótico; en la fase organizada se necesita cirugía para liberar el pulmón atrapado. Retirar la sonda es quitar el drenaje del pus."},
    {"id": "GN-R3-08", "grade": "R3", "caso": "Hombre de 72 años con aneurisma de aorta abdominal conocido llega a las 3:00 a. m. con dolor abdominal y lumbar súbito, intenso, y una masa abdominal pulsátil. Está pálido y sudoroso.", "tema": "Cirugía vascular: aorta, carótida y enfermedad arterial periférica — ruptura de aneurisma de aorta abdominal.", "t0": "FC 132 lpm, TA 82/52 mmHg, SatO2 95%, temperatura 36.2 °C, dolor abdominal y lumbar 10/10, Glasgow 15. Masa abdominal pulsátil y dolorosa, piel fría y moteada, diuresis escasa, Hb 9.0 g/dL.", "q": "¿Qué haces?", "opts": ["Dos vías gruesas, sangre cruzada, líquidos con hipotensión permisiva, aviso inmediato a cirugía vascular y quirófano urgente, con tomografía solo si el paciente se estabiliza y no retrasa la cirugía", "Pedir tomografía con contraste y esperar el reporte en urgencias", "Dar analgésico y antihipertensivo fuerte para bajar la TA a lo normal"], "ans": 0, "t1Good": "Se activa el protocolo de ruptura, FC 120 lpm, TA 90/58 mmHg, se llega a quirófano con sangre disponible; se controla el sangrado.", "t1Bad": "FC 150 lpm, TA 60/40 mmHg, Glasgow 12, paro inminente en el tomógrafo o en urgencias; subir la TA con líquidos en exceso o bajarla de más rompe el coágulo que taponaba la ruptura.", "t2Good": "Reparación quirúrgica o endovascular de urgencia, sobrevive con estancia en terapia intensiva.", "t2Bad": "Muerte por choque hemorrágico antes o durante el traslado a imagen.", "answer": "Reanimación con hipotensión permisiva, sangre disponible y quirófano urgente. La ruptura de aneurisma es un diagnóstico clínico y quirúrgico, no de tomografía.", "exp": "Dolor abdominal y lumbar súbito con masa pulsátil e hipotensión en un paciente con aneurisma conocido es ruptura de aneurisma de aorta abdominal hasta demostrar lo contrario. La tomografía retrasa y mata si el paciente está inestable. Se mantiene una TA baja permisiva (alrededor de 80-90 mmHg sistólica) para no desalojar el coágulo, se repone sangre y se opera de inmediato."},
    {"id": "GN-R3-09", "grade": "R3", "caso": "Hombre de 38 años con trauma abdominal grave, operado hace 12 horas con cirugía de control de daños y abdomen abierto, llega a las 3:00 a. m. en terapia intensiva con sangrado por el abdomen abierto, frío y con acidosis.", "tema": "Trauma complejo y cirugía de control de daños — tríada letal (hipotermia, acidosis y coagulopatía).", "t0": "FC 138 lpm, TA 84/52 mmHg, SatO2 92%, temperatura 34.8 °C, dolor no valorable (sedado), Glasgow 8 (sedado e intubado). Sangrado difuso por el abdomen abierto, pH 7.18, lactato 5.5 mmol/L, plaquetas 70,000, INR 1.9, fibrinógeno bajo, diuresis 15 mL/h.", "q": "¿Qué haces?", "opts": ["Recalentamiento activo, transfusión balanceada, corrección de calcio y fibrinógeno, líquidos y control del sangrado con empaquetamiento si es necesario, sin intentar una cirugía definitiva larga esta noche", "Llevarlo a quirófano para una cirugía definitiva de 6 horas", "Dar solo cristaloides fríos y esperar a que se caliente solo"], "ans": 0, "t1Good": "Temperatura 35.8 °C, pH 7.28, FC 120 lpm, TA 98/60 mmHg, el sangrado disminuye, lactato 3.8 mmol/L.", "t1Bad": "Temperatura 34.2 °C, pH 7.10, FC 152 lpm, TA 66/40 mmHg, sangrado incoercible, paro cardiaco: la cirugía larga y el frío agravan la tríada letal.", "t2Good": "Se corrige la tríada letal en terapia intensiva y se planea la cirugía definitiva en 24-48 h, cuando el paciente esté caliente, sin acidosis y con coagulación corregida; sobrevive.", "t2Bad": "Muerte por coagulopatía y choque hemorrágico.", "answer": "Corregir la tríada letal en terapia intensiva: calentar, transfundir balanceado, corregir fibrinógeno y calcio, y control temporal del sangrado. La cirugía definitiva espera.", "exp": "En trauma grave, hipotermia, acidosis y coagulopatía se potencian entre sí y forman la tríada letal. La cirugía de control de daños busca solo detener el sangrado y la contaminación, no reparar todo. Intentar una cirugía definitiva larga en un paciente frío, acidótico y coagulopático lo mata. Primero se corrige la fisiología y luego se opera lo definitivo."},
    {"id": "GN-R3-10", "grade": "R3", "caso": "Hombre de 57 años, día 7 postoperatorio de laparotomía por peritonitis, con abdomen abierto y sistema de presión negativa, llega a las 3:00 a. m. con fiebre, taquicardia y el abdomen muy tenso; la presión intraabdominal está alta y la diuresis cayó.", "tema": "Sepsis abdominal, abdomen abierto y paciente quirúrgico crítico — síndrome compartimental abdominal.", "t0": "FC 132 lpm, TA 96/58 mmHg, SatO2 90% con oxígeno, temperatura 39.1 °C, dolor 6/10, Glasgow 14. Abdomen tenso y distendido, presión intraabdominal 26 mmHg, diuresis 10 mL/h, frecuencia respiratoria 28/min, presión de la vía aérea alta, lactato 4.2 mmol/L, leucocitos 19,000.", "q": "¿Qué haces?", "opts": ["Medir la presión intraabdominal, optimizar líquidos sin sobrecargar, descompresión nasogástrica y rectal, sedación y relajación si es necesario, y descompresión quirúrgica urgente del abdomen si hay falla orgánica", "Dar 3 L de cristaloide a chorro para subir la TA", "Dar diurético fuerte y esperar"], "ans": 0, "t1Good": "Con descompresión y manejo, la presión intraabdominal baja a 18 mmHg, FC 116 lpm, TA 106/64 mmHg, diuresis 30 mL/h, SatO2 94%.", "t1Bad": "Presión intraabdominal 32 mmHg, FC 148 lpm, TA 76/46 mmHg, SatO2 84%, diuresis 0 mL/h, Glasgow 11: falla renal y respiratoria por compresión.", "t2Good": "Descompresión quirúrgica oportuna, la diuresis y la ventilación mejoran, sobrevive con abdomen abierto manejado.", "t2Bad": "Falla multiorgánica por hipertensión intraabdominal y muerte.", "answer": "Reconocer el síndrome compartimental abdominal y descomprimir el abdomen. Más líquidos a chorro empeoran la presión intraabdominal.", "exp": "Presión intraabdominal mayor de 20 mmHg con falla orgánica (oliguria, hipoxia, hipotensión) es síndrome compartimental abdominal. El abdomen tenso comprime riñones, pulmones y vasos. El tratamiento es bajar la presión: descompresión gastrointestinal, sedación, evitar sobrecarga de líquidos y, si hay falla orgánica, descompresión quirúrgica urgente. Dar litros de líquido a chorro aumenta el edema intestinal y la presión."},
    {"id": "GN-R4-01", "grade": "R4", "caso": "Hombre de 61 años, día 2 postoperatorio de hepatectomía mayor por colangiocarcinoma, llega a las 3:00 a. m. con sangrado por el drenaje, ictericia que aumenta y confusión leve.", "tema": "Cirugía hepatobiliar avanzada — hemorragia posthepatectomía e insuficiencia hepática.", "t0": "FC 126 lpm, TA 94/58 mmHg, SatO2 94%, temperatura 36.6 °C, dolor 5/10, Glasgow 14 (confuso leve). Drenaje con 350 mL de sangre en 3 h, bilirrubina total 4.8 mg/dL, INR 1.8, lactato 3.2 mmol/L, diuresis 20 mL/h, Hb cayó de 11.0 a 8.6 g/dL.", "q": "¿Qué pides y qué haces?", "opts": ["Transfusión balanceada, corrección de coagulación, vitamina K, lactato, gasometría, función hepática, tomografía o angiografía según estabilidad y aviso urgente a HPB y radiología intervencionista", "Dar solo cristaloide y esperar a la mañana", "Dar vasopresor y no transfundir"], "ans": 0, "t1Good": "La angiografía muestra sangrado de una rama arterial que se emboliza; FC 110 lpm, TA 106/64 mmHg, Glasgow 15, lactato 2.2 mmol/L.", "t1Bad": "FC 144 lpm, TA 76/46 mmHg, Glasgow 11, bilirrubina 6.5 mg/dL, INR 2.4, lactato 5.8 mmol/L: choque hemorrágico con insuficiencia hepática posthepatectomía.", "t2Good": "Hemostasia por embolización o cirugía, soporte hepático, sobrevive con recuperación lenta del hígado remanente.", "t2Bad": "Falla hepática fulminante, coagulopatía incoercible y muerte.", "answer": "Transfusión balanceada, corrección de coagulación y control del sangrado por angiografía o cirugía. El hígado remanente no perdona la hipoperfusión ni la coagulopatía.", "exp": "Tras una hepatectomía mayor, sangrado con caída de Hb, INR elevado, bilirrubina en ascenso y confusión es hemorragia con insuficiencia hepática posthepatectomía. El hígado remanente pequeño es vulnerable a la hipoperfusión. Se transfunde balanceado, se corrige la coagulación y se controla el sangrado, de preferencia por embolización si el paciente lo permite, sin esperar a que la falla hepática sea irreversible."},
    {"id": "GN-R4-02", "grade": "R4", "caso": "Mujer de 58 años, día 5 postoperatorio de pancreatoduodenectomía (Whipple) por cáncer de páncreas, llega a las 3:00 a. m. con sangrado por el drenaje y por la sonda nasogástrica, taquicardia y dolor abdominal.", "tema": "Cirugía pancreática avanzada — hemorragia postpancreatectomía tardía.", "t0": "FC 130 lpm, TA 90/56 mmHg, SatO2 95%, temperatura 37.9 °C, dolor 7/10, Glasgow 15. Drenaje con sangre y líquido turbio, sonda nasogástrica con 400 mL de sangre, Hb cayó de 10.8 a 7.9 g/dL, amilasa en el drenaje muy elevada (fuga pancreática conocida), lactato 3.0 mmol/L.", "q": "¿Qué pides y qué haces?", "opts": ["Dos vías gruesas, transfusión balanceada, ayuno, inhibidor de bomba de protones, octreótido si está indicado, angiotomografía urgente y aviso a cirugía HPB y radiología intervencionista", "Retirar el drenaje y dar analgésico", "Dar solo cristaloide y esperar otra Hb"], "ans": 0, "t1Good": "La angiotomografía muestra sangrado de la arteria gastroduodenal erosionada por la fuga pancreática; se emboliza; FC 112 lpm, TA 104/64 mmHg, Hb 8.8 g/dL tras transfundir.", "t1Bad": "FC 148 lpm, TA 72/44 mmHg, Glasgow 12, Hb 6.2 g/dL, nueva hematemesis: choque hemorrágico por erosión arterial.", "t2Good": "Hemostasia por embolización, manejo de la fuga pancreática con drenaje, sobrevive con estancia larga.", "t2Bad": "Sangrado incoercible, reintervención de urgencia con alta mortalidad.", "answer": "Reanimación, transfusión y angiotomografía urgente para localizar y embolizar el sangrado. La fuga pancreática erosiona arterias: es la causa clásica de la hemorragia tardía tras un Whipple.", "exp": "La hemorragia tardía tras una pancreatoduodenectomía, días después de la cirugía y con fuga pancreática, suele deberse a erosión de una arteria (con frecuencia la gastroduodenal) por el jugo pancreático. No es un sangrado de la herida: es arterial y potencialmente mortal. La angiotomografía localiza el vaso y la embolización lo controla con menos riesgo que una reintervención inmediata en un abdomen hostil."},
    {"id": "GN-R4-03", "grade": "R4", "caso": "Mujer de 63 años con cáncer de ovario y carcinomatosis peritoneal, operada hace 10 días con citorreducción, llega a las 3:00 a. m. con distensión abdominal, vómito y dolor cólico. No evacua desde hace dos días.", "tema": "Cirugía oncológica avanzada y carcinomatosis peritoneal — obstrucción intestinal maligna post citorreducción.", "t0": "FC 114 lpm, TA 110/66 mmHg, SatO2 96%, temperatura 37.9 °C, dolor cólico 7/10, Glasgow 15. Abdomen distendido, con dolor difuso, sin rigidez franca. Tomografía previa: enfermedad peritoneal residual. Creatinina 1.5 mg/dL, potasio 3.2 mEq/L, albúmina 2.6 g/dL.", "q": "¿Qué pides y qué decides?", "opts": ["Ayuno, sonda nasogástrica, líquidos, corregir electrolitos y nutrición, tomografía con contraste y valoración multidisciplinaria (cirugía, oncología y cuidados paliativos) antes de decidir entre cirugía, stent o manejo conservador", "Operar de inmediato sin imagen ni corrección", "Dar laxante y alimentación normal"], "ans": 0, "t1Good": "Se descomprime, se corrige el potasio, FC 100 lpm, TA 118/70 mmHg, diuresis 35 mL/h; la tomografía muestra obstrucción en un solo nivel, sin perforación ni isquemia, y el equipo decide el mejor manejo según el estado general y el pronóstico.", "t1Bad": "FC 136 lpm, TA 86/52 mmHg, temperatura 39.2 °C, lactato 4.6 mmol/L, abdomen rígido: perforación con peritonitis en una paciente desnutrida y con enfermedad avanzada.", "t2Good": "Manejo individualizado — cirugía selectiva, stent o manejo conservador con descompresión — con la paciente y la familia informadas del pronóstico; sobrevive el episodio sin una cirugía fútil.", "t2Bad": "Cirugía de urgencia sin beneficio, sepsis, estancia en terapia intensiva y muerte sin mejorar el pronóstico oncológico.", "answer": "Descompresión, corrección y valoración multidisciplinaria antes de decidir. En carcinomatosis, operar sin pensar el pronóstico es tan malo como no operar una obstrucción tratable.", "exp": "La obstrucción intestinal en carcinomatosis peritoneal no siempre es quirúrgica: puede haber un solo nivel obstruido y tratable, o enfermedad difusa sin solución quirúrgica. Se descomprime, se corrige y se decide con cirugía, oncología y cuidados paliativos, con la paciente informada. La cirugía en una paciente desnutrida, con enfermedad avanzada y sin beneficio esperado, aumenta el sufrimiento sin cambiar el pronóstico."},
    {"id": "GN-R4-04", "grade": "R4", "caso": "Hombre de 66 años, día 7 postoperatorio de resección anterior baja por cáncer de recto con anastomosis coloanal, llega a las 3:00 a. m. con fiebre, dolor pélvico intenso, secreción purulenta por el ano y taquicardia.", "tema": "Cirugía colorrectal avanzada — fuga de anastomosis baja y sepsis pélvica.", "t0": "FC 128 lpm, TA 98/60 mmHg, SatO2 94%, temperatura 39.1 °C, dolor pélvico 8/10, Glasgow 15. Secreción purulenta y fétida por el ano, dolor a la palpación pélvica, leucocitos 18,500, PCR muy elevada, lactato 3.1 mmol/L, creatinina 1.7 mg/dL.", "q": "¿Qué pides y qué haces?", "opts": ["Tomografía de pelvis con contraste rectal, hemocultivos, antibiótico de amplio espectro, ayuno, líquidos y valoración urgente para drenaje transanal o quirúrgico y posible estoma de derivación", "Dar antibiótico oral y esperar a la visita", "Hacer tacto rectal brusco e irrigar la anastomosis"], "ans": 0, "t1Good": "La tomografía muestra colección pélvica por fuga de anastomosis; se drena por vía transanal o quirúrgica y se deriva con estoma si es necesario; FC 110 lpm, TA 108/66 mmHg, temperatura 38.4 °C.", "t1Bad": "FC 144 lpm, TA 80/48 mmHg, temperatura 39.9 °C, Glasgow 13, lactato 5.0 mmol/L, dolor abdominal generalizado: peritonitis pélvica y choque séptico; la irrigación a presión agranda la fuga.", "t2Good": "Control del foco pélvico, estoma de derivación si está indicado, sobrevive y la anastomosis se revisa después.", "t2Bad": "Sepsis pélvica no controlada, reintervención mayor, pérdida de la anastomosis y estoma definitivo.", "answer": "Tomografía de pelvis, antibiótico y drenaje de la colección pélvica con derivación si es necesario. La fuga baja se drena y se deriva; no se irriga a presión.", "exp": "Tras una anastomosis coloanal, fiebre con dolor pélvico y secreción purulenta por el ano es fuga de anastomosis con sepsis pélvica. La tomografía de pelvis con contraste rectal confirma la fuga y la colección. El tratamiento es antibiótico, drenaje de la colección y derivación fecal para que la anastomosis descanse. Una anastomosis baja fugada no se salva con antibiótico solo."},
    {"id": "GN-R4-05", "grade": "R4", "caso": "Hombre de 70 años, día 6 postoperatorio de esofagectomía tipo Ivor Lewis por cáncer de esófago, llega a las 3:00 a. m. con fiebre, dolor torácico, taquicardia y el drenaje torácico con líquido bilioso.", "tema": "Cirugía esofagogástrica avanzada — fuga de anastomosis esofagogástrica intratorácica.", "t0": "FC 134 lpm, TA 96/60 mmHg, SatO2 90% con oxígeno, temperatura 39.3 °C, dolor torácico 8/10, Glasgow 15. Drenaje torácico con líquido bilioso y turbio, 300 mL en 12 h. Leucocitos 19,000, lactato 3.4 mmol/L, frecuencia respiratoria 28/min.", "q": "¿Qué pides y qué haces?", "opts": ["Tomografía de tórax con contraste oral hidrosoluble, hemocultivos, antibiótico de amplio espectro, ayuno, nutrición por yeyunostomía si la hay, drenaje torácico adecuado, y valoración urgente para stent endoscópico o cirugía según la gravedad", "Dar de comer por vía oral para probar la anastomosis", "Retirar el drenaje torácico"], "ans": 0, "t1Good": "La tomografía confirma fuga intratorácica con colección; se coloca stent cubierto o se reopera según el caso; FC 116 lpm, TA 106/66 mmHg, SatO2 94%.", "t1Bad": "FC 150 lpm, TA 76/46 mmHg, SatO2 84%, Glasgow 12, lactato 5.6 mmol/L: mediastinitis, empiema y choque séptico.", "t2Good": "Control de la fuga con stent o cirugía, drenaje y soporte en terapia intensiva; sobrevive con estancia larga.", "t2Bad": "Mediastinitis fulminante y muerte. La fuga intratorácica es más grave que la cervical porque contamina el tórax.", "answer": "Tomografía con contraste hidrosoluble, antibiótico, ayuno y control de la fuga con stent o cirugía. Nunca alimentar por vía oral ni retirar el drenaje.", "exp": "La fuga de la anastomosis esofagogástrica intratorácica contamina el mediastino y la pleura con contenido gástrico y biliar. Se confirma con tomografía y contraste hidrosoluble, se mantiene el drenaje torácico, se ayuna y se controla la fuga con stent endoscópico cubierto o con cirugía según el tamaño, la localización y la estabilidad del paciente. La nutrición se da por yeyunostomía, no por boca."},
    {"id": "GN-R4-06", "grade": "R4", "caso": "Hombre de 45 años con trauma toracoabdominal grave, operado hace 24 horas, en terapia intensiva, llega a las 3:00 a. m. con hipotensión refractaria, taquicardia, fiebre y lactato en ascenso pese a líquidos y antibiótico.", "tema": "Trauma complejo, abdomen abierto y cuidados críticos — choque séptico refractario en el paciente crítico quirúrgico.", "t0": "FC 136 lpm, TA 82/50 mmHg, SatO2 91% con ventilación mecánica, temperatura 39.4 °C, Glasgow 9 (sedado e intubado). Lactato 5.2 mmol/L, leucocitos 20,000, creatinina 2.1 mg/dL, diuresis 15 mL/h, plaquetas 85,000. Abdomen abierto con secreción turbia.", "q": "¿Qué haces en la primera hora?", "opts": ["Hemocultivos, lactato, gasometría, revisión de todos los focos (abdomen, pulmón, catéteres, orina), antibiótico de amplio espectro, líquidos con monitoreo dinámico, vasopresor (norepinefrina) y búsqueda urgente del foco no controlado para drenarlo o reoperarlo", "Subir el vasopresor al máximo sin buscar el foco", "Dar solo paracetamol y esperar"], "ans": 0, "t1Good": "Se encuentra una colección intraabdominal no drenada; se drena en quirófano, FC 118 lpm, TA 102/62 mmHg, lactato 3.6 mmol/L, diuresis 30 mL/h.", "t1Bad": "FC 152 lpm, TA 68/42 mmHg, lactato 7.8 mmol/L, Glasgow 7, diuresis 0 mL/h, pH 7.15: choque séptico refractario con falla multiorgánica.", "t2Good": "Control del foco, antibiótico ajustado y soporte en terapia intensiva; sobrevive con recuperación lenta.", "t2Bad": "Falla multiorgánica y muerte. En sepsis, el vasopresor sin control del foco es maquillaje.", "answer": "Cultivos, antibiótico en la primera hora, vasopresor y, sobre todo, búsqueda y control urgente del foco. La sepsis quirúrgica se cura drenando o reoperando, no solo con antibiótico.", "exp": "Choque séptico en un paciente quirúrgico crítico con abdomen abierto y lactato en ascenso es foco no controlado hasta demostrar lo contrario (Surviving Sepsis Campaign 2021). Se toman cultivos, se da antibiótico en la primera hora, se repone volumen con monitoreo y se inicia norepinefrina, pero el paso que cambia el desenlace es encontrar y controlar el foco: colección, fuga o catéter infectado. Sin control del foco, el antibiótico y el vasopresor no alcanzan."},
    {"id": "GN-R4-07", "grade": "R4", "caso": "Mujer de 49 años, 6 horas después de una tiroidectomía total por bocio grande, llega a las 3:00 a. m. con dificultad para respirar, estridor, el cuello hinchado y tensión en la herida. Está ansiosa y con la voz ronca.", "tema": "Cirugía endocrina, de cabeza y cuello y de mama — hematoma cervical post tiroidectomía con compromiso de la vía aérea.", "t0": "FC 124 lpm, TA 132/82 mmHg, SatO2 89% con oxígeno, temperatura 36.8 °C, dolor cervical 7/10, Glasgow 15. Cuello tenso y edematizado, herida abultada, estridor inspiratorio, frecuencia respiratoria 28/min, drenaje con 150 mL de sangre en 2 h.", "q": "¿Qué haces primero?", "opts": ["Abrir la herida en la cama para evacuar el hematoma y asegurar la vía aérea, con el equipo de quirófano y anestesia avisados de inmediato", "Pedir tomografía de cuello y esperar el reporte", "Dar oxígeno y esperar a la mañana"], "ans": 0, "t1Good": "Al abrir la herida sale el hematoma a presión, el estridor disminuye, SatO2 sube a 95%, FC 108 lpm, TA 122/76 mmHg; se lleva a quirófano para hemostasia definitiva.", "t1Bad": "SatO2 78%, FC 142 lpm, Glasgow 12, estridor grave, imposibilidad de intubar por la compresión traqueal: paro respiratorio.", "t2Good": "Vía aérea asegurada, hemostasia en quirófano, sobrevive sin daño neurológico.", "t2Bad": "Obstrucción completa de la vía aérea y muerte por asfixia en minutos.", "answer": "Abrir la herida en la cama para evacuar el hematoma y liberar la vía aérea. Es una emergencia de vía aérea, no de imagen.", "exp": "Tras una tiroidectomía, un hematoma cervical tenso con estridor y desaturación comprime la tráquea en un espacio cerrado que no se expande. La vía aérea se pierde en minutos y la intubación puede ser imposible por la compresión. Abrir la herida en la cama evacua el hematoma y descomprime la tráquea: es el paso que salva la vida, antes que la tomografía o el traslado."},
    {"id": "GN-R4-08", "grade": "R4", "caso": "Mujer de 41 años con obesidad mórbida, día 3 postoperatorio de manga gástrica, llega a las 3:00 a. m. con fiebre, taquicardia, dolor en hombro izquierdo y dolor epigástrico. El drenaje sale turbio.", "tema": "Cirugía bariátrica y metabólica y pared abdominal compleja — fuga de manga gástrica.", "t0": "FC 128 lpm, TA 100/62 mmHg, SatO2 94%, temperatura 38.9 °C, dolor epigástrico 8/10 y en hombro izquierdo, Glasgow 15. Drenaje con líquido turbio, 150 mL en 12 h. Leucocitos 17,000, PCR muy elevada, lactato 2.8 mmol/L, frecuencia respiratoria 26/min.", "q": "¿Qué pides y qué haces?", "opts": ["Tomografía con contraste oral hidrosoluble, hemocultivos, antibiótico de amplio espectro, ayuno, líquidos, mantener el drenaje y valoración urgente para stent endoscópico o cirugía según la gravedad", "Dar analgésico y dieta líquida para probar tolerancia", "Retirar el drenaje y dar antibiótico oral"], "ans": 0, "t1Good": "La tomografía muestra fuga en la parte alta de la manga con colección; se coloca stent o se drena; FC 112 lpm, TA 110/66 mmHg, temperatura 38.3 °C.", "t1Bad": "FC 144 lpm, TA 82/50 mmHg, temperatura 39.7 °C, Glasgow 13, lactato 4.8 mmol/L, abdomen rígido: peritonitis por fuga no controlada.", "t2Good": "Control de la fuga con stent o cirugía, drenaje y soporte; sobrevive con estancia larga.", "t2Bad": "Peritonitis, sepsis, reintervenciones múltiples y muerte.", "answer": "Tomografía con contraste hidrosoluble, antibiótico, ayuno y control de la fuga. La taquicardia persistente tras una manga gástrica es fuga hasta demostrar lo contrario.", "exp": "Tras una manga gástrica, taquicardia persistente con fiebre, dolor epigástrico y en hombro izquierdo (irritación diafragmática) y drenaje turbio es fuga de la línea de grapas. La fuga suele estar en la parte alta, cerca del ángulo de His. Se confirma con tomografía y contraste hidrosoluble, se ayuna, se da antibiótico y se controla la fuga con stent o cirugía. Dar dieta para \"probar\" contamina el abdomen."},
    {"id": "GN-R4-09", "grade": "R4", "caso": "Hombre de 68 años hipertenso llega a las 3:00 a. m. con dolor torácico desgarrador que se va a la espalda, sudoroso y con diferencia de presión entre ambos brazos.", "tema": "Cirugía vascular, torácica y emergencias toracoabdominales — disección aórtica aguda.", "t0": "FC 118 lpm, TA 178/102 mmHg en brazo derecho y 142/88 mmHg en brazo izquierdo, SatO2 96%, temperatura 36.7 °C, dolor torácico y dorsal 10/10, Glasgow 15. Soplo diastólico nuevo, pulsos femorales asimétricos, dolor desgarrador de inicio súbito.", "q": "¿Qué pides y qué haces?", "opts": ["Angiotomografía de aorta urgente, control de la frecuencia cardiaca y de la presión arterial (betabloqueador intravenoso primero, luego vasodilatador si es necesario), analgesia, aviso urgente a cirugía vascular y cardiotorácica, y evitar anticoagulación", "Dar anticoagulante por sospecha de infarto y pedir troponina para esperar", "Dar antiinflamatorio y enviarlo a casa como dolor muscular"], "ans": 0, "t1Good": "La angiotomografía muestra disección aórtica tipo B; con control de frecuencia y presión, FC 88 lpm, TA 128/78 mmHg, dolor 5/10, sin progresión.", "t1Bad": "FC 140 lpm, TA 200/120 mmHg, dolor 10/10, Glasgow 13, SatO2 90%: ruptura aórtica o taponamiento, paro inminente; la anticoagulación empeora el sangrado de la disección.", "t2Good": "Manejo médico con control estricto de frecuencia y presión o reparación endovascular según el tipo y las complicaciones; sobrevive.", "t2Bad": "Ruptura aórtica, taponamiento cardiaco y muerte.", "answer": "Angiotomografía urgente y control de la frecuencia cardiaca y la presión arterial, sin anticoagular. El dolor desgarrador con diferencia de presiones entre brazos es disección aórtica hasta demostrar lo contrario.", "exp": "La disección aórtica da dolor torácico desgarrador de inicio súbito, con diferencia de presión entre brazos, pulsos asimétricos y soplo nuevo por insuficiencia aórtica. La angiotomografía es el estudio de elección. El tratamiento inicial es bajar la frecuencia cardiaca y la fuerza de contracción (betabloqueador) y luego la presión arterial, para que la disección no progrese ni se rompa. Anticoagular por un supuesto infarto es un error grave."},
    {"id": "GN-R4-10", "grade": "R4", "caso": "Hombre de 64 años diabético, con pie diabético, llega a las 3:00 a. m. con el pie hinchado, caliente, con una úlcera que huele mal, fiebre alta y dolor que no lo deja dormir. Tiene glucosa de 320 mg/dL.", "tema": "Musculoesquelético y pie diabético — infección grave del pie diabético con sepsis.", "t0": "FC 122 lpm, TA 98/60 mmHg, SatO2 95%, temperatura 39.2 °C, dolor en el pie 9/10, Glasgow 15. Pie con edema, eritema que sube por la pierna, úlcera plantar con secreción purulenta y fétida, crepitación escasa, pulsos pedios débiles. Leucocitos 18,000, PCR muy elevada, lactato 3.0 mmol/L, creatinina 1.6 mg/dL.", "q": "¿Qué pides y qué haces?", "opts": ["Hemocultivos, cultivo de la úlcera, laboratorios, radiografía del pie, antibiótico de amplio espectro, líquidos, control glucémico, descarga del pie y valoración urgente para desbridamiento quirúrgico y estudio vascular", "Curación local y antibiótico oral en casa", "Poner compresión en la pierna y esperar"], "ans": 0, "t1Good": "La radiografía muestra gas en tejidos blandos y posible osteomielitis; en quirófano se desbrida el tejido necrosado; FC 106 lpm, TA 110/66 mmHg, temperatura 38.4 °C.", "t1Bad": "FC 140 lpm, TA 82/50 mmHg, temperatura 39.8 °C, Glasgow 13, lactato 5.0 mmol/L, el eritema sube hasta la rodilla: fascitis necrosante y choque séptico.", "t2Good": "Desbridamientos seriados, antibiótico, control glucémico y revascularización si es posible; se salva la pierna o se limita la amputación al mínimo necesario.", "t2Bad": "Amputación mayor, sepsis y muerte. En el pie diabético infectado, la curación local sin desbridar es dejar que la infección avance por dentro.", "answer": "Antibiótico de amplio espectro, cultivos, imagen y desbridamiento quirúrgico urgente con valoración vascular. La infección del pie diabético con signos sistémicos es una emergencia quirúrgica.", "exp": "Fiebre, leucocitosis, lactato elevado y úlcera con secreción fétida y eritema ascendente en un diabético es infección grave del pie diabético, con riesgo de fascitis necrosante y osteomielitis. El tratamiento es antibiótico, desbridamiento quirúrgico del tejido necrosado, descarga del pie, control glucémico y valoración vascular: sin flujo no hay curación. La compresión en una pierna infectada e isquémica empeora la perfusión."},
  ],
  adscrito: [
    {"id": "AP-R1-01", "grade": "R1", "tema": "Respuesta biológica al trauma y fisiología quirúrgica", "chain": [{"p": "P1", "nivel": "base", "q": "En pase de visita, día 2 tras una laparotomía mayor, el adscrito pregunta: ¿qué caracteriza la fase ebb de la respuesta al trauma?", "opts": ["Hipermetabolismo y balance nitrogenado negativo", "Fiebre alta por infección obligada", "Anabolismo con ganancia de masa muscular", "Hipometabolismo, vasoconstricción y conservación de energía"], "ans": 3, "exp": "La fase ebb dura las primeras 24–48 h: gasto bajo, vasoconstricción, oliguria y retención de sodio y agua para preservar volumen."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué mediador explica mejor la hiperglucemia y la resistencia a la insulina de la fase flow?", "opts": ["Aumento de insulina con hipoglucemia", "Déficit aislado de hormona de crecimiento", "Cortisol, catecolaminas y glucagón con resistencia periférica a la insulina", "Exceso de aldosterona sin efecto glucémico"], "ans": 2, "exp": "En la fase flow las hormonas contrarreguladoras elevan la glucosa y bloquean su uso periférico; por eso la hiperglucemia postoperatoria no se corrige solo con más insulina."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué marcador refleja mejor el catabolismo proteico sostenido en el paciente quirúrgico grave?", "opts": ["Glucosa capilar aislada", "Balance nitrogenado negativo persistente", "Sodio sérico", "Leucocitos en rango normal"], "ans": 1, "exp": "El balance nitrogenado negativo (nitrógeno excretado mayor que el ingerido) mide la pérdida neta de proteína; la glucosa y los leucocitos no cuantifican el catabolismo."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿cuándo empieza, en general, la fase flow tras el trauma?", "opts": ["Después de las primeras 24–48 h, tras la fase ebb", "Antes de que ocurra el trauma", "Solo si hay infección documentada", "A los 30 días del evento"], "ans": 0, "exp": "Primero ebb (24–48 h) y luego flow, hipermetabólica y catabólica, que puede durar días o semanas según la gravedad."}]},
    {"id": "AP-R1-02", "grade": "R1", "tema": "Líquidos y electrolitos", "chain": [{"p": "P1", "nivel": "base", "q": "Paciente con vómitos prolongados por obstrucción pilórica: ¿qué trastorno ácido-base y electrolítico espera el adscrito?", "opts": ["Acidosis metabólica con hiperpotasemia", "Alcalosis respiratoria con hipernatremia", "Acidosis respiratoria con hipercloremia", "Alcalosis metabólica hipoclorémica e hipopotasémica"], "ans": 3, "exp": "Se pierde HCl gástrico y potasio; el riñón retiene bicarbonato y pierde más K+ en la alcalosis, el cuadro clásico de la obstrucción alta."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué líquido es más adecuado para reponer pérdidas por sonda nasogástrica en ese paciente?", "opts": ["Solución glucosada al 5% sola", "Agua destilada intravenosa", "Solución salina al 0.9% con reposición de potasio según niveles", "Bicarbonato hipertónico de rutina"], "ans": 2, "exp": "La pérdida gástrica es rica en cloro; la salina repone Cl- y volumen, y el potasio se repone vigilado, sin bicarbonato de rutina."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: un paciente con Na+ de 118 mEq/L, asintomático leve y crónico: ¿cuál es la corrección segura?", "opts": ["Corregir más de 12 mEq/L en las primeras 24 h", "No corregir más de 8 mEq/L en 24 h para evitar desmielinización osmótica", "Dar agua libre en bolo rápido", "Restringir sodio por completo"], "ans": 1, "exp": "La corrección rápida de hiponatremia crónica causa desmielinización osmótica; el límite prudente es de 8 mEq/L/día (menos si hay alto riesgo)."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué electrolito debe revisarse primero ante debilidad muscular y arritmia tras diuréticos?", "opts": ["Potasio", "Magnesio", "Calcio", "Fósforo"], "ans": 0, "exp": "La hipopotasemia por diuréticos causa debilidad, íleo y arritmias; es el primer electrolito a verificar y reponer en ese escenario."}]},
    {"id": "AP-R1-03", "grade": "R1", "tema": "Estado de choque", "chain": [{"p": "P1", "nivel": "base", "q": "Paciente con hemorragia digestiva, taquicardia, hipotensión y piel fría y pálida: ¿qué tipo de choque es?", "opts": ["Choque distributivo", "Choque obstructivo", "Choque cardiogénico", "Choque hipovolémico hemorrágico"], "ans": 3, "exp": "Pérdida de volumen circulante con taquicardia compensadora, piel fría y pálida; la causa es la hemorragia, no una vasodilatación ni una falla cardiaca."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: en choque hemorrágico, ¿qué relación de hemoderivados se busca en la transfusión masiva actual?", "opts": ["Solo cristaloides hasta estabilizar", "Solo plaquetas", "Proporción balanceada cercana a 1:1:1 de concentrados eritrocitarios, plasma y plaquetas", "Plasma fresco en proporción 1:10"], "ans": 2, "exp": "La reanimación hemostática balanceada 1:1:1 imita la sangre total y limita la coagulopatía por dilución de los cristaloides en exceso."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué dato distingue el choque obstructivo por taponamiento cardiaco del hipovolémico?", "opts": ["Taquicardia en ambos, sin diferencias", "Ingurgitación yugular con hipotensión y ruidos cardiacos apagados (tríada de Beck)", "Piel caliente y fiebre", "Bradicardia con hipertensión"], "ans": 1, "exp": "En el taponamiento el llenado cardiaco está impedido y la presión venosa sube; en el hipovolémico las yugulares están colapsadas."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿cuál es la primera medida en choque hemorrágico antes de cualquier fármaco vasoactivo?", "opts": ["Controlar la hemorragia y reponer volumen", "Dar vasopresor en bolo", "Esperar el laboratorio completo", "Dar diurético"], "ans": 0, "exp": "Sin control del sangrado y reposición de volumen, el vasopresor solo aprieta un tanque vacío; la hemostasia es lo primero."}]},
    {"id": "AP-R1-04", "grade": "R1", "tema": "Cuidados perioperatorios", "chain": [{"p": "P1", "nivel": "base", "q": "Antes de una cirugía electiva, ¿qué ayuno mínimo recomienda la ASA para sólidos y líquidos claros?", "opts": ["Sólidos 2 h y líquidos claros 6 h", "Sólidos 4 h y líquidos claros 4 h", "Sólidos 12 h y líquidos claros 8 h", "Sólidos 6 h y líquidos claros 2 h"], "ans": 3, "exp": "ASA: sólidos 6 h, líquidos claros 2 h; ayunar más no reduce la aspiración y empeora deshidratación y catabolismo."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿cuándo debe administrarse la profilaxis antibiótica para que sea eficaz en la herida?", "opts": ["Al terminar la cirugía", "12 horas antes", "Dentro de los 60 minutos previos a la incisión", "Solo si la herida se infecta"], "ans": 2, "exp": "El antibiótico debe estar en tejido en concentración adecuada al momento de la incisión; darlo al final pierde la ventana preventiva."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: paciente con riesgo cardiaco intermedio para cirugía mayor no cardiaca: ¿qué estudio orienta mejor el riesgo según las guías actuales?", "opts": ["Electrocardiograma aislado", "Evaluación clínica con índices de riesgo (p. ej. RCRI) y capacidad funcional, con biomarcadores o ecocardiograma solo si cambian la conducta", "Cateterismo coronario de rutina", "Radiografía de tórax sola"], "ans": 1, "exp": "El riesgo se estratifica clínicamente; los estudios invasivos o de imagen de rutina no se piden si no van a cambiar la decisión quirúrgica o anestésica."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué medida sencilla reduce más la infección del sitio quirúrgico?", "opts": ["Normotermia, glucemia controlada y técnica estéril, sin rasurar con navaja", "Rasurar con navaja la noche anterior", "Antibiótico prolongado por 7 días en herida limpia", "Dejar la herida abierta siempre"], "ans": 0, "exp": "Mantener temperatura y glucosa, no rasurar con navaja y respetar la esterilidad son las medidas básicas; el antibiótico prolongado no compensa una mala técnica."}]},
    {"id": "AP-R1-05", "grade": "R1", "tema": "Nutrición en cirugía", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué vía de soporte nutricional se prefiere cuando el tubo digestivo funciona?", "opts": ["Nutrición parenteral total de inicio", "Ayuno prolongado", "Solo suero glucosado", "Nutrición enteral"], "ans": 3, "exp": "Si el intestino funciona, la vía enteral mantiene la mucosa, es más barata y tiene menos infecciones que la parenteral."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué complicación se vigila al reiniciar la alimentación tras ayuno prolongado con desnutrición?", "opts": ["Hipernatremia aislada", "Hipercalcemia grave", "Síndrome de realimentación, con caída de fósforo, potasio y magnesio", "Alcalosis respiratoria"], "ans": 2, "exp": "Al reiniciar, la insulina mete fósforo, potasio y magnesio a la célula y caen en sangre, con riesgo de arritmia e insuficiencia respiratoria; se inicia lento y se reponen."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: según ESPEN, ¿cuánto tiempo de ayuno oral esperado justifica iniciar soporte nutricional en el paciente quirúrgico desnutrido?", "opts": ["Solo después de 30 días", "Más de 7 días sin poder comer, o desnutrición grave con cirugía mayor próxima", "Nunca antes de operar", "Solo si hay obesidad"], "ans": 1, "exp": "ESPEN: el soporte se indica ante desnutrición o ayuno prolongado esperado; esperar semanas agrava la pérdida de masa magra y las complicaciones."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué dato de laboratorio baja primero en desnutrición proteica grave?", "opts": ["Albúmina", "Hemoglobina", "Glucosa", "Creatinina"], "ans": 0, "exp": "La albúmina baja refleja el estado proteico (con sus limitaciones como reactante de fase aguda), y es el marcador clásico que el adscrito pide en desnutrición."}]},
    {"id": "AP-R1-06", "grade": "R1", "tema": "Sangre, hemostasia y transfusión", "chain": [{"p": "P1", "nivel": "base", "q": "Paciente estable sin cardiopatía, Hb 6.9 g/dL: según la estrategia restrictiva (AABB), ¿qué se hace?", "opts": ["Transfundir 2 unidades hasta Hb 10 g/dL", "Transfundir plasma en lugar de eritrocitos", "No transfundir nunca por encima de 6 g/dL", "Transfundir 1 unidad y reevaluar"], "ans": 3, "exp": "Umbral restrictivo ~7 g/dL en el paciente estable: una unidad y reevaluar síntomas y Hb; llevar a 10 no mejora desenlaces y suma riesgos."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué complicación transfusional aparece en las primeras 6 horas con disnea, hipoxemia e infiltrados bilaterales sin sobrecarga evidente?", "opts": ["TACO por sobrecarga circulatoria", "Reacción hemolítica tardía", "TRALI, lesión pulmonar aguda relacionada con la transfusión", "Púrpura postransfusional"], "ans": 2, "exp": "TRALI es edema pulmonar no cardiogénico en las primeras 6 h; TACO es por sobrecarga, con hipertensión y respuesta a diuréticos, y suele distinguirse por el contexto de volumen."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: en coagulopatía con INR elevado y sangrado activo que requiere cirugía urgente, ¿qué corrige más rápido el INR?", "opts": ["Vitamina K oral", "Concentrado de complejo protrombínico (PCC)", "Plasma fresco congelado en dosis baja", "Ácido tranexámico solo"], "ans": 1, "exp": "El PCC aporta los factores dependientes de vitamina K concentrados y corrige el INR en minutos; la vitamina K tarda horas y el plasma requiere mucho volumen."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué prueba de cabecera orienta la hemostasia global en quirófano en el paciente que sangra?", "opts": ["Tromboelastografía o tromboelastometría (TEG/ROTEM)", "Hemoglobina aislada", "Glucosa capilar", "Gasometría sola"], "ans": 0, "exp": "TEG/ROTEM muestran en tiempo real la formación y la lisis del coágulo y guían qué hemoderivado falta, a diferencia de una Hb aislada."}]},
    {"id": "AP-R1-07", "grade": "R1", "tema": "Cicatrización y cuidado de las heridas quirúrgicas", "chain": [{"p": "P1", "nivel": "base", "q": "¿En qué fase de la cicatrización predominan los macrófagos y la limpieza de la herida?", "opts": ["Remodelación", "Epitelización final", "Maduración tardía", "Inflamatoria"], "ans": 3, "exp": "La fase inflamatoria (primeros días) limpia detritos y bacterias con neutrófilos y luego macrófagos, que además liberan factores de crecimiento."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué colágeno predomina al inicio y por cuál se sustituye en remodelación?", "opts": ["Tipo II siempre", "Tipo I al inicio, sustituido por tipo III", "Tipo III al inicio, sustituido por tipo I", "Tipo IV al inicio, sustituido por tipo II"], "ans": 2, "exp": "El colágeno III, débil y desorganizado, se reemplaza por colágeno I, más fuerte; aun así la herida solo alcanza ~70–80% de la resistencia original."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué factor sistémico retrasa más la cicatrización en el paciente quirúrgico?", "opts": ["Ejercicio moderado", "Desnutrición proteica, diabetes mal controlada y tabaquismo", "Edad joven", "Sueño adecuado"], "ans": 1, "exp": "La falta de proteína, la hiperglucemia y la vasoconstricción por tabaco reducen oxígeno tisular y síntesis de colágeno; son los factores que el adscrito siempre pregunta."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿cómo se clasifica una herida de apendicectomía por apendicitis perforada con pus?", "opts": ["Sucia o infectada", "Limpia-contaminada", "Contaminada", "Limpia"], "ans": 0, "exp": "Herida con pus o perforación de víscera con contenido infectado es sucia; la limpia es sin apertura de víscera ni inflamación, y la contaminada es apertura controlada sin pus franca."}]},
    {"id": "AP-R1-08", "grade": "R1", "tema": "Infección en cirugía", "chain": [{"p": "P1", "nivel": "base", "q": "Herida quirúrgica con eritema, calor y secreción purulenta al día 5: ¿qué es lo más probable?", "opts": ["Seroma estéril", "Dehiscencia sin infección", "Hematoma sin infección", "Infección del sitio quirúrgico superficial"], "ans": 3, "exp": "Eritema, calor, dolor y pus en los primeros 30 días es infección superficial del sitio quirúrgico (CDC 2017); el seroma es líquido claro sin signos inflamatorios."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: paciente diabético con dolor desproporcionado, eritema que avanza y crepitación en el pie: ¿qué se hace?", "opts": ["Solo antibiótico oral y observar", "Compresión venosa inmediata", "Sospechar fascitis necrosante: desbridamiento quirúrgico urgente sin esperar la imagen", "Curación diaria sin cirugía"], "ans": 2, "exp": "Dolor fuera de proporción con crepitación es fascitis necrosante hasta demostrar lo contrario; el retraso quirúrgico mata, la imagen no debe demorar el quirófano."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué cubre el espectro de la infección intraabdominal comunitaria leve-moderada que guía la elección empírica?", "opts": ["Solo grampositivos", "Gramnegativos entéricos, anaerobios y estreptococos, según guías WSES", "Solo hongos", "Solo virus"], "ans": 1, "exp": "La flora intraabdominal es mixta: E. coli y otros gramnegativos, Bacteroides y estreptococos; por eso el esquema empírico cubre ambos grupos."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿cuál es el pilar del tratamiento de un absceso quirúrgico?", "opts": ["Drenaje del absceso más antibiótico", "Antibiótico solo, sin drenaje", "Solo analgésico", "Esperar a que se reabsorba"], "ans": 0, "exp": "El pus encapsulado no lo resuelve el antibiótico solo; el drenaje es el tratamiento definitivo y el antibiótico es coadyuvante."}]},
    {"id": "AP-R1-09", "grade": "R1", "tema": "Trauma: evaluación inicial ATLS", "chain": [{"p": "P1", "nivel": "base", "q": "Según ATLS 10.ª ed., ¿cuál es el primer paso de la revisión primaria?", "opts": ["Circulación con control de hemorragia", "Evaluación neurológica", "Exposición completa", "Vía aérea con protección de columna cervical"], "ans": 3, "exp": "El ABCDE empieza por A: vía aérea permeable con control cervical; sin vía aérea no hay nada que reanimar después."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: paciente con trauma torácico, hipotensión, ingurgitación yugular y ausencia de murmullo vesicular en un hemitórax: ¿qué es?", "opts": ["Hemotórax simple", "Contusión pulmonar", "Neumotórax a tensión", "Fractura costal aislada"], "ans": 2, "exp": "Aire a presión que colapsa el pulmón y desvía el mediastino: hipotensión, yugulares ingurgitadas y silencio auscultatorio; se descomprime con aguja y luego sello."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: en la revisión primaria, ¿qué hallazgo indica hemorragia exsanguinante que exige control inmediato antes de seguir el ABCDE?", "opts": ["Taquicardia leve", "Sangrado externo masivo que no se controla con presión", "Dolor abdominal leve", "Fractura cerrada de antebrazo"], "ans": 1, "exp": "ATLS prioriza el control de la hemorragia externa catastrófica (torniquete o presión directa) incluso antes de completar A y B; es la causa de muerte más evitable."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué significa la E de la revisión primaria ABCDE?", "opts": ["Exposición y control de hipotermia", "Ecografía obligatoria", "Electrocardiograma", "Evaluación de extremidades"], "ans": 0, "exp": "E es exposición completa buscando lesiones ocultas, con prevención activa de hipotermia, que empeora coagulopatía, acidosis e hipotermia: la tríada letal."}]},
    {"id": "AP-R1-10", "grade": "R1", "tema": "Abdomen agudo y apendicitis aguda", "chain": [{"p": "P1", "nivel": "base", "q": "Dolor periumbilical que migra a fosa iliaca derecha, anorexia y fiebre baja: ¿cuál es el diagnóstico más probable?", "opts": ["Colecistitis aguda", "Diverticulitis sigmoidea", "Pancreatitis aguda", "Apendicitis aguda"], "ans": 3, "exp": "La migración del dolor visceral (T10) al somático en McBurney, con anorexia y febrícula, es la presentación clásica de apendicitis."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué signo es dolor a la descompresión en fosa iliaca derecha?", "opts": ["Signo de Murphy", "Signo de Rovsing invertido", "Signo de Blumberg", "Signo de Courvoisier"], "ans": 2, "exp": "Blumberg es dolor al soltar la palpación (irritación peritoneal); Murphy es de vesícula, Rovsing es dolor en fosa derecha al palpar la izquierda."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: según WSES 2020, ¿qué estudio de imagen se prefiere en el adulto con sospecha intermedia de apendicitis?", "opts": ["Radiografía simple de abdomen", "Tomografía computarizada con contraste", "Resonancia magnética siempre", "Ningún estudio, solo clínica"], "ans": 1, "exp": "WSES 2020: en el adulto con probabilidad intermedia la TC con contraste tiene la mejor precisión para confirmar o descartar apendicitis y sus complicaciones."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿cuál es el tratamiento definitivo de la apendicitis aguda no complicada?", "opts": ["Apendicectomía", "Solo antibiótico de por vida", "Solo ayuno", "Drenaje percutáneo siempre"], "ans": 0, "exp": "La apendicectomía (laparoscópica o abierta) es el tratamiento definitivo; el manejo solo con antibiótico tiene recurrencia y no es la conducta estándar en el medio quirúrgico."}]},
    {"id": "AP-R2-01", "grade": "R2", "tema": "Patología esofágica y ERGE", "chain": [{"p": "P1", "nivel": "base", "q": "Pirosis y regurgitación que empeoran al acostarse y mejoran con antiácidos: ¿qué es lo más probable?", "opts": ["Acalasia", "Divertículo de Zenker", "Cáncer de esófago", "Enfermedad por reflujo gastroesofágico"], "ans": 3, "exp": "Pirosis posprandial y nocturna con regurgitación es ERGE; la acalasia da disfagia y regurgitación de alimento no digerido sin pirosis predominante."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué hallazgo endoscópico define el esófago de Barrett?", "opts": ["Mucosa gástrica normal", "Úlcera duodenal", "Metaplasia intestinal con células caliciformes por encima de la unión gastroesofágica", "Várices esofágicas"], "ans": 2, "exp": "Barrett es epitelio columnar con metaplasia intestinal (células caliciformes) en el esófago distal por reflujo crónico; es premaligno para adenocarcinoma."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿en qué consiste la funduplicatura de Nissen?", "opts": ["Resección del esófago distal", "Envolver 360° el fondo gástrico alrededor del esófago distal para reforzar el esfínter inferior", "Dilatación endoscópica del píloro", "Colocar una prótesis esofágica"], "ans": 1, "exp": "Nissen es una funduplicatura total de 360°; aumenta la presión del esfínter esofágico inferior y corrige la hernia hiatal asociada."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué estudio confirma el reflujo cuando la endoscopia es normal y se duda del diagnóstico?", "opts": ["pH-metría esofágica de 24 horas", "Radiografía de tórax", "Ultrasonido abdominal", "Colonoscopia"], "ans": 0, "exp": "La pH-metría mide la exposición ácida real del esófago; la endoscopia normal no descarta ERGE no erosiva."}]},
    {"id": "AP-R2-02", "grade": "R2", "tema": "Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica", "chain": [{"p": "P1", "nivel": "base", "q": "Melena, hematemesis y caída de hemoglobina: ¿de dónde sangra más probablemente?", "opts": ["Colon sigmoides", "Intestino delgado distal", "Hemorroides", "Tracto digestivo alto, proximal al ligamento de Treitz"], "ans": 3, "exp": "Melena y hematemesis indican sangrado alto (proximal a Treitz); el sangrado bajo da hematoquecia y las hemorroides, sangre roja fresca."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué causa más frecuente de hemorragia digestiva alta por úlcera péptica debe buscarse y tratarse?", "opts": ["Cáncer de colon", "Várices por hipertensión arterial sistémica", "Helicobacter pylori y uso de AINE", "Divertículos duodenales"], "ans": 2, "exp": "H. pylori y los AINE son las dos causas dominantes de úlcera péptica; erradicar H. pylori y suspender el AINE son parte del tratamiento."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: en hemorragia por úlcera con coágulo adherido visible en endoscopia (Forrest IIb), ¿qué se hace?", "opts": ["Nada, solo observar", "Terapia endoscópica (inyección, clip o coagulación) más inhibidor de bomba de protones en infusión", "Cirugía inmediata siempre", "Transfundir hasta Hb 12 g/dL"], "ans": 1, "exp": "Forrest IIb tiene alto riesgo de resangrado; la hemostasia endoscópica combinada con IBP en dosis altas reduce resangrado y cirugía."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué complicación de la úlcera duodenal posterior sangra más y puede perforarse?", "opts": ["Úlcera duodenal posterior que erosiona la arteria gastroduodenal", "Úlcera gástrica anterior", "Gastritis erosiva leve", "Úlcera esofágica"], "ans": 0, "exp": "La úlcera posterior del bulbo duodenal está sobre la gastroduodenal; al erosionarla causa hemorragia masiva, a diferencia de la anterior, que tiende a perforar libre."}]},
    {"id": "AP-R2-03", "grade": "R2", "tema": "Patología hepática quirúrgica", "chain": [{"p": "P1", "nivel": "base", "q": "Fiebre, dolor en hipocondrio derecho y leucocitosis en paciente con antecedente de amibiasis: ¿qué absceso sospecha?", "opts": ["Absceso piógeno", "Tumor hepático", "Quiste hidatídico roto", "Absceso hepático amibiano"], "ans": 3, "exp": "En México, el absceso hepático amibiano (Entamoeba histolytica) es frecuente: fiebre, dolor en hipocondrio derecho y antecedente disentérico; el piógeno suele ser por vía biliar."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿cuál es el tratamiento de primera línea del absceso hepático amibiano no complicado?", "opts": ["Drenaje quirúrgico abierto de inicio", "Solo analgésico", "Metronidazol más un amebicida luminal", "Resección hepática"], "ans": 2, "exp": "El amibiano responde a metronidazol (tisular) más amebicida luminal para erradicar quistes; el drenaje se reserva para rotura, falta de respuesta o duda diagnóstica."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué segmento hepático es el más afectado por el absceso amibiano y por qué?", "opts": ["Lóbulo izquierdo, por su drenaje venoso", "Lóbulo derecho, por recibir más flujo portal del colon derecho", "Lóbulo caudado", "Ambos por igual"], "ans": 1, "exp": "La vena porta derecha recibe más flujo del colon ascendente, vía de llegada de las amibas; por eso el absceso amibiano predomina en el lóbulo derecho."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué estudio de imagen se pide primero ante sospecha de absceso hepático?", "opts": ["Ultrasonido hepático", "Radiografía simple", "Colonoscopia", "Gammagrafía ósea"], "ans": 0, "exp": "El ultrasonido es accesible, sin radiación y sensible para lesiones hepáticas; la TC se usa para caracterizar o planear drenaje."}]},
    {"id": "AP-R2-04", "grade": "R2", "tema": "Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18)", "chain": [{"p": "P1", "nivel": "base", "q": "Dolor en hipocondrio derecho, fiebre y signo de Murphy positivo: ¿qué es?", "opts": ["Cólico biliar simple", "Hepatitis viral", "Pancreatitis aguda", "Colecistitis aguda"], "ans": 3, "exp": "Dolor sostenido en hipocondrio derecho con fiebre, leucocitosis y Murphy positivo es colecistitis aguda; el cólico biliar dura horas y cede sin fiebre."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: según las Guías de Tokio TG18 (2018), ¿cuándo se indica colecistectomía laparoscópica temprana en colecistitis leve-moderada?", "opts": ["Después de 6 semanas siempre", "Nunca en el primer ingreso", "Temprana, dentro de los primeros 7 días del inicio, si el paciente lo permite", "Solo si hay colangitis"], "ans": 2, "exp": "TG18 recomienda colecistectomía temprana en grado I–II; operar tarde suma reingresos y complicaciones, y la cirugía diferida se reserva para casos seleccionados."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué tríada define la colangitis aguda (tríada de Charcot)?", "opts": ["Dolor, vómito y diarrea", "Dolor, fiebre e ictericia", "Fiebre, hipotensión y confusión", "Ictericia, prurito y pérdida de peso"], "ans": 1, "exp": "Charcot es fiebre con escalofrío, dolor en hipocondrio derecho e ictericia por obstrucción e infección biliar; si se agrega hipotensión y alteración mental es la pentada de Reynolds."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué estudio confirma un lito en el colédoco antes de la cirugía?", "opts": ["Colangiorresonancia magnética (CPRM) o ultrasonido endoscópico", "Radiografía simple de abdomen", "Electrocardiograma", "Prueba de función tiroidea"], "ans": 0, "exp": "La CPRM y el ultrasonido endoscópico visualizan el colédoco sin radiación ni contraste invasivo; la radiografía no ve la mayoría de los litos."}]},
    {"id": "AP-R2-05", "grade": "R2", "tema": "Pancreatitis aguda y crónica", "chain": [{"p": "P1", "nivel": "base", "q": "Dolor epigástrico intenso irradiado a espalda, vómito y lipasa tres veces el valor normal: ¿qué es?", "opts": ["Colecistitis aguda", "Úlcera perforada", "Infarto agudo de miocardio", "Pancreatitis aguda"], "ans": 3, "exp": "Dolor epigástrico en cinturón con lipasa o amilasa ≥3 veces lo normal cumple criterios de pancreatitis aguda (Atlanta revisado)."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿cuáles son las dos causas más frecuentes de pancreatitis aguda en México?", "opts": ["Trauma y virus", "Hipertrigliceridemia y fármacos", "Alcohol y litiasis biliar", "Cáncer y autoinmune"], "ans": 2, "exp": "La litiasis biliar y el alcohol explican la mayoría de los casos; la hipertrigliceridemia es importante pero menos frecuente, y el resto son causas poco comunes."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: en pancreatitis aguda grave, ¿qué complicación local define la necrosis pancreática infectada?", "opts": ["Colección líquida estéril", "Necrosis pancreática o peripancreática con infección demostrada o sospechada, a menudo con gas en la TC", "Pseudoquiste simple", "Derrame pleural leve"], "ans": 1, "exp": "La necrosis infectada es la complicación más temida; el gas en la colección en TC sugiere infección, y su manejo es escalonado (step-up), no cirugía abierta de inicio."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿cuál es el pilar inicial del tratamiento de la pancreatitis aguda leve?", "opts": ["Hidratación agresiva temprana, ayuno breve y analgesia", "Antibiótico profiláctico de rutina", "Cirugía inmediata", "Nutrición parenteral total de inicio"], "ans": 0, "exp": "La reanimación con líquidos, el control del dolor y la realimentación oral temprana cuando se tolera son la base; el antibiótico profiláctico no se usa en pancreatitis leve estéril."}]},
    {"id": "AP-R2-06", "grade": "R2", "tema": "Apendicitis aguda y abdomen agudo (R2)", "chain": [{"p": "P1", "nivel": "base", "q": "En el adulto, ¿qué escala clínica ayuda a estratificar la probabilidad de apendicitis antes de pedir imagen?", "opts": ["Escala de APACHE II", "Escala de Glasgow", "Escala de Child-Pugh", "Escala de Alvarado"], "ans": 3, "exp": "Alvarado suma migración del dolor, anorexia, náusea, dolor en fosa derecha, rebote, fiebre y leucocitosis; orienta quién necesita imagen y quién puede observarse."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué hallazgo en TC sugiere apendicitis complicada con perforación?", "opts": ["Apéndice de 5 mm sin inflamación", "Apéndice normal con grasa limpia", "Aire extraluminal, absceso periappendicular o líquido libre con realce de la pared", "Solo litiasis vesicular"], "ans": 2, "exp": "El aire fuera del apéndice, el absceso y el líquido libre indican perforación; un apéndice delgado sin cambios inflamatorios la descarta prácticamente."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ante un absceso periappendicular bien delimitado en paciente estable, ¿qué conducta recomienda WSES 2020?", "opts": ["Cirugía inmediata siempre", "Drenaje percutáneo más antibiótico y apendicectomía diferida en casos seleccionados", "Solo analgésico", "Alta sin tratamiento"], "ans": 1, "exp": "El absceso contenido se drena y se trata con antibiótico; operar de inmediato en tejido inflamado y friable aumenta complicaciones, por eso se difiere la apendicectomía."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué dato de laboratorio acompaña típicamente a la apendicitis aguda?", "opts": ["Leucocitosis con neutrofilia", "Leucopenia grave", "Trombocitopenia aislada", "Hipoglucemia"], "ans": 0, "exp": "La apendicitis inflamada eleva leucocitos con predominio de neutrófilos; su ausencia no la descarta, pero su presencia apoya el diagnóstico."}]},
    {"id": "AP-R2-07", "grade": "R2", "tema": "Hernias de la pared abdominal", "chain": [{"p": "P1", "nivel": "base", "q": "Protuberancia inguinal que aumenta con la tos y se reduce al acostarse: ¿qué es?", "opts": ["Lipoma", "Adenopatía", "Hidrocele", "Hernia inguinal reductible"], "ans": 3, "exp": "La hernia inguinal es una protrusión por un defecto de la pared que se reduce y aumenta con el esfuerzo; el hidrocele es líquido escrotal que no se reduce igual."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué hernia inguinal sale medial a los vasos epigástricos inferiores, por el triángulo de Hesselbach?", "opts": ["Indirecta", "Femoral", "Directa", "Obturatriz"], "ans": 2, "exp": "La directa protruye por la pared posterior (triángulo de Hesselbach), medial a los epigástricos; la indirecta sigue el cordón, lateral a ellos, por el anillo interno."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué complicación exige cirugía urgente en una hernia?", "opts": ["Hernia reductible sin dolor", "Estrangulación con isquemia del contenido herniado", "Hernia pequeña asintomática", "Hernia que solo se ve al toser"], "ans": 1, "exp": "La estrangulación corta el flujo sanguíneo del asa herniada y lleva a necrosis y perforación; es urgencia quirúrgica, no una hernia reductible tranquila."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué técnica de reparación inguinal sin tensión usa malla y es la más difundida?", "opts": ["Lichtenstein", "Bassini", "Shouldice sin malla", "Solo observación"], "ans": 0, "exp": "Lichtenstein coloca una malla sin tensión sobre la pared posterior; Bassini y Shouldice son reparaciones con tensión y sin malla."}]},
    {"id": "AP-R2-08", "grade": "R2", "tema": "Obstrucción intestinal, vólvulo e isquemia intestinal", "chain": [{"p": "P1", "nivel": "base", "q": "Distensión abdominal, vómito, ausencia de evacuaciones y niveles hidroaéreos en radiografía: ¿qué es?", "opts": ["Íleo paralítico leve", "Apendicitis", "Gastritis aguda", "Obstrucción intestinal mecánica"], "ans": 3, "exp": "La tríada distensión, vómito y falta de evacuaciones con niveles hidroaéreos es obstrucción mecánica; el íleo también distiende, pero sin un punto de bloqueo."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿cuál es la causa más frecuente de obstrucción de intestino delgado en el adulto operado?", "opts": ["Tumores primarios", "Hernias internas", "Adherencias postoperatorias", "Cuerpos extraños"], "ans": 2, "exp": "Las adherencias tras cirugía abdominal son la primera causa de obstrucción de delgado; las hernias son la segunda y los tumores, menos frecuentes."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué signo en TC sugiere isquemia intestinal en una obstrucción?", "opts": ["Pared intestinal con realce normal", "Falta de realce de la pared, neumatosis o gas en la vena porta", "Solo distensión leve", "Líquido libre escaso sin cambios"], "ans": 1, "exp": "La pared que no capta contraste, la neumatosis y el gas portal son signos de sufrimiento intestinal y obligan a cirugía urgente."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué vólvulo es el más frecuente en el adulto mayor con estreñimiento crónico?", "opts": ["Vólvulo sigmoideo", "Vólvulo de ciego", "Vólvulo gástrico", "Vólvulo de delgado"], "ans": 0, "exp": "El sigmoide redundante del adulto mayor con estreñimiento se torsiona con facilidad; en radiografía da la imagen clásica en grano de café."}]},
    {"id": "AP-R2-09", "grade": "R2", "tema": "Cáncer de colon", "chain": [{"p": "P1", "nivel": "base", "q": "Adulto con anemia ferropénica, pérdida de peso y cambio del hábito intestinal: ¿qué debe descartarse primero?", "opts": ["Hemorroides", "Infección urinaria", "Gastritis", "Cáncer de colon"], "ans": 3, "exp": "La anemia ferropénica en el adulto, con pérdida de peso y cambio intestinal, obliga a descartar cáncer de colon con colonoscopia; atribuirla a hemorroides es el error clásico."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué marcador tumoral se usa para el seguimiento del cáncer colorrectal, no para el diagnóstico?", "opts": ["Alfafetoproteína", "CA 125", "Antígeno carcinoembrionario (CEA)", "PSA"], "ans": 2, "exp": "El CEA no diagnostica cáncer de colon, pero su elevación basal y su tendencia en el seguimiento ayudan a detectar recurrencia."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: según NCCN, ¿qué estudio define la estadificación a distancia del cáncer de colon?", "opts": ["Radiografía de tórax sola", "Tomografía de tórax, abdomen y pelvis con contraste", "Ultrasonido abdominal solo", "Colonoscopia sola"], "ans": 1, "exp": "NCCN estadifica con TC toracoabdominal: busca metástasis hepáticas y pulmonares y extensión local; la colonoscopia diagnostica, no estadifica a distancia."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿cuál es el tratamiento curativo principal del cáncer de colon localizado?", "opts": ["Resección quirúrgica con márgenes y linfadenectomía", "Quimioterapia sola", "Radioterapia sola", "Solo observación"], "ans": 0, "exp": "La cirugía con resección oncológica y ganglios es el tratamiento curativo; la quimioterapia adyuvante se agrega según el estadio."}]},
    {"id": "AP-R2-10", "grade": "R2", "tema": "Cáncer de recto y ano, y patología anorrectal benigna", "chain": [{"p": "P1", "nivel": "base", "q": "Dolor anal intenso al evacuar con sangre roja fresca y desgarro visible en la línea media posterior: ¿qué es?", "opts": ["Hemorroides internas", "Cáncer de ano", "Fístula perianal", "Fisura anal aguda"], "ans": 3, "exp": "La fisura es un desgarro del anodermo, típicamente posterior, con dolor agudo al evacuar y sangrado escaso; las hemorroides sangran sin ese dolor desgarrante."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué absceso perianal exige drenaje quirúrgico urgente y no solo antibiótico?", "opts": ["Hemorroide interna grado I", "Fisura sin absceso", "Absceso perianal con dolor, fluctuación y fiebre", "Prurito anal sin masa"], "ans": 2, "exp": "El absceso es pus encapsulada y se drena; el antibiótico solo no lo resuelve y el retraso lleva a fístula o a sepsis perianal."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: en cáncer de recto medio-bajo localmente avanzado, ¿qué tratamiento neoadyuvante se usa antes de la cirugía según NCCN?", "opts": ["Cirugía directa sin nada previo", "Quimiorradioterapia neoadyuvante (o radioterapia de curso corto) seguida de resección", "Solo quimioterapia paliativa", "Solo endoscopia"], "ans": 1, "exp": "NCCN: el recto localmente avanzado se trata primero con quimiorradioterapia para reducir el tumor y el riesgo de recurrencia local, y luego se opera."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué estudio mide la distancia del tumor rectal al margen anal y orienta la cirugía?", "opts": ["Resonancia magnética de pelvis", "Colonoscopia sola", "Ultrasonido abdominal", "Radiografía simple"], "ans": 0, "exp": "La resonancia pélvica define la altura del tumor, su relación con el esfínter y el margen de resección circunferencial; es el estudio clave en cáncer de recto."}]},
    {"id": "AP-R3-01", "grade": "R3", "tema": "Cirugía oncológica: principios, estadificación y manejo multidisciplinario", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué significa la T en el sistema TNM de estadificación?", "opts": ["Tiempo de evolución", "Número de tumores a distancia", "Tipo de quimioterapia", "Tamaño y extensión del tumor primario"], "ans": 3, "exp": "T es el tumor primario, N los ganglios regionales y M las metástasis a distancia; juntos definen el estadio."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué principio oncológico se viola al biopsiar un tumor resecable por una vía que contamina un compartimento sano?", "opts": ["Ninguno, la biopsia siempre es inocua", "La estadificación ganglionar", "La siembra tumoral por trayecto de biopsia mal planeado", "La quimioterapia neoadyuvante"], "ans": 2, "exp": "El trayecto de biopsia debe planearse para resecarse con el tumor; si contamina otro compartimento, siembra células y complica la resección curativa."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué es el margen R0 en cirugía oncológica?", "opts": ["Resección con tumor residual microscópico", "Resección completa sin tumor residual micro ni macroscópico", "Resección paliativa con tumor visible", "Biopsia incisional"], "ans": 1, "exp": "R0 es margen libre en histopatología; R1 es residual microscópico y R2 macroscópico, y el objetivo curativo es siempre R0."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿quién decide el plan en cáncer: el cirujano solo o el equipo multidisciplinario?", "opts": ["El equipo multidisciplinario (cirugía, oncología, radioterapia, radiología, patología)", "El cirujano solo", "El paciente sin información", "El laboratorio"], "ans": 0, "exp": "El cáncer se decide en comité multidisciplinario; la cirugía sola sin oncología ni radioterapia pierde opciones curativas."}]},
    {"id": "AP-R3-02", "grade": "R3", "tema": "Cáncer de mama", "chain": [{"p": "P1", "nivel": "base", "q": "Mujer con nódulo mamario duro, fijo y no doloroso: ¿qué estudio de imagen se pide primero según la edad?", "opts": ["Ningún estudio", "Tomografía siempre", "Resonancia siempre", "Mastografía en mayor de 40 años, ultrasonido en menor de 40 o mama densa"], "ans": 3, "exp": "La mastografía es el estudio base en la mujer mayor; en la joven el ultrasonido caracteriza mejor el nódulo y evita radiación innecesaria."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué receptores definen el subtipo luminal del cáncer de mama?", "opts": ["HER2 positivo sin receptores hormonales", "Triple negativo", "Receptores de estrógeno y progesterona positivos, HER2 negativo", "Solo receptores de andrógenos"], "ans": 2, "exp": "El luminal es hormonosensible y HER2 negativo; el triple negativo no expresa ninguno de los tres y el HER2 positivo sobreexpresa HER2."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué es el ganglio centinela en cáncer de mama?", "opts": ["El ganglio más grande de la axila", "El primer ganglio que recibe el drenaje linfático del tumor y predice el estado axilar", "Cualquier ganglio palpable", "El ganglio supraclavicular"], "ans": 1, "exp": "Si el centinela es negativo, la axila suele estar libre y se evita la disección completa con su linfedema; si es positivo, se completa el manejo axilar."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué signo clínico sugiere cáncer de mama inflamatorio?", "opts": ["Mama enrojecida, edematosa y con piel de naranja de evolución rápida", "Nódulo móvil y blando", "Secreción láctea bilateral", "Dolor cíclico premenstrual"], "ans": 0, "exp": "El cáncer inflamatorio invade linfáticos dérmicos: eritema, edema y piel de naranja; se confunde con mastitis, pero no cede con antibiótico."}]},
    {"id": "AP-R3-03", "grade": "R3", "tema": "Cáncer colorrectal", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué vía de diseminación explica las metástasis hepáticas del cáncer de colon?", "opts": ["Vía linfática axilar", "Contigüidad con el pulmón", "Vía aérea", "Vía hematógena por la vena porta al hígado"], "ans": 3, "exp": "El drenaje venoso del colon va a la porta y al hígado, primer filtro; por eso el hígado es el sitio más frecuente de metástasis colorrectal."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué mutación orienta el uso de anti-EGFR (cetuximab) en cáncer colorrectal metastásico?", "opts": ["Mutación de BRCA", "Mutación de HER2", "Estado RAS (KRAS/NRAS): solo el RAS no mutado responde a anti-EGFR", "Mutación de EGFR siempre"], "ans": 2, "exp": "Con RAS mutado la vía está activada río abajo y el anti-EGFR no funciona; por eso se pide RAS antes de dar cetuximab o panitumumab."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué es la escisión total del mesorrecto (TME) en cáncer de recto?", "opts": ["Resección del colon derecho", "Resección del recto con su mesorrecto completo en el plano avascular, preservando nervios", "Amputación abdominoperineal siempre", "Resección local endoscópica"], "ans": 1, "exp": "La TME reseca el mesorrecto íntegro con sus ganglios y reduce la recurrencia local; es el estándar quirúrgico del cáncer de recto."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿a qué edad inicia en general el tamizaje de cáncer colorrectal en la persona de riesgo promedio?", "opts": ["A los 45 años", "A los 20 años", "A los 70 años", "Nunca si no hay síntomas"], "ans": 0, "exp": "El tamizaje inicia a los 45 años en riesgo promedio (colonoscopia o pruebas en heces); antes solo si hay antecedentes familiares o síndromes hereditarios."}]},
    {"id": "AP-R3-04", "grade": "R3", "tema": "Cáncer gástrico y de esófago", "chain": [{"p": "P1", "nivel": "base", "q": "Disfagia progresiva a sólidos y luego a líquidos, con pérdida de peso: ¿qué se sospecha?", "opts": ["ERGE leve", "Divertículo de Zenker", "Acalasia siempre", "Cáncer de esófago"], "ans": 3, "exp": "La disfagia mecánica progresiva con pérdida de peso en el adulto mayor es cáncer de esófago hasta demostrar lo contrario; la acalasia da disfagia a sólidos y líquidos desde el inicio."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué tipo histológico predomina en el cáncer de esófago distal asociado a Barrett?", "opts": ["Carcinoma epidermoide", "Linfoma", "Adenocarcinoma", "Melanoma"], "ans": 2, "exp": "El adenocarcinoma surge sobre Barrett en el esófago distal; el epidermoide predomina en el esófago medio y se asocia a tabaco y alcohol."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: en cáncer gástrico, ¿cuántos ganglios recomienda resecar la linfadenectomía D2 para una estadificación adecuada?", "opts": ["Menos de 5", "Al menos 15 ganglios", "Solo el centinela", "Ninguno"], "ans": 1, "exp": "Se requieren al menos 15 ganglios para estadificar bien el cáncer gástrico; la D2 reseca los ganglios perigástricos y de los vasos principales."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué estudio diagnostica el cáncer gástrico?", "opts": ["Endoscopia con biopsia", "Ultrasonido abdominal", "Radiografía de tórax", "Prueba de aliento"], "ans": 0, "exp": "La endoscopia ve la lesión y la biopsia confirma el diagnóstico; ningún estudio de imagen sustituye la histología."}]},
    {"id": "AP-R3-05", "grade": "R3", "tema": "Hígado, vía biliar y páncreas (HPB)", "chain": [{"p": "P1", "nivel": "base", "q": "¿Cuál es el tumor hepático primario maligno más frecuente en el adulto?", "opts": ["Colangiocarcinoma", "Adenoma", "Hemangioma", "Carcinoma hepatocelular"], "ans": 3, "exp": "El hepatocarcinoma es el cáncer primario de hígado más frecuente, asociado a cirrosis, hepatitis B/C y alcohol; el hemangioma es benigno."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué criterio limita la resección hepática en el paciente cirrótico?", "opts": ["El tamaño del tumor solamente", "La edad solamente", "La reserva funcional hepática (Child-Pugh, MELD y volumen del remanente futuro)", "El sexo"], "ans": 2, "exp": "En cirrosis lo que manda es cuánto hígado funcional queda; resecar de más causa insuficiencia hepática postoperatoria, aunque el tumor sea resecable técnicamente."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué tumor periampular se reseca con pancreaticoduodenectomía (Whipple)?", "opts": ["Tumor de cola de páncreas", "Tumor de cabeza de páncreas o periampular", "Tumor gástrico distal", "Tumor hepático izquierdo"], "ans": 1, "exp": "El Whipple reseca cabeza de páncreas, duodeno, vesícula y vía biliar distal con reconstrucción; la cola se reseca con pancreatectomía distal."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué marcador se eleva típicamente en el carcinoma hepatocelular?", "opts": ["Alfafetoproteína (AFP)", "CEA", "CA 19-9", "PSA"], "ans": 0, "exp": "La AFP se eleva en muchos hepatocarcinomas y se usa en vigilancia del cirrótico, aunque no es diagnóstica por sí sola."}]},
    {"id": "AP-R3-06", "grade": "R3", "tema": "Cirugía endocrina: tiroides, paratiroides y suprarrenal", "chain": [{"p": "P1", "nivel": "base", "q": "Nódulo tiroideo con TSH baja y captación alta en gammagrafía: ¿qué es?", "opts": ["Nódulo frío maligno", "Quiste simple", "Tiroiditis de Hashimoto", "Nódulo caliente autónomo (tóxico)"], "ans": 3, "exp": "El nódulo caliente produce hormona por su cuenta, suprime la TSH y rara vez es maligno; el frío no capta y tiene más riesgo de cáncer."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué complicación se vigila tras tiroidectomía total por lesión del nervio laríngeo recurrente?", "opts": ["Hipoglucemia", "Hipertensión arterial", "Disfonía y, si es bilateral, obstrucción de la vía aérea", "Diarrea"], "ans": 2, "exp": "El recurrente mueve las cuerdas vocales; su lesión unilateral da ronquera y la bilateral puede cerrar la glotis y exigir traqueostomía."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: en hiperparatiroidismo primario, ¿qué alteración bioquímica define el cuadro?", "opts": ["Calcio bajo con PTH baja", "Hipercalcemia con PTH elevada o inapropiadamente normal", "Hipocalcemia con PTH alta", "Calcio normal con PTH suprimida"], "ans": 1, "exp": "La paratiroides autónoma secreta PTH pese al calcio alto; por eso el calcio sube y la PTH no se suprime como debería."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué tumor suprarrenal causa hipertensión paroxística con cefalea, palpitaciones y sudoración?", "opts": ["Feocromocitoma", "Adenoma productor de aldosterona", "Carcinoma suprarrenal", "Quiste suprarrenal"], "ans": 0, "exp": "El feocromocitoma libera catecolaminas en crisis: hipertensión, cefalea, palpitaciones y sudoración; antes de operarlo se bloquea alfa."}]},
    {"id": "AP-R3-07", "grade": "R3", "tema": "Cirugía de tórax, pleura y mediastino", "chain": [{"p": "P1", "nivel": "base", "q": "Derrame pleural con líquido turbio, pH bajo y glucosa baja: ¿qué se sospecha?", "opts": ["Trasudado por insuficiencia cardiaca", "Hemotórax leve", "Quilotórax", "Empiema pleural"], "ans": 3, "exp": "El empiema es pus en la pleura: líquido turbio, pH <7.2 y glucosa baja; el trasudado cardiaco es claro, con pH normal y proteínas bajas."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿cuál es el tratamiento definitivo del empiema organizado con pulmón atrapado?", "opts": ["Antibiótico solo", "Toracocentesis única", "Decorticación quirúrgica", "Solo oxígeno"], "ans": 2, "exp": "La corteza fibrosa atrapa el pulmón y no se resuelve con tubo ni antibiótico; la decorticación retira la corteza y libera el pulmón."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué tumor del mediastino anterior es el más frecuente en el adulto?", "opts": ["Tumor neurogénico", "Timoma", "Quiste broncogénico", "Linfoma de Hodgkin"], "ans": 1, "exp": "En el mediastino anterior los timomas son los más frecuentes en el adulto; los neurogénicos predominan en el mediastino posterior."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué estudio de imagen se pide primero ante un nódulo pulmonar sospechoso?", "opts": ["Tomografía de tórax con contraste", "Radiografía de tórax", "Ultrasonido torácico", "Resonancia de tórax"], "ans": 0, "exp": "La TC caracteriza el nódulo, su tamaño, los ganglios y la extensión; la radiografía solo lo sugiere y no basta para decidir."}]},
    {"id": "AP-R3-08", "grade": "R3", "tema": "Cirugía vascular: aorta, carótida y enfermedad arterial periférica", "chain": [{"p": "P1", "nivel": "base", "q": "Dolor torácico desgarrante irradiado a espalda con diferencia de presión entre ambos brazos: ¿qué se sospecha?", "opts": ["Infarto agudo de miocardio", "Pericarditis", "Tromboembolia pulmonar", "Disección aórtica"], "ans": 3, "exp": "El dolor desgarrante con asimetría de pulsos o presión entre brazos es disección aórtica; el infarto da dolor opresivo sin esa asimetría."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: en disección aórtica tipo A de Stanford, ¿cuál es el tratamiento?", "opts": ["Solo control médico de la presión", "Endoprótesis siempre", "Cirugía urgente de la aorta ascendente", "Observación"], "ans": 2, "exp": "La tipo A (aorta ascendente) se opera de urgencia por riesgo de rotura y taponamiento; la tipo B no complicada se maneja médicamente."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué índice compara la presión sistólica del tobillo con la del brazo en enfermedad arterial periférica?", "opts": ["Índice de masa corporal", "Índice tobillo-brazo (ITB)", "Índice de choque", "Índice de Charlson"], "ans": 1, "exp": "El ITB <0.9 indica enfermedad arterial periférica; <0.4 sugiere isquemia grave y riesgo de pérdida de la extremidad."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué síntoma define la claudicación intermitente?", "opts": ["Dolor en la pantorrilla al caminar que cede con el reposo", "Dolor en reposo nocturno", "Dolor articular matutino", "Edema bilateral"], "ans": 0, "exp": "La claudicación es dolor muscular por isquemia al esfuerzo que desaparece al parar; el dolor en reposo ya es isquemia crítica."}]},
    {"id": "AP-R3-09", "grade": "R3", "tema": "Trauma complejo y cirugía de control de daños", "chain": [{"p": "P1", "nivel": "base", "q": "¿En qué consiste la cirugía de control de daños?", "opts": ["Operación definitiva completa en un solo tiempo", "Solo laparoscopia diagnóstica", "No operar nunca", "Control rápido de hemorragia y contaminación, cierre temporal y reanimación en terapia intensiva antes de la cirugía definitiva"], "ans": 3, "exp": "En el paciente exsanguinado e hipotérmico, la cirugía larga mata; se controla lo letal, se reanima y se vuelve después a la reparación definitiva."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿cuál es la tríada letal del trauma?", "opts": ["Fiebre, taquicardia y leucocitosis", "Hipotensión, bradicardia e hipertermia", "Hipotermia, acidosis y coagulopatía", "Dolor, vómito y diarrea"], "ans": 2, "exp": "Frío, ácido y sin coagular: cada uno empeora a los otros dos; romper la tríada con calor, sangre y control del sangrado es la prioridad."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: en trauma hepático grave con sangrado que no se controla con compresión, ¿qué maniobra temporal se usa?", "opts": ["Resección hepática inmediata", "Empaquetamiento (packing) perihepático", "Ligadura de la porta", "Solo cristaloides"], "ans": 1, "exp": "El packing comprime el hígado y controla el sangrado venoso hasta reanimar; la resección en el paciente inestable es casi siempre mortal."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué vía de acceso se usa en el paciente politraumatizado inestable con hemoperitoneo?", "opts": ["Laparotomía exploradora", "Laparoscopia", "Endoscopia", "Observación"], "ans": 0, "exp": "El inestable con sangre libre en abdomen se abre; la laparoscopia es para el estable seleccionado y la observación, para el estable sin sangrado activo."}]},
    {"id": "AP-R3-10", "grade": "R3", "tema": "Trasplante de órganos sólidos", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué órgano es el más trasplantado en el mundo?", "opts": ["Corazón", "Pulmón", "Hígado", "Riñón"], "ans": 3, "exp": "El trasplante renal es el más frecuente por la prevalencia de enfermedad renal terminal y la disponibilidad de donador vivo."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué fármaco inmunosupresor es la base del mantenimiento en la mayoría de los trasplantes?", "opts": ["Solo esteroide", "Solo antibiótico", "Inhibidor de calcineurina (tacrolimus o ciclosporina)", "Anticoagulante"], "ans": 2, "exp": "El tacrolimus es la base del mantenimiento inmunosupresor; los esteroides y el micofenolato lo acompañan, pero no lo sustituyen como eje."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué complicación vascular temprana amenaza el injerto hepático tras el trasplante?", "opts": ["Trombosis venosa profunda de la pierna", "Trombosis de la arteria hepática", "Várices esofágicas", "Estenosis de la vena cava"], "ans": 1, "exp": "La arteria hepática es el único aporte arterial del injerto; su trombosis causa necrosis biliar e insuficiencia del injerto y exige revascularización o retrasplante."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué se verifica antes de aceptar un donador de riñón vivo?", "opts": ["Compatibilidad, función renal del donador y ausencia de enfermedad que contraindique la donación", "Solo el grupo sanguíneo", "Solo la edad", "Nada, cualquiera puede donar"], "ans": 0, "exp": "El donador vivo se estudia completo: grupo, compatibilidad, función renal y salud general, porque debe quedar con un riñón sano para toda la vida."}]},
    {"id": "AP-R4-01", "grade": "R4", "tema": "Cirugía hepatobiliar avanzada", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué es la colangitis esclerosante primaria en una frase?", "opts": ["Infección aguda de la vesícula", "Litiasis del colédoco", "Tumor de la vesícula", "Enfermedad inflamatoria crónica que estrecha las vías biliares intra y extrahepáticas"], "ans": 3, "exp": "La colangitis esclerosante primaria fibrosa las vías biliares con estenosis múltiples; se asocia a colitis ulcerosa y a colangiocarcinoma."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué tumor de la confluencia biliar se conoce como tumor de Klatskin?", "opts": ["Adenoma hepático", "Carcinoma de vesícula", "Colangiocarcinoma hiliar", "Tumor de páncreas"], "ans": 2, "exp": "El Klatskin es el colangiocarcinoma de la confluencia de los hepáticos; su resección exige hepatectomía con reconstrucción biliar y margen R0."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué técnica aumenta el remanente hepático futuro antes de una hepatectomía mayor?", "opts": ["Quimioterapia sola", "Embolización portal preoperatoria", "Drenaje biliar sin cirugía", "Solo dieta"], "ans": 1, "exp": "Embolizar la porta del lado a resecar hipertrofia el remanente contralateral en semanas y hace resecable un hígado que antes era insuficiente."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué complicación temida sigue a una hepatectomía mayor?", "opts": ["Insuficiencia hepática postoperatoria", "Hiperglucemia leve", "Dolor de hombro", "Náusea leve"], "ans": 0, "exp": "Si el remanente es insuficiente, el hígado no cumple su función: ictericia, coagulopatía y encefalopatía; es la principal causa de muerte tras hepatectomía mayor."}]},
    {"id": "AP-R4-02", "grade": "R4", "tema": "Cirugía pancreática avanzada", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué tumor neuroendocrino pancreático causa hipoglucemia por exceso de insulina?", "opts": ["Gastrinoma", "VIPoma", "Glucagonoma", "Insulinoma"], "ans": 3, "exp": "El insulinoma secreta insulina sin freno: hipoglucemia en ayuno con síntomas neuroglucopénicos que ceden con glucosa (tríada de Whipple)."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué define que un cáncer de páncreas sea borderline resecable?", "opts": ["Metástasis a distancia", "Tumor menor de 1 cm", "Contacto limitado con vasos mesentéricos (porta o arteria mesentérica superior) sin oclusión completa, técnicamente resecable con reconstrucción vascular", "Ausencia de síntomas"], "ans": 2, "exp": "Borderline es el tumor con contacto vascular parcial que aún se puede resecar con reconstrucción, generalmente tras quimioterapia neoadyuvante; con metástasis ya es irresecable."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué complicación es la más temida tras pancreaticoduodenectomía?", "opts": ["Íleo leve", "Fístula pancreática postoperatoria", "Náusea", "Dolor de herida"], "ans": 1, "exp": "La fuga de la anastomosis pancreática activa enzimas, erosiona vasos y causa hemorragia y sepsis; es la complicación que más mata tras el Whipple."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué estudio estadifica el cáncer de páncreas y su relación vascular?", "opts": ["Tomografía multidetector con protocolo pancreático", "Radiografía simple", "Ultrasonido abdominal solo", "Colonoscopia"], "ans": 0, "exp": "La TC pancreática en fases arterial y venosa define resecabilidad, contacto vascular y metástasis; es el estudio que decide si se opera o se da neoadyuvancia."}]},
    {"id": "AP-R4-03", "grade": "R4", "tema": "Cirugía oncológica avanzada y carcinomatosis peritoneal", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué es la carcinomatosis peritoneal?", "opts": ["Infección del peritoneo", "Adherencias benignas", "Ascitis por cirrosis", "Siembra tumoral difusa sobre el peritoneo"], "ans": 3, "exp": "Es la diseminación de cáncer sobre la superficie peritoneal; antes se consideraba terminal, hoy en casos seleccionados se trata con citorreducción e HIPEC."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿en qué consiste la cirugía citorreductora con HIPEC?", "opts": ["Solo quimioterapia intravenosa", "Solo radioterapia", "Resección de todo el tumor visible en peritoneo más quimioterapia intraperitoneal hipertérmica", "Drenaje de ascitis"], "ans": 2, "exp": "Se quita todo el tumor macroscópico y se lava el abdomen con quimioterapia caliente para matar enfermedad microscópica; exige selección estricta del paciente."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué índice cuantifica la carga tumoral peritoneal?", "opts": ["Índice de Karnofsky", "Índice de carcinomatosis peritoneal (PCI)", "Índice de masa corporal", "Índice de Charlson"], "ans": 1, "exp": "El PCI puntúa el tumor en 13 regiones abdominales; un PCI alto predice citorreducción incompleta y peor pronóstico, y orienta si vale la pena operar."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué tumor es la indicación clásica de citorreducción con HIPEC?", "opts": ["Pseudomixoma peritoneal por tumor apendicular", "Cáncer de pulmón metastásico", "Cáncer de mama temprano", "Linfoma"], "ans": 0, "exp": "El pseudomixoma por neoplasia mucinosa apendicular es la indicación paradigmática de citorreducción e HIPEC, con supervivencia prolongada en casos seleccionados."}]},
    {"id": "AP-R4-04", "grade": "R4", "tema": "Cirugía colorrectal avanzada", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué es la escisión total del mesocolon (CME) en cáncer de colon?", "opts": ["Resección local del pólipo", "Solo quimioterapia", "Colectomía sin ganglios", "Resección del colon con su mesocolon completo en el plano embriológico, con ligadura vascular central"], "ans": 3, "exp": "La CME, análoga a la TME del recto, reseca el mesocolon íntegro con más ganglios y reduce la recurrencia local."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué es la vigilancia activa (watch and wait) en cáncer de recto?", "opts": ["No tratar nunca", "Operar sin neoadyuvancia", "Omitir la cirugía tras respuesta clínica completa a la neoadyuvancia, con vigilancia estrecha", "Solo quimioterapia paliativa"], "ans": 2, "exp": "Si el tumor desaparece clínicamente tras quimiorradioterapia, en centros expertos se puede vigilar sin operar, con rescate quirúrgico si reaparece."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué complicación define la fuga anastomótica colorrectal?", "opts": ["Íleo de 24 horas", "Dehiscencia de la anastomosis con salida de contenido intestinal o absceso perianastomótico", "Dolor leve de herida", "Estreñimiento postoperatorio"], "ans": 1, "exp": "La fuga es la falla de la anastomosis con contaminación; es la complicación más grave de la cirugía colorrectal y exige drenaje o reoperación."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué protege una anastomosis colorrectal baja de riesgo?", "opts": ["Ileostomía de protección temporal", "Nada, no se protege", "Solo antibiótico oral", "Ayuno de un mes"], "ans": 0, "exp": "La ileostomía desvía el contenido fecal y, si hay fuga, la convierte en un problema manejable en vez de una peritonitis fecal."}]},
    {"id": "AP-R4-05", "grade": "R4", "tema": "Cirugía esofagogástrica avanzada", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué operación se usa para el cáncer de esófago resecable?", "opts": ["Funduplicatura", "Solo dilatación", "Gastrectomía total siempre", "Esofagectomía con reconstrucción gástrica"], "ans": 3, "exp": "Se reseca el esófago enfermo y se sube el estómago tubularizado al tórax o cuello; es una de las cirugías más complejas por su morbilidad."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué complicación de la anastomosis esofagogástrica es la más temida?", "opts": ["Reflujo leve", "Náusea", "Fuga anastomótica con mediastinitis", "Pérdida de peso leve"], "ans": 2, "exp": "La fuga en el tórax contamina el mediastino y es mortal sin drenaje y soporte; por eso la vascularización del conducto gástrico es crítica."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué es la gastrectomía total con reconstrucción en Y de Roux?", "opts": ["Quitar solo el antro", "Quitar todo el estómago y conectar el esófago al yeyuno en Y de Roux", "Quitar el esófago", "Colocar una banda gástrica"], "ans": 1, "exp": "En cáncer gástrico proximal o difuso se quita todo el estómago y se reconstruye con yeyuno en Y para evitar el reflujo biliar al esófago."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué estudio valora la resecabilidad del cáncer de esófago?", "opts": ["Tomografía con PET-CT para enfermedad a distancia", "Endoscopia sola", "Radiografía simple", "Prueba de aliento"], "ans": 0, "exp": "El PET-CT detecta metástasis ocultas que la TC no ve y evita una esofagectomía fútil en enfermedad ya diseminada."}]},
    {"id": "AP-R4-06", "grade": "R4", "tema": "Trauma complejo, abdomen abierto y cuidados críticos", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué es el abdomen abierto?", "opts": ["Herida que no se cierra por infección", "Hernia ventral", "Laparotomía sin anestesia", "Abdomen que se deja sin cerrar la fascia, con cobertura temporal, para evitar hipertensión intraabdominal"], "ans": 3, "exp": "Tras control de daños o edema visceral, cerrar la fascia sube la presión intraabdominal y mata; se deja abierto con vacío o malla temporal y se cierra después."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué presión intraabdominal define el síndrome compartimental abdominal?", "opts": ["Mayor de 5 mmHg", "Cualquier presión positiva", "Presión sostenida mayor de 20 mmHg con disfunción orgánica", "Menor de 10 mmHg"], "ans": 2, "exp": "El síndrome compartimental es presión intraabdominal >20 mmHg con falla orgánica (renal, respiratoria); su tratamiento es descomprimir el abdomen."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: según Surviving Sepsis Campaign 2021, ¿qué se hace en la primera hora ante sepsis con hipotensión?", "opts": ["Esperar cultivos sin dar nada", "Medir lactato, tomar cultivos, dar antibiótico de amplio espectro y reanimar con cristaloides", "Dar vasopresor antes que líquidos", "Solo oxígeno"], "ans": 1, "exp": "La hora-1 de Surviving Sepsis: lactato, cultivos antes del antibiótico sin demorarlo, antibiótico temprano y líquidos; el vasopresor es si no responde a volumen."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué signo indica que el abdomen abierto con vacío está funcionando?", "opts": ["Drenaje de líquido peritoneal y descenso de la presión intraabdominal con mejoría de la diuresis", "Fiebre alta", "Distensión creciente", "Ausencia total de drenaje"], "ans": 0, "exp": "El vacío evacua líquido, baja la presión y el riñón vuelve a orinar; la distensión creciente y la anuria indican que el compartimento no se resolvió."}]},
    {"id": "AP-R4-07", "grade": "R4", "tema": "Cirugía endocrina, de cabeza y cuello y de mama (avanzada)", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué cáncer de tiroides es el más frecuente?", "opts": ["Medular", "Folicular", "Anaplásico", "Papilar"], "ans": 3, "exp": "El papilar es el cáncer tiroideo más común, de buen pronóstico y con diseminación linfática; el anaplásico es raro y agresivo."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué complicación metabólica sigue a la paratiroidectomía por hiperparatiroidismo grave de larga evolución?", "opts": ["Hipercalcemia persistente", "Hiperpotasemia", "Síndrome de hueso hambriento, con hipocalcemia por captación ósea de calcio", "Hipoglucemia"], "ans": 2, "exp": "Al quitar la paratiroides, el hueso desmineralizado absorbe calcio ávidamente y el calcio sérico cae; se previene con calcio y vitamina D."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué ganglio se diseca en el cáncer de mama con centinela positivo y alto riesgo axilar?", "opts": ["Solo el centinela", "Disección axilar completa de niveles I y II", "Ganglios cervicales", "Ninguno"], "ans": 1, "exp": "Con centinela positivo y criterios de alto riesgo se completa la disección axilar I–II; en casos seleccionados de bajo riesgo, la radioterapia puede sustituirla."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué estudio confirma un nódulo tiroideo sospechoso?", "opts": ["Biopsia por aspiración con aguja fina (BAAF)", "TSH sola", "Radiografía de cuello", "Gammagrafía sola"], "ans": 0, "exp": "La BAAF es el estudio que define si el nódulo es benigno o maligno; la TSH y la imagen orientan, pero no diagnostican."}]},
    {"id": "AP-R4-08", "grade": "R4", "tema": "Cirugía bariátrica y metabólica y pared abdominal compleja", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué índice de masa corporal define la obesidad mórbida (clase III)?", "opts": ["IMC mayor de 25", "IMC menor de 20", "IMC mayor de 30 sin comorbilidades", "IMC mayor de 40, o mayor de 35 con comorbilidades"], "ans": 3, "exp": "La cirugía bariátrica se indica con IMC ≥40 o ≥35 con diabetes, hipertensión o apnea del sueño, tras fallar el manejo médico."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿en qué consiste el bypass gástrico en Y de Roux?", "opts": ["Quitar todo el estómago", "Colocar una banda ajustable", "Crear un pequeño reservorio gástrico conectado al yeyuno en Y, con exclusión del resto gástrico y duodeno", "Solo dieta"], "ans": 2, "exp": "El bypass restringe y malabsorbe: el alimento pasa del reservorio al yeyuno sin pasar por duodeno, con remisión de diabetes en muchos casos."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué complicación tardía del bypass gástrico causa dolor abdominal postprandial por hernia interna?", "opts": ["Úlcera marginal", "Hernia interna por el defecto de Petersen o el ojal mesentérico", "Colelitiasis", "Reflujo leve"], "ans": 1, "exp": "Tras el bypass quedan defectos mesentéricos por donde se hernia el intestino; el dolor postprandial intermitente con obstrucción es hernia interna hasta demostrar lo contrario."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué es una hernia ventral compleja?", "opts": ["Hernia grande con pérdida de dominio, múltiples recidivas o pared contaminada", "Hernia pequeña reductible", "Hernia inguinal simple", "Lipoma de pared"], "ans": 0, "exp": "La pared compleja es defecto grande, pérdida de dominio o infección; exige planeación, malla y a veces separación de componentes, no una reparación simple."}]},
    {"id": "AP-R4-09", "grade": "R4", "tema": "Cirugía vascular, torácica y emergencias toracoabdominales", "chain": [{"p": "P1", "nivel": "base", "q": "¿Qué es un aneurisma de aorta abdominal?", "opts": ["Estrechamiento de la aorta", "Trombosis aórtica", "Disección de la aorta", "Dilatación de la aorta abdominal mayor de 3 cm"], "ans": 3, "exp": "Aneurisma es dilatación focal ≥3 cm (o 50% mayor que lo normal); el riesgo de rotura crece con el diámetro, y se opera electivamente a partir de ~5.5 cm en el hombre."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué síntoma indica rotura de aneurisma de aorta abdominal?", "opts": ["Dolor lumbar leve crónico", "Fiebre sin dolor", "Dolor abdominal o lumbar súbito, hipotensión y masa pulsátil", "Edema de piernas"], "ans": 2, "exp": "Dolor súbito con choque y masa pulsátil es rotura hasta demostrar lo contrario; es emergencia quirúrgica y no se espera la TC si el paciente está inestable."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué arteria se ocluye en la isquemia mesentérica aguda embólica?", "opts": ["Arteria renal", "Arteria mesentérica superior", "Arteria iliaca", "Arteria hepática"], "ans": 1, "exp": "La mesentérica superior irriga casi todo el intestino delgado; su oclusión embólica da dolor fuera de proporción con la exploración y exige revascularización urgente."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué estudio confirma la isquemia mesentérica aguda?", "opts": ["Angiotomografía de abdomen", "Radiografía simple", "Colonoscopia", "Electrocardiograma"], "ans": 0, "exp": "La angio-TC muestra la oclusión vascular y el sufrimiento intestinal; la radiografía es inespecífica y la colonoscopia no ve el intestino delgado."}]},
    {"id": "AP-R4-10", "grade": "R4", "tema": "Cirugía de trasplantes, bazo e inmunocomprometido", "chain": [{"p": "P1", "nivel": "base", "q": "¿Cuál es la indicación más frecuente de esplenectomía electiva?", "opts": ["Trauma esplénico", "Colecistitis", "Apendicitis", "Púrpura trombocitopénica inmune refractaria y enfermedades hematológicas"], "ans": 3, "exp": "El bazo destruye plaquetas en la PTI; la esplenectomía es tratamiento en casos refractarios, además de linfomas y anemias hemolíticas seleccionadas."}, {"p": "P2", "nivel": "sube", "q": "Si acierta, sube: ¿qué vacunación se da antes de una esplenectomía electiva?", "opts": ["Solo influenza", "Solo tétanos", "Neumococo, Haemophilus influenzae tipo b y meningococo (bacterias encapsuladas)", "Ninguna"], "ans": 2, "exp": "Sin bazo no se eliminan bacterias encapsuladas y la sepsis fulminante es el riesgo; por eso se vacuna antes de la cirugía electiva, al menos 2 semanas previas."}, {"p": "P3", "nivel": "sube", "q": "Sigue subiendo: ¿qué complicación infecciosa amenaza al trasplantado en el primer mes?", "opts": ["Citomegalovirus tardío", "Infección nosocomial bacteriana y de la herida quirúrgica", "Tuberculosis latente siempre", "Solo hongos"], "ans": 1, "exp": "En el primer mes predominan las infecciones quirúrgicas y nosocomiales; el citomegalovirus y los hongos aparecen después, con la inmunosupresión sostenida."}, {"p": "P4", "nivel": "rescata", "q": "Para rescatar la cadena: ¿qué órgano se trasplanta junto con el páncreas con más frecuencia?", "opts": ["Riñón (trasplante simultáneo riñón-páncreas en diabético con falla renal)", "Corazón", "Pulmón", "Hígado"], "ans": 0, "exp": "El diabético tipo 1 con enfermedad renal terminal recibe riñón y páncreas juntos; el páncreas solo es menos frecuente y más selectivo."}]},
  ],
  algoritmo: [
    {"id": "AA-R1-01", "grade": "R1", "title": "Evaluación primaria del politraumatizado (ABCDE)", "algoritmo": "Evaluación primaria ATLS — ABCDE.", "guia": "ATLS, 10.ª edición (American College of Surgeons).", "steps": ["Valorar la vía aérea con protección de la columna cervical.", "Valorar la respiración: frecuencia, saturación, movimientos torácicos y ruidos respiratorios.", "Controlar el sangrado externo con presión directa, torniquete o empaquetamiento.", "Valorar la circulación: pulso, presión, llenado capilar, sangrado externo visible y pelvis.", "Iniciar reanimación con líquidos y sangre según la respuesta, y buscar la fuente de sangrado.", "Valorar el estado neurológico: Glasgow, pupilas, glucemia capilar y lateralidad.", "Exponer al paciente y controlar la hipotermia (mantas, líquidos tibios, ambiente cálido).", "Pedir radiografía de tórax y pelvis, y FAST, como parte de la evaluación secundaria."], "exp": "la vía aérea mata en minutos y la respiración en segundos-minutos; nada de lo demás sirve si el paciente no ventila. El sangrado externo se controla antes de reponer volumen, porque reponer sin taponar es llenar un balde agujereado y además diluye factores de coagulación. La neurología va después de A-B-C porque una Glasgow baja puede ser hipoxia o choque, no solo lesión cerebral, y se malinterpreta si no se corrigió antes lo reversible. La exposición y la hipotermia cierran la primaria porque el frío empeora la coagulopatía, pero descubrir al paciente antes de asegurar A-B-C lo enfría sin haber ganado nada. La imagen (A) es evaluación secundaria: si se pide antes de la primaria, se pierde el tiempo dorado en la sala de rayos en vez de en la camilla de reanimación."},
    {"id": "AA-R1-02", "grade": "R1", "title": "Choque hemorrágico: clasificar, reponer y buscar la fuente", "algoritmo": "Manejo del choque hemorrágico y clasificación por clases.", "guia": "ATLS, 10.ª edición.", "steps": ["Colocar dos accesos venosos de grueso calibre y monitorizar signos vitales continuos.", "Controlar la hemorragia externa y la hipotermia, y evitar la cristaloidoterapia excesiva.", "Clasificar el choque (clases I–IV) por frecuencia cardiaca, presión arterial, presión de pulso, llenado capilar, frecuencia respiratoria, diuresis y estado mental.", "Reponer volumen inicial con cristaloides tibios y valorar si el paciente es respondedor, respondedor transitorio o no respondedor.", "Solicitar hemoglobina, lactato, gasometría, calcio y coagulación (TEG/ROTEM si hay).", "Activar el protocolo de transfusión masiva si hay choque clase III–IV o sangrado no controlado.", "Buscar la fuente de sangrado: tórax, abdomen, pelvis, retroperitoneo y huesos largos.", "Decidir el destino: quirófano, angioembolización o UCI, según la respuesta y la fuente."], "exp": "sin acceso venoso no hay reanimación posible, y sin control de la hemorragia externa todo lo que se infunde se pierde. Clasificar antes de reponer permite saber cuánto volumen se espera perder y qué respuesta esperar; clasificar después de litros de cristaloide ya no refleja la lesión sino la dilución. La respuesta a fluidos (respondedor / transitorio / no respondedor) es el dato que decide transfusión masiva y destino: un no respondedor no se \"sigue reponiendo\", se lleva a control quirúrgico del sangrado. Pedir laboratorios antes de clasificar y de dar el bolo inicial retrasa la reanimación por esperar números que al inicio son normales (la hemoglobina tarda en caer). Y el destino se decide al final, con fuente y respuesta conocidas: mandar a tomografía a un no respondedor es la forma clásica de perderlo en el pasillo."},
    {"id": "AA-R1-03", "grade": "R1", "title": "Reposición de líquidos: ¿responde o no responde?", "algoritmo": "Reanimación con cristaloides y valoración de la respuesta a fluidos.", "guia": "ATLS, 10.ª edición; Surviving Sepsis Campaign 2021 (para el contexto séptico).", "steps": ["Valorar el estado basal: signos vitales, peso, comorbilidades cardiacas o renales, pérdidas y electrolitos.", "Identificar el tipo de choque y su causa antes de elegir el fluido y la velocidad.", "Definir la meta: perfusión tisular adecuada (diuresis, presión arterial media, aclaramiento de lactato), no un número fijo de litros.", "Dar un bolo de cristaloide balanceado tibio y medir la respuesta.", "Reevaluar: presión arterial, frecuencia cardiaca, diuresis, estado mental, lactato y llenado capilar.", "Suspender o frenar los líquidos si hay signos de sobrecarga (estertores, ingurgitación yugular, edema, aumento de la presión venosa).", "Si no responde, escalar: vasopresores, sangre o inotrópicos según la causa, no más litros a ciegas.", "Corregir electrolitos (sodio, potasio, calcio) y reponer el potasio solo con diuresis comprobada."], "exp": "dar líquidos sin saber el estado basal ni el tipo de choque es tratar a ciegas: un cardiógeno se ahoga con el mismo bolo que salva a un hipovolémico. La meta se fija antes del bolo porque si no, cada litro \"parece poco\" y se termina en sobrecarga. La reevaluación es el paso que convierte un bolo en una prueba diagnóstica: sin ella no se sabe si el paciente respondió, y se sigue infundiendo por inercia. Escalar a vasopresores o sangre solo tiene sentido después de demostrar que no responde a fluidos; hacerlo antes enmascara la causa y retrasa el tratamiento correcto. El potasio va al final y con diuresis comprobada porque reponerlo en anuria u oliguria es fabricar una hiperpotasemia."},
    {"id": "AA-R1-04", "grade": "R1", "title": "Transfusión masiva y coagulopatía del trauma", "algoritmo": "Transfusión masiva balanceada y prevención de la tríada letal.", "guia": "ATLS, 10.ª edición; guías de transfusión masiva y control de daños (European guideline on management of major bleeding, 2023).", "steps": ["Reconocer el sangrado masivo: choque clase III–IV, sangrado visible no controlado o necesidad prevista de transfusión masiva.", "Activar el protocolo de transfusión masiva y avisar al banco de sangre.", "Dar ácido tranexámico precoz (dentro de las primeras 3 horas del sangrado).", "Transfundir en proporción balanceada (aprox. 1:1:1 de concentrados eritrocitarios, plasma y plaquetas) y reponer fibrinógeno si está bajo.", "Controlar quirúrgicamente o por angioembolización la fuente de sangrado en paralelo a la transfusión.", "Guiar la reposición con pruebas de coagulación viscoelástica (TEG/ROTEM) o coagulación convencional si no hay.", "Corregir calcio (el citrato del banco de sangre lo baja), potasio, temperatura y acidosis.", "Reevaluar hemoglobina, lactato y coagulación, y desescalar el protocolo cuando el sangrado se controla."], "exp": "reconocer y activar van primero porque el banco de sangre tarda en preparar los paquetes; si se pide sangre unidad por unidad, el paciente se desangra esperando. El tranexámico solo sirve precoz: después de 3 horas pierde beneficio y puede hacer daño, así que no puede esperar a que \"lleguen los laboratorios\". La proporción balanceada va antes que guiarse por laboratorios porque al inicio no hay tiempo de esperar resultados y la coagulopatía ya está instalada; los laboratorios ajustan después, no deciden el inicio. El control de la fuente corre en paralelo, nunca después de \"estabilizar\": no hay estabilización posible sin taponar el agujero. El calcio y la temperatura se corrigen durante la transfusión, no antes, porque cada unidad transfundida baja más el calcio y enfría más; y desescalar al final evita seguir transfundiendo a un paciente ya controlado, con el riesgo de sobrecarga y TRALI que eso trae."},
    {"id": "AA-R1-05", "grade": "R1", "title": "Sepsis quirúrgica: el paquete de la primera hora", "algoritmo": "Reconocimiento y paquete inicial de sepsis y choque séptico.", "guia": "Surviving Sepsis Campaign 2021.", "steps": ["Reconocer la sepsis: sospecha de infección + disfunción orgánica (qSOFA/SOFA, hipotensión, lactato alto, oliguria, alteración mental).", "Medir lactato inicial y repetirlo para valorar el aclaramiento.", "Tomar hemocultivos y cultivos del foco antes del antibiótico, sin retrasarlo.", "Iniciar antibiótico de amplio espectro dentro de la primera hora del reconocimiento.", "Dar cristaloides balanceados y valorar la respuesta; vasopresor (norepinefrina) si la presión arterial media no se sostiene.", "Buscar y controlar el foco quirúrgico (drenaje, desbridamiento o cirugía de control de daños) lo antes posible.", "Monitorizar diuresis, estado mental, saturación y presión arterial media como metas de perfusión.", "Reevaluar a la hora: lactato, presión, diuresis y necesidad de escalar o de control de foco."], "exp": "sin reconocer la sepsis no hay paquete que valga: cada hora de retraso en el antibiótico empeora la mortalidad, y el reloj empieza en el reconocimiento, no en la confirmación. El lactato se mide al inicio porque es el marcador que define gravedad y respuesta; medirlo después del bolo ya no dice de dónde partió. Los cultivos van antes del antibiótico pero sin retrasarlo: si se invierte el orden se pierde la microbiología, y si se espera al cultivo para dar el antibiótico se pierde al paciente. El control del foco es el paso quirúrgico que ningún antibiótico sustituye: un absceso no drenado seguirá sembrando bacterias por más antibiótico y vasopresor que se den. La reevaluación a la hora cierra el círculo porque la sepsis cambia rápido: un paciente que \"ya se trató\" y no se revalora es un paciente que se deteriora en silencio."},
    {"id": "AA-R1-06", "grade": "R1", "title": "Infección del sitio quirúrgico: clasificar y actuar", "algoritmo": "Clasificación y manejo de la infección del sitio quirúrgico (ISQ).", "guia": "CDC / NHSN, clasificación de heridas y de ISQ; guías WHO de prevención de ISQ 2018.", "steps": ["Valorar signos de alarma: eritema que avanza, dolor desproporcionado, fiebre, secreción purulenta, crepitación o necrosis.", "Valorar si hay infección necrosante de tejidos blandos: dolor fuera de proporción, bullas, crepitación, choque.", "Clasificar la herida (limpia, limpia-contaminada, contaminada, sucia) y el tipo de ISQ (superficial, profunda, órgano/espacio).", "Explorar la herida: abrir, drenar y tomar cultivo si hay colección, dehiscencia o signos de infección profunda.", "Iniciar antibiótico empírico dirigido al probable germen y al tipo de cirugía, y ajustarlo con el cultivo.", "Desbridar tejido necrótico y reevaluar la herida en curaciones seriadas; considerar cierre diferido o terapia de presión negativa.", "Revisar la profilaxis que se dio (o no se dio): antibiótico, momento, dosis, normotermia y glucemia.", "Documentar, notificar al equipo quirúrgico y dar seguimiento ambulatorio con signos de alarma por escrito."], "exp": "los signos de alarma y la fascitis necrosante van primero porque son lo único que mata en horas: una ISQ superficial espera, una fascitis no. Clasificar antes de explorar es ponerle nombre a algo que no se ha visto; la exploración es la que dice si hay pus, fascia gris o músculo muerto, y eso cambia la clasificación. El cultivo se toma al abrir, no después del antibiótico, o se cultiva el antibiótico. El desbridamiento va después del antibiótico inicial pero antes de revisar la profilaxis, porque la profilaxis es un análisis retrospectivo útil para el futuro, no un tratamiento del paciente que está infectado ahora. Documentar al final no es burocracia: sin registro, la ISQ no existe para vigilancia y el siguiente paciente recibe la misma profilaxis fallida."},
    {"id": "AA-R1-07", "grade": "R1", "title": "Herida compleja: ¿cierra, se deja abierta o presión negativa?", "algoritmo": "Manejo de la herida quirúrgica compleja y decisión de cierre.", "guia": "Guías WSES de manejo de heridas e infecciones de tejidos blandos; principios de cicatrización (Schwartz).", "steps": ["Valorar la herida: profundidad, tejido viable o necrótico, exudado, infección, bordes y tensión.", "Valorar factores que impiden el cierre: contaminación, edema, pérdida de tejido, isquemia o fístula.", "Desbridar el tejido no viable y controlar la infección y el exudado.", "Optimizar al paciente: perfusión, glucemia, nutrición, tabaquismo, anemia y medicamentos que frenan la cicatrización.", "Decidir el plan de cierre: primario, diferido, segunda intención o terapia de presión negativa (VAC).", "Si hay dehiscencia con evisceración, cubrir con apósito estéril húmedo, ayuno, sonda nasogástrica si aplica y llevar a quirófano.", "Proteger la herida con el apósito adecuado y programar curaciones con reevaluación seriada.", "Dar seguimiento: fotografiar/medición seriada, signos de alarma y criterios de alta o de reintervención."], "exp": "valorar antes de decidir es obvio pero es el error más común: cerrar una herida contaminada, isquémica o con fístula es fabricar una dehiscencia. El desbridamiento va antes de optimizar al paciente porque el tejido muerto es un foco de infección activo; optimizar sin desbridar es perfundir tejido muerto. La decisión de cierre solo tiene sentido con la herida limpia y el paciente optimizado: decidirla antes es comprometerse con un plan que la herida no va a cumplir. La evisceración es la excepción que salta la fila: no se \"valora y se programa\", se cubre y se va a quirófano, porque cada minuto expuesto es peritonitis. El apósito y el seguimiento cierran porque una herida que no se mide no se sabe si mejora o empeora."},
    {"id": "AA-R1-08", "grade": "R1", "title": "Abdomen agudo: del síntoma al diagnóstico sin perder tiempo", "algoritmo": "Abordaje diagnóstico inicial del abdomen agudo.", "guia": "Guías WSES de abdomen agudo (2020); principios de exploración abdominal (Schwartz).", "steps": ["Estabilizar primero si hay choque, deshidratación o sepsis: acceso venoso, líquidos, ayuno, sonda y monitoreo.", "Hacer historia dirigida: inicio, migración, carácter, irradiación, síntomas asociados, última ingesta, cirugías previas y comorbilidades.", "Explorar: inspección, auscultación, palpación, percusión, signos peritoneales y tacto rectal si aplica.", "Formular la hipótesis diagnóstica y el diagnóstico diferencial por cuadrante y por edad/sexo.", "Pedir laboratorios dirigidos: biometría, electrolitos, lactato, gasometría, función renal y hepática, amilasa/lipasa, examen de orina y prueba de embarazo.", "Pedir imagen según la sospecha: ecografía, tomografía con contraste o radiografía, no \"de rutina\" sin hipótesis.", "Decidir: observación, manejo médico, cirugía urgente o interconsulta (ginecología, urología, medicina interna).", "Reevaluar con exploración seriada: el abdomen agudo cambia en horas y la primera exploración no es la definitiva."], "exp": "estabilizar va primero porque un abdomen agudo con choque no espera a la historia completa; se reanima mientras se pregunta. La historia y la exploración van antes que los laboratorios y la imagen porque son las que formulan la hipótesis: pedir tomografía sin hipótesis es disparar a ciegas y encontrar hallazgos incidentales que confunden. El diferencial por cuadrante y edad/sexo es el paso que evita el error clásico de operar una apendicitis que era un embarazo ectópico o una torsión ovárica. La decisión se toma con historia, exploración, laboratorios e imagen juntos, no con un solo estudio. Y la exploración seriada es el cierre obligado: el abdomen agudo evoluciona, y el paciente que \"no tenía peritonismo\" a las 8 puede tenerlo a las 12; darlo de alta sin reevaluar es perder el diagnóstico en el momento en que se hizo evidente."},
    {"id": "AA-R1-09", "grade": "R1", "title": "Colecistitis aguda: Tokio TG18, de la sospecha al quirófano", "algoritmo": "Diagnóstico, severidad y momento quirúrgico de la colecistitis aguda.", "guia": "Tokyo Guidelines 2018 (TG18).", "steps": ["Hacer historia y exploración: dolor en hipocondrio derecho, Murphy positivo, fiebre, náusea y antecedente de cólico biliar.", "Descartar diagnósticos diferenciales: colangitis, coledocolitiasis, pancreatitis, hepatitis, úlcera perforada.", "Confirmar el diagnóstico con los criterios TG18: inflamación local (Murphy, dolor en hipocondrio derecho), inflamación sistémica (fiebre, leucocitosis, PCR) e imagen característica (ecografía o tomografía).", "Clasificar la severidad TG18: grado I leve, grado II moderada, grado III grave (disfunción orgánica).", "Iniciar manejo de soporte: ayuno, líquidos, analgesia, antieméticos y antibiótico si hay infección.", "Valorar riesgo quirúrgico y comorbilidades, y optimizar lo optimizable.", "Decidir el momento y el tipo de colecistectomía: laparoscópica temprana (dentro de las primeras 72 h del inicio en grado I–II) frente a drenaje percutáneo y cirugía diferida en grado III o alto riesgo.", "Seguimiento postoperatorio y estudio de la pieza; si no se operó, plan de colecistectomía de intervalo y signos de alarma."], "exp": "la clínica y el diferencial van antes que los criterios TG18 porque TG18 confirma, no inventa: un Murphy positivo con fiebre puede ser colangitis, y operar una colangitis como colecistitis es el error que se paga en UCI. La severidad se clasifica antes de decidir el momento quirúrgico porque es la severidad —no la preferencia del cirujano— la que dice si se opera temprano o se drena y se difiere. El soporte se inicia después de clasificar pero antes de la valoración de riesgo, porque un grado III se deteriora mientras se \"optimiza\" en papel. Y el plan de intervalo no es un alta sin más: el paciente no operado que se va sin fecha ni signos de alarma es el que regresa en colangitis o con una vesícula perforada."},
    {"id": "AA-R1-10", "grade": "R1", "title": "Nutrición perioperatoria: detectar, alimentar, no ayunar de más", "algoritmo": "Tamizaje, valoración y soporte nutricional perioperatorio.", "guia": "ESPEN 2021 (nutrición en cirugía); ERAS Society (recuperación mejorada después de cirugía).", "steps": ["Tamizar a todo paciente quirúrgico con una herramienta validada (NRS-2002 o MUST) al ingreso.", "Valorar al paciente en riesgo: pérdida de peso, ingesta, masa muscular, albúmina y comorbilidades.", "Iniciar soporte nutricional preoperatorio en el desnutrido o en riesgo (7–14 días si la cirugía es electiva y lo permite).", "Evitar el ayuno prolongado: líquidos claros hasta 2 h antes y carga de carbohidratos según ERAS, salvo contraindicación.", "Elegir la vía: oral primero, enteral si no cubre, parenteral solo si el tubo digestivo no es utilizable o no alcanza.", "Iniciar nutrición enteral temprana en el postoperatorio (dentro de las primeras 24 h si el tubo lo permite).", "Monitorizar tolerancia, glucemia, electrolitos (vigilar síndrome de realimentación) y función intestinal.", "Dar de alta con plan nutricional, suplementos si aplican y seguimiento; reevaluar en la consulta."], "exp": "el tamizaje va primero porque la desnutrición es invisible si no se busca: el paciente \"que se ve bien\" puede llevar 10 kg perdidos. La valoración completa solo se hace en quien el tamizaje marcó en riesgo; tamizar a todos y valorar a todos es inviable y valorar a nadie es negligente. El soporte preoperatorio va antes de la cirugía, no después, porque operar a un desnutrido sin prepararlo es programar la dehiscencia y la infección. Evitar el ayuno prolongado es un paso independiente del soporte: hasta el paciente bien nutrido se daña con 12 horas de ayuno innecesario. La vía se elige por el principio de \"si el tubo funciona, úsalo\": la parenteral antes que la enteral es más cara, más infecciosa y atrofia el intestino. Y el monitoreo del síndrome de realimentación es el paso que salva al desnutrido que por fin se alimenta: realimentar sin vigilar fósforo, potasio y magnesio es el error que convierte un éxito nutricional en una arritmia."},
    {"id": "AA-R2-01", "grade": "R2", "title": "ERGE y disfagia: ¿reflujo, motor o alarma?", "algoritmo": "Abordaje de la enfermedad por reflujo gastroesofágico y la disfagia.", "guia": "Guías ACG 2022 (ERGE); criterios de Lyon para ERGE (2018).", "steps": ["Hacer historia: pirosis, regurgitación, disfagia, dolor torácico, síntomas extraesofágicos y factores que lo agravan.", "Buscar datos de alarma: disfagia progresiva, pérdida de peso, anemia, hematemesis, edad avanzada de inicio o antecedente familiar de cáncer.", "Valorar medidas generales: peso, dieta, no acostarse tras comer, elevar cabecera y evitar tabaco y alcohol.", "Iniciar inhibidor de bomba de protones (IBP) en dosis estándar por 8 semanas si no hay alarma y el cuadro es típico.", "Reevaluar respuesta al IBP y ajustar: si responde, mantener la dosis mínima eficaz; si no, escalar el estudio antes que subir la dosis a ciegas.", "Hacer endoscopia si hay alarma, si no responde al IBP o si hay sospecha de esófago de Barrett o estenosis.", "Si la endoscopia es normal y persiste, hacer monitoreo de pH-impedancia y manometría de alta resolución (descartar acalasia y trastornos motores).", "Si se confirma ERGE refractaria o hernia hiatal con indicación, valorar cirugía antirreflujo (funduplicatura) en centro con experiencia."], "exp": "la historia y las alarmas van antes que el IBP porque un cáncer de esófago tratado como \"reflujo\" pierde meses: el IBP mejora los síntomas de casi todo y enmascara lo grave. Las medidas generales van antes o junto con el IBP, no después del fracaso, porque sin ellas el IBP trabaja contra el paciente. La reevaluación a las 8 semanas es el paso que separa al que responde del refractario; subir la dosis sin reevaluar es tratar el fracaso con más de lo mismo. La endoscopia y la manometría van después del fracaso terapéutico porque son las que distinguen reflujo verdadero, hipersensibilidad y trastorno motor (una acalasia operada como reflujo es un desastre). Y la cirugía va al final, con diagnóstico objetivo confirmado: operar un reflujo sin pH ni manometría es operar un síntoma, no una enfermedad."},
    {"id": "AA-R2-02", "grade": "R2", "title": "Hemorragia digestiva alta: ¿quién se va a casa y quién a endoscopia urgente?", "algoritmo": "Estratificación y manejo inicial de la hemorragia digestiva alta.", "guia": "Guías ACG 2021 (hemorragia digestiva alta); Glasgow-Blatchford Score.", "steps": ["Estabilizar: vía aérea si hay hematemesis masiva o alteración mental, accesos venosos, monitoreo y ayuno.", "Calcular Glasgow-Blatchford al ingreso (hemoglobina, presión, pulso, melena, síncope, comorbilidades, urea).", "Transfundir con estrategia restrictiva (umbral habitual de hemoglobina 7 g/dL en el paciente estable sin comorbilidad cardiaca grave).", "Dar IBP intravenoso en dosis alta y corregir coagulopatía; suspender anticoagulantes según el riesgo.", "Hacer endoscopia dentro de las primeras 24 h (urgente si hay inestabilidad o sangrado activo) y tratar la lesión (inyección, clip, banda o terapia térmica según la causa).", "Clasificar la lesión con Forrest en úlcera péptica y decidir si necesita segunda mirada o cirugía.", "Si el sangrado no se controla por endoscopia, escalar: angiografía con embolización o cirugía.", "Si Glasgow-Blatchford es 0–1 y no hay otros riesgos, considerar manejo ambulatorio con endoscopia programada y seguimiento estrecho."], "exp": "estabilizar va antes que puntuar: un Blatchford no resucita a nadie. El puntaje va antes de la endoscopia porque es el que dice quién necesita endoscopia urgente, quién puede esperar 24 h y quién se puede ir a casa; sin él, todos van a endoscopia urgente o todos esperan, y ambas cosas están mal. La transfusión restrictiva va antes de la endoscopia porque transfundir de más eleva la presión portal y puede reactivar el sangrado. El IBP se da antes de la endoscopia porque estabiliza el coágulo y mejora la visibilidad, pero no sustituye a la endoscopia. Forrest se clasifica después de ver la lesión, no antes: es un hallazgo endoscópico, no una predicción. Y el alta ambulatoria es una decisión del final, con puntaje bajo y endoscopia programada asegurada; darla de alta solo por \"verse bien\" sin puntaje es el alta que regresa sangrando."},
    {"id": "AA-R2-03", "grade": "R2", "title": "Absceso hepático: ¿antibiótico solo, aguja o drenaje?", "algoritmo": "Diagnóstico y manejo del absceso hepático (piogénico y amebiano).", "guia": "Guías WSES de infecciones intraabdominales; guías IDSA de absceso hepático.", "steps": ["Hacer historia y exploración: fiebre, dolor en hipocondrio derecho, antecedente de viaje, diarrea, enfermedad biliar o diabetes.", "Descartar diagnósticos diferenciales: quiste hidatídico, tumor necrosado, colangitis, colecistitis.", "Pedir laboratorios: biometría, función hepática, PCR, hemocultivos y serología para ameba si hay sospecha.", "Confirmar con imagen: ecografía o tomografía con contraste (tamaño, número, localización, pared, gas).", "Iniciar antibiótico empírico de amplio espectro (y metronidazol si se sospecha amebiano).", "Decidir drenaje: aspiración con aguja o drenaje percutáneo guiado por imagen según tamaño, localización y respuesta.", "Si el drenaje percutáneo falla, hay rotura o el absceso es multilocular complejo, valorar drenaje quirúrgico.", "Seguimiento con imagen seriada, duración del antibiótico según respuesta y estudio de la causa (vía biliar, portal, arterial)."], "exp": "la historia y el diferencial van antes que la imagen porque el error grave es pinchar un quiste hidatídico creyendo que es un absceso: la punción de un hidatídico puede causar anafilaxia y siembra. Los cultivos y la serología se piden antes del antibiótico para no esterilizar la muestra, pero el antibiótico no espera al resultado. El drenaje se decide con la imagen en mano (tamaño, número, localización): un absceso pequeño puede resolverse solo con antibiótico y uno grande no, y decidirlo sin medirlo es apostar. La cirugía es el rescate, no el primer paso: la mayoría se resuelve con antibiótico y drenaje percutáneo, y operar de entrada somete al paciente a un riesgo innecesario. Y buscar la causa al final no es opcional: un absceso \"curado\" sin estudiar la vía biliar es un absceso que regresa."},
    {"id": "AA-R2-04", "grade": "R2", "title": "Colangitis aguda: Tokio TG18 y drenaje biliar urgente", "algoritmo": "Diagnóstico, severidad y drenaje biliar en la colangitis aguda.", "guia": "Tokyo Guidelines 2018 (TG18) — colangitis aguda.", "steps": ["Hacer historia y exploración: fiebre, ictericia, dolor en hipocondrio derecho (tríada de Charcot), hipotensión o alteración mental (pentada de Reynolds).", "Descartar colangitis supurativa grave y choque séptico de origen biliar.", "Confirmar el diagnóstico con los criterios TG18: inflamación sistémica, colestasis y imagen de la vía biliar.", "Clasificar la severidad TG18: grado I leve, grado II moderada, grado III grave (disfunción orgánica).", "Iniciar soporte: líquidos, antibiótico de amplio espectro y corrección de la coagulopatía.", "Decidir el drenaje biliar: CPRE urgente (en las primeras 24 h si es grado III o no responde), percutáneo o quirúrgico según disponibilidad y anatomía.", "Estudiar la causa de la obstrucción: coledocolitiasis, estenosis, tumor o parásitos.", "Después del drenaje, planear el tratamiento definitivo de la causa (colecistectomía, extracción de litos, prótesis o cirugía) y seguimiento."], "exp": "la tríada de Charcot y la pentada de Reynolds se buscan primero porque son el reconocimiento clínico que dispara todo lo demás; una colangitis grave no se \"confirma con calma\". La severidad se clasifica antes del drenaje porque es la que fija la urgencia: un grado III no espera a mañana. El antibiótico y los líquidos se inician antes del drenaje pero no lo sustituyen: en colangitis, el drenaje es el tratamiento, el antibiótico es el acompañamiento; drenar tarde con antibiótico perfecto sigue siendo tarde. Estudiar la causa va después del drenaje porque la obstrucción hay que resolverla primero para que el paciente sobreviva a su estudio. Y el tratamiento definitivo va al final, con el paciente drenado y estable: hacer la colecistectomía definitiva en plena colangitis grave es operar en el peor momento posible."},
    {"id": "AA-R2-05", "grade": "R2", "title": "Coledocolitiasis: ¿CPRE antes, durante o después de la colecistectomía?", "algoritmo": "Estratificación de riesgo y manejo de la coledocolitiasis.", "guia": "Guías ASGE 2019 (estratificación de riesgo de coledocolitiasis); Tokyo Guidelines 2018.", "steps": ["Hacer historia, exploración y laboratorios: patrón colestásico, bilirrubina, fosfatasa alcalina y antecedente de cólico o pancreatitis.", "Estratificar el riesgo de coledocolitiasis según ASGE: alto, intermedio o bajo (lito visible, dilatación del colédoco, bilirrubina).", "Si el riesgo es intermedio, hacer colangiorresonancia o ultrasonido endoscópico antes de decidir.", "Si el riesgo es alto, hacer CPRE preoperatoria con extracción del lito.", "Si el riesgo es bajo, hacer colecistectomía laparoscópica sin estudio adicional de la vía biliar.", "En la colecistectomía, hacer colangiografía transcística si hay duda o hallazgo intraoperatorio.", "Si se encuentra un lito durante la cirugía, resolverlo: exploración laparoscópica de la vía biliar o CPRE postoperatoria.", "Seguimiento: confirmar la vía biliar libre y vigilar lito residual, colangitis o pancreatitis."], "exp": "estratificar va antes que cualquier procedimiento porque la CPRE no es inocua (pancreatitis post-CPRE, sangrado, perforación): hacerla a todos es dañar a los de bajo riesgo, y no hacerla a los de alto riesgo es dejar un lito que dará colangitis. El estudio no invasivo (colangiorresonancia o ecoendoscopia) va en el riesgo intermedio, no en el alto: en el alto se va directo a CPRE terapéutica, y estudiarlo antes solo retrasa el tratamiento. La colecistectomía sin estudio adicional solo es correcta en riesgo bajo, con la estratificación ya hecha; hacerla sin estratificar es apostar a que no hay lito. La colangiografía intraoperatoria es el seguro de la cirugía, no el plan principal: si se usa como sustituto de la estratificación preoperatoria, se descubre el lito cuando ya no hay endoscopista disponible. Y el seguimiento final confirma lo que todo el algoritmo prometió: una vía biliar libre, no solo una vesícula extirpada."},
    {"id": "AA-R2-06", "grade": "R2", "title": "Pancreatitis aguda: Atlanta revisada y el paso a paso (step-up)", "algoritmo": "Diagnóstico, severidad y manejo escalonado de la pancreatitis aguda.", "guia": "Clasificación de Atlanta revisada 2012; guías IAP/APA 2013 y WSES 2020 (pancreatitis necrotizante).", "steps": ["Confirmar el diagnóstico: dolor típico + lipasa/amilasa ≥3 veces el límite + imagen si hace falta (dos de tres criterios).", "Buscar la causa: biliar (ecografía), alcohol, triglicéridos, fármacos, hipercalcemia, post-CPRE.", "Iniciar reanimación con cristaloides, analgesia, ayuno inicial breve y corrección de electrolitos.", "Valorar con BISAP o APACHE II al ingreso y reevaluar la falla orgánica a las 48 h.", "Clasificar la severidad según Atlanta revisada: leve, moderadamente grave o grave (falla orgánica transitoria o persistente, complicaciones locales).", "Iniciar alimentación enteral temprana cuando el dolor y la náusea lo permitan; evitar la nutrición parenteral prolongada.", "Si hay necrosis infectada o deterioro, aplicar el abordaje escalonado (step-up): antibiótico, drenaje percutáneo o endoscópico, y necrosectomía mínimamente invasiva solo si es necesario, diferida de preferencia.", "Seguimiento: estudio de la causa biliar (colecistectomía en el mismo ingreso si es leve), colecciones y pseudoquiste."], "exp": "confirmar el diagnóstico va primero porque la lipasa alta sin dolor típico no es pancreatitis y el dolor típico con lipasa normal tampoco la descarta; los tres criterios evitan operar una \"pancreatitis\" que era otra cosa. La causa se busca temprano porque cambia el tratamiento (una biliar se opera, una por triglicéridos se trata médicamente). La severidad se clasifica a las 48 h, no al ingreso: Atlanta revisada exige ver si la falla orgánica persiste, y clasificar al ingreso es adivinar. La alimentación enteral temprana va antes que cualquier intervención sobre la necrosis porque el intestino alimentado protege contra la infección de la necrosis; ayunar \"por si acaso\" durante días es alimentar la infección. El step-up es el último recurso y diferido: necrosectomía precoz en necrosis estéril es el error histórico de la pancreatitis, y el drenaje percutáneo antes que la cirugía abierta es lo que bajó la mortalidad. Y la colecistectomía en el mismo ingreso (si es leve y biliar) es el cierre que evita la recurrencia: dar de alta sin operarla es programar la segunda pancreatitis."},
    {"id": "AA-R2-07", "grade": "R2", "title": "Apendicitis aguda: Alvarado, imagen y momento quirúrgico", "algoritmo": "Estratificación clínica e imagen en la sospecha de apendicitis aguda.", "guia": "Escala de Alvarado; guías WSES 2020 (apendicitis aguda, actualización Jerusalem).", "steps": ["Hacer historia: migración del dolor periumbilical a fosa ilíaca derecha, anorexia, náusea/vómito después del dolor, fiebre.", "Explorar: McBurney, Blumberg, Rovsing, psoas y obturador; tacto rectal si hay duda.", "Pedir laboratorios: biometría con diferencial, PCR, examen de orina y prueba de embarazo en mujeres en edad fértil.", "Calcular la escala de Alvarado (migración, anorexia, náusea, dolor en fosa ilíaca derecha, rebote, fiebre, leucocitosis, neutrofilia).", "Si Alvarado es bajo, observar o buscar otro diagnóstico; si es intermedio, hacer imagen (ecografía primero, tomografía si no es concluyente).", "Si Alvarado es alto o la imagen confirma, preparar para apendicectomía (antibiótico preoperatorio, ayuno, consentimiento).", "En el quirófano, clasificar: no complicada, gangrenosa, perforada o con absceso, y decidir laparoscopia frente a cirugía abierta.", "Si hay absceso o flemón, valorar manejo conservador con antibiótico y drenaje percutáneo, y apendicectomía de intervalo."], "exp": "la historia va primero porque la secuencia dolor-vómito es la firma de la apendicitis: si el vómito precede al dolor, el diagnóstico es otro y Alvarado no lo rescata. Los laboratorios van antes que Alvarado porque la escala los necesita (leucocitosis y neutrofilia son dos de sus puntos); calcularla sin ellos es inventarla. La imagen se reserva para el Alvarado intermedio: en el alto se opera y en el bajo se observa; hacer tomografía a todos irradia y retrasa, y no hacerla a los intermedios opera apéndices sanos. La clasificación intraoperatoria es la que decide el antibiótico postoperatorio y la duración: una no complicada no necesita días de antibiótico y una perforada sí. Y el absceso/flemón es la excepción que invierte la lógica: ahí no se opera de entrada, se drena y se difiere, porque operar un flemón es convertir una apendicectomía en una hemicolectomía."},
    {"id": "AA-R2-08", "grade": "R2", "title": "Obstrucción intestinal: ¿íleo, obstrucción o isquemia?", "algoritmo": "Abordaje de la obstrucción intestinal y detección de isquemia.", "guia": "Guías WSES 2018 (obstrucción intestinal adhesiva); guías de isquemia mesentérica.", "steps": ["Estabilizar: ayuno, sonda nasogástrica, líquidos, corrección de electrolitos y monitoreo de diuresis.", "Hacer historia: cirugías previas, hernias, dolor cólico, distensión, vómito, última evacuación y gases.", "Explorar: distensión, ruidos intestinales, cicatrices, hernias (todos los orificios) y tacto rectal.", "Pedir laboratorios: biometría, electrolitos, lactato, gasometría, función renal y grupo sanguíneo.", "Pedir imagen: radiografía y tomografía con contraste para nivel, causa y signos de isquemia.", "Buscar signos de isquemia o estrangulación: dolor continuo fuera de proporción, fiebre, taquicardia, leucocitosis, lactato alto, neumatosis o gas portal en la tomografía.", "Si no hay isquemia y la causa es adherencial, intentar manejo conservador (sonda, líquidos, Gastrografin si aplica) con reevaluación seriada.", "Si hay isquemia, estrangulación, perforación o fracaso del manejo conservador, ir a cirugía urgente."], "exp": "estabilizar va primero porque el obstruido llega deshidratado, hipoclorémico e hipopotasémico: operar o estudiar sin reponer es llevar a quirófano a un paciente en choque. La exploración de hernias va antes que la imagen porque una hernia estrangulada es diagnóstica con las manos y la tomografía no la va a resolver; es el orificio que se olvida revisar. Los signos de isquemia se buscan después de la imagen porque son en parte tomográficos (neumatosis, gas portal) y en parte clínicos (dolor fuera de proporción): sin imagen, la mitad de los signos no existe. El manejo conservador solo es correcto después de descartar isquemia: conservar a un isquémico es dejar que se necrose el intestino mientras \"se observa\". Y la cirugía es el rescate que se decide con criterios claros (isquemia, perforación, fracaso), no por impaciencia: operar toda obstrucción adhesiva de entrada es operar adherencias que se habrían resuelto solas."},
    {"id": "AA-R2-09", "grade": "R2", "title": "Enfermedad diverticular: Hinchey y la decisión de operar", "algoritmo": "Clasificación de Hinchey y manejo de la diverticulitis aguda.", "guia": "Clasificación de Hinchey (modificada); guías WSES 2020 y ASCRS 2020 (enfermedad diverticular).", "steps": ["Hacer historia y exploración: dolor en fosa ilíaca izquierda, fiebre, cambio del hábito intestinal, antecedente de diverticulitis.", "Pedir laboratorios: biometría, PCR, lactato y función renal.", "Confirmar con tomografía con contraste: engrosamiento, grasa pericolónica, absceso, aire libre o fístula.", "Clasificar según Hinchey: I absceso pericolónico, II absceso pélvico/distante, III peritonitis purulenta, IV peritonitis fecal.", "Hinchey I–II pequeño: antibiótico y manejo ambulatorio u hospitalario según el estado general.", "Hinchey II grande: drenaje percutáneo guiado por imagen más antibiótico.", "Hinchey III–IV: cirugía urgente (lavado, resección con anastomosis o Hartmann según el paciente y la contaminación).", "Seguimiento: colonoscopia diferida (6–8 semanas) para descartar cáncer, y valoración de cirugía electiva si hay episodios recurrentes o complicados."], "exp": "la tomografía va antes que Hinchey porque Hinchey es una clasificación tomográfica y quirúrgica, no clínica: sin imagen se está adivinando el estadio. El tratamiento se decide por estadio, no por síntoma: un Hinchey I no necesita drenaje y un Hinchey III no se resuelve con antibiótico, y tratarlos igual es el error en ambas direcciones. El drenaje percutáneo va antes que la cirugía en el Hinchey II grande porque convierte una urgencia en un problema electivo; operar un absceso grande de entrada es operar en el peor terreno. La cirugía urgente es para peritonitis (III–IV), no para dolor: operar un Hinchey I \"por si acaso\" es una resección innecesaria. Y la colonoscopia diferida es el cierre que no se puede saltar: una \"diverticulitis\" puede ser un cáncer perforado, y sin colonoscopia de seguimiento ese cáncer se diagnostica tarde, cuando ya dio metástasis."},
    {"id": "AA-R2-10", "grade": "R2", "title": "Cáncer de colon obstruido o perforado: la urgencia oncológica", "algoritmo": "Manejo de urgencia del cáncer de colon complicado (obstrucción o perforación).", "guia": "Guías NCCN de cáncer de colon (versión vigente); guías WSES de cáncer colorrectal de urgencia.", "steps": ["Hacer historia y exploración: obstrucción, distensión, dolor, fiebre, antecedente de cambio del hábito intestinal, sangre en heces o pérdida de peso.", "Estabilizar: líquidos, corrección de electrolitos, antibiótico si hay perforación o sepsis, y ayuno.", "Descartar isquemia, vólvulo y otras causas de obstrucción antes de asumir que es el tumor.", "Pedir tomografía con contraste: nivel de la obstrucción, perforación, aire libre, metástasis y resecabilidad.", "Valorar si el paciente es candidato a prótesis colónica (stent) como puente a la cirugía electiva, en obstrucción izquierda sin perforación.", "Decidir la cirugía de urgencia: resección con anastomosis primaria, Hartmann o derivación, según la contaminación, la estabilidad y la experiencia.", "Estadificar con la pieza y estudios de extensión, y presentar el caso en comité multidisciplinario.", "Planear la adyuvancia (quimioterapia) según el estadio y la recuperación, con seguimiento oncológico."], "exp": "la historia y la estabilización van antes que la tomografía porque el obstruido con perforación no espera al estudio; se reanima mientras se estudia. Descartar otras causas antes de asumir el tumor evita operar un vólvulo como si fuera cáncer y viceversa. La tomografía va antes que la decisión quirúrgica porque es la que dice si hay perforación (que descarta el stent), dónde está el tumor y si hay metástasis que cambien el objetivo de la cirugía. El stent como puente solo se valora después de la tomografía y solo en obstrucción izquierda sin perforación: ponerlo con perforación es sembrar tumor y pus en el peritoneo. La decisión entre anastomosis primaria y Hartmann se toma en el quirófano con el paciente y la contaminación reales, no en la hoja de indicaciones. Y la estadificación y la adyuvancia van al final porque la urgencia es sobrevivir a la complicación; el cáncer se trata después, con el paciente vivo y el estadio completo, no con una quimioterapia adivinada en la urgencia."},
    {"id": "AA-R3-01", "grade": "R3", "title": "Estadificación oncológica: del tumor al plan multidisciplinario", "algoritmo": "Estadificación TNM y decisión en comité multidisciplinario.", "guia": "AJCC Cancer Staging Manual, 8.ª edición; guías NCCN (versión vigente).", "steps": ["Hacer historia y exploración: síntomas, factores de riesgo, estado funcional (ECOG) y comorbilidades.", "Confirmar el diagnóstico histológico con biopsia antes de estadificar el tratamiento definitivo.", "Pedir estudios de extensión según el tumor: tomografía, resonancia, PET-CT, endoscopia o marcadores.", "Estadificar con TNM: tamaño e invasión local (T), ganglios (N) y metástasis (M).", "Valorar resecabilidad y operabilidad: ¿el tumor se puede quitar con márgenes? ¿el paciente aguanta la cirugía?", "Presentar el caso en comité multidisciplinario (cirugía, oncología médica, radioterapia, radiología, patología).", "Decidir la secuencia: cirugía primero, neoadyuvancia, adyuvancia o tratamiento paliativo.", "Informar al paciente, obtener consentimiento y planear el seguimiento y la vigilancia."], "exp": "la biopsia va antes que la estadificación definitiva porque estadificar sin histología es planear el tratamiento de un tumor que podría no ser ese tumor. Los estudios de extensión van antes que el TNM porque el TNM se construye con ellos; asignar un estadio con una tomografía incompleta es un estadio inventado. Resecabilidad y operabilidad son dos preguntas distintas y van antes del comité: un tumor resecable en un paciente inoperable no se opera, y un tumor irresecable en un paciente sano tampoco. El comité va antes que la decisión de secuencia porque la secuencia (neoadyuvancia frente a cirugía directa) es la decisión que más cambia el pronóstico y la que menos debe tomar una sola persona. Y el consentimiento va al final, con el plan completo: consentir una cirugía sin saber si habrá quimioterapia antes o después es consentir a medias."},
    {"id": "AA-R3-02", "grade": "R3", "title": "Cáncer de mama: triple evaluación y decisión quirúrgica", "algoritmo": "Triple evaluación y manejo del cáncer de mama.", "guia": "Guías NCCN de cáncer de mama (versión vigente); guías ASCO.", "steps": ["Hacer historia y exploración: masa, cambios en la piel o el pezón, secreción, ganglios axilares y antecedentes familiares.", "Hacer imagen: mastografía y ecografía (y resonancia si hay indicación).", "Hacer biopsia con aguja gruesa y pedir receptores (estrógeno, progesterona, HER2) y Ki-67.", "Clasificar con BI-RADS y correlacionar clínica, imagen y patología (triple evaluación).", "Estadificar: TNM, estudios de extensión si el estadio lo amerita y valoración de metástasis.", "Presentar en comité multidisciplinario y decidir la secuencia: cirugía conservadora frente a mastectomía, neoadyuvancia si aplica.", "Hacer ganglio centinela (o disección axilar si está indicado) y valorar márgenes en la pieza.", "Planear adyuvancia (radioterapia, quimioterapia, hormonoterapia o anti-HER2 según el subtipo) y seguimiento."], "exp": "la triple evaluación es un algoritmo en sí: clínica, imagen y biopsia deben concordar, y si una discordia se opera igual, se opera el diagnóstico equivocado. Los receptores se piden con la biopsia, no después de la cirugía, porque el subtipo (luminal, HER2, triple negativo) decide si hay neoadyuvancia y qué adyuvancia habrá; operar sin saber el subtipo es operar a ciegas. La estadificación va antes del comité porque el comité decide con el estadio completo, no con una sospecha. El ganglio centinela se hace en la cirugía, no antes, y su resultado decide la disección axilar: hacerlo como un procedimiento separado es una cirugía de más. Y la adyuvancia se planea al final, con subtipo, estadio, márgenes y ganglios: dar quimioterapia o radioterapia sin esos cuatro datos es tratar un cáncer que no se ha terminado de conocer."},
    {"id": "AA-R3-03", "grade": "R3", "title": "Cáncer colorrectal: estadificación, neoadyuvancia y cirugía", "algoritmo": "Manejo del cáncer colorrectal, con énfasis en recto y neoadyuvancia.", "guia": "Guías NCCN de cáncer de colon y de recto (versión vigente).", "steps": ["Confirmar con colonoscopia completa y biopsia; marcar el tumor (tatuaje) si se planea cirugía laparoscópica.", "Estadificar: tomografía toracoabdominal, resonancia pélvica en cáncer de recto y antígeno carcinoembrionario (CEA).", "Valorar el recto con resonancia: distancia al margen anal, invasión del mesorrecto, fascia mesorrectal y ganglios.", "Presentar en comité multidisciplinario.", "Si es recto localmente avanzado, dar neoadyuvancia (quimiorradioterapia o quimioterapia total neoadyuvante) y reestadificar.", "Si es colon localizado, ir a cirugía oncológica con márgenes y al menos 12 ganglios en la pieza.", "Hacer la cirugía con principios oncológicos: escisión total del mesorrecto en recto, ligadura vascular alta y márgenes libres.", "Planear adyuvancia según el estadio patológico y seguimiento con CEA, colonoscopia y tomografía."], "exp": "la colonoscopia completa va primero porque un cáncer colorrectal rara vez viene solo: hay tumores sincrónicos que cambian la cirugía, y el tatuaje es lo que permite encontrar el tumor en laparoscopia. La resonancia pélvica va antes que cualquier decisión en recto porque es la que dice si hay neoadyuvancia: operar un recto localmente avanzado sin neoadyuvancia es operar con el margen amenazado. La neoadyuvancia va antes que la cirugía solo en recto (y en casos seleccionados de colon), y la reestadificación después de ella es obligada: el tumor que respondió no es el mismo que se estadificó al inicio. Los 12 ganglios no son un capricho: con menos ganglios el estadio N es poco fiable y la adyuvancia se decide con un estadio mentiroso. Y la adyuvancia se planea con el estadio patológico final, no con el clínico: el patológico es el que manda."},
    {"id": "AA-R3-04", "grade": "R3", "title": "Cáncer gástrico y de esófago: ¿resecable, neoadyuvancia o paliación?", "algoritmo": "Estadificación y resecabilidad del cáncer gástrico y de esófago.", "guia": "Guías NCCN de cáncer gástrico y de esófago (versión vigente).", "steps": ["Confirmar con endoscopia y biopsia; clasificar el tipo histológico y la localización (Siewert en unión esofagogástrica).", "Valorar el estado nutricional y funcional: pérdida de peso, disfagia, albúmina y capacidad para tolerar quimioterapia o cirugía mayor.", "Estadificar: tomografía, PET-CT si aplica, ultrasonido endoscópico para la profundidad y ganglios, y laparoscopia diagnóstica con citología peritoneal en gástrico avanzado.", "Presentar en comité multidisciplinario.", "Si es resecable y localmente avanzado, dar quimioterapia perioperatoria (o quimiorradioterapia en esófago) y reestadificar.", "Hacer la cirugía con linfadenectomía adecuada (D2 en gástrico) y márgenes libres, con reconstrucción según el caso.", "Si es metastásico o irresecable, dar tratamiento sistémico paliativo y manejo de síntomas (prótesis, soporte nutricional).", "Planear adyuvancia o seguimiento según el estadio patológico, con vigilancia de recurrencia y de nutrición."], "exp": "la nutrición se valora antes que la estadificación completa porque el paciente caquéctico con disfagia no tolera ni la quimioterapia ni la cirugía: nutrirlo es parte del tratamiento, no un trámite. La laparoscopia diagnóstica va antes que la laparotomía en gástrico avanzado porque descubre la carcinomatosis que la tomografía no ve; sin ella, se abre un abdomen para cerrarlo sin hacer nada. La neoadyuvancia va antes que la cirugía en localmente avanzado porque es la que baja el estadio y mejora la resecabilidad; operar directo es operar el tumor en su peor momento. La paliación no es \"no hacer nada\": va en su propio paso, con tratamiento sistémico y manejo de síntomas, y decidirla tarde es dejar al paciente sin tratamiento mientras se discute una cirugía que no va a ocurrir. Y el seguimiento nutricional es el cierre propio de estos tumores: un gástrico operado que no se nutre no se recupera, por más márgenes libres que tenga la pieza."},
    {"id": "AA-R3-05", "grade": "R3", "title": "Tumor periampular y de páncreas: ¿resecable, borderline o irresecable?", "algoritmo": "Valoración de resecabilidad del tumor periampular y pancreático.", "guia": "Guías NCCN de adenocarcinoma pancreático (versión vigente); criterios de resecabilidad (NCCN/AHPBA).", "steps": ["Hacer historia y exploración: ictericia, pérdida de peso, dolor, diabetes de inicio reciente y antecedente familiar.", "Pedir tomografía pancreática trifásica con protocolo de páncreas y CA 19-9.", "Valorar la relación con los vasos: arteria mesentérica superior, tronco celiaco, vena porta y vena mesentérica superior.", "Clasificar: resecable, borderline resecable, localmente avanzado o metastásico.", "Presentar en comité multidisciplinario de HPB.", "Si hay ictericia y se planea neoadyuvancia o hay colangitis, drenar la vía biliar (prótesis) antes del tratamiento.", "Si es borderline o localmente avanzado, dar neoadyuvancia y reestadificar con imagen y CA 19-9.", "Si es resecable, ir a cirugía (pancreatoduodenectomía o pancreatectomía distal) en centro de alto volumen, y planear adyuvancia."], "exp": "la tomografía con protocolo de páncreas va antes que cualquier clasificación porque una tomografía convencional no ve la relación vascular, y la resecabilidad pancreática es una pregunta vascular. Clasificar antes del comité es necesario para que el comité discuta sobre un estadio, no sobre una impresión. El drenaje biliar va después del comité y solo si hay indicación (neoadyuvancia o colangitis): drenar a todo ictérico retrasa la cirugía y añade complicaciones, y no drenar al que va a neoadyuvancia lo deja sin quimioterapia por la bilirrubina alta. La neoadyuvancia va antes que la cirugía en borderline porque es la que convierte un tumor no operable en operable; operar un borderline directo es operar con margen positivo. Y la cirugía en centro de alto volumen no es un lujo: la mortalidad de la pancreatoduodenectomía depende del volumen, y operarla donde se hacen dos al año es el factor pronóstico que nadie escribe en la nota."},
    {"id": "AA-R3-06", "grade": "R3", "title": "Nódulo tiroideo: Bethesda y la decisión de operar", "algoritmo": "Abordaje del nódulo tiroideo y clasificación de Bethesda.", "guia": "Guías ATA 2015 (nódulos tiroideos); sistema Bethesda para citología tiroidea.", "steps": ["Hacer historia y exploración: crecimiento, síntomas compresivos, disfonía, antecedente de radiación, historia familiar y palpación del nódulo y ganglios.", "Pedir TSH y, si está alterada, perfil tiroideo completo.", "Hacer ecografía tiroidea: tamaño, composición, ecogenicidad, márgenes, microcalcificaciones y ganglios.", "Decidir biopsia por aspiración con aguja fina (BAAF) según el tamaño y las características ecográficas (TI-RADS/ATA).", "Clasificar la citología con Bethesda (I–VI) y decidir: repetir, vigilar, estudio molecular o cirugía.", "Si Bethesda es maligno o sospechoso, estadificar y planear la cirugía (lobectomía o tiroidectomía total con disección ganglionar si aplica).", "Preparar al paciente: valorar la voz (cuerdas vocales), el calcio y la función tiroidea antes de la cirugía.", "Seguimiento postoperatorio: patología definitiva, calcio, hormona tiroidea, tiroglobulina y ecografía de vigilancia."], "exp": "la TSH va antes que la ecografía porque un nódulo hipercaptante con TSH suprimida (nódulo caliente) rara vez es maligno y rara vez necesita BAAF; biopsiar sin TSH es biopsiar un nódulo que no lo necesitaba. La ecografía va antes que la BAAF porque es la que dice qué nódulo pinchar y si vale la pena: pinchar un nódulo de 5 mm sin características sospechosas es un procedimiento y una ansiedad innecesarios. Bethesda es la que decide, no la ecografía sola: una ecografía sospechosa con Bethesda benigno se vigila, y una ecografía tranquila con Bethesda maligno se opera. La valoración de la voz va antes de la cirugía, no después: si la cuerda ya estaba paralizada antes, la parálisis postoperatoria no es una complicación quirúrgica, y si no se documentó, no hay forma de saberlo. Y el seguimiento con tiroglobulina solo tiene sentido después de la tiroidectomía total y con la patología definitiva; pedirla antes es medir un número sin referencia."},
    {"id": "AA-R3-07", "grade": "R3", "title": "Nódulo pulmonar y cáncer de pulmón: ¿vigilar, biopsiar o resecar?", "algoritmo": "Abordaje del nódulo pulmonar y estadificación del cáncer de pulmón.", "guia": "Guías NCCN de cáncer de pulmón de células no pequeñas (versión vigente); guías Fleischner Society (nódulos pulmonares).", "steps": ["Hacer historia: tabaquismo, exposición, síntomas, pérdida de peso y comorbilidades.", "Caracterizar el nódulo en tomografía: tamaño, sólido o subsólido, bordes, crecimiento y ganglios.", "Estratificar el riesgo de malignidad (tamaño, edad, tabaquismo, características tomográficas).", "Si el riesgo es bajo, vigilar con tomografía seriada según Fleischner.", "Si el riesgo es intermedio o alto, hacer PET-CT y valorar biopsia (broncoscopia, aguja transtorácica o cirugía diagnóstica).", "Si se confirma cáncer, estadificar con TNM, pruebas moleculares (EGFR, ALK, PD-L1) y valoración funcional pulmonar y cardiaca.", "Presentar en comité multidisciplinario y decidir: cirugía, neoadyuvancia, radioterapia o tratamiento sistémico.", "Si se opera, hacer resección anatómica con linfadenectomía y planear adyuvancia y seguimiento."], "exp": "caracterizar antes que estratificar porque el riesgo depende de la tomografía: un nódulo de 4 mm no se maneja como uno de 25 mm, y sin medirlo no hay estratificación posible. La vigilancia es el tratamiento correcto del riesgo bajo: biopsiar todos los nódulos pequeños es dañar pulmones sanos y generar neumotórax por lesiones benignas. El PET-CT va antes que la biopsia en riesgo alto porque dice dónde biopsiar y si ya hay enfermedad a distancia que haga innecesaria la biopsia del nódulo. Las pruebas moleculares se piden con el diagnóstico, no después de la cirugía, porque en cáncer de pulmón el tratamiento sistémico depende de ellas y la neoadyuvancia puede ser la primera opción. La valoración funcional va antes del comité porque un cáncer resecable en un pulmón que no aguanta la resección no se opera; decidir la cirugía sin saber si el paciente la tolera es prometer una operación que no se puede cumplir."},
    {"id": "AA-R3-08", "grade": "R3", "title": "Isquemia aguda de extremidad: Rutherford y la ventana de 6 horas", "algoritmo": "Manejo de la isquemia aguda de la extremidad.", "guia": "Clasificación de Rutherford; guías ESVS 2020 (isquemia aguda de extremidad).", "steps": ["Hacer historia: inicio súbito, dolor, antecedente de fibrilación auricular, enfermedad arterial o embolia previa.", "Explorar: las 6 P (dolor, palidez, ausencia de pulso, parestesia, parálisis, poiquilotermia) y comparar con la extremidad contralateral.", "Clasificar según Rutherford: I viable, IIa marginalmente amenazada, IIb inmediatamente amenazada, III irreversible.", "Iniciar anticoagulación con heparina si no hay contraindicación, y analgesia.", "Pedir Doppler, índice tobillo-brazo y, si el tiempo lo permite, angiotomografía.", "Si es Rutherford IIb, revascularizar de urgencia (no hay tiempo para estudios largos).", "Si es Rutherford I–IIa, intentar revascularización: trombólisis, trombectomía o bypass según la causa y el tiempo.", "Si es Rutherford III o hay síndrome compartimental, valorar amputación o fasciotomía, y seguimiento con anticoagulación y estudio de la causa embólica."], "exp": "clasificar con Rutherford va antes que la imagen porque la clasificación es clínica y es la que fija la urgencia: una IIb no espera a la angiotomografía, y una I sí puede esperar. La heparina va antes que la imagen porque frena la propagación del trombo mientras se estudia; esperar al estudio para anticoagular es dejar que el trombo crezca. La imagen se pide \"si el tiempo lo permite\" porque en isquemia aguda el tiempo es músculo: cada hora de estudio es una hora menos de pierna viable. La revascularización urgente de la IIb va antes que la de la I–IIa en el orden lógico porque es la que no admite demora; invertirlo es trombolizar al viable mientras se necrosa el amenazado. Y la amputación en Rutherford III no es un fracaso del algoritmo: es reconocer la irreversibilidad y evitar una revascularización que reperfunde tejido muerto y mata por rabdomiólisis e hiperpotasemia."},
    {"id": "AA-R3-09", "grade": "R3", "title": "Cirugía de control de daños: operar poco, operar bien, volver después", "algoritmo": "Cirugía de control de daños en trauma grave.", "guia": "Guías WSES de control de daños; ATLS, 10.ª edición.", "steps": ["Reconocer al paciente que necesita control de daños: hipotermia, acidosis, coagulopatía (tríada letal), choque refractario o lesión grave con contaminación.", "Hacer la laparotomía abreviada: controlar el sangrado (empaquetamiento, ligadura, grapado) y controlar la contaminación (grapado intestinal sin anastomosis, drenaje).", "Cerrar temporalmente el abdomen (bolsa de Bogotá, VAC o cierre temporal) sin cerrar la fascia bajo tensión.", "Llevar a UCI: recalentar, corregir coagulopatía y acidosis, reponer sangre y estabilizar.", "Si hay sangrado no quirúrgico o lesión vascular compleja, usar angioembolización como complemento.", "Reevaluar: lactato, temperatura, coagulación, diuresis y necesidad de reintervención.", "Hacer la reoperación planeada (24–48 h): retirar empaques, hacer las anastomosis y el cierre definitivo si el paciente lo permite.", "Seguimiento: vigilancia de síndrome compartimental abdominal, infección y fístula enteroatmosférica."], "exp": "reconocer al candidato va primero porque el error es hacer la cirugía definitiva en el paciente equivocado: el paciente frío, acidótico y coagulopático no sobrevive a una operación larga, por bien hecha que sea. La laparotomía abreviada tiene dos objetivos y solo dos: que no se desangre y que no se contamine; todo lo demás (anastomosis, reconstrucción) es vanidad en ese momento. El cierre temporal va antes que la UCI porque cerrar la fascia bajo tensión en un abdomen edematoso es fabricar un síndrome compartimental. La UCI es donde se gana la cirugía definitiva: recalentar y corregir la coagulopatía es el tratamiento, no el descanso entre cirugías. La reoperación planeada va a las 24–48 h, no antes (el paciente no está corregido) ni mucho después (los empaques se infectan y las adherencias lo hacen imposible). Y la vigilancia de fístula enteroatmosférica es el cierre que recuerda el precio del abdomen abierto: cada día abierto es un día de riesgo de fístula."},
    {"id": "AA-R3-10", "grade": "R3", "title": "Hernia compleja y pérdida de dominio: preparar la pared antes de operarla", "algoritmo": "Valoración y preparación de la hernia ventral compleja y la pérdida de dominio.", "guia": "Guías EHS/AHS de hernia ventral; guías WSES de pared abdominal compleja.", "steps": ["Hacer historia y exploración: tamaño del defecto, hernias previas, cirugías, síntomas, piel y contaminación.", "Pedir tomografía con reconstrucción: tamaño del defecto, contenido del saco, pérdida de dominio (volumen del saco frente a la cavidad abdominal) y pared lateral.", "Valorar comorbilidades y optimizar: tabaquismo, diabetes, obesidad, nutrición y anticoagulación.", "Decidir si se necesita preparación preoperatoria: toxina botulínica, neumoperitoneo progresivo o ambas en pérdida de dominio.", "Planear el cierre: ¿se puede cerrar la fascia sin tensión? Si no, ¿qué cobertura se usará?", "Elegir la técnica: separación de componentes, malla (posición y tipo) y abordaje abierto o mínimamente invasivo.", "Hacer la cirugía con profilaxis, control de la contaminación y manejo del dolor.", "Seguimiento: vigilancia de infección de malla, seroma, recurrencia y rehabilitación de la pared abdominal."], "exp": "la tomografía va antes que la técnica porque la pérdida de dominio no se palpa: solo la tomografía dice si el contenido cabe de vuelta en el abdomen, y sin ese dato la cirugía termina en síndrome compartimental. La optimización va antes que la preparación preoperatoria porque la toxina botulínica y el neumoperitoneo no compensan un diabético descontrolado que fuma: preparan la pared, no al paciente. El plan de cierre va antes que la elección de la técnica porque la técnica sirve al cierre, no al revés: elegir la malla antes de saber si la fascia cierra es comprar el material antes de medir la obra. Y el seguimiento de infección de malla es el cierre obligado: una malla infectada no es una complicación menor, es una reoperación mayor, y detectarla tarde es perder la pared que se acaba de reconstruir."},
    {"id": "AA-R4-01", "grade": "R4", "title": "Colangiocarcinoma hiliar: Bismuth-Corlette y resecabilidad", "algoritmo": "Valoración del colangiocarcinoma hiliar (tumor de Klatskin).", "guia": "Clasificación de Bismuth-Corlette; guías NCCN de cáncer de vía biliar (versión vigente).", "steps": ["Hacer historia y exploración: ictericia, prurito, pérdida de peso, colangitis y antecedente de colangitis esclerosante primaria.", "Pedir laboratorios: patrón colestásico, bilirrubina, CA 19-9 y función hepática.", "Hacer imagen: colangiorresonancia y tomografía trifásica para la extensión biliar y vascular.", "Clasificar con Bismuth-Corlette (I–IV) según la extensión en la confluencia biliar.", "Valorar la resecabilidad: extensión vascular, atrofia lobar, metástasis y volumen hepático remanente.", "Si hay ictericia y se planea resección mayor, valorar drenaje biliar selectivo del futuro remanente y embolización portal.", "Presentar en comité multidisciplinario de HPB y decidir: resección, trasplante en casos seleccionados o paliación.", "Si se reseca, hacer hepatectomía con resección de la vía biliar y linfadenectomía; si no, paliación con prótesis y seguimiento."], "exp": "la colangiorresonancia va antes que Bismuth porque Bismuth es una clasificación de imagen: sin ella se está clasificando una impresión. La resecabilidad se valora antes del comité porque el comité decide sobre un tumor ya caracterizado, no sobre una sospecha. El drenaje biliar selectivo va antes que la resección pero solo del futuro remanente: drenar el lóbulo que se va a quitar es inútil y drenar ambos es contaminar el remanente. La embolización portal va antes que la cirugía mayor porque es la que hace crecer el remanente; operar sin remanente suficiente es programar una falla hepática postoperatoria. Y la paliación no es el fracaso del algoritmo: en un Bismuth IV irresecable, la prótesis bien puesta vale más que una resección imposible."},
    {"id": "AA-R4-02", "grade": "R4", "title": "Fístula pancreática postoperatoria: ISGPS y el manejo escalonado", "algoritmo": "Diagnóstico y manejo de la fístula pancreática postoperatoria.", "guia": "Definición y clasificación ISGPS 2016 (fístula pancreática postoperatoria); guías de manejo de fístula pancreática.", "steps": ["Sospechar la fístula: drenaje con amilasa alta, fiebre, dolor, leucocitosis o deterioro postoperatorio tras cirugía pancreática.", "Medir amilasa en el líquido de drenaje al tercer día postoperatorio y compararla con la amilasa sérica.", "Clasificar según ISGPS: fuga bioquímica (antes grado A), grado B (cambio en el manejo) o grado C (reintervención, falla orgánica o muerte).", "Mantener el drenaje permeable, ayuno o nutrición enteral, análogos de somatostatina si aplica y antibiótico si hay infección.", "Hacer tomografía con contraste si hay deterioro: colección, absceso, sangrado o isquemia.", "Si hay colección infectada, drenar por vía percutánea o endoscópica antes que reoperar.", "Si hay sangrado o deterioro grave, ir a reintervención urgente (control del sangrado, lavado, drenaje).", "Seguimiento: gasto del drenaje, cierre de la fístula, nutrición y vigilancia de pseudoquiste o estenosis."], "exp": "la amilasa del drenaje al tercer día es el criterio diagnóstico: medirla antes es medir el trauma quirúrgico, y no medirla es no diagnosticar la fístula más común de la cirugía pancreática. Clasificar con ISGPS va antes que la tomografía porque la clasificación dice si la fístula es un hallazgo de laboratorio o una complicación que cambia el manejo; hacer tomografía a una fuga bioquímica es irradiar un número. El manejo conservador va antes que la imagen en el paciente estable: la mayoría de las fístulas grado B se resuelven con drenaje permeable y paciencia. El drenaje percutáneo va antes que la reoperación porque una colección drenada por piel no necesita una laparotomía; reoperar una colección drenable es la reoperación que se pudo evitar. Y la reintervención urgente se reserva para el sangrado y el deterioro grave: reoperar una fístula estable es convertir una complicación manejable en una catástrofe."},
    {"id": "AA-R4-03", "grade": "R4", "title": "Carcinomatosis peritoneal: PCI, selección y citorreducción con HIPEC", "algoritmo": "Selección para citorreducción e HIPEC en carcinomatosis peritoneal.", "guia": "Índice de carcinomatosis peritoneal (PCI, Sugarbaker); guías de citorreducción e HIPEC.", "steps": ["Confirmar el diagnóstico y el origen: histología, tumor primario y estudios de extensión.", "Valorar el estado funcional, la nutrición y las comorbilidades del paciente.", "Calcular el PCI con tomografía y, si hace falta, laparoscopia diagnóstica.", "Valorar la resecabilidad: ¿se puede lograr citorreducción completa (CC-0/CC-1)? ¿Hay enfermedad extraperitoneal?", "Presentar en comité multidisciplinario de oncología peritoneal.", "Si es candidato, dar quimioterapia sistémica neoadyuvante si aplica y reevaluar el PCI.", "Hacer la citorreducción completa seguida de HIPEC en centro con experiencia.", "Seguimiento: quimioterapia adyuvante si aplica, vigilancia de recurrencia, nutrición y calidad de vida."], "exp": "el estado funcional va antes que el PCI porque un PCI bajo en un paciente que no aguanta 10 horas de cirugía no es operable; el PCI mide el tumor, no al paciente. El PCI se calcula con tomografía y se confirma con laparoscopia porque la tomografía subestima la carcinomatosis: operar con un PCI \"bajo\" que en realidad es alto es abrir para cerrar sin hacer nada. La citorreducción completa es el criterio que decide todo: si no se puede lograr CC-0/CC-1, el HIPEC no tiene sentido y la cirugía mayor no se justifica. La neoadyuvancia va antes que la cirugía en los candidatos porque baja el PCI y selecciona a los que responden; operar sin ella es operar el peor PCI posible. Y el centro con experiencia no es un detalle logístico: la mortalidad de la citorreducción con HIPEC depende del equipo, y hacerla donde no se hace habitualmente es el factor pronóstico que no aparece en el PCI."},
    {"id": "AA-R4-04", "grade": "R4", "title": "Cáncer rectal localmente avanzado: neoadyuvancia total y vigilancia y espera", "algoritmo": "Quimioterapia total neoadyuvante y estrategia de vigilancia y espera (watch and wait) en cáncer de recto.", "guia": "Guías NCCN de cáncer de recto (versión vigente); estudios RAPIDO y PRODIGE 23 (quimioterapia total neoadyuvante).", "steps": ["Confirmar con colonoscopia, biopsia y resonancia pélvica: distancia al margen anal, fascia mesorrectal y ganglios.", "Estadificar con tomografía toracoabdominal y CEA.", "Presentar en comité multidisciplinario.", "Dar quimioterapia total neoadyuvante (quimioterapia sistémica + quimiorradioterapia) en el localmente avanzado.", "Reestadificar con resonancia, endoscopia y exploración digital tras la neoadyuvancia.", "Si hay respuesta clínica completa, ofrecer vigilancia y espera (watch and wait) con seguimiento estrecho, como alternativa a la cirugía.", "Si hay respuesta parcial o no hay respuesta, hacer la resección oncológica (escisión total del mesorrecto) con márgenes libres.", "Seguimiento: resonancia seriada, endoscopia, CEA y vigilancia de recurrencia local y a distancia."], "exp": "la resonancia pélvica va antes que la neoadyuvancia porque es la que dice quién es localmente avanzado: dar quimioterapia total a un recto temprano es sobretratar, y no darla a uno avanzado es operar con el margen amenazado. La reestadificación va después de la neoadyuvancia con tres modalidades (resonancia, endoscopia y tacto) porque ninguna sola define la respuesta completa: la vigilancia y espera basada en una sola prueba es una cirugía omitida por un falso negativo. La vigilancia y espera solo se ofrece con respuesta clínica completa y con seguimiento estrecho garantizado: ofrecerla sin seguimiento es abandonar al paciente, no evitarle una cirugía. Y la cirugía sigue siendo el plan si no hay respuesta completa: la neoadyuvancia no sustituye a la resección, la prepara, y el que no respondió no se vigila, se opera."},
    {"id": "AA-R4-05", "grade": "R4", "title": "Cáncer de esófago: CROSS, neoadyuvancia y esofagectomía", "algoritmo": "Manejo del cáncer de esófago resecable con quimiorradioterapia neoadyuvante (CROSS).", "guia": "Guías NCCN de cáncer de esófago (versión vigente); estudio CROSS.", "steps": ["Confirmar con endoscopia y biopsia; clasificar histología (adenocarcinoma o epidermoide) y localización.", "Valorar el estado nutricional y funcional: disfagia, pérdida de peso, albúmina y capacidad pulmonar y cardiaca.", "Estadificar: tomografía, PET-CT, ultrasonido endoscópico y, si aplica, laparoscopia diagnóstica.", "Presentar en comité multidisciplinario.", "Si es resecable y localmente avanzado, dar quimiorradioterapia neoadyuvante según CROSS y reestadificar.", "Hacer la esofagectomía con linfadenectomía y reconstrucción (gástrica habitualmente) en centro de alto volumen.", "Si es metastásico o irresecable, dar tratamiento sistémico paliativo, prótesis esofágica o soporte nutricional.", "Seguimiento: patología definitiva, adyuvancia si aplica, nutrición, vigilancia de recurrencia y de fístula anastomótica."], "exp": "la nutrición se valora antes que la estadificación completa porque el paciente con disfagia grave no tolera la quimiorradioterapia ni la cirugía sin soporte nutricional previo: nutrirlo es parte del tratamiento oncológico. La histología va antes que CROSS porque el esquema y la respuesta difieren entre adenocarcinoma y epidermoide; dar el mismo tratamiento sin saber el tipo es tratar a medias. La reestadificación después de CROSS es obligada: el tumor que respondió puede ser operable y el que progresó puede ya no serlo, y operar sin reestadificar es operar el tumor de hace tres meses. La esofagectomía en centro de alto volumen no es una preferencia: es la cirugía con la mortalidad más dependiente del volumen, y la fístula anastomótica es la complicación que define el postoperatorio. Y la paliación con prótesis es un tratamiento activo, no un abandono: un esófago obstruido con prótesis come, y uno sin ella no."},
    {"id": "AA-R4-06", "grade": "R4", "title": "Síndrome compartimental abdominal: medir, descomprimir, no cerrar", "algoritmo": "Detección y manejo del síndrome compartimental abdominal.", "guia": "Guías WSACS (World Society of the Abdominal Compartment Syndrome); guías WSES de abdomen abierto.", "steps": ["Sospecharlo en el paciente de riesgo: trauma grave, reanimación masiva, pancreatitis grave, sepsis abdominal, abdomen tenso y oliguria.", "Medir la presión intraabdominal (habitualmente por vía vesical) y calcular la presión de perfusión abdominal.", "Clasificar la hipertensión intraabdominal (grados I–IV) y confirmar el síndrome compartimental si hay disfunción orgánica nueva.", "Iniciar medidas médicas: sedación y relajación, evitar la sobrecarga de líquidos, drenar colecciones, descomprimir el tubo digestivo y optimizar la perfusión.", "Reevaluar la presión intraabdominal y la función orgánica tras las medidas médicas.", "Si fracasan las medidas médicas o hay deterioro grave, hacer descompresión quirúrgica (laparotomía descompresiva) y dejar el abdomen abierto.", "Manejar el abdomen abierto con presión negativa y lavados, y cerrar la fascia en cuanto sea posible.", "Seguimiento: función renal y respiratoria, nutrición, fístula enteroatmosférica y rehabilitación de la pared."], "exp": "sospecharlo va primero porque el síndrome compartimental no se ve, se mide: el abdomen tenso con oliguria que se atribuye a \"falta de líquidos\" es el paciente que se sigue llenando de líquidos hasta que el riñón deja de perfundir. Medir va antes que tratar porque sin número no se sabe si hay hipertensión ni de qué grado; tratar sin medir es adivinar. Las medidas médicas van antes que la descompresión porque muchas hipertensiones se resuelven sin abrir: descomprimir de entrada a todo hipertenso es operar abdomens que se habrían resuelto con sedación y drenaje. La reevaluación tras las medidas médicas es la que decide la cirugía: sin ella no se sabe si fracasaron. Y dejar el abdomen abierto tras la descompresión no es un fracaso: cerrarlo de nuevo bajo tensión es recrear el síndrome que se acaba de descomprimir."},
    {"id": "AA-R4-07", "grade": "R4", "title": "Feocromocitoma: bloquear alfa antes de tocar el tumor", "algoritmo": "Preparación preoperatoria del feocromocitoma.", "guia": "Guías Endocrine Society 2014 (feocromocitoma y paraganglioma).", "steps": ["Sospecharlo: hipertensión paroxística, cefalea, palpitaciones, sudoración, crisis hipertensivas o incidentaloma suprarrenal.", "Confirmar bioquímicamente con metanefrinas libres en plasma o fraccionadas en orina de 24 h.", "Localizar con tomografía o resonancia suprarrenal, y estudios funcionales si hay duda o enfermedad extraadrenal.", "Valorar el corazón y descartar cardiomiopatía por catecolaminas antes de la cirugía.", "Iniciar bloqueo alfa (fenoxibenzamina o doxazosina) 7–14 días antes de la cirugía, con expansión de volumen.", "Añadir betabloqueo solo después del bloqueo alfa establecido, si hay taquicardia o arritmia.", "Hacer la adrenalectomía (laparoscópica habitualmente) con monitoreo arterial invasivo y anestesia con experiencia.", "Seguimiento postoperatorio: presión arterial, glucemia, metanefrinas y estudio genético si aplica."], "exp": "confirmar bioquímicamente va antes que localizar porque un incidentaloma suprarrenal no funcionante no es un feocromocitoma: operar un incidentaloma sin metanefrinas es operar una masa que no era el problema. La valoración cardiaca va antes que el bloqueo porque la cardiomiopatía por catecolaminas cambia el riesgo anestésico y puede ser la primera manifestación. El bloqueo alfa va antes que el betabloqueo, siempre: dar betabloqueo sin alfa deja el alfa sin oposición y precipita una crisis hipertensiva, el error clásico y letal de este tumor. El bloqueo dura 7–14 días, no horas: operar antes es operar a un paciente no bloqueado, y la manipulación del tumor en quirófano es la crisis hipertensiva que se quiso evitar. Y el estudio genético va al final, con el diagnóstico confirmado: una proporción importante es hereditaria, y no estudiarla es dejar sin diagnóstico a la familia."},
    {"id": "AA-R4-08", "grade": "R4", "title": "Fuga tras manga gástrica: ¿drenar, stent o reoperar?", "algoritmo": "Manejo de la fuga gástrica tras cirugía bariátrica (manga gástrica).", "guia": "Guías ASMBS de cirugía bariátrica; guías de manejo de fuga gástrica post-bariátrica.", "steps": ["Sospechar la fuga: taquicardia persistente, fiebre, dolor, leucocitosis o deterioro tras manga gástrica.", "Estabilizar: líquidos, antibiótico de amplio espectro, ayuno y monitoreo en UCI si hay sepsis.", "Confirmar con tomografía con contraste oral/IV y, si hace falta, estudio con contraste hidrosoluble.", "Clasificar: fuga temprana o tardía, contenida o libre, con o sin sepsis, y localización (unión esofagogástrica habitualmente).", "Si es contenida y el paciente está estable, manejar conservadoramente: drenaje percutáneo, nutrición enteral/parenteral y antibiótico.", "Si hay sepsis o colección no drenable, valorar endoscopia: stent cubierto, clips o terapia de vacío endoscópico.", "Si fracasa el manejo conservador y endoscópico, o hay peritonitis, ir a reintervención quirúrgica (lavado, drenaje, reparación o conversión).", "Seguimiento: cierre de la fuga, nutrición, estenosis y seguimiento bariátrico a largo plazo."], "exp": "la taquicardia persistente es el signo más precoz y va primero porque la fuga no siempre duele donde se espera: esperar al dolor abdominal es esperar a la peritonitis. Estabilizar va antes que confirmar porque el paciente séptico no espera al estudio; se reanima mientras se estudia. Clasificar va antes que tratar porque la fuga contenida estable y la fuga libre con peritonitis son dos enfermedades distintas: la primera se maneja, la segunda se opera. La endoscopia va antes que la reoperación porque el stent o el vacío endoscópico cierran fugas que la cirugía no puede reparar en tejido inflamado; reoperar de entrada es suturar sobre tejido que no va a cicatrizar. Y la reintervención es el rescate, no el plan A: operar una fuga contenida estable es convertir una complicación manejable en una catástrofe quirúrgica."},
    {"id": "AA-R4-09", "grade": "R4", "title": "Disección aórtica: Stanford A o B, y el tiempo manda", "algoritmo": "Diagnóstico y manejo de la disección aórtica aguda.", "guia": "Guías ESC 2024 (enfermedades de la aorta); clasificación de Stanford.", "steps": ["Sospecharla: dolor torácico o interescapular súbito y desgarrante, asimetría de pulsos o presión, déficit neurológico o choque.", "Estabilizar: monitoreo, accesos venosos, control del dolor y evitar la hipertensión que propaga la disección.", "Iniciar control de la frecuencia cardiaca y la presión arterial (betabloqueo IV primero, luego vasodilatador si hace falta).", "Confirmar con angiotomografía de aorta (o ecocardiograma transesofágico si el paciente no puede ir a tomografía).", "Clasificar con Stanford: tipo A (aorta ascendente) o tipo B (aorta descendente).", "Si es Stanford A, llevar a cirugía cardiaca de urgencia.", "Si es Stanford B no complicado, manejar médicamente en UCI con control estricto de presión y vigilancia.", "Si es Stanford B complicado (rotura, malperfusión, expansión o dolor refractario), valorar TEVAR (reparación endovascular) de urgencia."], "exp": "sospecharla va primero porque la disección se confunde con infarto y el tratamiento del infarto (trombólisis, anticoagulación) mata al disecado: la sospecha es lo que evita el error letal. El control de la frecuencia y la presión va antes que la confirmación porque cada latido con presión alta propaga la disección; esperar a la tomografía para bajar la presión es dejar que la disección avance. El betabloqueo va antes que el vasodilatador, siempre: vasodilatar sin bajar la frecuencia aumenta la fuerza de eyección y propaga la disección, el mismo error de orden que en el feocromocitoma. Stanford se clasifica después de la imagen porque es una clasificación anatómica: sin imagen no se sabe si es A o B, y la decisión (cirugía de urgencia frente a manejo médico) depende enteramente de esa letra. Y el TEVAR en el B complicado es el rescate, no el plan A del B no complicado: intervenir un B no complicado es someter a un paciente estable a un procedimiento que no necesita."},
    {"id": "AA-R4-10", "grade": "R4", "title": "Fístula enterocutánea: SNAP y el plan en cuatro letras", "algoritmo": "Manejo de la fístula enterocutánea (SNAP).", "guia": "Principios SNAP (Sepsis, Nutrición, Anatomía, Procedimiento); guías WSES de fístulas enteroatmosféricas y enterocutáneas.", "steps": ["Reconocer la fístula: salida de contenido intestinal por la herida o el drenaje, con pérdida de líquidos y electrolitos.", "Controlar la sepsis: drenar colecciones, antibiótico y valorar si hay peritonitis o absceso.", "Reponer líquidos y electrolitos según el gasto de la fístula (alto o bajo gasto) y proteger la piel.", "Iniciar soporte nutricional: enteral si es posible (distal a la fístula o por vía enteral que no la alimente), parenteral si no.", "Definir la anatomía: fistulografía, tomografía y tránsito intestinal para saber origen, trayecto, longitud y si hay obstrucción distal.", "Esperar el cierre espontáneo (semanas a meses) si no hay sepsis, obstrucción distal ni factores que lo impidan.", "Si no cierra o hay indicación, planear la cirugía definitiva (resección del segmento fistuloso con anastomosis) cuando el paciente esté optimizado y hayan pasado al menos 6 semanas.", "Seguimiento: nutrición, cierre de la herida, rehabilitación y vigilancia de recurrencia."], "exp": "SNAP es el orden en sí: sepsis primero, porque una fístula séptica no cierra y el paciente se muere antes de que la nutrición haga efecto. La reposición de líquidos va antes que la nutrición porque una fístula de alto gasto deshidrata en horas; nutrir sin reponer es alimentar a un paciente en choque. La anatomía se define después de estabilizar y nutrir, no antes: la fistulografía en un paciente séptico y desnutrido no cambia el plan inmediato y sí lo retrasa. Esperar el cierre espontáneo es el paso que exige paciencia: la mayoría de las fístulas que van a cerrar lo hacen en semanas, y operarlas antes es operar un abdomen hostil que no va a cicatrizar. La cirugía definitiva espera al menos 6 semanas y al paciente optimizado porque operar antes es operar adherencias de cemento y un paciente desnutrido: la fístula se cierra, pero se abre otra. Y el seguimiento nutricional es el cierre que recuerda que la fístula es una enfermedad de meses, no de días."},
  ],
  sepaso: [
    {"id": "QP-R1-01", "grade": "R1", "tema": "Trauma: evaluación inicial ATLS", "nota": "Hombre de 34 años, motociclista, choque contra automóvil. Llega a Urgencias consciente, agitado, con fractura expuesta de tibia derecha y dolor abdominal. Signos: TA 88/60 mmHg, FC 128 lpm, FR 26 rpm, SatO2 94% con mascarilla, Glasgow 14. Se realiza ABCDE: vía aérea permeable con collarín, murmullo vesicular bilateral, abdomen doloroso en hipocondrio izquierdo, pelvis estable, FAST positivo en Morrison y esplénico. Se canalizan dos vías periféricas gruesas, se inicia reanimación con cristaloides, se solicita hemoglobina, grupo y Rh, pruebas cruzadas, radiografía de tórax y pelvis, y TAC de abdomen con contraste. Se avisa a Cirugía y Ortopedia. Se indica ayuno, sonda vesical y monitorización continua.", "error": "Se inició reanimación con cristaloides en bolo amplio sin haber activado el protocolo de transfusión masiva ni haber solicitado concentrados eritrocitarios de forma inmediata, y no se documentó la administración de ácido tranexámico dentro de la primera hora en un paciente con hemorragia activa y choque hemorrágico.", "consecuencia": "Dilución de factores de coagulación, hipotermia y acidosis — la tríada letal — con progresión del choque hemorrágico y muerte evitable antes de llegar a quirófano.", "debio": "Activar desde el inicio el protocolo de transfusión masiva (proporción balanceada de eritrocitos, plasma y plaquetas, según protocolo local, ATLS 10.ª ed.), minimizar cristaloides, administrar ácido tranexámico en la primera hora (y hasta las 3 horas) del trauma, y mantener la estrategia de hipotensión permisiva hasta el control quirúrgico de la hemorragia.", "exp": "En choque hemorrágico el cristaloides en exceso no sustituye sangre: diluye, enfría y acidifica. La reanimación hemostática temprana y el tranexámico son el estándar; el resto del manejo (FAST, TAC, avisos) estaba bien."},
    {"id": "QP-R1-02", "grade": "R1", "tema": "Líquidos y electrolitos", "nota": "Mujer de 68 años, postoperada día 2 de hemicolectomía derecha por cáncer de colon. Evoluciona con íleo, náusea y debilidad. Laboratorios: Na 128 mEq/L, K 3.1 mEq/L, Cl 96 mEq/L, HCO3 26 mEq/L, creatinina 1.1 mg/dL, glucosa 140 mg/dL. Gasto urinario 0.6 mL/kg/h. Recibe solución salina 0.9% a 100 mL/h, dieta líquida suspendida, sonda nasogástrica a derivación con gasto de 600 mL/día, y metoclopramida. Se solicita reposición de potasio oral y control de electrolitos en 24 horas. Se documenta balance hídrico estricto.", "error": "Hiponatremia (128) e hipopotasemia (3.1) con pérdidas por sonda nasogástrica se están tratando con solución salina 0.9% y potasio oral, sin reponer el potasio por vía intravenosa ni corregir la hiponatremia con la velocidad adecuada, y sin considerar que la solución salina en exceso agrava la acidosis hiperclorémica y no corrige el déficit de potasio con íleo (la vía oral no se absorbe).", "consecuencia": "Arritmias por hipopotasemia, prolongación del íleo, debilidad muscular y deterioro neurológico por hiponatremia; riesgo de paro cardiaco si el potasio sigue cayendo.", "debio": "Reposición intravenosa de potasio (con monitorización cardiaca y controles frecuentes), corrección lenta y vigilada de la hiponatremia según su cronicidad y síntomas, reposición de las pérdidas por sonda nasogástrica mililitro por mililitro con solución balanceada, y suspender la vía oral mientras persista el íleo.", "exp": "Con íleo, el potasio oral no se absorbe; la hipopotasemia se corrige por vía intravenosa y vigilada. La salina 0.9% no es la solución de reposición universal: en pérdidas gástricas y con cloro alto, una solución balanceada es preferible."},
    {"id": "QP-R1-03", "grade": "R1", "tema": "Estado de choque", "nota": "Hombre de 72 años, día 3 postoperatorio de laparotomía por perforación de úlcera duodenal. Presenta TA 85/55 mmHg, FC 122 lpm, llenado capilar de 4 segundos, extremidades frías, gasto urinario 0.3 mL/kg/h, lactato 4.8 mmol/L, leucocitos 18,000/µL, temperatura 38.9 °C. Herida quirúrgica con eritema y secreción purulenta fétida. Se diagnostica choque séptico, se toman hemocultivos, se inicia norepinefrina por vía periférica, se indica meropenem 1 g IV cada 8 horas y se programa reintervención para lavado y drenaje. Se solicita lactato de control en 2 horas.", "error": "Se inició vasopresor (norepinefrina) antes de completar la reanimación con volumen, y no se documentó la administración de cristaloides balanceados en bolo (30 mL/kg) en las primeras horas ni la medición de presión arterial media objetivo; además, el meropenem se indicó sin ajuste ni valoración de función renal en un paciente con oliguria.", "consecuencia": "Hipoperfusión persistente, daño renal agudo progresivo, falla multiorgánica y muerte; el antibiótico mal dosificado puede ser ineficaz o tóxico.", "debio": "Reanimación inicial con cristaloides balanceados (30 mL/kg, Surviving Sepsis Campaign), reevaluación dinámica de la respuesta a volumen y solo después vasopresor si la PAM sigue <65 mmHg, preferentemente por vía central; ajustar la dosis del antibiótico a la función renal y revalorarla diariamente; control de foco quirúrgico urgente, que sí se programó.", "exp": "En choque séptico el orden importa: volumen primero, vasopresor después. La norepinefrina no sustituye la reanimación hídrica, y ningún antibiótico se prescribe sin mirar la creatinina en un paciente oligúrico."},
    {"id": "QP-R1-04", "grade": "R1", "tema": "Cuidados perioperatorios", "nota": "Hombre de 59 años, diabético tipo 2 e hipertenso, programado para colecistectomía laparoscópica electiva por colelitiasis sintomática. Medicación habitual: metformina 850 mg cada 12 horas, losartán 50 mg al día, atorvastatina 20 mg al día. Laboratorios preoperatorios: HbA1c 7.8%, creatinina 0.9 mg/dL, hemoglobina 14.2 g/dL. Se indica ayuno de 8 horas para sólidos y 2 horas para líquidos claros, profilaxis antitrombótica con heparina de bajo peso molecular la noche previa, antibiótico profiláctico cefazolina 2 g IV 30 minutos antes de la incisión, y se suspende la metformina el día de la cirugía. Se programa primera cirugía de la mañana.", "error": "Se suspendió la metformina solo el día de la cirugía y no se documentó ningún plan de reinicio (48 horas después y solo con función renal normal), en un paciente que recibirá anestesia general y tiene riesgo de deterioro renal agudo postoperatorio.", "consecuencia": "Acidosis láctica asociada a metformina si hay deterioro renal agudo o uso de contraste yodado, complicación rara pero mortal.", "debio": "Suspender la metformina 24-48 horas antes de la cirugía electiva (o al menos el día previo según protocolo local), verificar creatinina postoperatoria y reiniciarla solo 48 horas después con función renal normal y alimentación oral restablecida; documentar el plan por escrito en la nota preoperatoria.", "exp": "La metformina no se suspende \"el mero día\" como trámite: el riesgo es la acidosis láctica si el riñón falla o hay contraste. El plan de suspensión y reinicio debe quedar escrito, no implícito."},
    {"id": "QP-R1-05", "grade": "R1", "tema": "Nutrición en cirugía", "nota": "Mujer de 54 años, con cáncer gástrico, pérdida de 12 kg en 3 meses (18% del peso corporal), albúmina 2.8 g/dL, programada para gastrectomía total en 10 días. Se valora por Nutrición: se indica dieta hipercalórica e hiperproteica oral, suplementos orales 2 veces al día, y se cita a control en una semana. No se coloca acceso enteral ni se inicia nutrición parenteral. Se documenta \"paciente con desnutrición moderada, manejo conservador, revalorar\".", "error": "Paciente con desnutrición grave (pérdida >10% en 6 meses, albúmina <3.0) y cirugía mayor oncológica en 10 días, a quien se le da solo dieta oral y suplementos sin asegurar la ingesta real ni iniciar soporte nutricional preoperatorio estructurado (nutrición enteral por sonda o parenteral si la vía oral es insuficiente), desaprovechando la ventana preoperatoria.", "consecuencia": "Mayor riesgo de dehiscencia de anastomosis, infección de herida, neumonía, estancia prolongada y mortalidad postoperatoria; la cirugía sobre un paciente desnutrido es una de las causas evitables de complicación.", "debio": "Soporte nutricional preoperatorio de 7-14 días (guías ESPEN): calcular requerimientos, asegurar ingesta con suplementos orales vigilados y, si no cubre >60% de lo requerido, iniciar nutrición enteral (sonda nasoenteral) y valorar parenteral; diferir la cirugía electiva si es necesario hasta mejorar el estado nutricional, con revaloración objetiva (peso, ingesta, prealbúmina).", "exp": "La desnutrición grave no se resuelve con \"coma bien y regrese en una semana\". Antes de una gastrectomía, el soporte nutricional es parte del tratamiento, no un adorno."},
    {"id": "QP-R1-06", "grade": "R1", "tema": "Sangre, hemostasia y transfusión", "nota": "Mujer de 45 años, postoperada de histerectomía, con sangrado vaginal moderado y hemoglobina de 7.8 g/dL (previa 11.5 g/dL), estable hemodinámicamente, sin sangrado activo visible, FC 98 lpm, TA 110/70 mmHg. Se solicitan 2 concentrados eritrocitarios y se transfunden de inmediato. Se indica hierro oral al egreso. No se solicita ferritina ni se documenta la causa del descenso de hemoglobina más allá del sangrado quirúrgico. La paciente es Testigo de Jehová y lo tiene anotado en el expediente, pero la nota no lo menciona.", "error": "Se transfundieron concentrados eritrocitarios sin verificar ni respetar la voluntad documentada de la paciente Testigo de Jehová, que rechaza transfusiones de sangre, y sin haber explorado antes alternativas (hierro intravenoso, eritropoyetina, optimización hemostática, cirugía de control del sangrado) ni obtenido un consentimiento informado específico para la transfusión.", "consecuencia": "Violación grave de la autonomía del paciente y del consentimiento informado, con consecuencias éticas, legales y de confianza; además, la transfusión en una paciente estable con Hb 7.8 sin síntomas graves suele ser innecesaria según una estrategia restrictiva.", "debio": "Respetar la negativa documentada, no transfundir, aplicar manejo sin sangre (patient blood management): hierro intravenoso, eritropoyetina si aplica, ácido tranexámico, control quirúrgico del sangrado, y documentar la conversación con la paciente y su familia; transfundir solo si hay indicación vital y con el marco legal y ético correspondiente.", "exp": "Una hemoglobina de 7.8 en una paciente estable no obliga a transfundir, y menos aún contra su voluntad documentada. La autonomía no es un detalle del expediente: es el primer dato que se revisa."},
    {"id": "QP-R1-07", "grade": "R1", "tema": "Cicatrización y cuidado de las heridas quirúrgicas", "nota": "Hombre de 61 años, diabético mal controlado (HbA1c 9.4%), obeso (IMC 34), postoperado día 5 de laparotomía por obstrucción intestinal. Herida con dehiscencia parcial de 3 cm, tejido de granulación pálido, exudado escaso, sin eritema ni fiebre. Se indica curación diaria con solución salina, desbridamiento cortante en cama, y se mantiene la misma cobertura antibiótica de amplio espectro iniciada en el postoperatorio inmediato. Se documenta \"herida en evolución favorable\" y se planea el egreso en 48 horas.", "error": "Se mantiene antibiótico de amplio espectro al día 5 sin evidencia de infección de herida (sin eritema, sin fiebre, sin leucocitosis documentada) solo por la dehiscencia, y no se aborda el factor principal del mal cicatrizado: el control glucémico (HbA1c 9.4%) ni la optimización nutricional y de oxigenación tisular; además, se planea el egreso sin un plan de curación avanzada ni seguimiento de la herida.", "consecuencia": "Resistencia antimicrobiana, infección por Clostridioides difficile, costos innecesarios y, sobre todo, dehiscencia completa o evisceración por no corregir la hiperglucemia que impide la cicatrización.", "debio": "Suspender el antibiótico si no hay infección documentada, optimizar el control glucémico perioperatorio (glucosa 140-180 mg/dL en el paciente hospitalizado), valorar nutrición y aporte proteico, curación adecuada con desbridamiento selectivo y cobertura apropiada, y seguimiento estrecho de la herida antes del egreso.", "exp": "La dehiscencia en un diabético descontrolado no se cura con más antibiótico: se cura controlando la glucosa. El antibiótico sin infección es el error que se ve; la glucosa sin controlar es el que mata la herida."},
    {"id": "QP-R1-08", "grade": "R1", "tema": "Infección en cirugía", "nota": "Mujer de 38 años, con apendicitis aguda perforada y peritonitis generalizada, llevada a apendicectomía abierta y lavado peritoneal. En el postoperatorio se indica piperacilina-tazobactam 4.5 g IV cada 6 horas, con plan de 7 días. Al día 4 evoluciona afebril, con leucocitos normales, tolerando dieta, herida limpia y drenaje con gasto mínimo seroso. Se decide completar los 7 días de antibiótico \"para asegurar\" y retirar el drenaje al día 7 junto con el egreso.", "error": "Se prolonga el antibiótico a 7 días en una peritonitis con control de foco adecuado y evolución favorable al día 4, cuando la evidencia (WSES, guías de infección intraabdominal) apoya cursos cortos de 3-4 días tras un control de foco adecuado, y se mantiene un drenaje innecesariamente hasta el día 7.", "consecuencia": "Resistencia antimicrobiana, infección por C. difficile, estancia prolongada, costos y riesgo de infección asociada al drenaje retenido.", "debio": "Suspender el antibiótico al día 3-4 tras el control adecuado del foco y la mejoría clínica, retirar el drenaje cuando el gasto sea mínimo y seroso (no esperar al egreso), y egresar antes con seguimiento ambulatorio.", "exp": "\"Completar por si acaso\" no es un plan antibiótico. Con foco controlado y paciente afebril, el curso corto es igual de eficaz y mucho más seguro."},
    {"id": "QP-R1-09", "grade": "R1", "tema": "Abdomen agudo y apendicitis aguda", "nota": "Mujer de 26 años, embarazada de 18 semanas, con dolor en fosa iliaca derecha de 12 horas de evolución, náusea, vómito, fiebre de 38.2 °C, leucocitos 14,500/µL, signo de McBurney positivo. Se sospecha apendicitis aguda. Se solicita ultrasonido abdominal, que reporta \"apéndice no visualizado, sin líquido libre\". Se decide manejo conservador con antibiótico y observación, difiriendo la cirugía \"para proteger el embarazo\". Se indica paracetamol y ayuno.", "error": "Ante una sospecha clínica alta de apendicitis en una embarazada con ultrasonido no concluyente, se optó por manejo conservador y observación en lugar de completar el estudio con resonancia magnética (sin radiación, alta sensibilidad) o proceder a la exploración quirúrgica, retrasando el diagnóstico de una apendicitis que en el embarazo se perfora con mayor rapidez y con mayor riesgo fetal.", "consecuencia": "Perforación apendicular, peritonitis, sepsis materna, pérdida fetal y parto pretérmino; el retraso quirúrgico en la embarazada es más peligroso que la cirugía misma.", "debio": "Completar con resonancia magnética abdominal/pélvica ante ultrasonido no diagnóstico, con valoración conjunta de Cirugía y Ginecoobstetricia, y proceder a apendicectomía (laparoscópica si es factible) sin demora si la sospecha persiste; la cirugía en el segundo trimestre es segura y la perforación es el verdadero riesgo para el feto.", "exp": "Un ultrasonido \"no visualizado\" no descarta apendicitis, y en el embarazo el reloj corre más rápido. La resonancia o el quirófano, no la espera, es lo que protege al binomio."},
    {"id": "QP-R1-10", "grade": "R1", "tema": "Profesionalismo médico, ética y consentimiento informado", "nota": "Hombre de 70 años, con hernia inguinal bilateral sintomática, programado para hernioplastia laparoscópica bilateral. En la consulta preoperatoria se le explica el procedimiento, los riesgos de sangrado, infección y recurrencia, y firma el consentimiento informado para \"hernioplastia laparoscópica bilateral\". Durante la cirugía, el cirujano encuentra un lipoma del cordón espermático del lado derecho y decide resecarlo, y además identifica una hernia femoral pequeña no diagnosticada del lado izquierdo y la repara con malla. Al final, la nota quirúrgica documenta ambos hallazgos y procedimientos adicionales. El paciente evoluciona bien y es egresado al día siguiente.", "error": "Se realizaron dos procedimientos adicionales no contemplados en el consentimiento informado (resección de lipoma y reparación de hernia femoral) sin haber obtenido el consentimiento del paciente para esas eventualidades ni haberlas incluido como posibilidades en el consentimiento preoperatorio, y sin documentar una justificación de urgencia que lo hiciera impostergable.", "consecuencia": "Violación del consentimiento informado y de la autonomía del paciente, con exposición legal y pérdida de confianza; el paciente tiene derecho a decidir sobre cada intervención en su cuerpo, incluso las \"menores\".", "debio": "Incluir en el consentimiento preoperatorio las eventualidades razonablemente previsibles (hallazgos incidentales, hernias concomitantes, resección de lipomas) o, si el hallazgo es inesperado y no urgente, limitarse al procedimiento consentido y programar lo adicional para una segunda intervención con consentimiento específico; documentar la conversación y la justificación si la ampliación era impostergable.", "exp": "El consentimiento no es un permiso en blanco para todo lo que se encuentre dentro. Lo que no se explicó ni se consintió no se hace, salvo urgencia real documentada."},
    {"id": "QP-R2-01", "grade": "R2", "tema": "Patología esofágica y ERGE", "nota": "Hombre de 52 años, con pirosis de 5 años de evolución, regurgitación nocturna y disfagia ocasional a sólidos. Se realiza endoscopia: esofagitis grado B de Los Ángeles y hernia hiatal de 3 cm. Se inicia omeprazol 20 mg al día y medidas higiénico-dietéticas. El paciente mejora parcialmente. Se programa funduplicatura laparoscópica tipo Nissen por \"ERGE refractaria\" a las 8 semanas, sin manometría esofágica ni pH-metría previas. La nota indica \"candidato ideal a cirugía antirreflujo\".", "error": "Se programa una funduplicatura de Nissen (360°) sin manometría esofágica preoperatoria, estudio indispensable para descartar acalasia o un trastorno motor esofágico (aperistalsis) que contraindica una funduplicatura completa.", "consecuencia": "Disfagia grave postoperatoria, imposibilidad para eructar o vomitar, distensión por gas y necesidad de reintervención; una funduplicatura total sobre un esófago sin peristalsis es un desastre funcional.", "debio": "Manometría esofágica de alta resolución y pH-metría (o impedancia-pH) antes de cualquier cirugía antirreflujo, para confirmar reflujo patológico y descartar trastorno motor; si hay aperistalsis, optar por funduplicatura parcial (Toupet) o manejo médico.", "exp": "La disfagia ocasional era la pista: en ERGE con disfagia, la manometría no es opcional. Operar el reflujo sin conocer la motilidad es operar a ciegas."},
    {"id": "QP-R2-02", "grade": "R2", "tema": "Úlcera péptica y hemorragia digestiva alta", "nota": "Hombre de 66 años, con hematemesis y melena de 6 horas, TA 95/60 mmHg, FC 118 lpm, Hb 8.1 g/dL. Endoscopia urgente: úlcera duodenal con vaso visible sangrante (Forrest IIa), se realiza hemostasia con clip y adrenalina. Se inicia omeprazol IV en infusión, transfusión de 1 concentrado eritrocitario, y se indica dieta líquida a las 24 horas. Se documenta \"hemostasia exitosa\". No se solicita prueba de Helicobacter pylori ni se programa seguimiento endoscópico. Se egresa al día 3 con omeprazol oral 20 mg al día por 4 semanas.", "error": "No se investigó ni se trató Helicobacter pylori, causa principal de la úlcera duodenal, y el omeprazol se indicó a dosis estándar (20 mg) en lugar de la dosis alta recomendada tras hemostasia endoscópica de una lesión de alto riesgo (Forrest IIa).", "consecuencia": "Resangrado de la úlcera en los primeros días y recurrencia ulcerosa a largo plazo por H. pylori no erradicado; la úlcera vuelve, y con ella la hemorragia.", "debio": "Omeprazol IV a dosis alta (bolo de 80 mg seguido de infusión de 8 mg/h por 72 horas) tras hemostasia de lesión de alto riesgo, toma de biopsias o prueba no invasiva para H. pylori, erradicación con esquema triple o cuádruple según resistencia local, y confirmación de la erradicación; endoscopia de control si hay duda de hemostasia.", "exp": "El clip detiene el sangrado de hoy; la erradicación de H. pylori y el inhibidor de bomba a dosis alta evitan el de mañana. Tratar la úlcera sin buscar H. pylori es dejar la causa intacta."},
    {"id": "QP-R2-03", "grade": "R2", "tema": "Patología hepática quirúrgica", "nota": "Hombre de 41 años, con fiebre de 2 semanas, dolor en hipocondrio derecho y leucocitosis. TAC: lesión hipodensa única de 8 cm en lóbulo derecho del hígado, con realce periférico. Se diagnostica absceso hepático piógeno. Se inicia ceftriaxona más metronidazol IV, se solicita drenaje percutáneo guiado por ultrasonido y se programa para el día siguiente. No se solicitan serología para Entamoeba histolytica, hemocultivos ni pruebas de función hepática completas. El drenaje obtiene material achocolatado (\"pasta de anchoas\").", "error": "El material drenado es clásico de absceso amebiano (\"pasta de anchoas\"), pero el paciente recibió antibiótico para absceso piógeno sin que se hubiera solicitado serología amebiana ni se hubiera iniciado metronidazol como tratamiento específico amebiano de forma prioritaria, y se indicó drenaje percutáneo de rutina cuando el absceso amebiano no complicado suele resolverse con tratamiento médico y el drenaje se reserva para casos seleccionados.", "consecuencia": "Tratamiento inadecuado y prolongado, riesgo de ruptura del absceso a pleura, pericardio o peritoneo, y drenaje innecesario con riesgo de sobreinfección y fístula.", "debio": "Ante un absceso hepático en México, solicitar siempre serología para Entamoeba histolytica y considerar el origen amebiano; el metronidazol es el tratamiento de primera línea del absceso amebiano y el drenaje solo si hay riesgo de ruptura, compresión o falta de respuesta; el absceso piógeno sí requiere drenaje más antibiótico, por eso distinguirlos antes de pinchar importa.", "exp": "En México, un absceso hepático es amebiano hasta demostrar lo contrario. La \"pasta de anchoas\" lo gritaba; el drenaje de rutina y la serología omitida son el error."},
    {"id": "QP-R2-04", "grade": "R2", "tema": "Patología biliar (Tokio TG18)", "nota": "Mujer de 63 años, con dolor en hipocondrio derecho de 3 días, fiebre de 38.6 °C, ictericia, TA 100/65 mmHg, FC 105 lpm. Laboratorios: leucocitos 16,000/µL, bilirrubina total 4.2 mg/dL, fosfatasa alcalina 320 U/L, PCR 18 mg/dL. Ultrasonido: vesícula con pared engrosada, lito impactado en cuello, vía biliar dilatada a 11 mm. Se diagnostica colangitis aguda grado II (moderada, Tokio TG18). Se inicia ceftriaxona IV, ayuno, y se programa CPRE para el día siguiente por la mañana. Se documenta \"drenaje biliar temprano programado\".", "error": "Colangitis aguda grado II con ictericia y dilatación de vía biliar, en la que se difirió el drenaje biliar (CPRE) hasta el día siguiente, cuando la guía de Tokio TG18 recomienda drenaje biliar temprano y urgente en colangitis moderada-grave; además, no se valoró el grado de severidad completo ni se documentó la presencia de disfunción orgánica.", "consecuencia": "Progresión a colangitis grave con choque séptico, falla hepática y muerte; cada hora de obstrucción biliar infectada sin drenaje empeora el pronóstico.", "debio": "Drenaje biliar urgente (CPRE en las primeras 24 horas, y antes si hay deterioro o grado III), antibiótico de amplio espectro, reanimación hídrica y monitorización en terapia intensiva si hay disfunción orgánica; la colangitis es una urgencia de drenaje, no de \"mañana por la mañana\".", "exp": "La colangitis no espera al horario de la CPRE. Antibiótico sin drenaje es como apagar un incendio sin abrir la puerta: el pus sigue ahí."},
    {"id": "QP-R2-05", "grade": "R2", "tema": "Pancreatitis aguda y crónica", "nota": "Hombre de 48 años, con dolor epigástrico intenso irradiado a espalda, vómito, lipasa 1,800 U/L, leucocitos 15,000/µL, hematocrito 48%, creatinina 1.4 mg/dL, calcio 7.6 mg/dL. TAC al ingreso: páncreas aumentado de tamaño, sin necrosis. Se diagnostica pancreatitis aguda grave por criterios de Ranson y APACHE II. Se indica ayuno absoluto, sonda nasogástrica, reanimación con solución salina 0.9% a 250 mL/h, analgesia con tramadol, y meropenem profiláctico \"para prevenir necrosis infectada\". Se programa TAC de control a las 72 horas.", "error": "Se indicó antibiótico profiláctico (meropenem) en una pancreatitis aguda sin necrosis infectada documentada, práctica que las guías actuales desaconsejan, y la reanimación se hizo con solución salina 0.9% en lugar de una solución balanceada (Ringer lactato), que ha demostrado mejores resultados en pancreatitis aguda.", "consecuencia": "Resistencia antimicrobiana, infección por C. difficile y sobreinfección fúngica sin beneficio; la salina en exceso favorece acidosis hiperclorémica y empeora la perfusión pancreática.", "debio": "Reanimación temprana y agresiva con Ringer lactato, analgesia adecuada, ayuno breve con reintroducción temprana de dieta oral según tolerancia, y reservar el antibiótico solo para necrosis infectada documentada o sospecha alta con deterioro; el TAC de control a las 72 horas sí estaba indicado.", "exp": "El antibiótico profiláctico en pancreatitis no previene la necrosis infectada: la crea de otra forma. Y el Ringer lactato, no la salina, es el líquido de la pancreatitis."},
    {"id": "QP-R2-06", "grade": "R2", "tema": "Apendicitis aguda y abdomen agudo", "nota": "Hombre de 29 años, con dolor en fosa iliaca derecha de 18 horas, anorexia, fiebre 38.0 °C, leucocitos 13,000/µL, PCR 6 mg/dL, escala de Alvarado 8. Se realiza apendicectomía laparoscópica: apéndice inflamado sin perforación, sin líquido libre. Postoperatorio sin complicaciones, tolera dieta al día 1, afebril. Se indica ceftriaxona más metronidazol IV por 5 días \"para cubrir la infección\" y egreso al día 3.", "error": "Antibiótico postoperatorio por 5 días en una apendicitis aguda no complicada (sin perforación, sin absceso, sin peritonitis), cuando tras una apendicectomía con control adecuado del foco no se requiere antibiótico postoperatorio, o a lo sumo una dosis perioperatoria.", "consecuencia": "Resistencia antimicrobiana, C. difficile, estancia y costos innecesarios, y el mensaje falso de que \"toda apendicitis lleva antibiótico largo\".", "debio": "Una sola dosis de antibiótico profiláctico preoperatorio (o ninguna prolongación postoperatoria) en apendicitis no complicada, egreso temprano al día 1-2 y seguimiento ambulatorio.", "exp": "La apendicitis no complicada se cura con la cirugía, no con 5 días de antibiótico. El antibiótico postoperatorio es para la perforada, no para la inflamada."},
    {"id": "QP-R2-07", "grade": "R2", "tema": "Hernias de la pared abdominal", "nota": "Hombre de 71 años, con hernia inguinal derecha incarcerada de 6 horas, dolor intenso, vómito, distensión abdominal, sin evacuaciones. Exploración: tumoración inguinal dolorosa, irreductible, sin cambios de coloración en la piel. Laboratorios normales, radiografía de abdomen con niveles hidroaéreos. Se intenta reducción manual bajo sedación, que fracasa. Se programa hernioplastia de urgencia con malla de polipropileno. En cirugía se encuentra asa de intestino delgado viable, sin necrosis, y se coloca malla. Postoperatorio sin complicaciones.", "error": "Se colocó malla sintética permanente en una hernia incarcerada de urgencia con intestino comprometido y posible contaminación, sin documentar la valoración del riesgo de infección de malla ni considerar reparación sin malla (técnica de Shouldice o Bassini) o malla biológica según el grado de contaminación; además, se intentó reducción manual de una hernia incarcerada con datos de obstrucción, maniobra riesgosa por el peligro de reducir un asa necrosada al abdomen.", "consecuencia": "Infección de la malla, necesidad de retirarla, recurrencia herniaria, sepsis por un asa necrosada reducida inadvertidamente y reintervención.", "debio": "En hernia incarcerada con obstrucción no intentar reducción manual; cirugía urgente, valoración de viabilidad intestinal, y en caso de contaminación o isquemia, reparación sin malla sintética permanente (o diferir la colocación de malla); la malla es para la hernia electiva limpia, no para el intestino en riesgo.", "exp": "La malla en campo contaminado es un cuerpo extraño esperando infectarse, y la reducción manual de un asa que puede estar muerta es jugar a la ruleta con el intestino dentro."},
    {"id": "QP-R2-08", "grade": "R2", "tema": "Obstrucción intestinal, vólvulo e isquemia intestinal", "nota": "Mujer de 76 años, con dolor abdominal cólico, distensión, vómito fecaloide y ausencia de evacuaciones de 3 días. Antecedente de cirugía de colon hace 2 años. TAC: dilatación de asas de intestino delgado, niveles hidroaéreos, punto de transición en íleon, sin signos de isquemia ni neumatosis, sin líquido libre. Se diagnostica obstrucción intestinal por adherencias. Se indica ayuno, sonda nasogástrica, reposición hídrica, corrección de electrolitos y manejo conservador con vigilancia. Al día 3 persiste la obstrucción sin mejoría; se solicita gastrografín por sonda nasogástrica y se decide esperar 48 horas más.", "error": "Se prolongó el manejo conservador más allá de las 72 horas sin resolución en una obstrucción por adherencias, sin haber usado el gastrografín (contraste hidrosoluble) de forma temprana como prueba terapéutica y diagnóstica, y sin documentar criterios claros de fracaso del manejo conservador que obligaran a operar.", "consecuencia": "Isquemia intestinal, perforación, peritonitis, sepsis y muerte; la obstrucción que no se resuelve no se \"espera\": se opera.", "debio": "Manejo conservador con gastrografín temprano (a las 24-48 horas) como prueba diagnóstica y terapéutica, y cirugía si no hay resolución en 72 horas o antes si aparecen datos de isquemia, estrangulación o deterioro clínico; la decisión de operar debe estar escrita desde el día 1.", "exp": "El gastrografín no es un adorno del día 3: dado a tiempo, resuelve muchas obstrucciones y dice cuáles no se van a resolver. Esperar sin fecha límite es dejar que el intestino decida por ti."},
    {"id": "QP-R2-09", "grade": "R2", "tema": "Enfermedad diverticular y patología benigna de colon", "nota": "Hombre de 58 años, con dolor en fosa iliaca izquierda, fiebre 38.4 °C, leucocitos 14,000/µL. TAC: diverticulitis aguda no complicada (Hinchey Ia), engrosamiento de sigmoides, sin absceso ni aire libre. Se inicia ciprofloxacino más metronidazol oral, dieta líquida, y se indica colonoscopia en 6 semanas para descartar cáncer. El paciente mejora en 48 horas. Se egresa con antibiótico oral por 10 días y cita de colonoscopia.", "error": "Se indicó antibiótico por 10 días en una diverticulitis aguda no complicada en un paciente inmunocompetente, cuando las guías actuales (WSES, ASCRS) apoyan el manejo sin antibiótico o con curso corto en casos seleccionados no complicados; el error concreto es la duración excesiva y la falta de valoración de manejo ambulatorio sin antibiótico.", "consecuencia": "Resistencia antimicrobiana, C. difficile, costos y medicalización innecesaria de una enfermedad que en su forma no complicada es autolimitada con soporte.", "debio": "En diverticulitis no complicada en paciente inmunocompetente y sin comorbilidades graves, manejo conservador con dieta, analgesia y observación, con antibiótico solo si hay comorbilidad, inmunosupresión o deterioro; si se usa, curso corto (4-5 días); la colonoscopia a las 6 semanas sí estaba indicada.", "exp": "La diverticulitis no complicada no es una infección que exija 10 días de antibiótico. El TAC dijo \"no complicada\"; el tratamiento debió escucharlo."},
    {"id": "QP-R2-10", "grade": "R2", "tema": "Cáncer de colon", "nota": "Hombre de 64 años, con anemia ferropénica, pérdida de 8 kg y cambio en el hábito intestinal. Colonoscopia: tumor en colon ascendente, biopsia adenocarcinoma moderadamente diferenciado. TAC de estadificación: tumor localizado, sin metástasis a distancia, ganglios regionales sospechosos. Se programa hemicolectomía derecha laparoscópica con linfadenectomía. Laboratorios: Hb 9.8 g/dL, albúmina 3.4 g/dL. Se indica hierro intravenoso preoperatorio y se programa la cirugía en 5 días. No se solicita valoración de anestesia ni estudios de extensión con CEA basal.", "error": "No se solicitó el antígeno carcinoembrionario (CEA) basal preoperatorio, marcador indispensable para el seguimiento oncológico posterior.", "consecuencia": "Sin CEA basal no hay referencia para detectar recurrencia en el seguimiento; un CEA que sube después no se puede interpretar sin saber de dónde partió.", "debio": "Solicitar CEA basal antes de la cirugía, optimizar la anemia con hierro intravenoso, y completar la estadificación y valoración preanestésica antes de programar.", "exp": "El CEA basal se toma antes de operar o no sirve después; sin basal, el seguimiento oncológico va a ciegas."},
    {"id": "QP-R3-01", "grade": "R3", "tema": "Cirugía oncológica: principios y estadificación", "nota": "Mujer de 55 años, con tumor palpable en mama derecha de 3 cm, biopsia con aguja gruesa: carcinoma ductal infiltrante, receptores de estrógeno y progesterona positivos, HER2 negativo. Se programa mastectomía radical modificada con disección axilar completa para la próxima semana. En el expediente no hay reporte de estudios de extensión (TAC de tórax/abdomen, gammagrama óseo ni PET), ni nota de comité de tumores, ni valoración de oncología médica. La nota quirúrgica planeada indica \"resección con márgenes amplios y vaciamiento axilar de niveles I-III\".", "error": "Se programa cirugía oncológica mayor sin estadificación completa ni discusión en comité multidisciplinario de tumores, y con disección axilar completa planeada de entrada sin haber realizado biopsia de ganglio centinela, que es el estándar para estadificar la axila en cáncer de mama temprano clínicamente negativo.", "consecuencia": "Cirugía innecesariamente radical (linfedema, lesión nerviosa, dolor crónico), estadificación incorrecta, tratamiento sistémico mal planeado y posible enfermedad metastásica no detectada que haría inútil la cirugía.", "debio": "Estadificación completa según la etapa clínica, discusión en comité de tumores con cirugía, oncología médica, radioterapia y patología, y biopsia de ganglio centinela como primer paso axilar; la disección axilar completa solo si el centinela es positivo o hay ganglios clínicamente positivos.", "exp": "En oncología nadie opera solo: el comité y la estadificación van antes que el bisturí, y la axila se estadifica con centinela, no con vaciamiento de rutina."},
    {"id": "QP-R3-02", "grade": "R3", "tema": "Cáncer de mama", "nota": "Mujer de 48 años, con carcinoma ductal infiltrante de 1.8 cm en cuadrante superior externo de mama izquierda, ganglios clínicamente negativos, receptores hormonales positivos, HER2 negativo, Ki-67 bajo. Se realiza cirugía conservadora (tumorectomía) con biopsia de ganglio centinela negativa y márgenes libres. La paciente es egresada al día 2 con analgésicos y cita de seguimiento en cirugía en un mes. No se solicita valoración de radioterapia ni de oncología médica; la nota indica \"tratamiento quirúrgico completo, seguimiento clínico\".", "error": "Tras una cirugía conservadora de mama no se indicó radioterapia adyuvante, parte indispensable del tratamiento conservador, ni se derivó a oncología médica para valorar terapia endocrina adyuvante en un tumor receptor hormonal positivo.", "consecuencia": "Recurrencia local mucho mayor (la cirugía conservadora sin radioterapia recurre como si no se hubiera tratado bien) y recurrencia sistémica por no recibir terapia endocrina; el beneficio de conservar la mama se pierde.", "debio": "Derivación inmediata a radioterapia (irradiación de la mama conservada) y a oncología médica para terapia endocrina adyuvante por 5-10 años, con seguimiento oncológico estructurado; la cirugía es solo el primer paso.", "exp": "Conservar la mama sin radioterapia no es tratamiento conservador: es tratamiento incompleto. La cirugía quita el tumor; la radioterapia y la terapia endocrina evitan que vuelva."},
    {"id": "QP-R3-03", "grade": "R3", "tema": "Cáncer colorrectal", "nota": "Hombre de 60 años, con adenocarcinoma de recto medio (a 8 cm del margen anal), estadio clínico T3N1M0 por resonancia magnética de pelvis y TAC. Se programa resección anterior baja con escisión total del mesorrecto para la próxima semana. No se ha administrado neoadyuvancia ni se ha discutido quimiorradioterapia preoperatoria en comité; la nota indica \"cirugía directa, adyuvancia según patología\".", "error": "Cáncer de recto localmente avanzado (T3N1) llevado directo a cirugía sin terapia neoadyuvante (quimiorradioterapia o quimioterapia total neoadyuvante), que es el estándar actual para reducir el tumor, mejorar la resección y disminuir la recurrencia local.", "consecuencia": "Mayor riesgo de margen circunferencial positivo, recurrencia local y peor supervivencia; operar un recto T3N1 sin neoadyuvancia es operar en desventaja.", "debio": "Discusión en comité multidisciplinario y neoadyuvancia (quimiorradioterapia de curso largo o corto, o terapia neoadyuvante total según guías NCCN) antes de la cirugía, con reestadificación posterior y cirugía con escisión total del mesorrecto en el momento óptimo.", "exp": "El recto no es el colon: un T3N1 se trata antes de operarlo. La neoadyuvancia no retrasa la cirugía, la hace curativa."},
    {"id": "QP-R3-04", "grade": "R3", "tema": "Cirugía endocrina: tiroides", "nota": "Mujer de 42 años, con nódulo tiroideo de 3.5 cm, biopsia por aspiración con aguja fina: Bethesda V (sospechoso de malignidad). Se programa tiroidectomía total. Laboratorios preoperatorios: TSH normal, calcio sérico normal. No se solicita laringoscopia preoperatoria ni medición de parathormona, y no se documenta la valoración de las cuerdas vocales. En el postoperatorio inmediato la paciente presenta disfonía y calcio de 7.2 mg/dL con parestesias peribucales.", "error": "No se realizó laringoscopia preoperatoria para documentar la movilidad de las cuerdas vocales antes de una tiroidectomía total, estudio recomendado en todo paciente que va a cirugía tiroidea, y no se documentó el plan de preservación paratiroidea ni la medición de calcio y PTH postoperatorios de forma protocolizada.", "consecuencia": "Si hay lesión del nervio laríngeo recurrente, no se puede saber si era previa o quirúrgica, con implicaciones médico-legales y terapéuticas; la hipocalcemia por hipoparatiroidismo no detectada a tiempo puede causar tetania, laringoespasmo y paro cardiaco.", "debio": "Laringoscopia preoperatoria en todo paciente programado para tiroidectomía, identificación y preservación de paratiroides y del nervio laríngeo recurrente, y medición protocolizada de calcio y PTH en el postoperatorio inmediato para detectar hipoparatiroidismo antes de los síntomas.", "exp": "Antes de operar la tiroides se mira cómo se mueven las cuerdas, porque después ya nadie sabe si la lesión era tuya o venía de antes. Y el calcio postoperatorio no se espera a que dé síntomas."},
    {"id": "QP-R3-05", "grade": "R3", "tema": "Cirugía vascular: aorta", "nota": "Hombre de 74 años, hipertenso, fumador, con aneurisma de aorta abdominal infrarrenal de 6.2 cm detectado por ultrasonido y confirmado por angio-TAC. Asintomático, sin dolor ni datos de ruptura. Se programa reparación endovascular (EVAR) electiva para dentro de 3 semanas. Se solicita valoración cardiológica preoperatoria y control de presión arterial. No se documenta consejo antitabaco ni estatina, y se indica \"reposo relativo en casa hasta la cirugía\".", "error": "Aneurisma de aorta abdominal de 6.2 cm (por encima del umbral quirúrgico de 5.5 cm en hombres) con cirugía diferida 3 semanas sin un plan de vigilancia estrecha ni educación sobre signos de alarma de ruptura, y sin optimización médica (estatina, antiagregación, cesación tabáquica) documentada; el error concreto es el diferimiento sin advertir al paciente que debe acudir de inmediato ante dolor abdominal, lumbar o síncope.", "consecuencia": "Ruptura del aneurisma antes de la cirugía, con mortalidad mayor al 80%; el paciente en casa sin saber qué es una alarma no llega vivo al hospital.", "debio": "Programar la reparación con la mayor prontitud posible (no diferir 3 semanas sin justificación), optimizar médicamente (estatina, control de presión, cesación tabáquica), y dar por escrito los signos de alarma de ruptura con la indicación de acudir a Urgencias de inmediato; si la espera es inevitable, vigilancia estrecha y contacto directo.", "exp": "Un aneurisma de 6.2 cm no espera tres semanas en casa sin instrucciones. El umbral se cruzó; el reloj de la ruptura ya está corriendo."},
    {"id": "QP-R3-06", "grade": "R3", "tema": "Trauma complejo y cirugía de control de daños", "nota": "Hombre de 28 años, politraumatizado por accidente automovilístico: fractura de pelvis inestable, lesión hepática grado IV, lesión esplénica grado III, hemoperitoneo masivo, TA 75/45 mmHg, FC 140 lpm, temperatura 34.8 °C, pH 7.18, INR 2.1, lactato 6.5 mmol/L. En quirófano se realiza laparotomía: empaquetamiento hepático, esplenectomía, control de sangrado pélvico con empaquetamiento, y se decide \"completar la cirugía definitiva en el mismo tiempo quirúrgico\" con reparación de todas las lesiones y cierre de pared abdominal, con duración total de 5 horas.", "error": "En un paciente con la tríada letal completa (hipotermia, acidosis, coagulopatía) se intentó cirugía definitiva prolongada en un solo tiempo, en lugar de cirugía de control de daños: control rápido de la hemorragia y la contaminación, empaquetamiento, cierre temporal y reanimación en terapia intensiva, con reintervención programada a las 24-48 horas.", "consecuencia": "Muerte en quirófano o en el postoperatorio inmediato por coagulopatía incoercible, hipotermia y acidosis progresivas; la cirugía definitiva en un paciente que se está muriendo lo mata más rápido que las lesiones.", "debio": "Cirugía de control de daños: laparotomía abreviada (control de hemorragia y contaminación, empaquetamiento), cierre temporal con sistema de presión negativa, reanimación hemostática, corrección de hipotermia, acidosis y coagulopatía en UCI, y cirugía definitiva diferida cuando la fisiología lo permita.", "exp": "El control de daños no es operar menos por flojera: es operar lo justo para que el paciente sobreviva a su propia fisiología. Cinco horas de cirugía definitiva con pH de 7.18 es una sentencia."},
    {"id": "QP-R3-07", "grade": "R3", "tema": "Cirugía de tórax, pleura y mediastino", "nota": "Hombre de 65 años, con derrame pleural derecho masivo y antecedente de cáncer de pulmón. Se realiza toracocentesis diagnóstica: líquido serohemático, proteínas 4.5 g/dL, LDH pleural 400 U/L, citología negativa. Se coloca sonda pleural con drenaje de 1,500 mL en la primera hora y se deja a derivación. El paciente presenta tos intensa, disnea súbita y SatO2 de 88% tras el drenaje. La radiografía muestra edema pulmonar unilateral. Se documenta \"derrame drenado exitosamente\".", "error": "Se drenaron 1,500 mL de líquido pleural en la primera hora sin control del volumen ni de la presión intrapleural, provocando edema pulmonar por reexpansión, complicación evitable al limitar el drenaje inicial a 1,000-1,500 mL con vigilancia y pinzamiento intermitente.", "consecuencia": "Edema pulmonar por reexpansión, hipoxemia grave, necesidad de ventilación mecánica y muerte; el pulmón que se reexpande de golpe se inunda.", "debio": "Drenaje pleural controlado: no más de 1,000 mL en la primera hora (o 1,500 mL como máximo absoluto con vigilancia estrecha), pinzamiento intermitente, monitorización de síntomas (tos, dolor torácico, disnea) y suspensión inmediata del drenaje ante tos intensa o dolor; la toracocentesis terapéutica debe ser lenta y vigilada.", "exp": "Drenar un derrame masivo no es vaciar un balde: el pulmón colapsado crónicamente se reexpande con edema si lo liberas de golpe. El volumen y la velocidad son el tratamiento."},
    {"id": "QP-R3-08", "grade": "R3", "tema": "Trasplante de órganos sólidos", "nota": "Hombre de 50 años, receptor de trasplante renal hace 6 meses, con inmunosupresión con tacrolimus, micofenolato y prednisona. Presenta dolor abdominal, fiebre y leucocitosis. TAC: apendicitis aguda perforada con absceso periapendicular. Se realiza apendicectomía abierta y drenaje del absceso. Postoperatorio: se mantiene la misma inmunosupresión sin ajustes, se indica antibiótico de amplio espectro y se egresa al día 5. No se solicita nivel de tacrolimus ni valoración de nefrología/trasplantes durante el ingreso.", "error": "No se ajustó ni se monitorizó la inmunosupresión durante una infección grave (peritonitis por apendicitis perforada) en un receptor de trasplante, ni se midieron niveles de tacrolimus, que además interactúan con los antibióticos y con el ayuno y la disfunción renal del postoperatorio.", "consecuencia": "Sepsis no controlada por inmunosupresión excesiva, o rechazo agudo del injerto si se suspende de golpe sin plan; toxicidad por tacrolimus (nefrotoxicidad, neurotoxicidad) por niveles no vigilados.", "debio": "Valoración inmediata por el equipo de trasplantes/nefrología, reducción temporal y protocolizada de la inmunosupresión durante la sepsis (generalmente suspender el antimetabolito y ajustar el inhibidor de calcineurina), medición seriada de niveles de tacrolimus y de función renal, y reintroducción gradual de la inmunosupresión al resolverse la infección.", "exp": "En un trasplantado con sepsis, la inmunosupresión no se deja en piloto automático: se ajusta con el equipo de trasplantes y con niveles en la mano. Ni seguir igual ni suspender todo: ajustar con plan."},
    {"id": "QP-R3-09", "grade": "R3", "tema": "Sepsis abdominal, abdomen abierto y paciente crítico", "nota": "Mujer de 70 años, con peritonitis secundaria por dehiscencia de anastomosis colónica, llevada a reintervención: lavado peritoneal, resección del segmento dehiscente, colostomía terminal y abdomen abierto con sistema de presión negativa. Ingresa a UCI con norepinefrina, ventilación mecánica y antibiótico de amplio espectro. Al día 2, con mejoría hemodinámica y lactato normal, se programa cierre de pared abdominal definitivo \"para no dejar el abdomen abierto más tiempo\". La nota indica cierre fascial primario con malla sintética.", "error": "Se planea el cierre fascial definitivo precoz (día 2) en un abdomen abierto con peritonitis y contaminación, sin haber realizado lavados seriados ni confirmado el control del foco, y con malla sintética en campo contaminado; el abdomen abierto se cierra cuando el foco está controlado y la fascia lo permite, generalmente entre los días 5-7, no por calendario.", "consecuencia": "Síndrome compartimental abdominal, dehiscencia, fístula enteroatmosférica, infección de malla y muerte; cerrar a la fuerza un abdomen que aún está séptico es peor que dejarlo abierto.", "debio": "Lavados peritoneales seriados y revaloración del foco, cierre fascial progresivo solo cuando la contaminación esté controlada, el edema haya disminuido y la fascia se aproxime sin tensión; si no es posible el cierre primario, cierre con malla biológica o sistema de tracción fascial y planeación de hernia ventral posterior.", "exp": "El abdomen abierto no se cierra por impaciencia: se cierra cuando la sepsis lo permite. Día 2 con peritonitis es cerrar la puerta con el incendio adentro."},
    {"id": "QP-R3-10", "grade": "R3", "tema": "Bazo", "nota": "Hombre de 24 años, con trauma abdominal cerrado, lesión esplénica grado III, estable hemodinámicamente tras reanimación, sin otras lesiones. Se decide manejo conservador con reposo absoluto, monitorización en UCI, hemoglobina seriada y ayuno. Evoluciona bien, sin resangrado. Al día 5 se egresa con indicaciones de reposo y cita en una semana. El paciente pregunta si necesita vacunas; se le responde que no, \"porque no se operó el bazo\".", "error": "Se egresó al día 5 sin documentar ni entregar las indicaciones de actividad tras una lesión esplénica grado III manejada conservadoramente (reposo relativo, prohibición de deportes de contacto y esfuerzos intensos por 6-8 semanas), ni los signos de alarma de ruptura diferida, ni el plan de imagen de control.", "consecuencia": "Ruptura esplénica diferida en casa o durante un esfuerzo, con choque hemorrágico y muerte; el bazo que sangró una vez puede volver a sangrar sin aviso.", "debio": "Egreso con indicaciones escritas: reposo relativo, prohibición de deportes de contacto y esfuerzos intensos por 6-8 semanas (según grado), signos de alarma (dolor abdominal súbito, mareo, síncope) con indicación de acudir a Urgencias de inmediato, y TAC o ultrasonido de control según protocolo; la vacunación antineumocócica y contra Haemophilus y meningococo se reserva para la esplenectomía, no para el manejo conservador, y así debió explicarse.", "exp": "El manejo conservador del bazo no termina con el egreso: termina con las instrucciones. Un grado III sin plan de actividad ni alarmas es un resangrado esperando el momento."},
    {"id": "QP-R4-01", "grade": "R4", "tema": "Cirugía hepatobiliar avanzada", "nota": "Hombre de 58 años, con tumor de Klatskin (colangiocarcinoma hiliar) tipo IIIa de Bismuth-Corlette, bilirrubina total 12 mg/dL, sin metástasis a distancia. Se programa hepatectomía derecha extendida con resección de la vía biliar. Se realiza drenaje biliar preoperatorio con prótesis endoscópica y se solicita volumetría hepática por TAC: remanente hepático futuro (lóbulo izquierdo) del 22%. Se indica optimización nutricional y se programa la cirugía para la próxima semana. No se documenta embolización portal preoperatoria ni valoración de función hepática con verde de indocianina.", "error": "Remanente hepático futuro del 22% en un hígado colestásico, por debajo del umbral de seguridad (30-40% en hígado enfermo o colestásico), sin haber realizado embolización portal preoperatoria para hipertrofiar el remanente antes de una hepatectomía mayor.", "consecuencia": "Falla hepática posthepatectomía, la principal causa de muerte tras resección hepática mayor; el hígado que queda no alcanza para vivir.", "debio": "Embolización portal preoperatoria del lóbulo a resecar, esperar 4-6 semanas con volumetría de control hasta alcanzar un remanente suficiente (>30-40% en hígado colestásico), optimizar la bilirrubina con drenaje biliar y valorar la función hepática antes de programar la resección.", "exp": "El porcentaje de hígado que queda decide si el paciente sobrevive a la cirugía. Con 22% y colestasis no se opera: se emboliza, se espera y se vuelve a medir."},
    {"id": "QP-R4-02", "grade": "R4", "tema": "Cirugía pancreática avanzada", "nota": "Mujer de 62 años, con adenocarcinoma de cabeza de páncreas de 2.5 cm, resecable por TAC (sin invasión vascular), CA 19-9 de 450 U/mL, bilirrubina 8 mg/dL, sin metástasis. Se programa pancreatoduodenectomía (Whipple) directa para la próxima semana, sin neoadyuvancia ni drenaje biliar preoperatorio. La nota indica \"tumor resecable, cirugía de entrada, adyuvancia según patología\".", "error": "Cáncer de páncreas resecable llevado directo a cirugía sin valorar terapia neoadyuvante (estándar creciente, guías NCCN), en un tumor con CA 19-9 elevado (450 U/mL) que sugiere enfermedad micrometastásica oculta.", "consecuencia": "Recurrencia temprana por enfermedad micrometastásica no tratada, cirugía sobre un tumor que pudo haberse reducido, y peor supervivencia global; el Whipple sin neoadyuvancia en este escenario desperdicia la ventana de tratamiento sistémico.", "debio": "Discusión en comité multidisciplinario, valoración de quimioterapia neoadyuvante (por ejemplo, FOLFIRINOX modificado según estado funcional) con reestadificación posterior, drenaje biliar si hay colangitis o demora quirúrgica, y Whipple solo tras la neoadyuvancia y con bilirrubina optimizada.", "exp": "Un CA 19-9 de 450 no es un tumor \"tranquilo\": grita enfermedad sistémica oculta. El páncreas resecable de hoy se trata primero con quimioterapia y luego con cirugía, no al revés."},
    {"id": "QP-R4-03", "grade": "R4", "tema": "Cirugía oncológica avanzada y carcinomatosis peritoneal", "nota": "Mujer de 54 años, con cáncer de ovario con carcinomatosis peritoneal, índice de carcinomatosis peritoneal (PCI) de 24 por TAC y laparoscopia diagnóstica. Se programa cirugía citorreductora con quimioterapia intraperitoneal hipertérmica (HIPEC) para la próxima semana. La paciente tiene ECOG 2, albúmina 2.9 g/dL, pérdida de 10 kg, y antecedente de 2 líneas de quimioterapia sistémica. No se documenta valoración de fragilidad, de estado nutricional ni de la probabilidad de citorreducción completa (CC-0).", "error": "Se programa citorreducción más HIPEC, procedimiento de muy alta morbilidad, en una paciente frágil (ECOG 2, desnutrición grave, PCI alto de 24) sin haber documentado la valoración de resecabilidad completa ni la optimización preoperatoria, y sin discutir en comité si la citorreducción completa es alcanzable; con PCI de 24 la probabilidad de CC-0 es baja y el beneficio del HIPEC es dudoso.", "consecuencia": "Morbimortalidad perioperatoria muy alta sin beneficio oncológico, estancia prolongada en UCI, fístulas y muerte; una citorreducción incompleta con HIPEC es el peor escenario: todo el riesgo, ningún beneficio.", "debio": "Valoración multidisciplinaria estricta de la probabilidad de citorreducción completa, optimización nutricional y funcional preoperatoria, y selección rigurosa: citorreducción más HIPEC solo si la CC-0 es alcanzable y la paciente lo tolera; si no, quimioterapia sistémica o cuidados paliativos.", "exp": "El HIPEC no es para quien lo pide, es para quien lo tolera y en quien se logra citorreducción completa. Un PCI de 24 con ECOG 2 y desnutrición es una selección que se hizo con el corazón, no con los criterios."},
    {"id": "QP-R4-04", "grade": "R4", "tema": "Cirugía colorrectal avanzada", "nota": "Hombre de 68 años, con cáncer de recto bajo (a 4 cm del margen anal), T3N1, que recibió quimiorradioterapia neoadyuvante con buena respuesta. Se programa resección abdominoperineal (operación de Miles) con colostomía permanente. En la valoración preoperatoria no se documenta la conversación sobre la colostomía permanente ni la valoración por el servicio de estomas, ni se discute la posibilidad de preservación de esfínteres con resección anterior ultrabaja e ileostomía temporal de protección. El paciente firma el consentimiento para \"resección de recto con colostomía\".", "error": "Se planea una colostomía permanente (Miles) sin haber discutido con el paciente la alternativa de preservación de esfínteres ni haberlo valorado por el servicio de estomas, y sin documentar una decisión compartida sobre un estoma definitivo que cambia la vida del paciente para siempre.", "consecuencia": "Colostomía permanente evitable, deterioro de la calidad de vida, depresión y mala adaptación al estoma por falta de preparación; una decisión de este calibre no se toma sin el paciente.", "debio": "Discusión detallada de las opciones (preservación de esfínteres con resección anterior ultrabaja e ileostomía temporal vs. Miles con colostomía permanente), valoración preoperatoria por enfermería de estomas con marcaje del sitio, educación y apoyo psicológico, y decisión compartida documentada en el consentimiento informado.", "exp": "Una colostomía permanente no es un detalle técnico: es una vida distinta. Se discute, se marca, se prepara, y se decide con el paciente, no por él."},
    {"id": "QP-R4-05", "grade": "R4", "tema": "Cirugía bariátrica y metabólica", "nota": "Mujer de 39 años, con obesidad mórbida (IMC 46), diabetes tipo 2, hipertensión y apnea del sueño, programada para bypass gástrico en Y de Roux laparoscópico. Valoración preoperatoria: cardiología, neumología y endocrinología sin contraindicaciones. Se indica dieta líquida 2 semanas antes, profilaxis antitrombótica y antibiótica. No se solicita valoración psiquiátrica ni psicológica preoperatoria, ni se documenta la evaluación de trastornos de la conducta alimentaria o de consumo de alcohol. La nota indica \"paciente motivada, comprende el procedimiento\".", "error": "No se realizó la valoración psiquiátrica/psicológica preoperatoria obligatoria antes de una cirugía bariátrica, que forma parte del protocolo multidisciplinario y detecta trastornos de la conducta alimentaria, depresión, consumo de alcohol y expectativas irreales que predicen el fracaso o las complicaciones.", "consecuencia": "Fracaso en la pérdida de peso, transferencia de adicciones (alcohol), trastornos alimentarios postoperatorios, depresión y reganancia de peso; operar el estómago sin valorar la cabeza es operar la mitad del problema.", "debio": "Evaluación psicológica/psiquiátrica formal preoperatoria como parte del equipo multidisciplinario (cirugía, nutrición, psicología, endocrinología), con detección de trastornos alimentarios, depresión y consumo de sustancias, y tratamiento previo si es necesario; el bypass no se programa sin ese visto bueno.", "exp": "La cirugía bariátrica es un tratamiento multidisciplinario por norma, no por cortesía. Sin valoración psicológica no hay bypass: hay un estómago operado y una conducta sin tratar."},
    {"id": "QP-R4-06", "grade": "R4", "tema": "Complicaciones quirúrgicas complejas, fístulas y nutrición", "nota": "Hombre de 66 años, día 8 postoperatorio de pancreatoduodenectomía, con drenaje abdominal con gasto de 400 mL/día de líquido claro con amilasa de 12,000 U/L (amilasa sérica 90 U/L). Se diagnostica fístula pancreática postoperatoria grado B. Se mantiene el drenaje, ayuno absoluto, nutrición parenteral total y octreótido. Al día 14 el gasto persiste en 350 mL/día, sin fiebre ni leucocitosis. Se decide mantener el mismo manejo \"hasta que cierre sola\" sin estudios de imagen ni valoración de nutrición enteral.", "error": "Fístula pancreática grado B manejada con ayuno prolongado y nutrición parenteral total por más de 2 semanas, sin haber iniciado nutrición enteral (que es segura y preferible en fístula pancreática) ni haber realizado TAC para descartar una colección asociada que requiera drenaje, y sin un plan escalonado de manejo.", "consecuencia": "Desnutrición, atrofia intestinal, infección asociada a catéter por nutrición parenteral prolongada, estancia hospitalaria eterna y fístula que no cierra por falta de soporte nutricional adecuado.", "debio": "Iniciar nutrición enteral temprana (yeyunal si es necesario), mantener el drenaje bien posicionado, realizar TAC para descartar colecciones, suspender el octreótido si no hay beneficio demostrado, y revalorar con un plan escalonado (drenaje percutáneo de colecciones, endoscopia o cirugía solo si fracasa el manejo conservador).", "exp": "La fístula pancreática no se cura con ayuno y parenteral eterna: se cura con nutrición enteral, drenaje que funcione y descartar la colección que la mantiene abierta."},
    {"id": "QP-R4-07", "grade": "R4", "tema": "Cirugía vascular, torácica y emergencias toracoabdominales", "nota": "Hombre de 70 años, con dolor torácico súbito desgarrante irradiado a espalda, TA 190/110 mmHg en brazo derecho y 150/90 mmHg en brazo izquierdo, soplo diastólico, ensanchamiento mediastinal en radiografía. Angio-TAC: disección aórtica tipo A de Stanford (ascendente). Se inicia control de presión arterial con nitroprusiato IV, analgesia y se avisa a cirugía cardiotorácica. Se indica \"control de TA <120 mmHg sistólica\" y se espera la valoración quirúrgica. No se administra betabloqueador.", "error": "En una disección aórtica aguda se inició vasodilatador (nitroprusiato) sin betabloqueo previo, lo que aumenta la fuerza de eyección y la velocidad de propagación de la disección; el orden correcto es betabloqueador primero (para reducir la dP/dt) y después vasodilatador si la presión sigue alta.", "consecuencia": "Propagación de la disección, ruptura aórtica, taponamiento cardiaco y muerte en minutos; el nitroprusiato solo es gasolina para la disección.", "debio": "Betabloqueador IV primero (esmolol o labetalol) para control de la frecuencia cardiaca (<60 lpm) y de la dP/dt, y solo después vasodilatador (nitroprusiato o nicardipino) para la presión sistólica objetivo de 100-120 mmHg; cirugía urgente de la disección tipo A sin demora.", "exp": "En disección aórtica el orden es ley: beta primero, vasodilatador después. Al revés, el vasodilatador aumenta el golpe de cada latido sobre la pared disecada."},
    {"id": "QP-R4-08", "grade": "R4", "tema": "Cirugía de trasplantes, bazo e inmunocomprometido", "nota": "Mujer de 33 años, con púrpura trombocitopénica inmune refractaria a esteroides y rituximab, plaquetas 18,000/µL, programada para esplenectomía laparoscópica electiva. Se solicita valoración hematológica, se indica vacunación antineumocócica, contra Haemophilus influenzae tipo b y antimeningocócica, y se programa la cirugía para 3 días después de las vacunas. Se indica profilaxis antibiótica perioperatoria y transfusión de plaquetas en quirófano. La nota indica \"vacunación completa preoperatoria\".", "error": "Las vacunas contra gérmenes encapsulados se administraron solo 3 días antes de la esplenectomía, cuando deben aplicarse al menos 2 semanas antes de la cirugía electiva para lograr una respuesta inmune adecuada; con 3 días, la paciente llega al quirófano sin protección.", "consecuencia": "Sepsis fulminante posesplenectomía (OPSI), con mortalidad de hasta 50%, por neumococo, Haemophilus o meningococo; la vacuna puesta tarde es casi como no ponerla.", "debio": "Aplicar las vacunas al menos 2 semanas antes de la esplenectomía electiva (idealmente 4-6 semanas), documentar el esquema completo y, si la cirugía es urgente y no se alcanzó el plazo, vacunar en el postoperatorio temprano (a las 2 semanas) y dar profilaxis antibiótica y educación de por vida sobre el riesgo de OPSI.", "exp": "La vacuna posesplenectomía tiene fecha: mínimo 2 semanas antes. Tres días antes es llegar tarde a la única protección que tiene el paciente sin bazo."},
    {"id": "QP-R4-09", "grade": "R4", "tema": "Liderazgo quirúrgico, gestión, ética, investigación y enseñanza", "nota": "Residente de segundo año realiza una apendicectomía laparoscópica bajo supervisión. Durante el procedimiento, el residente lesiona inadvertidamente el ciego con el trocar, lesión que el adscrito repara con sutura en el mismo tiempo quirúrgico. El paciente evoluciona bien. En la nota quirúrgica se documenta \"procedimiento sin complicaciones\" y no se menciona la lesión ni su reparación. En el pase de visita se informa al paciente que \"todo salió bien\". El residente comenta el evento con sus compañeros pero no se registra en el sistema de eventos adversos del hospital.", "error": "No se documentó ni se informó al paciente sobre una lesión iatrogénica (perforación de ciego) ocurrida durante la cirugía y reparada en el mismo acto, violando el deber de veracidad, el consentimiento informado continuo y el sistema de reporte de eventos adversos; la nota quirúrgica dice \"sin complicaciones\" cuando sí las hubo.", "consecuencia": "Pérdida de confianza, exposición legal grave si el paciente desarrolla una complicación y descubre que se le ocultó, y pérdida de la oportunidad de aprendizaje institucional; los errores que se esconden se repiten.", "debio": "Documentar la lesión y su reparación en la nota quirúrgica, informar al paciente (y a su familia) con honestidad y empatía sobre lo ocurrido, lo que se hizo y la vigilancia posterior, y registrar el evento en el sistema de eventos adversos para análisis y prevención; la revelación honesta es un deber ético, no una opción.", "exp": "\"Sin complicaciones\" con un ciego suturado es mentir en el expediente. El paciente tiene derecho a saber qué pasó en su cuerpo, y el hospital tiene derecho a aprender del error."},
    {"id": "QP-R4-10", "grade": "R4", "tema": "Musculoesquelético y pie diabético", "nota": "Hombre de 63 años, diabético tipo 2 de 20 años de evolución, con úlcera plantar en pie derecho de 4 cm, con exposición tendinosa, pulsos pedios débiles, índice tobillo-brazo de 0.55, HbA1c 9.8%, leucocitos 16,000/µL, PCR elevada y secreción purulenta. Se diagnostica pie diabético infectado con isquemia. Se inicia antibiótico de amplio espectro, curaciones diarias y descarga con bota ortopédica. Se programa desbridamiento quirúrgico para la próxima semana. No se solicita valoración vascular urgente ni estudios de perfusión adicionales.", "error": "Pie diabético infectado con isquemia crítica (índice tobillo-brazo 0.55, pulsos débiles) en el que se difirió la valoración vascular urgente y el desbridamiento quirúrgico por una semana, cuando la infección con isquemia requiere desbridamiento urgente y revascularización temprana; la infección en un pie isquémico no espera.", "consecuencia": "Progresión de la infección, gangrena, amputación mayor y sepsis con muerte; cada día sin desbridamiento ni perfusión es tejido que se pierde.", "debio": "Desbridamiento quirúrgico urgente de la úlcera infectada, valoración vascular inmediata (angio-TAC o angiografía) con plan de revascularización, antibiótico guiado por cultivos profundos, control glucémico estricto y descarga total; el pie diabético infectado e isquémico es una urgencia, no una cita de la próxima semana.", "exp": "Infección más isquemia es la peor combinación del pie diabético: el antibiótico no llega donde no hay sangre y la infección no espera al desbridamiento de la próxima semana."},
  ],
  duelo: [
    {"id": "DR-R1-01", "grade": "R1", "tag": "Estado de choque", "q": "En un adulto de 70 kg, ¿qué pérdida sanguínea corresponde al choque hipovolémico clase III del ATLS?", "opts": ["1,500–2,000 mL (30–40 % de la volemia)", "Menos de 750 mL (menos del 15 %)", "750–1,500 mL (15–30 %)", "Más de 2,000 mL (más del 40 %)"], "ans": 0, "exp": "La clase III del ATLS es 30–40 % de pérdida (1,500–2,000 mL en 70 kg), con taquicardia marcada, hipotensión y oliguria."},
    {"id": "DR-R1-02", "grade": "R1", "tag": "Líquidos y electrolitos", "q": "¿Cuál es la concentración de sodio del suero fisiológico al 0.9 %?", "opts": ["77 mEq/L", "154 mEq/L", "130 mEq/L", "100 mEq/L"], "ans": 1, "exp": "El suero fisiológico aporta 154 mEq/L de sodio y 154 mEq/L de cloro, por eso su uso masivo favorece acidosis hiperclorémica."},
    {"id": "DR-R1-03", "grade": "R1", "tag": "Nutrición en cirugía", "q": "En un paciente crítico que no puede comer por vía oral, ¿cuándo debe iniciarse la nutrición enteral según ESPEN?", "opts": ["Después de 7 días de ayuno", "Solo cuando tolere dieta oral completa", "Dentro de las primeras 24–48 horas", "Nunca; siempre es mejor la parenteral"], "ans": 2, "exp": "ESPEN recomienda nutrición enteral temprana (24–48 h) en el paciente crítico, porque preserva la mucosa intestinal y reduce infecciones."},
    {"id": "DR-R1-04", "grade": "R1", "tag": "Sangre, hemostasia y transfusión", "q": "En un paciente quirúrgico estable, sin cardiopatía, ¿cuál es el umbral restrictivo habitual para transfundir concentrado eritrocitario?", "opts": ["Hemoglobina menor de 10 g/dL", "Hemoglobina menor de 9 g/dL", "Hemoglobina menor de 8 g/dL", "Hemoglobina menor de 7 g/dL"], "ans": 3, "exp": "La estrategia restrictiva (umbral de 7 g/dL en el paciente estable) es segura y reduce transfusiones innecesarias según las guías de la AABB."},
    {"id": "DR-R1-05", "grade": "R1", "tag": "Cicatrización y cuidado de las heridas", "q": "¿Qué tipo de colágeno predomina en la fase proliferativa temprana de la cicatrización?", "opts": ["Colágeno tipo III", "Colágeno tipo I", "Colágeno tipo II", "Colágeno tipo IV"], "ans": 0, "exp": "Al inicio se deposita colágeno tipo III, débil y desorganizado; con la remodelación es sustituido por colágeno tipo I, más resistente."},
    {"id": "DR-R1-06", "grade": "R1", "tag": "Infección en cirugía", "q": "¿Cuándo debe administrarse la profilaxis antibiótica preoperatoria para que sea eficaz?", "opts": ["12 horas antes de la incisión", "Dentro de los 60 minutos previos a la incisión", "Al terminar la cirugía, en recuperación", "24 horas después de la cirugía"], "ans": 1, "exp": "El antibiótico debe estar en tejido en el momento de la incisión; darlo antes de los 60 minutos previos es el estándar aceptado (120 min para vancomicina)."},
    {"id": "DR-R1-07", "grade": "R1", "tag": "Hernias de pared abdominal", "q": "¿Qué hernia es más frecuente en mujeres y tiene el mayor riesgo de estrangulación?", "opts": ["Hernia inguinal indirecta", "Hernia umbilical", "Hernia femoral", "Hernia incisional"], "ans": 2, "exp": "La hernia femoral predomina en mujeres, su anillo es rígido y estrecho, por eso se estrangula con más frecuencia y suele requerir reparación pronta."},
    {"id": "DR-R1-08", "grade": "R1", "tag": "Abdomen agudo y apendicitis aguda", "q": "En un adolescente con sospecha de apendicitis aguda, ¿cuál es el estudio de imagen de primera línea?", "opts": ["Tomografía con contraste", "Resonancia magnética", "Radiografía simple de abdomen", "Ultrasonido"], "ans": 3, "exp": "En niños y adolescentes se prefiere el ultrasonido como primer estudio porque no irradia; la tomografía se reserva para casos dudosos o complicados."},
    {"id": "DR-R1-09", "grade": "R1", "tag": "Patología biliar", "q": "¿Cuáles son los tres componentes de la tríada de Charcot en la colangitis aguda?", "opts": ["Fiebre, ictericia y dolor en hipocondrio derecho", "Fiebre, vómito y masa palpable", "Ictericia, prurito y pérdida de peso", "Dolor, distensión y ausencia de evacuaciones"], "ans": 0, "exp": "La tríada de Charcot (fiebre, ictericia y dolor en hipocondrio derecho) es el cuadro clásico de la colangitis; con hipotensión y confusión se vuelve la pentada de Reynolds."},
    {"id": "DR-R1-10", "grade": "R1", "tag": "Trauma: evaluación inicial ATLS", "q": "En la evaluación primaria del ATLS, ¿qué corresponde a la letra A?", "opts": ["Circulación con control de hemorragia", "Vía aérea con protección de la columna cervical", "Respiración y ventilación", "Déficit neurológico"], "ans": 1, "exp": "La A del ABCDE es la vía aérea, siempre con control de la columna cervical; sin vía aérea permeable nada de lo demás importa."},
    {"id": "DR-R1-11", "grade": "R1", "tag": "Profesionalismo, ética y consentimiento informado", "q": "¿Qué tres elementos debe reunir un consentimiento informado válido?", "opts": ["Firma del familiar, testigos y sello del hospital", "Urgencia, gravedad y disponibilidad de quirófano", "Capacidad, información adecuada y voluntariedad", "Diagnóstico confirmado, presupuesto y fecha de cirugía"], "ans": 2, "exp": "Sin capacidad para decidir, sin información comprensible sobre riesgos y alternativas, y sin libertad para elegir, no hay consentimiento válido."},
    {"id": "DR-R1-12", "grade": "R1", "tag": "Técnica quirúrgica", "q": "¿Qué sutura es monofilamento, no absorbible y la más usada para el cierre de la fascia abdominal?", "opts": ["Ácido poliglicólico", "Catgut crómico", "Poliglactina 910 (Vicryl)", "Polipropileno"], "ans": 3, "exp": "El polipropileno es monofilamento no absorbible, con mínima reacción tisular y alta resistencia, ideal para el cierre aponeurótico."},
    {"id": "DR-R1-13", "grade": "R1", "tag": "Piel y tejido subcutáneo", "q": "En el melanoma cutáneo, ¿cuál es el factor pronóstico más importante?", "opts": ["El grosor de Breslow", "El color de la lesión", "La edad del paciente", "La localización en extremidades"], "ans": 0, "exp": "El grosor de Breslow (en milímetros, desde la capa granulosa hasta la célula más profunda) es el principal predictor de metástasis y supervivencia."},
    {"id": "DR-R1-14", "grade": "R1", "tag": "Estado de choque", "q": "En el choque séptico, ¿en cuánto tiempo deben iniciarse los antibióticos según la Surviving Sepsis Campaign?", "opts": ["Dentro de las primeras 6 horas", "Dentro de la primera hora", "Dentro de las primeras 3 horas", "Después de tener todos los cultivos"], "ans": 1, "exp": "En el choque séptico cada hora de retraso antibiótico aumenta la mortalidad, por eso la meta es administrarlos dentro de la primera hora."},
    {"id": "DR-R1-15", "grade": "R1", "tag": "Líquidos y electrolitos", "q": "¿Qué hallazgo electrocardiográfico es clásico de la hipopotasemia?", "opts": ["Ondas T picudas", "QRS ensanchado", "Onda U prominente", "Intervalo QT acortado"], "ans": 2, "exp": "La hipopotasemia produce aplanamiento de la onda T, depresión del ST y onda U prominente; las T picudas son de hiperpotasemia."},
    {"id": "DR-R1-16", "grade": "R1", "tag": "Cuidados perioperatorios", "q": "¿Qué escala se usa para estimar el riesgo de tromboembolia venosa en el paciente quirúrgico?", "opts": ["Escala de Alvarado", "Escala de Glasgow", "Escala de Child-Pugh", "Escala de Caprini"], "ans": 3, "exp": "La escala de Caprini estratifica el riesgo de tromboembolia venosa y guía la intensidad de la profilaxis (mecánica, farmacológica o ambas)."},
    {"id": "DR-R1-17", "grade": "R1", "tag": "Infección en cirugía", "q": "¿Cómo se clasifica una colecistectomía electiva en la que se abre la vesícula de forma controlada, sin derrame ni infección?", "opts": ["Herida limpia-contaminada", "Herida limpia", "Herida contaminada", "Herida sucia o infectada"], "ans": 0, "exp": "Abrir una víscera hueca en condiciones controladas, sin contaminación grosera, define la herida limpia-contaminada."},
    {"id": "DR-R1-18", "grade": "R1", "tag": "Trauma: evaluación inicial ATLS", "q": "Paciente hipotenso tras trauma cerrado de abdomen, con FAST positivo. ¿Cuál es la conducta correcta?", "opts": ["Observación y FAST de control en 6 horas", "Llevarlo de inmediato a quirófano (laparotomía)", "Tomografía de abdomen con contraste", "Transfundir y esperar a que se estabilice"], "ans": 1, "exp": "Paciente inestable con FAST positivo tiene sangrado intraabdominal activo; no se pierde tiempo en tomografía, se va a quirófano."},
    {"id": "DR-R1-19", "grade": "R1", "tag": "Nutrición en cirugía", "q": "¿Qué vitamina es indispensable para la síntesis de colágeno y la cicatrización?", "opts": ["Vitamina A", "Vitamina D", "Vitamina C", "Vitamina B12"], "ans": 2, "exp": "La vitamina C es cofactor de la hidroxilación de prolina y lisina en la síntesis de colágeno; su déficit produce heridas que no cierran."},
    {"id": "DR-R1-20", "grade": "R1", "tag": "Sangre, hemostasia y transfusión", "q": "¿Cuál es el umbral habitual de plaquetas para realizar una cirugía mayor en un paciente sin sangrado activo?", "opts": ["10,000/µL", "20,000/µL", "100,000/µL", "50,000/µL"], "ans": 3, "exp": "Para cirugía mayor se busca al menos 50,000 plaquetas/µL; para procedimientos menores o punción lumbar el umbral es distinto."},
    {"id": "DR-R2-01", "grade": "R2", "tag": "Patología esofágica y ERGE", "q": "¿Cuál es el estudio de referencia (estándar de oro) para confirmar el reflujo gastroesofágico?", "opts": ["Endoscopia digestiva alta", "pHmetría esofágica de 24 horas", "Manometría esofágica", "Serie esofagogastroduodenal con bario"], "ans": 1, "exp": "La pHmetría de 24 horas documenta los episodios de reflujo ácido y su correlación con los síntomas; la endoscopia ve el daño, no siempre el reflujo."},
    {"id": "DR-R2-02", "grade": "R2", "tag": "Úlcera péptica y hemorragia digestiva alta", "q": "En la clasificación endoscópica de Forrest, ¿qué corresponde al grado Ia?", "opts": ["Úlcera con base limpia", "Coágulo adherido", "Sangrado activo en chorro", "Vaso visible sin sangrado"], "ans": 2, "exp": "Forrest Ia es sangrado activo en chorro y Ib en rezumado; ambos tienen el mayor riesgo de resangrado y requieren hemostasia endoscópica."},
    {"id": "DR-R2-03", "grade": "R2", "tag": "Patología hepática quirúrgica", "q": "¿Cuál es el tratamiento de primera línea del absceso hepático amebiano no complicado?", "opts": ["Drenaje quirúrgico abierto", "Resección hepática", "Drenaje percutáneo de rutina", "Metronidazol"], "ans": 3, "exp": "El absceso amebiano responde al metronidazol en la gran mayoría de los casos; el drenaje se reserva para falta de respuesta, riesgo de ruptura o duda diagnóstica."},
    {"id": "DR-R2-04", "grade": "R2", "tag": "Patología biliar (Tokio TG18)", "q": "Según las Guías de Tokio TG18, ¿qué define a la colecistitis aguda grado III (grave)?", "opts": ["Disfunción de algún órgano (cardiovascular, neurológica, respiratoria, renal, hepática o hematológica)", "Duración de los síntomas mayor de 72 horas", "Leucocitos mayores de 18,000/µL sin falla orgánica", "Vesícula con pared engrosada en el ultrasonido"], "ans": 0, "exp": "El grado III de Tokio es la colecistitis con disfunción orgánica; el grado II es la moderada (leucocitosis marcada, masa palpable o síntomas prolongados)."},
    {"id": "DR-R2-05", "grade": "R2", "tag": "Pancreatitis aguda", "q": "Según la clasificación de Atlanta revisada, ¿qué define a la pancreatitis aguda grave?", "opts": ["Dolor abdominal que dura más de 48 horas", "Falla orgánica persistente por más de 48 horas", "Amilasa mayor de tres veces el límite normal", "Presencia de un pseudoquiste"], "ans": 1, "exp": "La pancreatitis grave es la que cursa con falla orgánica persistente (>48 h); si la falla es transitoria es moderadamente grave."},
    {"id": "DR-R2-06", "grade": "R2", "tag": "Apendicitis aguda y abdomen agudo", "q": "Según las guías de la WSES, ¿cuál es el abordaje quirúrgico de elección para la apendicitis aguda no complicada?", "opts": ["Laparotomía media", "Incisión de McBurney siempre", "Apendicectomía laparoscópica", "Manejo conservador con antibiótico en todos los casos"], "ans": 2, "exp": "La WSES recomienda la apendicectomía laparoscópica como primera opción por menor dolor, menos infección de herida y alta más temprana."},
    {"id": "DR-R2-07", "grade": "R2", "tag": "Hernias de la pared abdominal", "q": "¿En qué se distingue anatómicamente la hernia inguinal indirecta de la directa?", "opts": ["La indirecta sale por el triángulo de Hesselbach", "La indirecta se origina medial a los vasos epigástricos inferiores", "La indirecta nunca llega al escroto", "La indirecta es siempre bilateral"], "ans": 3, "exp": "La hernia indirecta sigue el conducto inguinal desde el anillo interno, lateral a los vasos epigástricos inferiores; la directa protruye por el triángulo de Hesselbach, medial a ellos."},
    {"id": "DR-R2-08", "grade": "R2", "tag": "Obstrucción intestinal y vólvulo", "q": "¿Qué signo radiológico es clásico del vólvulo de sigmoides?", "opts": ["Signo del grano de café", "Niveles hidroaéreos en escalera", "Signo de la doble pared", "Neumoperitoneo"], "ans": 0, "exp": "El asa sigmoidea distendida y torcida dibuja en la radiografía la imagen del grano de café, orientada hacia el cuadrante superior derecho."},
    {"id": "DR-R2-09", "grade": "R2", "tag": "Enfermedad diverticular", "q": "En la clasificación de Hinchey, ¿qué corresponde al estadio III de la diverticulitis complicada?", "opts": ["Absceso pericólico", "Peritonitis purulenta generalizada", "Absceso pélvico a distancia", "Peritonitis fecal generalizada"], "ans": 1, "exp": "Hinchey III es peritonitis purulenta generalizada por ruptura de absceso; el IV es peritonitis fecal, el I absceso pericólico y el II absceso a distancia."},
    {"id": "DR-R2-10", "grade": "R2", "tag": "Cáncer de colon", "q": "¿Qué manifestación es más típica del cáncer de colon derecho?", "opts": ["Cambio en el hábito intestinal con heces acintadas", "Tenesmo y sangrado rojo rutilante", "Anemia ferropénica y pérdida de peso", "Obstrucción intestinal como primer síntoma"], "ans": 2, "exp": "El colon derecho tiene luz amplia y contenido líquido, por eso el tumor sangra de forma oculta y se presenta con anemia ferropénica; el izquierdo obstruye antes."},
    {"id": "DR-R2-11", "grade": "R2", "tag": "Cáncer de recto y ano", "q": "¿A partir de qué edad se recomienda en México el tamizaje de cáncer colorrectal en personas de riesgo promedio?", "opts": ["30 años", "40 años", "50 años", "45 años"], "ans": 3, "exp": "Las guías actuales adelantan el inicio del tamizaje a los 45 años en personas de riesgo promedio, por el aumento de casos en adultos jóvenes."},
    {"id": "DR-R2-12", "grade": "R2", "tag": "Trauma abdominal e infección intraabdominal", "q": "En un paciente hemodinámicamente estable con lesión esplénica cerrada, ¿cuál es el manejo inicial preferido?", "opts": ["Manejo no operatorio con vigilancia estrecha", "Esplenectomía inmediata", "Laparotomía exploradora de rutina", "Transfusión masiva preventiva"], "ans": 0, "exp": "En el paciente estable con lesión esplénica, el manejo no operatorio (con o sin embolización) preserva el bazo y es el estándar actual."},
    {"id": "DR-R2-13", "grade": "R2", "tag": "Patología esofágica", "q": "¿Qué define histológicamente al esófago de Barrett?", "opts": ["Metaplasia escamosa del esófago distal", "Metaplasia intestinal (columnar con células caliciformes) del esófago distal", "Displasia de alto grado sin metaplasia", "Inflamación eosinofílica de la mucosa"], "ans": 1, "exp": "El Barrett es la sustitución del epitelio escamoso por epitelio columnar de tipo intestinal, lesión premaligna que exige vigilancia endoscópica."},
    {"id": "DR-R2-14", "grade": "R2", "tag": "Patología gástrica quirúrgica", "q": "Ante una úlcera gástrica, ¿qué debe hacerse siempre durante la endoscopia?", "opts": ["Dilatar la úlcera", "Medir el pH gástrico", "Tomar biopsias de los bordes", "Cauterizarla aunque no sangre"], "ans": 2, "exp": "A diferencia de la duodenal, la úlcera gástrica puede ser maligna, por eso siempre se biopsian sus bordes y se repite la endoscopia para confirmar cicatrización."},
    {"id": "DR-R2-15", "grade": "R2", "tag": "Pancreatitis crónica", "q": "¿Qué hallazgo de imagen es más característico de la pancreatitis crónica avanzada?", "opts": ["Vesícula distendida sin cálculos", "Engrosamiento de la pared gástrica", "Dilatación de la vía biliar sin obstrucción", "Páncreas atrófico con calcificaciones"], "ans": 3, "exp": "La pancreatitis crónica avanzada muestra páncreas atrófico, conducto dilatado e irregular y calcificaciones parenquimatosas, con dolor crónico e insuficiencia exocrina y endocrina."},
    {"id": "DR-R2-16", "grade": "R2", "tag": "Patología biliar", "q": "¿Cuál es el mejor estudio no invasivo para confirmar una coledocolitiasis antes de decidir tratamiento?", "opts": ["Colangiorresonancia magnética", "Radiografía simple de abdomen", "Tomografía sin contraste", "Ultrasonido endoscópico en todos los casos"], "ans": 0, "exp": "La colangiorresonancia tiene alta sensibilidad y especificidad para cálculos del colédoco sin ser invasiva; la CPRE se reserva para cuando se va a tratar."},
    {"id": "DR-R2-17", "grade": "R2", "tag": "Enfermedad diverticular", "q": "En una diverticulitis complicada con absceso mayor de 4 cm, ¿cuál es la conducta recomendada?", "opts": ["Antibiótico oral y alta inmediata", "Drenaje percutáneo guiado por imagen más antibióticos", "Colectomía de urgencia en todos los casos", "Colonoscopia urgente"], "ans": 1, "exp": "Los abscesos diverticulares mayores de 3–4 cm se drenan por vía percutánea con antibióticos, lo que evita o difiere la cirugía de urgencia."},
    {"id": "DR-R2-18", "grade": "R2", "tag": "Obstrucción intestinal e isquemia", "q": "¿Qué dato clínico es el más sugestivo de isquemia intestinal en una obstrucción?", "opts": ["Distensión abdominal leve", "Ruidos intestinales aumentados", "Dolor desproporcionado respecto a la exploración física", "Náusea sin vómito"], "ans": 2, "exp": "En la isquemia mesentérica el dolor es intenso y no corresponde a lo poco que se encuentra al explorar el abdomen, un dato de alarma que obliga a actuar rápido."},
    {"id": "DR-R2-19", "grade": "R2", "tag": "Patología anorrectal benigna", "q": "¿Dónde se localiza con más frecuencia la fisura anal crónica?", "opts": ["En la línea media anterior", "En el cuadrante lateral izquierdo", "En el cuadrante lateral derecho", "En la línea media posterior"], "ans": 3, "exp": "La fisura anal suele estar en la línea media posterior, donde la irrigación es más pobre; una fisura lateral debe hacer sospechar otra enfermedad."},
    {"id": "DR-R2-20", "grade": "R2", "tag": "Sepsis quirúrgica", "q": "En una infección intraabdominal, ¿cuál es el principio terapéutico más importante junto con los antibióticos?", "opts": ["Control del foco (drenaje o resección de la fuente)", "Ayuno prolongado de 7 días", "Corticoides a dosis altas", "Nutrición parenteral inmediata"], "ans": 0, "exp": "Sin control del foco (drenar el absceso o resecar el órgano perforado) los antibióticos no resuelven la infección intraabdominal."},
    {"id": "DR-R3-01", "grade": "R3", "tag": "Cirugía oncológica", "q": "En la estadificación TNM, ¿qué significa la letra N?", "opts": ["Tamaño del tumor primario", "Presencia de metástasis a distancia", "Afectación de ganglios linfáticos regionales", "Grado de diferenciación del tumor"], "ans": 2, "exp": "T es el tumor primario, N los ganglios regionales y M las metástasis a distancia; juntos definen el estadio y el pronóstico."},
    {"id": "DR-R3-02", "grade": "R3", "tag": "Cáncer de mama", "q": "¿Qué define al cáncer de mama triple negativo?", "opts": ["HER2 positivo con receptores hormonales positivos", "Receptores de estrógeno y progesterona positivos", "Solo HER2 positivo", "Sin receptores de estrógeno, progesterona ni HER2"], "ans": 3, "exp": "El triple negativo no expresa ER, PR ni HER2, por eso no responde a hormonoterapia ni a anti-HER2 y su tratamiento es quimioterapia."},
    {"id": "DR-R3-03", "grade": "R3", "tag": "Cáncer colorrectal", "q": "En el cáncer colorrectal metastásico, ¿qué implica una mutación de KRAS?", "opts": ["No hay respuesta a los anticuerpos anti-EGFR (cetuximab, panitumumab)", "Respuesta garantizada a la inmunoterapia", "El tumor es siempre resecable", "No se necesita quimioterapia"], "ans": 0, "exp": "KRAS mutado mantiene activada la vía EGFR río abajo, por lo que los anti-EGFR no funcionan; solo los tumores KRAS nativo (wild-type) se benefician."},
    {"id": "DR-R3-04", "grade": "R3", "tag": "Cáncer gástrico y de esófago", "q": "Según la clasificación de Lauren, ¿qué forma de cáncer gástrico produce linitis plástica?", "opts": ["Tipo intestinal", "Tipo difuso", "Tipo mixto", "Tipo papilar"], "ans": 1, "exp": "El tipo difuso de Lauren infiltra la pared gástrica sin formar masa, la vuelve rígida y engrosada (linitis plástica o estómago en bota de cuero)."},
    {"id": "DR-R3-05", "grade": "R3", "tag": "Hígado, vía biliar y páncreas (HPB)", "q": "¿Qué es el tumor de Klatskin?", "opts": ["Tumor del cuerpo del páncreas", "Tumor de la vesícula biliar", "Colangiocarcinoma hiliar (de la confluencia biliar)", "Tumor del lóbulo hepático izquierdo"], "ans": 2, "exp": "El tumor de Klatskin es el colangiocarcinoma de la confluencia de los conductos hepáticos derecho e izquierdo, de resección compleja y mal pronóstico."},
    {"id": "DR-R3-06", "grade": "R3", "tag": "Cirugía endocrina", "q": "Antes de operar un feocromocitoma, ¿qué bloqueo debe iniciarse primero?", "opts": ["Betabloqueo solo", "Calcioantagonistas solos", "Anestesia general sin preparación", "Alfabloqueo, y solo después betabloqueo si hace falta"], "ans": 3, "exp": "El betabloqueo sin alfabloqueo previo deja sin oposición la vasoconstricción alfa y puede precipitar una crisis hipertensiva durante la cirugía."},
    {"id": "DR-R3-07", "grade": "R3", "tag": "Cirugía de tórax", "q": "En un neumotórax a tensión, ¿cuál es la maniobra inmediata que salva la vida?", "opts": ["Descompresión con aguja en el segundo espacio intercostal, línea medioclavicular", "Toracotomía de urgencia en la cama", "Intubación sin descompresión previa", "Radiografía de tórax para confirmar"], "ans": 0, "exp": "El neumotórax a tensión es diagnóstico clínico y no espera imagen; la descompresión con aguja convierte la tensión en neumotórax simple y luego se coloca sonda."},
    {"id": "DR-R3-08", "grade": "R3", "tag": "Cirugía vascular", "q": "En un hombre, ¿a partir de qué diámetro se recomienda habitualmente reparar un aneurisma de aorta abdominal asintomático?", "opts": ["3.0 cm", "5.5 cm", "4.0 cm", "7.0 cm"], "ans": 1, "exp": "El umbral clásico de reparación electiva del aneurisma de aorta abdominal en hombres es 5.5 cm (5.0 cm en mujeres), por el balance entre riesgo de ruptura y riesgo quirúrgico."},
    {"id": "DR-R3-09", "grade": "R3", "tag": "Trauma complejo y control de daños", "q": "¿Qué tres elementos forman la tríada letal del trauma?", "opts": ["Hipotensión, taquicardia y fiebre", "Anemia, leucocitosis y trombocitopenia", "Hipotermia, acidosis y coagulopatía", "Hipoxia, hipercapnia y bradicardia"], "ans": 2, "exp": "Hipotermia, acidosis y coagulopatía se potencian entre sí y matan; la cirugía de control de daños busca interrumpirlas antes de la reparación definitiva."},
    {"id": "DR-R3-10", "grade": "R3", "tag": "Cirugía mínimamente invasiva y pared abdominal compleja", "q": "En una hernia ventral compleja con pérdida de dominio, ¿qué técnica ayuda a cerrar la línea media?", "opts": ["Malla en puente sin cerrar la fascia", "Reparación con sutura simple", "Hernioplastia sin malla", "Separación de componentes"], "ans": 3, "exp": "La separación de componentes libera los músculos oblicuos y permite avanzar la fascia hacia la línea media para lograr un cierre sin tensión."},
    {"id": "DR-R3-11", "grade": "R3", "tag": "Trasplante de órganos sólidos", "q": "¿Cuándo ocurre el rechazo hiperagudo de un injerto?", "opts": ["En minutos a horas tras la reperfusión, por anticuerpos preformados", "A los 6 meses, por falta de inmunosupresión", "A los 5 años, por nefrotoxicidad crónica", "Solo en trasplante de córnea"], "ans": 0, "exp": "El rechazo hiperagudo es mediado por anticuerpos preformados contra el donador, trombosa el injerto en minutos a horas y por eso se previene con la prueba cruzada."},
    {"id": "DR-R3-12", "grade": "R3", "tag": "Sepsis abdominal y abdomen abierto", "q": "En el abdomen abierto, ¿qué sistema se usa con más frecuencia para el manejo temporal de la herida?", "opts": ["Cierre primario con grapas", "Terapia de presión negativa (sistema de vacío)", "Bolsa de Bogotá definitiva", "Dejar la herida al aire sin cobertura"], "ans": 1, "exp": "La presión negativa protege las vísceras, controla el líquido peritoneal y facilita cierres fasciales progresivos hasta el cierre definitivo."},
    {"id": "DR-R3-13", "grade": "R3", "tag": "Bazo", "q": "Después de una esplenectomía, ¿contra qué microorganismos debe vacunarse al paciente?", "opts": ["Solo contra influenza", "Solo contra tétanos", "Neumococo, Haemophilus influenzae tipo B y meningococo", "Solo contra hepatitis B"], "ans": 2, "exp": "Sin bazo se pierde la defensa contra bacterias encapsuladas, por eso la vacunación contra neumococo, Hib y meningococo es obligatoria, idealmente antes de la cirugía electiva."},
    {"id": "DR-R3-14", "grade": "R3", "tag": "Glándulas salivales", "q": "¿Cuál es el tumor benigno más frecuente de la glándula parótida?", "opts": ["Carcinoma mucoepidermoide", "Tumor de Warthin", "Carcinoma adenoide quístico", "Adenoma pleomorfo"], "ans": 3, "exp": "El adenoma pleomorfo es el tumor salival más frecuente; crece lento, puede malignizarse con el tiempo y se trata con parotidectomía conservando el nervio facial."},
    {"id": "DR-R3-15", "grade": "R3", "tag": "Cirugía reconstructiva", "q": "¿Qué distingue a un colgajo libre de un colgajo pediculado?", "opts": ["El colgajo libre requiere anastomosis microvascular de sus vasos", "El colgajo libre no tiene vasos propios", "El colgajo libre solo sirve para piel", "El colgajo libre nunca se necrosa"], "ans": 0, "exp": "El colgajo libre se secciona con su pedículo vascular y se reconecta con microcirugía en el sitio receptor; el pediculado mantiene su aporte original."},
    {"id": "DR-R3-16", "grade": "R3", "tag": "Cáncer de mama", "q": "En la cirugía conservadora de mama, ¿cómo se identifica el ganglio centinela?", "opts": ["Por palpación durante la cirugía", "Con colorante azul patente y/o radiocoloide (tecnecio-99m)", "Por tomografía preoperatoria", "Por biopsia de todos los ganglios axilares"], "ans": 1, "exp": "El ganglio centinela es el primero que drena el tumor y se localiza con colorante azul, radiocoloide o ambos; si es negativo se evita la disección axilar completa."},
    {"id": "DR-R3-17", "grade": "R3", "tag": "Cirugía vascular", "q": "¿En qué caso está indicada la endarterectomía carotídea?", "opts": ["Estenosis asintomática menor del 50 %", "Oclusión carotídea completa crónica", "Estenosis carotídea sintomática mayor del 70 %", "Estenosis carotídea sin síntomas ni placa ulcerada"], "ans": 2, "exp": "La endarterectomía tiene el mayor beneficio en estenosis sintomática grave (>70 %), donde reduce claramente el riesgo de infarto cerebral."},
    {"id": "DR-R3-18", "grade": "R3", "tag": "Cirugía oncológica", "q": "¿Qué significa una resección R0?", "opts": ["Tumor residual macroscópico", "Tumor residual microscópico", "Resección paliativa sin intención curativa", "Resección completa sin tumor residual macro ni microscópico"], "ans": 3, "exp": "R0 es resección con márgenes libres en el estudio histopatológico; R1 deja tumor microscópico y R2, tumor visible."},
    {"id": "DR-R3-19", "grade": "R3", "tag": "Cirugía de tórax", "q": "En un empiema pleural organizado (fase III), ¿cuál es el tratamiento definitivo?", "opts": ["Decorticación quirúrgica", "Antibiótico oral prolongado sin drenaje", "Toracocentesis única", "Observación"], "ans": 0, "exp": "En la fase organizada el pulmón está atrapado por una corteza fibrótica; solo la decorticación libera el pulmón y permite su reexpansión."},
    {"id": "DR-R3-20", "grade": "R3", "tag": "Paciente quirúrgico crítico", "q": "En el abdomen abierto, ¿cuál es la meta del manejo de la pared abdominal?", "opts": ["Dejar siempre una hernia ventral planeada", "Lograr el cierre fascial primario lo antes posible", "Cerrar la piel y dejar la fascia abierta", "Retirar la malla en la primera semana"], "ans": 1, "exp": "El cierre fascial temprano reduce fístulas, infecciones y hernias; cada día con el abdomen abierto disminuye la probabilidad de cerrarlo."},
    {"id": "DR-R4-01", "grade": "R4", "tag": "Cirugía hepatobiliar avanzada", "q": "En la pancreaticoduodenectomía (Whipple), ¿cuál es la complicación más temida de la anastomosis pancreática?", "opts": ["Hemorragia de la anastomosis biliar", "Estenosis de la anastomosis gástrica", "Dehiscencia de la herida", "Fístula pancreática postoperatoria"], "ans": 3, "exp": "La fuga de la anastomosis pancreatoyeyunal es la complicación más temida del Whipple porque puede provocar abscesos, hemorragia y sepsis."},
    {"id": "DR-R4-02", "grade": "R4", "tag": "Cirugía pancreática avanzada", "q": "¿Qué tríada caracteriza al insulinoma?", "opts": ["Tríada de Whipple: síntomas de hipoglucemia en ayuno, glucosa baja documentada y alivio con glucosa", "Dolor, ictericia y pérdida de peso", "Diarrea, rubor y broncoespasmo", "Hiperglucemia, poliuria y polidipsia"], "ans": 0, "exp": "El insulinoma produce insulina en exceso; la tríada de Whipple (síntomas en ayuno, glucosa baja y alivio con glucosa) es su sello diagnóstico."},
    {"id": "DR-R4-03", "grade": "R4", "tag": "Cirugía oncológica avanzada y carcinomatosis peritoneal", "q": "¿Qué es el HIPEC?", "opts": ["Quimioterapia intravenosa convencional", "Quimioterapia intraperitoneal hipertérmica tras citorreducción", "Radioterapia externa pélvica", "Inmunoterapia oral"], "ans": 1, "exp": "El HIPEC baña la cavidad peritoneal con quimioterapia caliente tras resecar todo el tumor visible, para eliminar enfermedad microscópica residual."},
    {"id": "DR-R4-04", "grade": "R4", "tag": "Cirugía colorrectal avanzada", "q": "¿Qué procedimiento implica resecar en bloque recto, vejiga y órganos genitales por cáncer pélvico localmente avanzado?", "opts": ["Resección anterior baja", "Amputación abdominoperineal", "Exenteración pélvica", "Colectomía subtotal"], "ans": 2, "exp": "La exenteración pélvica reseca en bloque los órganos pélvicos comprometidos y requiere derivaciones urinaria y fecal definitivas."},
    {"id": "DR-R4-05", "grade": "R4", "tag": "Cirugía esofagogástrica avanzada", "q": "¿Qué técnica de esofagectomía combina abordaje abdominal y torácico derecho?", "opts": ["Esofagectomía transhiatal", "Esofagectomía por toracoscopia sola", "Esofagectomía cervical", "Esofagectomía de Ivor Lewis"], "ans": 3, "exp": "La técnica de Ivor Lewis combina laparotomía y toracotomía derecha, con anastomosis esofagogástrica en el tórax."},
    {"id": "DR-R4-06", "grade": "R4", "tag": "Trauma complejo y cuidados críticos", "q": "En un paciente con hemorragia exsanguinante y tríada letal, ¿qué estrategia quirúrgica se aplica?", "opts": ["Laparotomía abreviada con empaquetamiento (control de daños)", "Reparación definitiva de todas las lesiones en un solo tiempo", "Cierre abdominal inmediato sin revisar", "Observación en terapia intensiva sin cirugía"], "ans": 0, "exp": "En el paciente exsanguinado se controla el sangrado y la contaminación, se empaqueta y se cierra temporalmente; la reparación definitiva espera a corregir la fisiología en terapia intensiva."},
    {"id": "DR-R4-07", "grade": "R4", "tag": "Cirugía endocrina, de cabeza y cuello y de mama", "q": "¿Cuál es el tipo histológico más frecuente de cáncer de tiroides?", "opts": ["Carcinoma anaplásico", "Carcinoma papilar", "Carcinoma medular", "Carcinoma folicular"], "ans": 1, "exp": "El carcinoma papilar representa la gran mayoría de los cánceres de tiroides, tiene buen pronóstico y suele tratarse con tiroidectomía total."},
    {"id": "DR-R4-08", "grade": "R4", "tag": "Cirugía bariátrica y pared abdominal compleja", "q": "¿Qué procedimiento bariátrico se considera el estándar de referencia por su balance entre pérdida de peso y control metabólico?", "opts": ["Banda gástrica ajustable", "Balón intragástrico", "Bypass gástrico en Y de Roux", "Gastroplastia vertical"], "ans": 2, "exp": "El bypass en Y de Roux combina restricción y malabsorción, con la mayor evidencia de pérdida de peso sostenida y remisión de diabetes tipo 2."},
    {"id": "DR-R4-09", "grade": "R4", "tag": "Cirugía vascular y emergencias toracoabdominales", "q": "En la disección aórtica, ¿qué tipo exige cirugía de urgencia?", "opts": ["Stanford B sin complicaciones", "Disección crónica estable", "Disección limitada a la aorta descendente", "Stanford A (afecta la aorta ascendente)"], "ans": 3, "exp": "La disección Stanford A compromete la aorta ascendente y puede romperse o taponar el corazón, por eso es una emergencia quirúrgica inmediata."},
    {"id": "DR-R4-10", "grade": "R4", "tag": "Cirugía de trasplantes", "q": "¿Cuál es el inmunosupresor inhibidor de la calcineurina más usado en el trasplante de órganos sólidos?", "opts": ["Tacrolimus", "Azatioprina", "Micofenolato sin inhibidor de calcineurina", "Prednisona sola"], "ans": 0, "exp": "El tacrolimus es el inhibidor de la calcineurina de referencia en trasplante, base de la inmunosupresión de mantenimiento junto con micofenolato y esteroide."},
    {"id": "DR-R4-11", "grade": "R4", "tag": "Complicaciones quirúrgicas, fístulas y nutrición", "q": "¿Cómo se clasifica una fístula enterocutánea con gasto mayor de 500 mL al día?", "opts": ["De bajo gasto", "De alto gasto", "De gasto moderado", "Fístula cerrada"], "ans": 1, "exp": "Más de 500 mL al día es fístula de alto gasto, con mayor riesgo de deshidratación, desequilibrio electrolítico y desnutrición, y menor probabilidad de cierre espontáneo."},
    {"id": "DR-R4-12", "grade": "R4", "tag": "Liderazgo quirúrgico y seguridad del paciente", "q": "¿Qué herramienta de la OMS, aplicada antes de la incisión, reduce las complicaciones quirúrgicas?", "opts": ["La escala de Apgar", "El parte de quirófano", "La lista de verificación de seguridad quirúrgica (checklist)", "La hoja de enfermería"], "ans": 2, "exp": "La lista de verificación de la OMS (identidad del paciente, sitio, antibiótico, equipo) reduce mortalidad y complicaciones cuando se aplica en equipo y en voz alta."},
    {"id": "DR-R4-13", "grade": "R4", "tag": "Endoscopia", "q": "¿Cuál es la complicación más frecuente de la CPRE?", "opts": ["Perforación duodenal", "Hemorragia grave", "Colangitis", "Pancreatitis post-CPRE"], "ans": 3, "exp": "La pancreatitis es la complicación más frecuente de la CPRE; la perforación y la hemorragia son menos frecuentes pero más graves."},
    {"id": "DR-R4-14", "grade": "R4", "tag": "Nefrourología", "q": "En un tumor renal localizado menor de 4 cm (T1a), ¿cuál es la cirugía de elección cuando es técnicamente factible?", "opts": ["Nefrectomía parcial", "Nefrectomía radical en todos los casos", "Vigilancia sin tratamiento", "Embolización como único tratamiento"], "ans": 0, "exp": "En tumores renales pequeños la nefrectomía parcial preserva función renal con el mismo control oncológico que la radical, por eso es la preferida."},
    {"id": "DR-R4-15", "grade": "R4", "tag": "Aparato genital femenino", "q": "Una paciente con embarazo ectópico roto, hipotensa y con hemoperitoneo requiere:", "opts": ["Metotrexato y observación", "Cirugía de urgencia", "Espera a que se resuelva solo", "Antibioticoterapia"], "ans": 1, "exp": "El ectópico roto con inestabilidad hemodinámica es una emergencia quirúrgica; el metotrexato solo es opción en ectópicos no rotos, estables y seleccionados."},
    {"id": "DR-R4-16", "grade": "R4", "tag": "Aparato genital masculino", "q": "¿Dentro de cuántas horas debe resolverse una torsión testicular para salvar el testículo?", "opts": ["Dentro de las primeras 24 horas", "Dentro de las primeras 12 horas", "Dentro de las primeras 6 horas", "Dentro de la primera semana"], "ans": 2, "exp": "La torsión testicular es una urgencia: después de 6 horas de isquemia la probabilidad de salvar el testículo cae drásticamente."},
    {"id": "DR-R4-17", "grade": "R4", "tag": "Musculoesquelético y pie diabético", "q": "En el pie diabético, ¿qué factor es el principal determinante de la falta de cicatrización de una úlcera?", "opts": ["La edad del paciente", "El color de la piel", "La duración de la diabetes", "La isquemia (mala perfusión arterial)"], "ans": 3, "exp": "Sin perfusión no hay cicatrización: la úlcera isquémica no cierra aunque se cure y se descargue, por eso la evaluación vascular es obligatoria."},
    {"id": "DR-R4-18", "grade": "R4", "tag": "Cirugía hepatobiliar avanzada", "q": "¿Qué clasificación indica que una resección hepática mayor está contraindicada por mala función hepática?", "opts": ["Child-Pugh C", "Child-Pugh A", "ASA I", "MELD menor de 10"], "ans": 0, "exp": "Child-Pugh C es cirrosis descompensada con mala reserva hepática; una resección mayor precipitaría falla hepática, por eso está contraindicada."},
    {"id": "DR-R4-19", "grade": "R4", "tag": "Complicaciones quirúrgicas y nutrición", "q": "¿Cuándo está indicada la nutrición parenteral en el paciente quirúrgico?", "opts": ["En todo paciente en ayuno de 24 horas", "Cuando la vía enteral es imposible o insuficiente por más de 7 días", "Como primera opción en el paciente crítico", "Solo en pacientes ambulatorios"], "ans": 1, "exp": "La nutrición parenteral es el plan B: se usa cuando el intestino no puede usarse por más de 7 días, porque la enteral siempre es preferible cuando es posible."},
    {"id": "DR-R4-20", "grade": "R4", "tag": "Liderazgo, ética e investigación", "q": "Antes de iniciar un estudio con pacientes, ¿qué aprobación es indispensable?", "opts": ["La del jefe de servicio solamente", "La del laboratorio", "La del comité de ética en investigación", "La del paciente más grave del estudio"], "ans": 2, "exp": "Ningún estudio con pacientes puede iniciar sin la aprobación del comité de ética, que protege los derechos, la seguridad y el consentimiento de los participantes."},
  ],
  imagen: [
    {"id": "IM-R1-01", "grade": "R1", "tema": "Trauma: evaluación inicial ATLS", "imagen": "Radiografía de tórax posteroanterior, en inspiración, de un hemitórax derecho con ausencia completa de trama vascular desde el vértice hasta la base. Se observa una línea fina, nítida, de pleura visceral desplazada hacia el centro, que delimita un espacio negro, sin marcas pulmonares, entre la pared torácica y el pulmón colapsado. El pulmón derecho está retraído hacia el hilio, con densidad homogénea y volumen claramente disminuido. La tráquea y el mediastino están desplazados hacia el lado izquierdo, contralateral a la lesión. No se ven fracturas costales evidentes en esta proyección ni nivel hidroaéreo. El hemitórax izquierdo conserva trama vascular normal hasta la periferia y el diafragma izquierdo está en posición habitual.", "pistas": ["El paciente respira con dificultad, está hipotenso y taquicárdico, con ingurgitación yugular y ausencia de murmullo vesicular en un hemitórax.", "La desviación traqueal es contralateral y el cuadro empeoró rápidamente tras iniciar ventilación con presión positiva.", "Es un diagnóstico clínico: no se espera la radiografía para actuar (ATLS, 10.ª edición)."], "dx": "Neumotórax a tensión derecho.", "hallazgo": "Ausencia de trama vascular periférica con pulmón colapsado hacia el hilio y desplazamiento mediastínico contralateral.", "exp": "El aire a presión en el espacio pleural colapsa el pulmón y desplaza el mediastino, comprometiendo el retorno venoso y el gasto cardiaco. Por eso es una emergencia clínica: descompresión inmediata con aguja o toracostomía con dedo y luego tubo pleural, sin esperar la imagen. La radiografía solo confirma lo que la exploración ya gritaba."},
    {"id": "IM-R1-02", "grade": "R1", "tema": "Abdomen agudo y apendicitis aguda", "imagen": "Tomografía computarizada de abdomen y pelvis con contraste intravenoso, corte axial a la altura de la fosa iliaca derecha. Se identifica una estructura tubular, ciega en su extremo, de 11 mm de diámetro máximo, con pared engrosada de 4 mm que refuerza de forma circunferencial tras el contraste. Su luz está ocupada por un apendicolito hiperdenso, redondeado, de 6 mm. Alrededor hay estriación de la grasa mesentérica, con aumento de la densidad y aspecto sucio, y una pequeña colección líquida de 12 mm adyacente a la punta. No se observa gas extraluminal libre ni absceso organizado de mayor tamaño. El ciego conserva su pared y el íleon terminal no muestra engrosamiento. El resto del abdomen no tiene líquido libre significativo.", "pistas": ["Dolor que empezó alrededor del ombligo y migró a la fosa iliaca derecha, con anorexia y fiebre baja.", "Dolor a la descompresión en el punto de McBurney y leucocitosis con neutrofilia.", "El diámetro mayor de 6 mm y el apendicolito aumentan el riesgo de perforación y de fracaso del manejo conservador."], "dx": "Apendicitis aguda no complicada, con apendicolito.", "hallazgo": "Apéndice de 11 mm, pared engrosada con refuerzo, apendicolito intraluminal y estriación de la grasa periapendicular.", "exp": "El diámetro mayor de 6 mm, el engrosamiento mural y la grasa sucia son los signos tomográficos clásicos de apendicitis. El apendicolito es un factor de riesgo de perforación, por lo que el manejo habitual es la apendicectomía, laparoscópica de preferencia, y no el alta con antibiótico sin plan quirúrgico."},
    {"id": "IM-R1-03", "grade": "R1", "tema": "Patología biliar: colelitiasis, colecistitis aguda y colangitis", "imagen": "Ecografía de hipocondrio derecho, en decúbito supino, con transductor convexo. La vesícula biliar está distendida, de 10 cm de longitud, con pared engrosada de 5 mm, en dos capas, con refuerzo posterior discreto. En su interior hay un cálculo ecogénico, redondeado, de 18 mm, impactado en el cuello vesicular, con sombra acústica posterior nítida. Hay lodo biliar en el fondo y una pequeña cantidad de líquido perivesicular anecoico en el lecho hepático. El colédoco mide 5 mm y no se ven cálculos en su interior en este estudio. El hígado tiene ecogenicidad homogénea y no hay dilatación de la vía biliar intrahepática.", "pistas": ["Dolor en hipocondrio derecho de más de 6 horas, con náusea, vómito y fiebre de 38,5 °C.", "Signo de Murphy positivo y leucocitosis; el dolor no cede con analgésicos habituales.", "La ecografía es el estudio de primera línea y el cálculo impactado en el cuello explica que el cuadro no sea un simple cólico biliar."], "dx": "Colecistitis aguda litiásica.", "hallazgo": "Pared vesicular de 5 mm, cálculo de 18 mm impactado en el cuello con sombra acústica y líquido perivesicular.", "exp": "La impactación del cálculo obstruye el cístico, la vesícula se distiende y su pared se inflama y se engrosa. Con fiebre, leucocitosis y Murphy positivo se trata de colecistitis aguda, no de cólico: el manejo es ayuno, antibiótico, analgesia y colecistectomía laparoscópica temprana dentro de las primeras 72 horas cuando no hay contraindicación."},
    {"id": "IM-R1-04", "grade": "R1", "tema": "Hernias de pared abdominal y obstrucción intestinal", "imagen": "Radiografía simple de abdomen de pie, en proyección anteroposterior. Se observan múltiples asas de intestino delgado marcadamente dilatadas, de más de 3,5 cm de diámetro, distribuidas en el centro del abdomen, con niveles hidroaéreos escalonados, en forma de escalera, en al menos cuatro niveles distintos. Las asas muestran pliegues circulares completos que cruzan toda la luz (válvulas conniventes). Hay escaso gas en el colon y en el recto, con el marco cólico apenas visible y sin dilatación colónica. No se ve gas libre bajo el diafragma ni neumatosis intestinal. La silueta del psoas está borrada del lado derecho.", "pistas": ["Distensión abdominal progresiva, vómito bilioso, ausencia de evacuaciones y de flatos desde hace dos días.", "Antecedente de cirugía abdominal previa y dolor de tipo cólico que va y viene.", "El patrón de niveles escalonados con válvulas conniventes y colon vacío orienta al nivel de la obstrucción."], "dx": "Obstrucción de intestino delgado, probablemente por adherencias.", "hallazgo": "Asas de delgado dilatadas con niveles hidroaéreos escalonados, válvulas conniventes y colon sin gas.", "exp": "La dilatación del delgado con niveles en escalera y colon colapsado es el patrón radiográfico clásico de obstrucción mecánica de intestino delgado. Las adherencias postquirúrgicas son la causa más frecuente en el adulto operado. El manejo inicial es ayuno, sonda nasogástrica, reposición de líquidos y electrolitos y TC con contraste para buscar isquemia, estrangulación o causa distinta; la cirugía es urgente si hay peritonitis, isquemia o no resuelve."},
    {"id": "IM-R1-05", "grade": "R1", "tema": "Infección en cirugía", "imagen": "Tomografía computarizada de muslo, corte axial con contraste intravenoso. En el compartimento anterior del muslo se observa un marcado engrosamiento de la fascia profunda, con realce y líquido en los planos fasciales. Hay múltiples burbujas de gas disecando los planos musculares y subcutáneos, visibles como imágenes redondeadas hipodensas, negras, alineadas a lo largo de la fascia lata. El músculo adyacente tiene densidad heterogénea, con áreas de baja atenuación que sugieren necrosis, y el tejido celular subcutáneo está engrosado, con estriación y edema extenso. No hay absceso único bien delimitado ni colección drenable por vía percutánea. Los vasos femorales conservan su luz, sin trombosis visible.", "pistas": ["Dolor en el muslo desproporcionado a lo que se ve en la piel, que empeora en horas, con fiebre alta, taquicardia y mal estado general.", "La piel tiene una zona de eritema violáceo con una ampolla hemorrágica y crepitación a la palpación.", "El gas en los planos fasciales es un signo de alarma, pero su ausencia no descarta el diagnóstico y la imagen nunca debe retrasar el quirófano."], "dx": "Fascitis necrosante de muslo.", "hallazgo": "Gas disecando los planos fasciales, engrosamiento y realce fascial con necrosis muscular, sin absceso único drenable.", "exp": "La fascitis necrosante es una infección de tejidos blandos que avanza por la fascia y mata por sepsis y necrosis. El dolor desproporcionado, la crepitación y el gas en la TC son claves, pero el diagnóstico es clínico-quirúrgico: desbridamiento amplio urgente, antibiótico de amplio espectro (con clindamicina por su efecto antitoxina en estreptococo), reexploración en 24 horas y terapia intensiva. Esperar la imagen para operar es el error clásico."},
    {"id": "IM-R1-06", "grade": "R1", "tema": "Cicatrización y cuidado de las heridas quirúrgicas", "imagen": "Fotografía clínica de la pared abdominal anterior, centrada en una herida quirúrgica de línea media, a la altura del ombligo. La herida, de unos 12 cm, está abierta en su tercio medio: los bordes cutáneos están separados unos 3 cm y entre ellos asoma una masa rosada, brillante y húmeda, con pliegues intestinales visibles y peristaltismo aparente. No hay exudado purulento franco, pero los bordes están eritematosos y edematosos, con puntos de sutura rotos y restos de material de sutura colgando. La piel circundante está tensa y brillante. No se ven signos de sangrado activo en la foto.", "pistas": ["Paciente en el séptimo día postoperatorio de una laparotomía, que refiere haber sentido un \"jalón\" y salida de líquido rosado por la herida tras toser.", "El drenaje era líquido seroso, en cantidad mayor de lo habitual, y la herida se veía \"abierta\" al retirarle el apósito.", "La salida de contenido abdominal por la herida es la forma mayor de este problema y exige protección inmediata del contenido expuesto."], "dx": "Evisceración (dehiscencia de herida quirúrgica con exposición de vísceras).", "hallazgo": "Separación de los bordes de la herida con protrusión de asas intestinales visibles.", "exp": "La evisceración es la dehiscencia completa de la pared con salida de vísceras. El líquido seroso rosado (\"salmon pink\") tras la tos es el aviso clásico de dehiscencia fascial. La conducta es cubrir el contenido con compresas estériles húmedas, ayuno, antibiótico, no intentar reintroducir las asas en la cama y llevar a quirófano para cierre, con atención a factores como infección, desnutrición y aumento de presión intraabdominal."},
    {"id": "IM-R1-07", "grade": "R1", "tema": "Piel y tejido adiposo subcutáneo", "imagen": "Fotografía clínica de primer plano de una lesión pigmentada en la espalda. Es una mancha de 14 mm de diámetro, de bordes irregulares, con muescas y zonas en las que el borde se pierde en la piel sana. Su color es heterogéneo: predominan el marrón oscuro y el negro, con áreas de marrón claro y un sector gris azulado. La superficie es ligeramente elevada en el centro, con una zona ulcerada pequeña y costra hemática. Alrededor no hay eritema extenso ni satélites visibles, pero la lesión destaca claramente frente a los lunares vecinos, pequeños, redondos y de color uniforme.", "pistas": ["La lesión creció en los últimos meses y cambió de color; el paciente refiere que a veces pica y sangró una vez al rascarse.", "Cumple varias letras de la regla ABCDE: asimetría, bordes irregulares, color variado, diámetro mayor de 6 mm y evolución.", "No se toma biopsia incisional de este tipo de lesión: la conducta es la escisión completa con margen para estudio histopatológico."], "dx": "Lesión pigmentada sospechosa de melanoma.", "hallazgo": "Lesión de 14 mm, asimétrica, de bordes irregulares, color heterogéneo con sector gris azulado y ulceración central.", "exp": "El melanoma se sospecha por el ABCDE: asimetría, borde irregular, color heterogéneo, diámetro mayor de 6 mm y evolución (cambio). Una lesión que crece, cambia de color, pica y sangra debe escindirse completa con margen estrecho para diagnóstico histopatológico, sin biopsia incisional parcial que pueda comprometer la estadificación; después se define el manejo oncológico según el Breslow y la estadificación."},
    {"id": "IM-R1-08", "grade": "R1", "tema": "Sangre, hemostasia y transfusión / Cuidados perioperatorios", "imagen": "Ecografía Doppler venosa de la pierna, en modo B y Doppler color, a la altura de la vena femoral común y la vena poplítea. En modo B, la vena femoral común se ve dilatada, con contenido ecogénico intraluminal que ocupa toda la luz y que no se desplaza con la respiración. Al comprimir con el transductor, la vena no colapsa: sus paredes no se juntan, a diferencia de la arteria vecina, que colapsa y se reexpande con el pulso. En Doppler color no hay flujo dentro de la vena afectada, mientras que la arteria femoral muestra flujo pulsátil normal. La vena poplítea presenta el mismo patrón: material ecogénico y ausencia de compresibilidad.", "pistas": ["Paciente postoperado, encamado, con dolor y edema unilateral de la pierna, que aumentó en dos días.", "La diferencia de perímetro entre ambas piernas es de 3 cm y hay dolor a la palpación de la pantorrilla.", "El signo ecográfico decisivo no es el flujo, sino la compresibilidad: una vena sana colapsa, una trombosada no."], "dx": "Trombosis venosa profunda proximal (femoral y poplítea).", "hallazgo": "Vena no compresible con material ecogénico intraluminal y ausencia de flujo Doppler.", "exp": "La ecografía de compresión es el estudio de primera línea para la trombosis venosa profunda: la falta de compresibilidad es el signo más fiable. El contexto postoperatorio con inmovilización reúne los elementos de la tríada de Virchow. El manejo es anticoagulación terapéutica (salvo contraindicación hemorrágica), movilización, medias de compresión y búsqueda de embolia pulmonar si hay disnea, dolor torácico o hipoxemia."},
    {"id": "IM-R1-09", "grade": "R1", "tema": "Estado de choque", "imagen": "Radiografía de tórax posteroanterior en decúbito supino. La silueta cardiaca está agrandada, con índice cardiotorácico mayor de 0,5. Ambos campos pulmonares muestran un patrón intersticial difuso, con líneas B de Kerley en las bases y engrosamiento de las cisuras. Hay borramiento de los ángulos costofrénicos por derrame pleural bilateral, mayor del lado derecho, y redistribución vascular hacia los vértices, con vasos hiliares prominentes. No hay consolidación lobar ni neumotórax. El mediastino no está ensanchado y no hay fracturas visibles.", "pistas": ["Paciente con disnea progresiva, ortopnea y crepitantes bibasales, tras haber recibido varios litros de líquidos en pocas horas.", "La presión arterial es alta, hay ingurgitación yugular y la saturación cayó sin fiebre ni expectoración purulenta.", "El patrón es de congestión, no de infección: el problema es el volumen, no el antibiótico."], "dx": "Edema pulmonar cardiogénico por sobrecarga de volumen.", "hallazgo": "Cardiomegalia, redistribución vascular, líneas de Kerley y derrame pleural bilateral.", "exp": "La sobrecarga de líquidos en un corazón que no la tolera produce congestión pulmonar: disnea, ortopnea, crepitantes, cardiomegalia e infiltrado intersticial con derrame. Es un recordatorio de que la reanimación con líquidos en el choque debe guiarse por la respuesta y no por el volumen total: ante estos signos se frena la infusión, se optimiza la precarga con diurético y se reevalúa la función cardiaca."},
    {"id": "IM-R1-10", "grade": "R1", "tema": "Técnica quirúrgica y cirugía de mínima invasión", "imagen": "Fotografía de laparoscopia, vista desde la óptica umbilical, del cuadrante superior derecho del abdomen. En el centro se observa la vesícula biliar distendida, de pared engrosada y color violáceo oscuro, con el fondo adherido al lecho hepático. El triángulo hepatocístico está cubierto por grasa inflamada y adherencias densas que impiden distinguir con claridad el conducto cístico y la arteria cística. A la izquierda de la imagen se ve el borde hepático, con superficie irregular, y a la derecha el colon transverso desplazado hacia abajo por el retractor. No se identifica la visión crítica de seguridad: no se ven dos estructuras entrando a la vesícula ni el lecho hepático despejado.", "pistas": ["Es una colecistectomía laparoscópica en un paciente con varios días de dolor y fiebre; la disección no avanza.", "El cirujano no logra la visión crítica de seguridad y la anatomía está distorsionada por la inflamación.", "La decisión correcta no es seguir disecando a ciegas ni cortar lo que no se identifica: hay una maniobra de seguridad clásica antes de lesionar la vía biliar."], "dx": "Colecistitis aguda grave con triángulo hepatocístico no disecable — situación de riesgo de lesión de vía biliar (visión crítica de seguridad no alcanzada).", "hallazgo": "Vesícula violácea y distendida con triángulo hepatocístico cubierto de adherencias, sin visión crítica de seguridad.", "exp": "La visión crítica de seguridad exige identificar claramente el conducto cístico y la arteria cística entrando a la vesícula, con el lecho hepático despejado. Cuando la inflamación lo impide, la conducta segura es detenerse, hacer una pausa, pedir ayuda, considerar colangiografía intraoperatoria o convertir a cirugía abierta, o realizar una colecistectomía subtotal, antes que lesionar la vía biliar. La lesión de vía biliar es la complicación más temida de la colecistectomía laparoscópica."},
    {"id": "IM-R2-01", "grade": "R2", "tema": "Patología esofágica y ERGE", "imagen": "Endoscopia digestiva alta, vista del esófago distal, a unos 35 cm de la arcada dentaria. Por encima de la unión gastroesofágica se observa un segmento de mucosa de color salmón, aterciopelada, que asciende 4 cm en forma de lengüetas, en contraste nítido con la mucosa escamosa normal, pálida y brillante, del esófago proximal. La mucosa salmón tiene superficie lisa, sin ulceraciones ni nódulos visibles, y sus bordes forman un patrón en \"lenguas de fuego\". La unión gastroesofágica está desplazada hacia arriba y hay una hernia hiatal pequeña. No se ven várices ni estenosis en este segmento.", "pistas": ["Reflujo y pirosis de años de evolución, que no responde bien a los inhibidores de bomba de protones.", "El cambio de color corresponde a un cambio de epitelio: el escamoso es reemplazado por epitelio columnar.", "Es una lesión premaligna que exige biopsias protocolizadas y vigilancia endoscópica, aunque no haya displasia en la primera muestra."], "dx": "Esófago de Barrett, segmento largo (4 cm), sin displasia visible.", "hallazgo": "Mucosa color salmón de 4 cm por encima de la unión gastroesofágica, en lengüetas, con límite nítido con el epitelio escamoso.", "exp": "El reflujo crónico sustituye el epitelio escamoso esofágico por epitelio columnar con metaplasia intestinal: el esófago de Barrett. Es un precursor del adenocarcinoma de esófago, por lo que se confirma con biopsias (protocolo de Seattle) y se vigila periódicamente; el manejo incluye control del reflujo y, si hay displasia, ablación o resección endoscópica según el grado."},
    {"id": "IM-R2-02", "grade": "R2", "tema": "Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica", "imagen": "Endoscopia digestiva alta, vista del bulbo duodenal. En la pared anterior se observa una úlcera redondeada, de 12 mm, con bordes regulares y fondo limpio, blanquecino, sin sangrado activo. En el centro del fondo hay un vaso visible: un punto prominente, de color rojizo oscuro, no sangrante, que sobresale del lecho ulceroso como un pequeño botón. La mucosa circundante está eritematosa y edematosa, con pliegues engrosados. No hay coágulo adherido ni sangre fresca en el lumen. El píloro y el antro gástrico no muestran otras lesiones.", "pistas": ["Melena y hematemesis de 12 horas de evolución, con taquicardia, hipotensión y hemoglobina de 7,8 g/dL.", "El vaso visible sin sangrado activo es una de las lesiones de mayor riesgo de resangrado de la clasificación de Forrest.", "Aunque no sangra en este momento, la conducta endoscópica no es solo observar: requiere terapia hemostática y luego inhibidor de bomba de protones en infusión."], "dx": "Úlcera duodenal sangrante, Forrest IIa (vaso visible no sangrante).", "hallazgo": "Úlcera duodenal de 12 mm con vaso visible prominente en su fondo, sin sangrado activo.", "exp": "La clasificación de Forrest estratifica el riesgo de resangrado: el vaso visible (IIa) tiene riesgo alto y exige hemostasia endoscópica (inyección con adrenalina más clip o terapia térmica) y bomba de protones intravenosa a dosis alta. La cirugía queda para el sangrado que no se controla endoscópicamente, la perforación o la recidiva; la úlcera duodenal sangrante rara vez se opera de primera intención hoy."},
    {"id": "IM-R2-03", "grade": "R2", "tema": "Patología hepática quirúrgica: abscesos, quistes, tumores y trauma hepático", "imagen": "Tomografía computarizada de abdomen con contraste intravenoso en fase portal, corte axial a la altura del hígado. En el lóbulo derecho, segmento VII, se observa una lesión redondeada, hipodensa, de 7 cm de diámetro, con pared gruesa que refuerza de forma periférica tras el contraste, en anillo. Su interior es heterogéneo, con densidad líquida y un nivel interno, sin gas ni calcificaciones. Alrededor hay edema del parénquima hepático adyacente y una pequeña cantidad de líquido perihepático. La vía biliar no está dilatada y no hay otras lesiones focales hepáticas. El resto del abdomen no muestra colecciones.", "pistas": ["Fiebre de una semana, dolor en hipocondrio derecho y leucocitosis, en un paciente con antecedente de diarrea disentérica hace un mes.", "El absceso es único, en el lóbulo derecho, y el antecedente de disentería orienta a la etiología.", "El manejo no es solo antibiótico: el tamaño y la localización obligan a drenaje, y el tipo de drenaje depende de si el contenido es amebiano o piógeno."], "dx": "Absceso hepático amebiano, lóbulo derecho.", "hallazgo": "Lesión hipodensa única de 7 cm en el lóbulo derecho, con refuerzo periférico en anillo y antecedente de disentería.", "exp": "El absceso hepático amebiano, por Entamoeba histolytica, suele ser único, en el lóbulo derecho, tras una colitis amebiana. Se diferencia del piógeno por el antecedente disentérico y porque el aspirado es \"pasta de anchoas\", estéril. El tratamiento es metronidazol más un amebicida luminal, con drenaje percutáneo si es mayor de 5 cm, hay riesgo de rotura, no responde al tratamiento médico o está en el lóbulo izquierdo."},
    {"id": "IM-R2-04", "grade": "R2", "tema": "Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18)", "imagen": "Colangiopancreatografía retrógrada endoscópica (CPRE), imagen fluoroscópica en proyección anteroposterior. Se observa la vía biliar intrahepática dilatada y el colédoco dilatado, de 14 mm de diámetro, con un defecto de llenado redondeado, radiolúcido, de 10 mm, en su tercio distal, rodeado por contraste: un cálculo que ocupa casi toda la luz. Por debajo del cálculo el contraste pasa en forma de un chorro fino hacia el duodeno. No se ve fuga de contraste ni estenosis maligna. La vesícula no se opacifica en esta imagen y el conducto pancreático principal se ve de calibre normal.", "pistas": ["Ictericia, dolor en hipocondrio derecho y fiebre de 39 °C, con la tríada de Charcot completa.", "Bilirrubina y fosfatasa alcalina elevadas, con leucocitosis y colédoco dilatado en la ecografía previa.", "Es una urgencia biliar según los criterios de Tokio (TG18): la descompresión no puede esperar días."], "dx": "Colangitis aguda por coledocolitiasis, con cálculo de 10 mm en colédoco distal.", "hallazgo": "Colédoco de 14 mm con defecto de llenado redondeado de 10 mm en su tercio distal y contraste que pasa en chorro fino.", "exp": "La obstrucción del colédoco por un cálculo, con infección de la bilis retenida, produce la tríada de Charcot: dolor, ictericia y fiebre; si se suma hipotensión y alteración mental es la pentada de Reynolds. Es una urgencia: antibiótico, reanimación y descompresión biliar urgente por CPRE con extracción del cálculo, según los criterios de Tokio TG18 para colangitis aguda."},
    {"id": "IM-R2-05", "grade": "R2", "tema": "Pancreatitis aguda y crónica", "imagen": "Tomografía computarizada de abdomen con contraste intravenoso, corte axial a la altura del páncreas. El páncreas está aumentado de tamaño, con contornos mal definidos y densidad heterogénea. Más del 50 % del cuerpo y la cola no refuerzan tras el contraste: se ven zonas extensas de parénquima sin realce, negras, que corresponden a necrosis. Alrededor hay colecciones líquidas peripancreáticas heterogéneas, con áreas de densidad grasa y burbujas de gas en su interior, que se extienden hacia la gotiera paracólica izquierda. La vesícula no tiene cálculos visibles en este corte y el colédoco no está dilatado. No hay pseudoquiste único bien delimitado.", "pistas": ["Dolor epigástrico intenso irradiado a la espalda, de una semana de evolución, con lipasa muy elevada al inicio y ahora fiebre, taquicardia y leucocitosis.", "La falta de realce del parénquima en la TC es el signo de necrosis; el gas dentro de las colecciones sugiere infección de la necrosis.", "El manejo inicial de la necrosis infectada no es la cirugía abierta inmediata: la vía actual es escalonada, de menos a más invasiva."], "dx": "Pancreatitis aguda necrotizante con necrosis infectada del cuerpo y la cola.", "hallazgo": "Más del 50 % del páncreas sin realce tras el contraste, con colecciones peripancreáticas heterogéneas con gas.", "exp": "La necrosis pancreática se reconoce por la ausencia de realce en la TC con contraste; el gas en las colecciones sugiere infección. El abordaje actual es escalonado (step-up): antibiótico, soporte en terapia intensiva, drenaje percutáneo o endoscópico primero y necrosectomía mínimamente invasiva solo si no resuelve, difiriendo la intervención todo lo posible más allá de la cuarta semana."},
    {"id": "IM-R2-06", "grade": "R2", "tema": "Hernias de la pared abdominal", "imagen": "Tomografía computarizada de abdomen y pelvis con contraste intravenoso, corte axial a la altura de la ingle derecha. En el canal femoral derecho se observa un saco herniario de 3 cm que contiene un asa de intestino delgado con pared engrosada, de 6 mm, que refuerza poco tras el contraste y tiene líquido en su luz. El asa está atrapada en un orificio estrecho, con dilatación del asa proximal y colapso del asa distal. Hay estriación de la grasa vecina y una pequeña cantidad de líquido libre en la pelvis. El canal femoral izquierdo es normal y no hay otras hernias visibles en este corte.", "pistas": ["Tumoración dolorosa, tensa e irreductible en la ingle, por debajo del ligamento inguinal, en una mujer mayor.", "Vómito, distensión y ausencia de flatos desde hace un día, con dolor que no cede.", "Esta hernia, por su orificio estrecho y su localización, tiene el mayor riesgo de estrangulación de todas las hernias de la ingle."], "dx": "Hernia femoral estrangulada, con asa de intestino delgado comprometida.", "hallazgo": "Saco herniario en el canal femoral con asa de delgado atrapada, pared engrosada con poco realce y dilatación proximal.", "exp": "La hernia femoral sale por debajo del ligamento inguinal, por el canal femoral, y su anillo rígido y estrecho la hace la hernia inguinal con mayor riesgo de incarceración y estrangulación. La pared engrosada con escaso realce y la obstrucción con dilatación proximal sugieren isquemia del asa atrapada. Es una urgencia quirúrgica: no se intenta reducción forzada en la cama y se opera para liberar el asa y reparar el defecto, resecando el intestino si no es viable."},
    {"id": "IM-R2-07", "grade": "R2", "tema": "Obstrucción intestinal, vólvulo e isquemia intestinal", "imagen": "Angiotomografía computarizada de abdomen, fase arterial, corte axial y reconstrucción coronal. Se observa un defecto de llenado, una imagen de \"parada abrupta\", en la arteria mesentérica superior, a unos 4 cm de su origen en la aorta, con ausencia de contraste distal a ese punto. Las asas de intestino delgado del territorio afectado tienen pared engrosada, de 5 mm, con escaso o nulo realce tras el contraste, y hay líquido libre en la cavidad. No se ve neumatosis intestinal ni gas en la vena porta en este estudio. El tronco celiaco y la arteria mesentérica inferior están permeables.", "pistas": ["Dolor abdominal intenso, desproporcionado a la exploración física, de inicio súbito, en una paciente con fibrilación auricular sin anticoagulación.", "Lactato de 4,6 mmol/L, leucocitosis y acidosis metabólica, con abdomen todavía blando.", "La oclusión embólica proximal, con intestino aún viable en la imagen, abre una ventana de tratamiento endovascular antes de que la isquemia sea irreversible."], "dx": "Isquemia mesentérica aguda por embolia de la arteria mesentérica superior.", "hallazgo": "Defecto de llenado con parada abrupta en la arteria mesentérica superior a 4 cm de su origen, con asas sin realce en su territorio.", "exp": "El dolor desproporcionado a la exploración, en una paciente con fibrilación auricular, con lactato elevado, es el cuadro clásico de la embolia mesentérica. La angio-TC es el estudio de elección: muestra la oclusión y la viabilidad intestinal. El manejo es reanimación, anticoagulación, antibiótico y revascularización urgente (embolectomía o trombólisis endovascular) con laparotomía para valorar la viabilidad y resecar el intestino necrosado; el tiempo es intestino."},
    {"id": "IM-R2-08", "grade": "R2", "tema": "Enfermedad diverticular y patología benigna de colon", "imagen": "Tomografía computarizada de abdomen y pelvis con contraste intravenoso y rectal, corte axial a la altura del colon sigmoides. El sigmoides muestra engrosamiento mural circunferencial de 8 mm, con estriación de la grasa pericólica, que está sucia y engrosada, y múltiples divertículos en su pared. Adyacente a la pared, en el mesosigmoides, hay una colección líquida de 4 cm, con pared que refuerza y pequeñas burbujas de gas en su interior, sin comunicación franca con la luz intestinal. No hay gas libre intraperitoneal ni líquido libre difuso. El resto del colon no muestra engrosamiento.", "pistas": ["Dolor en fosa iliaca izquierda, fiebre de 38,5 °C y leucocitosis, en un paciente mayor con antecedente de episodios similares.", "Es el equivalente en el lado izquierdo de la apendicitis, pero el estudio de elección no es la colonoscopia en la fase aguda.", "La colección pericólica de 4 cm define el estadio de Hinchey y decide entre antibiótico solo o drenaje percutáneo."], "dx": "Diverticulitis aguda complicada del sigmoides, Hinchey Ib (absceso pericólico).", "hallazgo": "Sigmoides engrosado con divertículos, grasa sucia y absceso pericólico de 4 cm con gas en su interior.", "exp": "La diverticulitis aguda se reconoce por el engrosamiento mural del sigmoides con divertículos y grasa pericólica inflamada. La clasificación de Hinchey estratifica la complicación: el absceso pericólico (Ib) se maneja con antibiótico y drenaje percutáneo guiado por imagen si es mayor de 3–4 cm o no responde; la cirugía de urgencia se reserva para la peritonitis, la perforación libre o el fracaso del manejo conservador, y la colonoscopia se difiere unas 6 semanas para descartar cáncer."},
    {"id": "IM-R2-09", "grade": "R2", "tema": "Cáncer de colon", "imagen": "Colonoscopia, vista del colon ascendente. Se observa una lesión exofítica, fungosa, de unos 5 cm, que ocupa más de la mitad de la luz intestinal. Su superficie es irregular, friable, de color rojo oscuro con áreas blanquecinas y necróticas, y sangra al contacto con el endoscopio. Los bordes son elevados, duros e irregulares, y la lesión no se desplaza con la insuflación. El colon proximal no puede explorarse porque la lesión casi ocluye la luz. La mucosa circundante es de aspecto normal.", "pistas": ["Anemia ferropénica, pérdida de peso de 8 kg y cambio en el hábito intestinal en un paciente mayor de 60 años.", "La sangre oculta en heces fue positiva y la lesión es friable y sangra al contacto.", "El diagnóstico no se hace solo por la vista: hacen falta biopsias y estadificación completa antes de decidir la cirugía."], "dx": "Cáncer de colon ascendente, lesión fungosa ulcerada (probable adenocarcinoma).", "hallazgo": "Lesión exofítica de 5 cm, friable, con superficie necrótica que sangra al contacto y casi ocluye la luz del colon ascendente.", "exp": "El cáncer de colon derecho se presenta de forma insidiosa con anemia ferropénica, pérdida de peso y sangre oculta, porque las lesiones fungosas sangran de forma crónica y la luz es amplia, por lo que la obstrucción es tardía. La colonoscopia con biopsia confirma el adenocarcinoma y la estadificación con TC de tórax, abdomen y pelvis y antígeno carcinoembrionario define el manejo: resección oncológica con linfadenectomía y quimioterapia adyuvante según el estadio."},
    {"id": "IM-R2-10", "grade": "R2", "tema": "Cáncer de recto y ano, y patología anorrectal benigna", "imagen": "Resonancia magnética de pelvis, secuencia T2, corte axial y sagital, centrada en el recto medio. Se observa un engrosamiento mural circunferencial del recto, de 12 mm, en un segmento de 5 cm, con señal intermedia que invade la grasa mesorrectal en 4 mm más allá de la muscular propia. La fascia mesorrectal está a 2 mm del borde tumoral en su punto más cercano. Hay dos ganglios mesorrectales de 7 y 9 mm, de bordes irregulares y señal heterogénea. El esfínter anal no está invadido y no hay lesiones en el hígado visibles en este estudio.", "pistas": ["Rectorragia, tenesmo y sensación de evacuación incompleta en un paciente de 58 años.", "Al tacto rectal se palpa una masa dura, fija, a 7 cm del margen anal.", "La distancia a la fascia mesorrectal y la invasión de la grasa definen si el tratamiento empieza con cirugía o con neoadyuvancia."], "dx": "Cáncer de recto medio, estadio clínico T3 N1, con margen de resección circunferencial amenazado (fascia a 2 mm).", "hallazgo": "Tumor rectal de 5 cm que invade 4 mm la grasa mesorrectal, fascia mesorrectal a 2 mm, con ganglios mesorrectales sospechosos.", "exp": "La RM de pelvis es el estudio clave para estadificar el cáncer de recto: mide la invasión de la grasa mesorrectal, la distancia a la fascia mesorrectal (margen circunferencial) y los ganglios. Un T3 con fascia amenazada y ganglios positivos indica tratamiento neoadyuvante (quimiorradioterapia o radioterapia de curso corto, según las guías NCCN de cáncer de recto) antes de la resección mesorrectal total, para reducir la recidiva local."},
    {"id": "IM-R3-01", "grade": "R3", "tema": "Cirugía oncológica: principios, estadificación y manejo multidisciplinario", "imagen": "PET-TC de cuerpo entero, imágenes fusionadas en cortes axiales y reconstrucción de máxima intensidad (MIP). Se observa captación intensa y focal de fluorodesoxiglucosa (FDG) en el colon sigmoides, con un valor de captación estandarizado (SUV) máximo de 14, que corresponde a una lesión mural engrosada visible en la TC. Además hay tres focos hipermetabólicos en el hígado, en los segmentos V, VI y VIII, de 12 a 25 mm, con SUV de 9 a 11, que coinciden con lesiones hipodensas en la TC. También se ve un ganglio hipermetabólico en el mesenterio del sigmoides, de 11 mm, con SUV de 6. No hay captación patológica en el tórax ni en los huesos. La captación fisiológica en cerebro, miocardio y vías urinarias se ve normal.", "pistas": ["Paciente con cáncer de sigmoides ya diagnosticado por colonoscopia, en el que se busca enfermedad a distancia antes de decidir el plan.", "La captación no es solo del tumor primario: hay focos en el hígado y en un ganglio, que cambian el estadio.", "La presencia de metástasis hepáticas no significa automáticamente que no se opere, pero sí que el caso debe discutirse en comité multidisciplinario y que el orden del tratamiento cambia."], "dx": "Cáncer de colon sigmoides con metástasis hepáticas múltiples y ganglio mesentérico positivo (enfermedad metastásica, estadio IV).", "hallazgo": "Captación intensa de FDG en el sigmoides (SUV 14), tres focos hepáticos hipermetabólicos y un ganglio mesentérico positivo.", "exp": "La PET-TC muestra el tumor primario y la enfermedad a distancia en un solo estudio: el SUV alto en el sigmoides, las lesiones hepáticas hipermetabólicas y el ganglio positivo establecen enfermedad metastásica. Esto cambia el estadio a IV y el plan ya no es cirugía directa sin más: se discute en comité multidisciplinario, se valora quimioterapia sistémica y la resecabilidad de las metástasis hepáticas, que en casos seleccionados pueden operarse con intención curativa."},
    {"id": "IM-R3-02", "grade": "R3", "tema": "Cáncer de mama", "imagen": "Mastografía bilateral, proyecciones craneocaudal y mediolateral oblicua. En el cuadrante superior externo de la mama izquierda se observa un nódulo denso, de 18 mm, de bordes espiculados, con prolongaciones radiadas que se extienden hacia el tejido vecino y retracción de la piel suprayacente. Asociado al nódulo hay un grupo de microcalcificaciones pleomórficas, finas y agrupadas en un área de 12 mm, de morfología irregular. La mama derecha no muestra nódulos ni microcalcificaciones sospechosas. No hay ganglios axilares de aspecto patológico visibles en esta proyección, aunque la valoración axilar requiere ecografía.", "pistas": ["Nódulo palpable, duro, fijo y no doloroso en la mama izquierda, en una mujer de 55 años, que notó retracción del pezón.", "Los bordes espiculados y las microcalcificaciones pleomórficas agrupadas son los dos signos mastográficos más sospechosos de malignidad.", "La mastografía no da el diagnóstico definitivo: la lesión es BI-RADS 5 y exige biopsia con aguja gruesa antes de cualquier cirugía."], "dx": "Cáncer de mama izquierda, nódulo espiculado con microcalcificaciones pleomórficas (BI-RADS 5, alta sospecha de malignidad).", "hallazgo": "Nódulo de 18 mm de bordes espiculados con retracción cutánea y microcalcificaciones pleomórficas agrupadas.", "exp": "El nódulo espiculado con microcalcificaciones pleomórficas es el patrón mastográfico clásico del carcinoma mamario. BI-RADS 5 significa alta probabilidad de malignidad y obliga a biopsia percutánea con aguja gruesa para el diagnóstico histológico y los receptores hormonales y HER2, y a estadificación con ecografía axilar; la cirugía se planea después del diagnóstico tisular, no por la imagen sola."},
    {"id": "IM-R3-03", "grade": "R3", "tema": "Cáncer colorrectal", "imagen": "Tomografía computarizada de abdomen y pelvis con contraste intravenoso, corte axial a la altura del colon derecho. Se observa un engrosamiento mural asimétrico y excéntrico del colon ascendente, de 15 mm, en un segmento de 6 cm, con refuerzo heterogéneo tras el contraste y pérdida de la estratificación normal de la pared. La grasa pericólica está estriada y hay tres ganglios regionales de 8 a 12 mm, redondeados, con realce. No hay obstrucción completa: el colon proximal está dilatado de forma leve y hay paso de contraste distal. No se ven lesiones hepáticas focales en este estudio ni líquido libre.", "pistas": ["Anemia ferropénica, pérdida de peso y masa palpable en el flanco derecho, con sangre oculta en heces positiva.", "El engrosamiento excéntrico con ganglios regionales es el patrón de un tumor de colon derecho, distinto del de una colitis, que suele ser circunferencial y segmentaria larga.", "La estadificación no termina en esta TC: hacen falta la colonoscopia con biopsia, el antígeno carcinoembrionario y la TC de tórax."], "dx": "Cáncer de colon ascendente, con ganglios regionales sospechosos (estadio clínico T3 N1).", "hallazgo": "Engrosamiento mural excéntrico de 15 mm en el colon ascendente, de 6 cm, con grasa sucia y tres ganglios regionales de 8–12 mm.", "exp": "El cáncer de colon derecho se presenta con anemia ferropénica y masa palpable, y en la TC se ve como engrosamiento mural asimétrico con ganglios regionales. La confirmación es histológica por colonoscopia con biopsia y la estadificación completa define si la cirugía es de entrada o si hay neoadyuvancia; la resección oncológica es la hemicolectomía derecha con linfadenectomía y ligadura vascular alta."},
    {"id": "IM-R3-04", "grade": "R3", "tema": "Cáncer gástrico y de esófago", "imagen": "Endoscopia digestiva alta, vista del cuerpo y el antro gástrico. La mucosa gástrica está engrosada, rígida y con pliegues engrosados que no se distienden con la insuflación: el estómago no se expande y el endoscopio avanza con dificultad. En el antro se observa una lesión ulcerada, de 25 mm, con bordes elevados, irregulares y duros, fondo necrótico y sangrado leve al contacto. La mucosa circundante es pálida, con aspecto atrófico y vasos visibles. El píloro está estrechado y el paso del endoscopio al duodeno es difícil.", "pistas": ["Pérdida de peso de 12 kg, saciedad precoz, vómito postprandial y anemia, en un paciente con antecedente de gastritis atrófica.", "El estómago rígido que no se distiende sugiere infiltración difusa de la pared, el patrón clásico de la linitis plástica.", "Las biopsias superficiales pueden salir negativas en este patrón porque el tumor infiltra la submucosa; a veces hacen falta biopsias profundas o en sacabocados."], "dx": "Cáncer gástrico avanzado, tipo difuso con linitis plástica y lesión ulcerada antral.", "hallazgo": "Estómago rígido, no distensible, con pliegues engrosados y úlcera antral de 25 mm de bordes elevados y fondo necrótico.", "exp": "La linitis plástica es la forma difusa del cáncer gástrico, que infiltra toda la pared y deja el estómago rígido como una \"bota de cuero\", con saciedad precoz y vómito. La endoscopia con biopsias confirma el adenocarcinoma difuso, y la estadificación con TC y laparoscopia de estadificación define si hay carcinomatosis; el pronóstico es malo y el manejo es multidisciplinario, con quimioterapia perioperatoria y gastrectomía en los casos resecables."},
    {"id": "IM-R3-05", "grade": "R3", "tema": "Hígado, vía biliar y páncreas (HPB)", "imagen": "Colangiorresonancia magnética (RMCP), reconstrucción de máxima intensidad y cortes axiales. Se observa una estenosis abrupta y larga de la confluencia de los conductos hepáticos derecho e izquierdo, en el hilio hepático, con dilatación de la vía biliar intrahepática bilateral por encima de la estenosis, en forma de \"árbol podado\". La vía biliar extrahepática distal a la estenosis es de calibre normal. En el hilio se ve una masa de señal intermedia, de 25 mm, que rodea la confluencia y engloba la rama derecha de la arteria hepática. No hay cálculos en la vía biliar ni lesiones focales hepáticas a distancia.", "pistas": ["Ictericia progresiva, prurito y pérdida de peso en un paciente mayor, sin dolor cólico ni fiebre.", "La dilatación intrahepática con colédoco distal normal localiza la obstrucción en el hilio, no en la cabeza del páncreas.", "Es el tumor de la confluencia biliar por excelencia y su resecabilidad depende de la extensión vascular y de la atrofia hepática, según la clasificación de Bismuth-Corlette."], "dx": "Colangiocarcinoma hiliar (tumor de Klatskin), con invasión de la confluencia biliar.", "hallazgo": "Estenosis de la confluencia de los hepáticos con dilatación intrahepática bilateral, masa hiliar de 25 mm que engloba la arteria hepática derecha.", "exp": "El tumor de Klatskin obstruye la confluencia de los conductos hepáticos y produce ictericia obstructiva con dilatación intrahepática y colédoco distal normal. La RMCP es el estudio clave para clasificarlo (Bismuth-Corlette) y valorar la resecabilidad: la invasión vascular y la extensión bilateral condicionan si se puede resecar con hepatectomía mayor, con drenaje biliar preoperatorio del remanente futuro y manejo en un centro hepatobiliar."},
    {"id": "IM-R3-06", "grade": "R3", "tema": "Cirugía endocrina: tiroides, paratiroides y suprarrenal", "imagen": "Ecografía de cuello, en escala de grises y Doppler color, centrada en el lóbulo tiroideo derecho. Se observa un nódulo sólido, hipoecoico, de 22 mm, de bordes irregulares, con microcalcificaciones puntiformes en su interior y forma más alta que ancha. El nódulo tiene vascularidad intranodular aumentada en el Doppler y un halo hipoecoico incompleto. El resto del parénquima tiroideo es heterogéneo, con patrón micronodular. Hay un ganglio cervical lateral de 12 mm, redondeado, sin hilio graso visible, sospechoso.", "pistas": ["Nódulo tiroideo palpable, duro, de crecimiento en meses, en una mujer de 40 años, con función tiroidea normal.", "La forma más alta que ancha, la hipoecogenicidad, las microcalcificaciones y los bordes irregulares son los rasgos ecográficos de mayor sospecha.", "La ecografía estratifica el riesgo (TI-RADS), pero el diagnóstico se hace con punción por aspiración con aguja fina guiada por ecografía."], "dx": "Nódulo tiroideo de alta sospecha de malignidad (TI-RADS 5), probable carcinoma papilar de tiroides, con ganglio cervical sospechoso.", "hallazgo": "Nódulo hipoecoico de 22 mm, más alto que ancho, con microcalcificaciones, bordes irregulares y vascularidad intranodular, más ganglio sin hilio graso.", "exp": "La ecografía tiroidea con TI-RADS estratifica el riesgo de malignidad: hipoecogenicidad, forma más alta que ancha, bordes irregulares y microcalcificaciones son los rasgos de mayor sospecha. El siguiente paso es la punción con aguja fina guiada por ecografía; si confirma carcinoma papilar, el manejo es quirúrgico (lobectomía o tiroidectomía total según el tamaño y el riesgo) con valoración de los ganglios cervicales."},
    {"id": "IM-R3-07", "grade": "R3", "tema": "Cirugía de tórax, pleura y mediastino", "imagen": "Tomografía computarizada de tórax con contraste intravenoso, corte axial a la altura de las bases pulmonares. En el hemitórax derecho se observa una colección pleural tabicada, de 6 cm de espesor, con pared engrosada que refuerza tras el contraste (signo de la pleura dividida, o \"split pleura\"), con contenido heterogéneo, líquido y con pequeñas burbujas de gas en su interior. El pulmón adyacente está colapsado parcialmente y hay engrosamiento de la pleura parietal y visceral. No hay neumotórax ni lesión pulmonar cavitada visible. El hemitórax izquierdo no tiene derrame.", "pistas": ["Fiebre persistente, dolor torácico pleurítico y disnea, dos semanas después de una neumonía que no mejoró con antibiótico.", "El líquido pleural es purulento, con pH menor de 7,2 y glucosa baja, y no drena bien por el tubo pleural.", "El signo de la pleura dividida y los tabiques indican que el derrame ya está en fase organizada y que el tubo simple no va a resolverlo."], "dx": "Empiema pleural tabicado, en fase fibrinopurulenta a organizada.", "hallazgo": "Colección pleural tabicada con pared engrosada que refuerza (signo de la pleura dividida) y gas en su interior, con pulmón colapsado.", "exp": "El empiema es pus en la cavidad pleural, habitualmente tras una neumonía. Cuando se tabica y la pleura se engrosa, el drenaje simple por tubo fracasa: el manejo es drenaje con tubo de grueso calibre o, si hay tabiques y pulmón atrapado, toracoscopia (VATS) para desbridar, romper los tabiques y decorticar, más antibiótico prolongado. Esperar a que \"se reabsorba\" deja un pulmón atrapado."},
    {"id": "IM-R3-08", "grade": "R3", "tema": "Cirugía vascular: aorta, carótida y enfermedad arterial periférica", "imagen": "Angiotomografía computarizada de abdomen, reconstrucción sagital y axial, fase arterial. Se observa una dilatación fusiforme de la aorta infrarrenal, de 6,2 cm de diámetro máximo, con trombo mural excéntrico en su pared y calcificaciones. El aneurisma se extiende 5 cm por debajo de las arterias renales y termina antes de la bifurcación aórtica. Las arterias renales están permeables y su origen no está comprometido. No hay signos de rotura: no hay hematoma retroperitoneal ni extravasación de contraste. Las arterias iliacas comunes tienen dilatación leve, de 18 mm.", "pistas": ["Masa abdominal pulsátil, no dolorosa, en un hombre de 72 años, fumador e hipertenso, hallada por casualidad.", "El diámetro mayor de 5,5 cm en el hombre es el umbral clásico de reparación electiva, y este lo supera.", "La decisión no es solo el diámetro: la anatomía del cuello infrarrenal y de las iliacas define si se repara por vía endovascular o abierta."], "dx": "Aneurisma de aorta abdominal infrarrenal, de 6,2 cm, no roto.", "hallazgo": "Dilatación fusiforme infrarrenal de 6,2 cm con trombo mural, cuello de 5 cm bajo las renales, sin hematoma retroperitoneal.", "exp": "El aneurisma de aorta abdominal es una dilatación mayor de 3 cm; por encima de 5,5 cm en hombres (5,0 cm en mujeres) el riesgo de rotura justifica la reparación electiva. La angio-TC define la anatomía para elegir entre reparación endovascular (EVAR) y cirugía abierta, según el cuello, la angulación y las iliacas. Un aneurisma roto, con dolor súbito, hipotensión y masa pulsátil, es una emergencia que no espera a la imagen."},
    {"id": "IM-R3-09", "grade": "R3", "tema": "Trauma complejo y cirugía de control de daños", "imagen": "Fotografía de quirófano, vista cenital del abdomen abierto tras una laparotomía. La cavidad abdominal está ocupada por compresas quirúrgicas blancas, empapadas en sangre, colocadas en los cuatro cuadrantes como empaquetamiento (packing) perihepático y pélvico. No se ve cierre de la pared: los bordes de la incisión están separados y cubiertos por una lámina plástica transparente estéril (bolsa de Bogotá), suturada a la piel, que deja ver las compresas por debajo. Hay drenajes saliendo por los flancos y el campo está lleno de sangre oscura, con el intestino apenas visible entre las compresas. No hay anastomosis ni cierre definitivo visible.", "pistas": ["Paciente con trauma abdominal penetrante, hipotenso, hipotérmico, acidótico y coagulopático, que no dejó de sangrar en el quirófano.", "La tríada letal (hipotermia, acidosis y coagulopatía) es la que obliga a cambiar de estrategia: no se puede terminar la cirugía en un solo tiempo.", "La estrategia tiene nombre propio y tres fases: control rápido de la hemorragia y la contaminación, reanimación en terapia intensiva y reintervención planeada."], "dx": "Cirugía de control de daños, fase de empaquetamiento con abdomen abierto (bolsa de Bogotá) — trauma abdominal grave con tríada letal.", "hallazgo": "Abdomen abierto con compresas de empaquetamiento en los cuatro cuadrantes y cierre temporal con bolsa de Bogotá, sin cierre fascial definitivo.", "exp": "En el trauma grave con hipotermia, acidosis y coagulopatía, la cirugía definitiva mata: la estrategia es la cirugía de control de daños, que controla la hemorragia y la contaminación lo más rápido posible, empaqueta, deja el abdomen abierto con cierre temporal y lleva al paciente a terapia intensiva a corregir la tríada, para reoperar de forma planeada en 24–48 horas. Es una decisión de fisiología, no de anatomía."},
    {"id": "IM-R3-10", "grade": "R3", "tema": "Trasplante de órganos sólidos", "imagen": "Ecografía Doppler del hígado trasplantado, en el hipocondrio derecho, a las 48 horas del trasplante. El parénquima hepático se ve homogéneo, sin colecciones perihepáticas. En el Doppler color, la arteria hepática no muestra flujo: no hay señal arterial en el hilio, mientras que la vena porta tiene flujo hepatopetal normal y las venas hepáticas drenan bien. En el Doppler espectral de la arteria hepática no se obtiene onda: silencio arterial. El conducto biliar no está dilatado en este estudio y no hay trombosis portal visible.", "pistas": ["Receptor de trasplante hepático que en el segundo día postoperatorio presenta elevación brusca de transaminasas, fiebre y deterioro de la función del injerto.", "La ausencia de flujo arterial con porta permeable es el hallazgo que más se teme en el postoperatorio inmediato del trasplante hepático.", "Es una urgencia vascular del injerto: cada hora sin flujo arterial acerca la necrosis biliar y la pérdida del órgano, y exige confirmación inmediata y reintervención."], "dx": "Trombosis de la arteria hepática postrasplante hepático.", "hallazgo": "Ausencia completa de flujo arterial hepático en el Doppler, con vena porta permeable y parénquima sin colecciones.", "exp": "La trombosis de la arteria hepática es la complicación vascular más temida del trasplante hepático: el injerto depende de la arteria para la vía biliar y su oclusión produce necrosis biliar, abscesos y pérdida del injerto. El Doppler es el estudio de primera línea y su sospecha exige confirmación urgente con angio-TC y reintervención inmediata (trombectomía y revisión de la anastomosis) o retrasplante si el injerto ya no es viable."},
    {"id": "IM-R4-01", "grade": "R4", "tema": "Cirugía hepatobiliar avanzada", "imagen": "Tomografía computarizada de abdomen con contraste intravenoso, corte axial a la altura del hígado. En el lóbulo derecho, segmento VI, se observa una lesión quística redondeada, bien delimitada, de 9 cm de diámetro, con pared gruesa de 4 mm que refuerza levemente tras el contraste. En su interior hay líquido de densidad homogénea y varias vesículas hijas pequeñas, redondeadas, dispuestas en la periferia, como un \"panal\". No hay gas ni nivel líquido en su interior. La vía biliar no está dilatada y no hay otras lesiones hepáticas. El resto del abdomen es normal.", "pistas": ["Masa palpable en hipocondrio derecho, de crecimiento lento, en un paciente que vive en zona rural y convive con perros.", "Las vesículas hijas en la periferia son el signo patognomónico de este quiste y lo distinguen de un quiste simple o de un absceso.", "La punción de este quiste está contraindicada por el riesgo de siembra y de choque anafiláctico: el manejo es quirúrgico, con protección del campo para evitar el derrame del contenido."], "dx": "Quiste hidatídico hepático (equinococosis quística), con vesículas hijas.", "hallazgo": "Lesión quística de 9 cm con pared gruesa y vesículas hijas periféricas en panal, sin gas ni dilatación biliar.", "exp": "El quiste hidatídico, por Echinococcus granulosus, es un quiste parasitario de crecimiento lento, frecuente en zonas ganaderas. Las vesículas hijas son diagnósticas. No se punza: el derrame del líquido hidatídico puede producir anafilaxia y siembra peritoneal. El manejo es quirúrgico (quistesctomía con protección con compresas con solución hipertónica, o hepatectomía según la localización) más albendazol perioperatorio."},
    {"id": "IM-R4-02", "grade": "R4", "tema": "Cirugía pancreática avanzada", "imagen": "Tomografía computarizada de abdomen con contraste intravenoso en fase pancreática, corte axial y coronal, a la altura de la cabeza del páncreas. Se observa una masa hipodensa, mal delimitada, de 3 cm, en la cabeza del páncreas, que no refuerza como el parénquima normal. La masa contacta la vena mesentérica superior en menos de 180 grados de su circunferencia, sin deformarla ni ocluirla, y está a 2 mm de la arteria mesentérica superior, sin contacto directo. El conducto pancreático principal está dilatado, de 6 mm, y el colédoco distal está estrechado, con dilatación proximal de 12 mm (signo del doble conducto). No hay metástasis hepáticas ni carcinomatosis visible.", "pistas": ["Ictericia indolora, pérdida de peso de 10 kg y dolor epigástrico sordo, en un paciente de 65 años.", "La dilatación simultánea del conducto pancreático y del colédoco es el signo del doble conducto, clásico del tumor de la cabeza del páncreas.", "El contacto venoso menor de 180 grados, sin deformidad, y la ausencia de contacto arterial definen la categoría de resecabilidad: no es claramente resecable ni irresecable."], "dx": "Adenocarcinoma de cabeza de páncreas, borderline resecable, con signo del doble conducto.", "hallazgo": "Masa hipodensa de 3 cm en la cabeza del páncreas, contacto menor de 180° con la vena mesentérica superior, sin contacto arterial, con doble conducto dilatado.", "exp": "El adenocarcinoma de cabeza de páncreas produce ictericia obstructiva indolora con doble conducto dilatado. La TC en fase pancreática define la resecabilidad por el contacto vascular: el contacto venoso menor de 180° sin deformidad, sin contacto arterial, es borderline resecable, lo que indica quimioterapia neoadyuvante antes de la pancreaticoduodenectomía (Whipple), en un centro de alto volumen y con discusión multidisciplinaria."},
    {"id": "IM-R4-03", "grade": "R4", "tema": "Cirugía oncológica avanzada y carcinomatosis peritoneal", "imagen": "Tomografía computarizada de abdomen y pelvis con contraste intravenoso, corte axial y coronal. Se observan múltiples implantes peritoneales: nódulos de 5 a 20 mm en el epiplón mayor, que está engrosado y con aspecto de \"pastel epiploico\" (omental cake), con aumento de la densidad de la grasa. Hay implantes en la superficie del hígado, en el fondo de saco de Douglas y en la gotiera paracólica derecha, con escasa cantidad de ascitis. El tumor primario, en el colon sigmoides, se ve como un engrosamiento mural de 12 mm. No hay metástasis hepáticas parenquimatosas ni obstrucción intestinal completa.", "pistas": ["Paciente con cáncer de sigmoides conocido, con distensión abdominal, ascitis y pérdida de peso, en quien se valora si aún hay opción quirúrgica.", "El epiplón engrosado en \"pastel\" y los nódulos peritoneales múltiples son la forma de presentación de la siembra peritoneal.", "La decisión ya no es solo resecar el tumor primario: hay un índice que cuantifica la carga peritoneal y una cirugía combinada con quimioterapia intraperitoneal que solo se ofrece en casos seleccionados."], "dx": "Carcinomatosis peritoneal por cáncer de colon sigmoides, con omental cake e implantes múltiples.", "hallazgo": "Epiplón mayor engrosado en \"pastel epiploico\", implantes peritoneales múltiples en hígado, Douglas y gotiera paracólica, con ascitis.", "exp": "La carcinomatosis peritoneal es la siembra del cáncer en el peritoneo; el omental cake es su signo tomográfico clásico. El manejo se decide con el índice de carcinomatosis peritoneal (PCI) y la posibilidad de citorreducción completa: en casos seleccionados, con poca carga y sin enfermedad extraperitoneal, se ofrece cirugía citorreductora más quimioterapia intraperitoneal hipertérmica (HIPEC); en la mayoría, el manejo es quimioterapia sistémica paliativa."},
    {"id": "IM-R4-04", "grade": "R4", "tema": "Trauma complejo, abdomen abierto y cuidados críticos", "imagen": "Fotografía clínica del abdomen anterior, centrada en una herida de laparotomía en la línea media que no ha cerrado. La herida está abierta en toda su longitud y en su centro se observa un orificio en el intestino delgado expuesto, por el que sale contenido intestinal líquido, de color verdoso y con restos de alimento, que se derrama sobre la piel y las compresas circundantes. El intestino expuesto está edematoso, con adherencias y con una superficie granular, sin peritoneo ni piel que lo cubra. Alrededor de la herida hay piel macerada y eritematosa, y un sistema de presión negativa colocado de forma parcial, que no sella por la salida continua de contenido.", "pistas": ["Paciente con abdomen abierto tras un trauma grave y varias reintervenciones, que lleva semanas en terapia intensiva con un gasto alto por la herida.", "La fístula no está en la piel intacta ni en un trayecto largo: el intestino está abierto directamente en la herida, sin tejido que lo cubra.", "Es la complicación más temida del abdomen abierto y su manejo inicial no es operarla de inmediato: primero se protege la piel, se controla la sepsis y se optimiza la nutrición, y la cirugía definitiva se difiere meses."], "dx": "Fístula enteroatmosférica en abdomen abierto.", "hallazgo": "Orificio intestinal expuesto en el centro de una herida abdominal abierta, con salida continua de contenido intestinal sobre la piel.", "exp": "La fístula enteroatmosférica es una fístula del intestino directamente a la atmósfera, sin trayecto ni piel, típica del abdomen abierto tras trauma o sepsis. Es una catástrofe nutricional y séptica: el manejo es control de la sepsis, protección de la piel y aislamiento del efluente, nutrición, y cirugía definitiva diferida varios meses, cuando el abdomen esté \"congelado\" y la inflamación haya cedido; operarla pronto casi siempre la empeora."},
    {"id": "IM-R4-05", "grade": "R4", "tema": "Cirugía endocrina, de cabeza y cuello y de mama", "imagen": "Tomografía computarizada de abdomen con contraste intravenoso, corte axial a la altura de las glándulas suprarrenales. En la suprarrenal derecha se observa una masa redondeada, bien delimitada, de 4,5 cm, heterogénea, con áreas quísticas y de necrosis central, que refuerza de forma intensa y heterogénea tras el contraste y lava parcialmente en la fase tardía. La masa desplaza el hígado hacia arriba y el riñón derecho hacia abajo, sin invadirlos. La suprarrenal izquierda es normal, de 8 mm de grosor, y no hay ganglios retroperitoneales aumentados ni lesiones hepáticas.", "pistas": ["Crisis de hipertensión paroxística, con cefalea, palpitaciones y sudoración, que aparecen en episodios y no se controlan con antihipertensivos habituales.", "Las metanefrinas en orina de 24 horas están muy elevadas y la masa es mayor de 4 cm, heterogénea y con necrosis.", "Antes de tocar esta masa hay un paso obligatorio de preparación farmacológica: operar sin bloqueo puede desencadenar una crisis hipertensiva mortal en el quirófano."], "dx": "Feocromocitoma de suprarrenal derecha.", "hallazgo": "Masa suprarrenal derecha de 4,5 cm, heterogénea, con necrosis central y refuerzo intenso, con metanefrinas elevadas.", "exp": "El feocromocitoma es un tumor cromafín de la médula suprarrenal que secreta catecolaminas y produce crisis hipertensivas paroxísticas con cefalea, palpitaciones y sudoración. El diagnóstico bioquímico es con metanefrinas y la imagen localiza la masa. El manejo es adrenalectomía, pero antes es obligatorio el bloqueo alfa (fentolamina o fenoxibenzamina) durante 10–14 días, con reposición de volumen, para evitar una crisis hipertensiva intraoperatoria; nunca se opera sin esa preparación ni se hace biopsia percutánea."},
    {"id": "IM-R4-06", "grade": "R4", "tema": "Cirugía bariátrica y metabólica y pared abdominal compleja", "imagen": "Tomografía computarizada de abdomen con contraste oral e intravenoso, corte axial y coronal, a la altura del estómago operado. Se observa el tubo gástrico de la manga gástrica, con una solución de continuidad en su borde superior, cerca de la unión gastroesofágica, por la que sale contraste oral hacia una colección líquida de 5 cm en el espacio subfrénico izquierdo, con burbujas de gas en su interior. La colección tiene pared que refuerza y comprime el lóbulo hepático izquierdo. No hay contraste libre difuso en toda la cavidad ni neumoperitoneo masivo. Los drenajes quirúrgicos están colocados cerca de la colección.", "pistas": ["Paciente al quinto día de una manga gástrica, con taquicardia persistente, fiebre y dolor en el hombro izquierdo, que no mejora con analgésicos.", "La taquicardia persistente tras cirugía bariátrica es el signo de alarma más precoz de esta complicación, antes que la fiebre o el dolor.", "La fuga está en el sitio clásico de la manga, cerca de la unión gastroesofágica, y el manejo depende de si hay sepsis, de si la colección está contenida y de si se puede drenar por vía endoscópica o percutánea."], "dx": "Fuga de la línea de grapas de manga gástrica, en la unión gastroesofágica, con colección subfrénica contenida.", "hallazgo": "Salida de contraste oral por el borde superior del tubo gástrico hacia una colección subfrénica de 5 cm con gas.", "exp": "La fuga de la manga gástrica es su complicación más temida y suele ocurrir cerca de la unión gastroesofágica, donde la presión es mayor y la vascularización es peor. La taquicardia persistente es el signo precoz clave. El manejo es ayuno, antibiótico, reanimación y drenaje de la colección (percutáneo o endoscópico, con prótesis o terapia de vacío endoscópico según el caso); la reintervención quirúrgica se reserva para la sepsis no controlada o la peritonitis difusa."},
    {"id": "IM-R4-07", "grade": "R4", "tema": "Cirugía vascular, torácica y emergencias toracoabdominales", "imagen": "Angiotomografía computarizada de tórax y abdomen, reconstrucción axial y sagital, fase arterial. Se observa un colgajo intimal en la aorta descendente, distal a la salida de la arteria subclavia izquierda, que divide la aorta en dos luces: una luz verdadera, más pequeña y que se opacifica antes, y una luz falsa, mayor, con flujo más lento y trombo parcial en su interior. La disección se extiende por toda la aorta torácica descendente hasta la aorta abdominal, por encima de las arterias renales. La aorta ascendente es de calibre normal, sin colgajo ni hematoma intramural. No hay signos de rotura ni derrame pleural masivo.", "pistas": ["Dolor torácico desgarrante, de inicio súbito, que irradia a la espalda y migra hacia el abdomen, en un hipertenso mal controlado.", "La presión arterial es diferente en ambos brazos y hay un soplo diastólico, pero el electrocardiograma no muestra infarto.", "La disección no compromete la aorta ascendente, lo que cambia por completo el manejo: no es cirugía cardiaca de emergencia, sino control médico estricto y, en casos complicados, reparación endovascular."], "dx": "Disección aórtica tipo B de Stanford (DeBakey III), de la aorta descendente, no complicada.", "hallazgo": "Colgajo intimal en la aorta descendente distal a la subclavia izquierda, con luz verdadera y luz falsa, aorta ascendente normal.", "exp": "La disección aórtica tipo B afecta la aorta descendente distal a la subclavia izquierda y, si no está complicada (sin rotura, sin malperfusión, sin expansión), el manejo inicial es médico: control estricto de la presión arterial y de la frecuencia cardiaca con betabloqueador y vasodilatador, en terapia intensiva. La reparación endovascular (TEVAR) se reserva para las complicadas: rotura, malperfusión de órganos, dolor refractario o expansión del diámetro. La tipo A, en cambio, es quirúrgica de emergencia."},
    {"id": "IM-R4-08", "grade": "R4", "tema": "Nefrourología", "imagen": "Tomografía computarizada de abdomen y pelvis sin contraste, corte axial y coronal, a la altura de los riñones y la pelvis. En el uréter izquierdo, a la altura de la unión ureterovesical, se observa un cálculo hiperdenso, redondeado, de 7 mm, que ocluye la luz ureteral. Por encima del cálculo, el uréter está dilatado y el riñón izquierdo muestra hidronefrosis moderada, con dilatación de la pelvis renal y los cálices, y aumento del grosor del parénquima con edema (signo del \"anillo\" perirrenal). El riñón derecho es normal, sin litiasis ni dilatación. No hay gas ni colecciones.", "pistas": ["Dolor cólico en el flanco izquierdo, de inicio súbito, que irradia a la ingle, con náusea, vómito y hematuria macroscópica.", "La TC sin contraste es el estudio de elección para la litiasis: el cálculo se ve hiperdenso y la hidronefrosis confirma la obstrucción.", "El tamaño del cálculo y su localización distal definen la probabilidad de expulsión espontánea y si se observa, se fragmenta o se extrae por endoscopia."], "dx": "Litiasis ureteral izquierda obstructiva, de 7 mm en la unión ureterovesical, con hidronefrosis moderada.", "hallazgo": "Cálculo hiperdenso de 7 mm en el uréter distal izquierdo, con dilatación ureteral e hidronefrosis por encima.", "exp": "La TC sin contraste es el estándar para la urolitiasis: muestra el cálculo, su tamaño y la obstrucción. Un cálculo distal de 7 mm tiene una probabilidad intermedia de expulsión espontánea; el manejo es analgesia, hidratación, alfabloqueador como terapia expulsiva y valoración urológica para litotricia extracorpórea o ureteroscopia si no se expulsa, hay infección, deterioro renal o dolor incoercible. La fiebre con obstrucción es una urgencia: hay que descomprimir la vía urinaria."},
    {"id": "IM-R4-09", "grade": "R4", "tema": "Aparato genital masculino", "imagen": "Ecografía Doppler escrotal, en modo B y Doppler color, del testículo izquierdo. El testículo izquierdo está aumentado de tamaño, con ecogenicidad heterogénea y áreas hipoecoicas que sugieren edema y congestión. El epidídimo está engrosado y el cordón espermático muestra el signo del remolino (\"whirlpool sign\"): las estructuras del cordón se ven enrolladas en espiral. En el Doppler color no hay flujo arterial ni venoso dentro del testículo izquierdo, mientras que el testículo derecho muestra flujo normal, simétrico, con ondas arteriales de baja resistencia. Hay un hidrocele reactivo pequeño.", "pistas": ["Dolor escrotal súbito, intenso, en un adolescente, con náusea y vómito, sin fiebre ni síntomas urinarios.", "El testículo afectado está elevado, horizontalizado y muy doloroso, con reflejo cremastérico ausente.", "Es una urgencia quirúrgica con ventana de horas: cada hora sin flujo acerca la pérdida del testículo y el diagnóstico no debe retrasarse con estudios innecesarios si la sospecha es alta."], "dx": "Torsión testicular izquierda, con ausencia de flujo Doppler.", "hallazgo": "Testículo aumentado y heterogéneo, signo del remolino en el cordón y ausencia completa de flujo Doppler, con testículo contralateral normal.", "exp": "La torsión testicular es la torsión del cordón espermático que corta el flujo al testículo; el dolor súbito en un adolescente, con testículo elevado y horizontal y reflejo cremastérico ausente, es el cuadro clásico. El Doppler confirma la ausencia de flujo y el signo del remolino, pero si la sospecha clínica es alta no se debe retrasar el quirófano por la imagen: la detorsión y la orquidopexia bilateral deben hacerse dentro de las primeras 6 horas para salvar el testículo."},
    {"id": "IM-R4-10", "grade": "R4", "tema": "Musculoesquelético y pie diabético", "imagen": "Radiografía del pie derecho, proyecciones anteroposterior y oblicua. En el antepié, a la altura de la cabeza del primer metatarsiano y la base de la falange proximal del hallux, se observa una zona de osteólisis: el hueso cortical está destruido e irregular, con pérdida de la definición de la articulación metatarsofalángica y rarefacción ósea. En los tejidos blandos adyacentes hay una úlcera visible como un defecto cutáneo con gas en los tejidos blandos vecinos, en forma de pequeñas burbujas radiolúcidas. No hay fractura aguda ni luxación. Los demás huesos del pie conservan su densidad, aunque hay calcificaciones vasculares en el dorso del pie.", "pistas": ["Úlcera plantar en el antepié, de semanas de evolución, en un paciente diabético con neuropatía, que no duele pero drena secreción fétida.", "La prueba de \"sonda a hueso\" (probe-to-bone) fue positiva: la sonda toca hueso a través de la úlcera.", "La destrucción ósea con gas en los tejidos blandos y la sonda positiva confirman la complicación, que cambia el tratamiento de una úlcera superficial a un problema óseo que exige desbridamiento y antibiótico prolongado."], "dx": "Pie diabético con osteomielitis del primer metatarsiano y úlcera plantar infectada, con gas en tejidos blandos.", "hallazgo": "Osteólisis y destrucción cortical de la cabeza del primer metatarsiano, con úlcera, gas en tejidos blandos y sonda a hueso positiva.", "exp": "La osteomielitis es la complicación grave del pie diabético: la úlcera neuropática se infecta y la infección llega al hueso. La radiografía muestra la osteólisis y el gas, y la sonda a hueso positiva es altamente sugestiva. El manejo es desbridamiento quirúrgico del hueso infectado, cultivos profundos, antibiótico prolongado, descarga del pie y control glucémico y vascular; sin tratarlo, la progresión es a la amputación."},
  ],
};
